const CROP_MACHINE_OIL_CAP_BASE = 48;

function getCropMachineOilCap() {
  let mult = 1;
  try {
    if (isSkillActive("skill_leak_proof_tank")) {
      const s = SKILL_BOOSTS.find(sk => sk.id === "skill_leak_proof_tank");
      mult = s && s.oilTankMult || 1;
    }
  } catch (e) {}
  return CROP_MACHINE_OIL_CAP_BASE * mult;
}

const RESTOCK_GEM_COST = {
  seeds: 15,
  tools: 10,
  all: 20
};

function isBuildingBoostActive(id) {
  return typeof isBoostActive === "function" ? isBoostActive(id) : false;
}

function getArtistCoinCostMult() {
  if (!isBuildingBoostActive("artist_discount")) return 1;
  const b = BOOSTS.find(x => x.id === "artist_discount");
  return b && b.coinCostMultAll || 1;
}

function computeBoostedStock(baseStock, kind, itemName) {
  let mult = 1;
  if (kind === "seed" && isBuildingBoostActive("warehouse_stock")) mult *= 1.2;
  if (kind === "tool" && isBuildingBoostActive("toolshed_stock")) mult *= 1.5;
  let flatAdd = 0;
  if (kind === "tool" && itemName && typeof BOOSTS !== "undefined") {
    BOOSTS.forEach(b => {
      if (b.category === "tools" && b.scope === "tool" && b.target === itemName && b.stockAdd && typeof isBoostActive === "function" && isBoostActive(b.id)) {
        flatAdd += b.stockAdd;
      }
    });
  }
  if (kind === "seed" && itemName && typeof BOOSTS !== "undefined" && isFullMoonToday()) {
    BOOSTS.forEach(b => {
      if (b.scope === "fruitList" && b.fruits && b.fruits.includes(itemName) && b.stockAdd && typeof isBoostActive === "function" && isBoostActive(b.id)) {
        flatAdd += b.stockAdd;
      }
    });
  }
  return baseStock * mult + flatAdd;
}

const SYNODIC_MONTH_DAYS = 29.530588853;

function isFullMoonToday(date) {
  date = date || new Date;
  const knownFullMoonUTC = Date.UTC(2024, 0, 25, 17, 54, 0);
  const synodicMonthMs = SYNODIC_MONTH_DAYS * 864e5;
  const diffMs = date.getTime() - knownFullMoonUTC;
  const cycles = diffMs / synodicMonthMs;
  const frac = cycles - Math.floor(cycles);
  const daysFromFull = Math.min(frac, 1 - frac) * SYNODIC_MONTH_DAYS;
  return daysFromFull <= 1;
}

function fullMoonSeedStockQty(name) {
  const baseStock = BASE_STOCK_FRUITS[name];
  if (baseStock == null) return baseStock;
  return computeBoostedStock(baseStock, "seed", name);
}

function computeRestockCost24h(baseStock, kind, count, cyclesPerDay, cyclesPerStockUnit, maxRestocksPerDay, itemName) {
  if (!baseStock || !count || !cyclesPerDay) return 0;
  const boostedStock = computeBoostedStock(baseStock, kind, itemName);
  const stockConsumingCyclesPerDay = cyclesPerDay / (cyclesPerStockUnit || 1);
  const cyclesPerRestock = boostedStock / count;
  if (cyclesPerRestock <= 0) return 0;
  let restocksPerDay = stockConsumingCyclesPerDay / cyclesPerRestock;
  if (maxRestocksPerDay != null) restocksPerDay = Math.min(restocksPerDay, maxRestocksPerDay);
  const gemCost = typeof getRestockGemCost === "function" ? getRestockGemCost(kind, itemName) : kind === "tool" ? RESTOCK_GEM_COST.tools : RESTOCK_GEM_COST.seeds;
  const gemsPerDay = restocksPerDay * gemCost;
  return typeof gemsToFlower === "function" ? gemsToFlower(gemsPerDay) : 0;
}

