const SEASON_ORDER = [ "Spring", "Summer", "Autumn", "Winter" ];

const SEASON_EMOJI = {
  Spring: '<img src="icons/season_spring.png" alt="Spring" style="width:14px;height:14px;vertical-align:-3px;image-rendering:pixelated;">',
  Summer: '<img src="icons/season_summer.png" alt="Summer" style="width:14px;height:14px;vertical-align:-3px;image-rendering:pixelated;">',
  Autumn: '<img src="icons/season_autumn.png" alt="Autumn" style="width:14px;height:14px;vertical-align:-3px;image-rendering:pixelated;">',
  Winter: '<img src="icons/season_winter.png" alt="Winter" style="width:14px;height:14px;vertical-align:-3px;image-rendering:pixelated;">'
};

function getCropSeasons(name) {
  const d = BASE_CROPS[name];
  return d && Array.isArray(d.seasons) && d.seasons.length ? d.seasons : SEASON_ORDER.slice();
}

function isCropInSeason(name, season) {
  season = season || previewSeason;
  return getCropSeasons(name).includes(season);
}

function getFruitSeasons(name) {
  const d = BASE_FRUITS[name];
  return d && Array.isArray(d.seasons) && d.seasons.length ? d.seasons : SEASON_ORDER.slice();
}

function isFruitInSeason(name, season) {
  season = season || previewSeason;
  return getFruitSeasons(name).includes(season);
}

function renderCropSeasonBadges(name) {
  const seasons = getCropSeasons(name);
  if (seasons.length === SEASON_ORDER.length) return `<span class="crop-season-badges" title="Grows year-round">${SEASON_ORDER.map(s => `<span class="active-season">${SEASON_EMOJI[s]}</span>`).join("")}</span>`;
  return `<span class="crop-season-badges">${seasons.map(s => `<span class="${s === previewSeason ? "active-season" : ""}" title="${s}">${SEASON_EMOJI[s]}</span>`).join("")}</span>`;
}

function renderFruitSeasonBadges(name) {
  const seasons = getFruitSeasons(name);
  if (seasons.length === SEASON_ORDER.length) return `<span class="crop-season-badges" title="Grows year-round">${SEASON_ORDER.map(s => `<span class="active-season">${SEASON_EMOJI[s]}</span>`).join("")}</span>`;
  return `<span class="crop-season-badges">${seasons.map(s => `<span class="${s === previewSeason ? "active-season" : ""}" title="${s}">${SEASON_EMOJI[s]}</span>`).join("")}</span>`;
}

const SEASON_ANCHOR_MS = new Date(2026, 6, 6, 8, 0, 0, 0).getTime();

const SEASON_ANCHOR_INDEX = 1;

const SEASON_WEEK_MS = 7 * 24 * 60 * 60 * 1e3;

function getRealSeason(now) {
  now = typeof now === "number" ? now : Date.now();
  const weekIndex = Math.floor((now - SEASON_ANCHOR_MS) / SEASON_WEEK_MS);
  const idx = ((SEASON_ANCHOR_INDEX + weekIndex) % 4 + 4) % 4;
  return SEASON_ORDER[idx];
}

let currentSeason = getRealSeason();

let previewSeason = currentSeason;

let selectedSeason = previewSeason;

function applySeasonTheme(season) {
  document.body.setAttribute("data-season", season.toLowerCase());
}

function renderSeasonToggle() {
  document.querySelectorAll(".season-toggle").forEach(wrap => {
    wrap.querySelectorAll("button").forEach(btn => {
      btn.classList.toggle("active", btn.dataset.season === previewSeason);
    });
  });
  const noteText = previewSeason === currentSeason ? `📅 This week's real season: ${currentSeason}` : `👀 Previewing ${previewSeason} — real season is ${currentSeason} (resets on refresh)`;
  [ "seasonToggleNote", "cropsSeasonToggleNote", "fishMarketSeasonToggleNote", "fruitsSeasonToggleNote" ].forEach(id => {
    const note = document.getElementById(id);
    if (note) note.textContent = noteText;
  });
}

function setPreviewSeason(season) {
  previewSeason = season;
  selectedSeason = season;
  if (typeof invalidateCostCache === "function") invalidateCostCache();
  applySeasonTheme(season);
  renderSeasonToggle();
  renderBoostPanel();
  if (typeof renderResourceList === "function") renderResourceList();
  if (typeof renderHoneyList === "function") renderHoneyList();
  if (typeof renderCropsList === "function") renderCropsList();
  if (typeof renderFruitsList === "function") renderFruitsList();
  if (typeof renderComposterList === "function") renderComposterList();
  if (typeof renderFishMarketCardsList === "function") renderFishMarketCardsList();
}

setInterval(() => {
  const real = getRealSeason();
  if (real !== currentSeason) {
    const wasFollowingReal = previewSeason === currentSeason;
    currentSeason = real;
    if (wasFollowingReal) {
      setPreviewSeason(currentSeason);
    } else {
      renderSeasonToggle();
    }
  }
}, 6e4);

