function getNodeTierCounts(resourceName) {
  if (!isTieredResource(resourceName)) return null;
  let v = nodeCounts[resourceName];
  if (typeof v !== "object" || v === null) {
    v = {
      base: parseFloat(v) || 0,
      tier1: 0,
      tier2: 0
    };
    nodeCounts[resourceName] = v;
  }
  return v;
}

function getNodeTierQty(resourceName, tierKey) {
  const t = getNodeTierCounts(resourceName);
  return t ? parseFloat(t[tierKey]) || 0 : 0;
}

function setNodeTierQty(resourceName, tierKey, val) {
  const t = getNodeTierCounts(resourceName);
  if (!t) return;
  t[tierKey] = parseFloat(val) || 0;
  saveNodeCounts();
  nodeCountsTouched.add(resourceName);
  saveNodeCountsTouched();
}

function getNodeCount(resourceName) {
  if (isTieredResource(resourceName)) {
    const t = getNodeTierCounts(resourceName);
    return RESOURCE_NODE_TIERS[resourceName].reduce((sum, tier) => sum + (parseFloat(t[tier.key]) || 0), 0);
  }
  return parseFloat(nodeCounts[resourceName]) || 0;
}

function setNodeCount(resourceName, val) {
  nodeCounts[resourceName] = val;
  saveNodeCounts();
  nodeCountsTouched.add(resourceName);
  saveNodeCountsTouched();
}

function getResourceTieredYieldTotal(resourceName, boostedYieldVal, perTierYield) {
  if (!isTieredResource(resourceName)) return boostedYieldVal * getNodeCount(resourceName);
  const t = getNodeTierCounts(resourceName);
  return RESOURCE_NODE_TIERS[resourceName].reduce((sum, tier) => {
    const qty = parseFloat(t[tier.key]) || 0;
    const perNodeYield = perTierYield && perTierYield[tier.key] != null ? perTierYield[tier.key] : boostedYieldVal;
    return sum + qty * (tier.mult * perNodeYield + tier.yieldAdd);
  }, 0);
}

function getResourceToolUsageTotal(resourceName) {
  if (!isTieredResource(resourceName)) return getNodeCount(resourceName);
  const t = getNodeTierCounts(resourceName);
  return RESOURCE_NODE_TIERS[resourceName].reduce((sum, tier) => {
    const qty = parseFloat(t[tier.key]) || 0;
    return sum + qty * tier.mult;
  }, 0);
}

