function ingredientKindLabel(name) {
  if (FLOWER_VARIETIES[name]) return "Flower";
  if (BASE_CROPS[name]) return "Crop";
  if (BASE_FRUITS[name]) return "Fruit";
  return "";
}

function seedIngredientOptionsList(seedKey) {
  const set = new Set;
  Object.keys(FLOWER_VARIETIES).forEach(vn => {
    const v = FLOWER_VARIETIES[vn];
    if (v.seed === seedKey) v.ingredients.forEach(i => set.add(i));
  });
  return Array.from(set).sort();
}

function findVarietiesBySeedIngredient(seedKey, ingredientName) {
  return Object.keys(FLOWER_VARIETIES).filter(vn => {
    const v = FLOWER_VARIETIES[vn];
    return v.seed === seedKey && v.ingredients.includes(ingredientName);
  });
}

let resourceMaterialMode = safeLSJSON(localStorage.getItem("hl_resource_material_mode"), {});

function getMaterialMode(resourceName, materialName) {
  if ((materialName || "").toLowerCase() === "oil") return "collect";
  const key = resourceName + ":" + materialName;
  if (Object.prototype.hasOwnProperty.call(resourceMaterialMode, key)) return resourceMaterialMode[key];
  return resourceName === "AnimalFeed" ? "buy" : "collect";
}

function setMaterialMode(resourceName, materialName, mode) {
  if ((materialName || "").toLowerCase() === "oil") return;
  resourceMaterialMode[resourceName + ":" + materialName] = mode;
  localStorage.setItem("hl_resource_material_mode", JSON.stringify(resourceMaterialMode));
}

