function getMissingPlotNodeFields() {
  const missing = [];
  if (!globalPlotCountTouched && globalPlotCount <= 0) missing.push("🌾 Crop plots");
  Object.keys(RESOURCE_DATA).forEach(name => {
    if (!nodeCountsTouched.has(name) && getNodeCount(name) <= 0) {
      const label = name === "Wood" ? "Tree" : name;
      missing.push(`${ICONS[name] || "⛏️"} ${label} node count`);
    }
  });
  if (!nodeCountsTouched.has("Lava Pit") && getNodeCount("Lava Pit") <= 0) missing.push("🌋 Lava Pit node count");
  return missing;
}

function hasPlotsNodesData() {
  return getMissingPlotNodeFields().length === 0;
}

const MEDICINE_RECIPE = {
  Lemon: 5,
  Honey: 3
};

function getBoostedMedicineRecipe() {
  const skill = SKILL_BOOSTS.find(s => s.id === "skill_alternate_medicine");
  const active = skill && typeof isBoostActive === "function" && isBoostActive("skill_alternate_medicine");
  const cut = active ? 1 : 0;
  const out = {};
  Object.keys(MEDICINE_RECIPE).forEach(name => {
    out[name] = Math.max(0, MEDICINE_RECIPE[name] - cut);
  });
  return out;
}

function getMedicineIngredientMode(name) {
  return getMaterialMode("AnimalMedicine", name);
}

function setMedicineIngredientMode(name, mode) {
  setMaterialMode("AnimalMedicine", name, mode);
}

function computeMedicineCostCoins(visited) {
  let total = 0;
  const recipe = getBoostedMedicineRecipe();
  Object.keys(recipe).forEach(name => {
    const mode = getMedicineIngredientMode(name);
    total += recipe[name] * getMaterialUnitCostCoins(name, mode, visited);
  });
  return total;
}

function computeMedicineCostFlower(visited) {
  return coinsToFlower(computeMedicineCostCoins(visited));
}

function getGlobalCureModifiers() {
  let cureFree = false, cureCostMult = 1;
  ANIMAL_BOOSTS.filter(b => b.scope === "animalGlobal" && isBoostActive(b.id)).forEach(b => {
    if (b.freeCure) cureFree = true;
    if (b.cureCostMult) cureCostMult *= b.cureCostMult;
  });
  return {
    cureFree: cureFree,
    cureCostMult: cureCostMult
  };
}

let animalSicknessEstimate = safeLSJSON(localStorage.getItem("hl_animal_sickness_estimate"), {
  chicken: {
    sickHeads: 0
  },
  sheep: {
    sickHeads: 0
  },
  cow: {
    sickHeads: 0
  }
});

function saveAnimalSicknessEstimate() {
  localStorage.setItem("hl_animal_sickness_estimate", JSON.stringify(animalSicknessEstimate));
}

function getSicknessEstimate(type) {
  return animalSicknessEstimate[type] || {
    sickHeads: 0
  };
}

function getEffectiveSickHeads(type) {
  const qty = Math.max(0, parseFloat(getAnimalCount(type).qty) || 0);
  const est = getSicknessEstimate(type);
  let sickHeads = Math.min(Math.max(0, est.sickHeads || 0), qty);
  if (isSkillActive("skill_healthy_livestock")) sickHeads *= .5;
  return sickHeads;
}

function getCuresPerLevelForType(type) {
  const qty = Math.max(0, parseFloat(getAnimalCount(type).qty) || 0);
  if (qty <= 0) return 0;
  const sickHeads = getEffectiveSickHeads(type);
  return sickHeads / qty;
}

