const BOOSTED_STATS_CACHE_TTL_MS = 80;

const __boostedCropStatsMemo = new Map;

const __boostedFruitStatsMemo = new Map;

const __boostedGreenhouseStatsMemo = new Map;

const __boostedResourceStatsMemo = new Map;

const __boostedLavaPitStatsMemo = new Map;

function __memoWithTTL(cache, key, computeFn) {
  const now = Date.now();
  const hit = cache.get(key);
  if (hit && now - hit.at < BOOSTED_STATS_CACHE_TTL_MS) return hit.result;
  const result = computeFn();
  cache.set(key, {
    result: result,
    at: now
  });
  return result;
}

function computeBoostedCropStats(cropName, baseYield, baseTimeSec, plotCountOverride, windowSec, includeBeeSwarm) {
  const key = cropName + "|" + baseYield + "|" + baseTimeSec + "|" + plotCountOverride + "|" + windowSec + "|" + includeBeeSwarm;
  return __memoWithTTL(__boostedCropStatsMemo, key, () => computeBoostedCropStatsUncached(cropName, baseYield, baseTimeSec, plotCountOverride, windowSec, includeBeeSwarm));
}

function computeBoostedFruitStats(fruitName, baseYield, baseTimeSec, baseMinHarvest, nodeCountOverride, windowSec) {
  const key = fruitName + "|" + baseYield + "|" + baseTimeSec + "|" + baseMinHarvest + "|" + nodeCountOverride + "|" + windowSec;
  return __memoWithTTL(__boostedFruitStatsMemo, key, () => computeBoostedFruitStatsUncached(fruitName, baseYield, baseTimeSec, baseMinHarvest, nodeCountOverride, windowSec));
}

function computeBoostedGreenhouseStats(name, baseYield, baseTimeSec, nodeCountOverride, windowSec) {
  const key = name + "|" + baseYield + "|" + baseTimeSec + "|" + nodeCountOverride + "|" + windowSec;
  return __memoWithTTL(__boostedGreenhouseStatsMemo, key, () => computeBoostedGreenhouseStatsUncached(name, baseYield, baseTimeSec, nodeCountOverride, windowSec));
}

function computeBoostedResourceStats(resourceName, baseYield, baseTimeSec, windowSec) {
  const key = resourceName + "|" + baseYield + "|" + baseTimeSec + "|" + windowSec;
  return __memoWithTTL(__boostedResourceStatsMemo, key, () => computeBoostedResourceStatsUncached(resourceName, baseYield, baseTimeSec, windowSec));
}

function computeBoostedLavaPitStats(baseTimeSec) {
  const key = String(baseTimeSec);
  return __memoWithTTL(__boostedLavaPitStatsMemo, key, () => computeBoostedLavaPitStatsUncached(baseTimeSec));
}

function invalidateCostCache() {
  __cookingCostMemo.clear();
  __materialCostMemo.clear();
  __toolCostMemo.clear();
  __petCardMemo.clear();
  __fishBasicFiguresMemo.clear();
  __fishAgedFiguresMemo.clear();
  __fishCatchXPMemo.clear();
  __cookingFoodExpMemo.clear();
  __cookingFoodTimeMemo.clear();
  __crabFiguresMemo = null;
  __seaweedFiguresMemo = null;
  __boostedCropStatsMemo.clear();
  __boostedFruitStatsMemo.clear();
  __boostedGreenhouseStatsMemo.clear();
  __boostedResourceStatsMemo.clear();
  __boostedLavaPitStatsMemo.clear();
}

function getItemCostByName(name, visited) {
  if (__materialCostMemo.has(name)) return __materialCostMemo.get(name);
  if (visited && visited.has(name)) return 0;
  const branchVisited = new Set(visited || []);
  branchVisited.add(name);
  const result = getItemCostByNameUncached(name, branchVisited);
  __materialCostMemo.set(name, result);
  return result;
}

function getItemCostByNameUncached(name, visited) {
  visited = visited || new Set;
  if ((name || "").toLowerCase() === "salt") {
    if (visited.has("salt")) return 0;
    visited.add("salt");
    return computeSaltUnitCostCoins();
  }
  if ((name || "").toLowerCase() === "honey") {
    if (visited.has("honey")) return 0;
    visited.add("honey");
    const econ = computeHiveEconomics(visited);
    return econ.hiveStats.honeyPerHiveDay > 0 ? econ.costPerHiveDay / econ.hiveStats.honeyPerHiveDay * coinPerFlower : 0;
  }
  if ((name || "").toLowerCase() === "obsidian") {
    if (visited.has("obsidian")) return 0;
    visited.add("obsidian");
    return computeLavaPitFigures(currentSeason).costPerUnit;
  }
  if (typeof BASE_COMPOSTERS !== "undefined") {
    const composterName = Object.keys(BASE_COMPOSTERS).find(k => BASE_COMPOSTERS[k].wormName === name);
    if (composterName) {
      const key = "worm:" + name;
      if (visited.has(key)) return 0;
      visited.add(key);
      const fig = computeComposterFigures(composterName, visited);
      return fig.wormAvg > 0 ? fig.ingredientCostCoins / fig.wormAvg : 0;
    }
  }
  if (typeof FISH_MARKET_ITEM_NAMES !== "undefined" && FISH_MARKET_ITEM_NAMES.includes(name)) {
    const key = "fishmarket:" + name;
    if (visited.has(key)) return 0;
    visited.add(key);
    const season = typeof previewSeason !== "undefined" && previewSeason ? previewSeason : "Spring";
    const totalCoins = fishMarketItemCostCoins(name, "collect", season, visited);
    const meta = typeof getFishMarketMeta === "function" ? getFishMarketMeta(name) : null;
    const yieldQty = meta && meta.yield ? meta.yield : 1;
    return yieldQty > 0 ? totalCoins / yieldQty : totalCoins;
  }
  if (typeof FISH_CATCH_DATA !== "undefined" && FISH_CATCH_DATA[name]) {
    const key = "fishcatch:" + name;
    if (visited.has(key)) return 0;
    visited.add(key);
    const fig = computeBasicFishFigures(name, visited);
    return fig ? fig.costCoins : 0;
  }
  if (typeof CRUSTACEAN_CATCH_DATA !== "undefined" && CRUSTACEAN_CATCH_DATA[name]) {
    const key = "crustacean:" + name;
    if (visited.has(key)) return 0;
    visited.add(key);
    const fig = computeCrustaceanFigures(name, visited);
    return fig ? fig.totalCoins : 0;
  }
  if ((name || "") === "Crab") {
    const key = "crab";
    if (visited.has(key)) return 0;
    visited.add(key);
    const fig = computeCrabFigures();
    return fig ? fig.costCoins : 0;
  }
  if ((name || "") === "Seaweed") {
    const key = "seaweed";
    if (visited.has(key)) return 0;
    visited.add(key);
    const fig = computeSeaweedFigures();
    return fig ? fig.costCoins : 0;
  }
  if (RESOURCE_DATA[name]) {
    const key = "resource:" + name;
    if (visited.has(key)) return 0;
    visited.add(key);
    return computeResourceFigures(name, visited).costPerUnit;
  }
  if (BASE_CROPS[name]) return getCropCostCoins(name, visited);
  if (BASE_FRUITS[name]) return getFruitCostCoins(name, visited);
  if (BASE_GREENHOUSE[name]) return getGreenhouseCostCoins(name, visited);
  if (FLOWER_VARIETIES[name]) return getFlowerVarietyCostCoins(name, visited);
  const animalType = Object.keys(ANIMAL_DATA).find(t => ANIMAL_DATA[t].products.some(p => p.toLowerCase() === (name || "").toLowerCase()));
  if (animalType) {
    const key = "animal:" + animalType;
    if (visited.has(key)) return 0;
    visited.add(key);
    return computeAnimalTypeFigures(animalType, visited).costPerUnit;
  }
  const tool = toolRecipes.find(t => (t.producesName || "").toLowerCase() === (name || "").toLowerCase());
  if (tool) return getToolCostCoins(tool.id, visited);
  return 0;
}

function getMaterialUnitCostCoins(materialName, mode, visited) {
  if (mode === "buy") {
    const m = marketItems.find(x => (x.name || "").toLowerCase() === materialName.toLowerCase());
    if (m) return (m.flowerPrice || 0) * coinPerFlower;
    return getItemCostByName(materialName, visited);
  }
  return getItemCostByName(materialName, visited);
}

function traceZeroCostBoosts(name, visited) {
  visited = visited || new Set;
  if (visited.has(name)) return [];
  visited.add(name);
  const found = [];
  const addFound = arr => (arr || []).forEach(b => {
    if (b && !found.some(f => f.id === b.id)) found.push(b);
  });
  if (BASE_CROPS[name]) {
    if (hasFreeCostBoost(name)) addFound(getActiveBoostsForCrop(name).filter(b => b.freeCost));
    return found;
  }
  if (BASE_FRUITS[name]) {
    if (hasFreeCostBoostFruit(name)) addFound(getActiveBoostsForFruit(name).filter(b => b.freeCost));
    return found;
  }
  if (BASE_GREENHOUSE[name]) {
    if (hasFreeCostBoostGreenhouse(name)) addFound(getActiveBoostsForGreenhouse(name).filter(b => b.freeCost));
    return found;
  }
  if (typeof FISH_CATCH_DATA !== "undefined" && FISH_CATCH_DATA[name]) {
    const fig = computeBasicFishFigures(name);
    if (fig) {
      if (fig.rodCost === 0 && typeof fishingRodIsFree === "function" && fishingRodIsFree()) {
        addFound(fishingBoostsActiveByScope("fishRod").filter(b => b.rodFreeCost));
      }
      if (fig.chum && fig.chum.unit === 0) addFound(traceZeroCostBoosts(fig.chum.name, visited));
      if (fig.bait && fig.bait.cost === 0) addFound(traceZeroCostBoosts(fig.bait.name, visited));
    }
    return found;
  }
  if (typeof CRUSTACEAN_CATCH_DATA !== "undefined" && CRUSTACEAN_CATCH_DATA[name]) {
    const fig = computeCrustaceanFigures(name, visited);
    if (fig) {
      if (fig.trapCost === 0 && typeof crustaceanTrapIsFree === "function" && crustaceanTrapIsFree()) {
        addFound(fishingBoostsActiveByScope("crustacean").filter(b => b.crustaceanTrapFreeCost));
      }
      if (fig.chumCost === 0 && fig.selectedChum) addFound(traceZeroCostBoosts(fig.selectedChum, visited));
    }
    return found;
  }
  if (typeof FISH_MARKET_ITEM_NAMES !== "undefined" && FISH_MARKET_ITEM_NAMES.includes(name)) {
    const season = typeof previewSeason !== "undefined" && previewSeason ? previewSeason : "Spring";
    const ingredients = fishMarketItemIngredients(name, season);
    ingredients.forEach(([ing]) => addFound(traceZeroCostBoosts(ing, visited)));
    return found;
  }
  if (typeof COOKING_BUILDINGS !== "undefined") {
    for (const b of COOKING_BUILDINGS) {
      const rec = COOKING_RECIPES[b] && COOKING_RECIPES[b][name];
      if (rec) {
        Object.keys(rec.ingredients).forEach(ing => addFound(traceZeroCostBoosts(ing, visited)));
        return found;
      }
    }
  }
  if ((name || "") === "Seaweed" || (name || "") === "Crab") {
    const fig = name === "Seaweed" ? computeSeaweedFigures() : computeCrabFigures();
    if (fig && fig.costCoins === 0 && fig.rodCost === 0 && typeof fishingRodIsFree === "function" && fishingRodIsFree()) {
      addFound(fishingBoostsActiveByScope("fishRod").filter(b => b.rodFreeCost));
    }
    return found;
  }
  return found;
}

function getActiveBoostsForResource(resourceName) {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "resources" && (b.scope === "resource" && (b.target || "").toLowerCase() === resourceName.toLowerCase() || b.scope === "resourceList" && (b.resources || []).some(r => r.toLowerCase() === resourceName.toLowerCase()) || b.scope === "resourceEffects"));
}

function allocateAoeAcrossTiers(resourceName, plotCap) {
  const tiers = RESOURCE_NODE_TIERS[resourceName] || [];
  let remaining = plotCap;
  const result = {};
  tiers.slice().reverse().forEach(t => {
    const totalNodes = getNodeTierQty(resourceName, t.key);
    const affectedNodes = Math.max(0, Math.min(totalNodes, remaining));
    remaining -= affectedNodes;
    result[t.key] = {
      totalNodes: totalNodes,
      affectedNodes: affectedNodes
    };
  });
  return result;
}

function getAoeNodeBasis(b, resourceName) {
  if (isTieredResource(resourceName)) {
    const perTier = allocateAoeAcrossTiers(resourceName, b.plotCap);
    const totalNodes = Object.values(perTier).reduce((s, a) => s + a.totalNodes, 0);
    const affectedNodes = Object.values(perTier).reduce((s, a) => s + a.affectedNodes, 0);
    return {
      totalNodes: totalNodes,
      affectedNodes: affectedNodes,
      perTier: perTier
    };
  }
  const totalNodes = getNodeCount(resourceName);
  return {
    totalNodes: totalNodes,
    affectedNodes: Math.min(totalNodes, b.plotCap),
    perTier: null
  };
}

function computeBoostedResourceStatsUncached(resourceName, baseYield, baseTimeSec, windowSec) {
  windowSec = windowSec || 86400;
  const active = getActiveBoostsForResource(resourceName);
  const tiered = isTieredResource(resourceName);
  let addSum = 0, multBonusSum = 0;
  let alwaysTimeMult = 1, toolCostMult = 1, noToolNeeded = false;
  const materialSwaps = [];
  const limitedTimeFactors = [];
  const haveSyncData = hasLimitedBoostSyncData();
  const perTierAddSum = tiered ? {} : null;
  if (tiered) RESOURCE_NODE_TIERS[resourceName].forEach(t => {
    perTierAddSum[t.key] = 0;
  });
  const budAddSum = {};
  const budPerTierAddSum = tiered ? {} : null;
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    const bYieldAdd = b.resourceEffects ? b.resourceEffects[resourceName] || 0 : b.yieldAdd || 0;
    const budKey = b.isBud && b.budId ? b.budId : null;
    if (bYieldAdd) {
      if (b.plotCap) {
        const basis = getAoeNodeBasis(b, resourceName);
        const fraction = basis.totalNodes > 0 ? basis.affectedNodes / basis.totalNodes : 0;
        const contribution = bYieldAdd * fraction * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
        if (tiered && basis.perTier) {
          Object.keys(basis.perTier).forEach(key => {
            const a = basis.perTier[key];
            const tierFraction = a.totalNodes > 0 ? a.affectedNodes / a.totalNodes : 0;
            const tierContribution = bYieldAdd * tierFraction * coverageFraction;
            if (budKey) {
              if (!budPerTierAddSum[key]) budPerTierAddSum[key] = {};
              budPerTierAddSum[key][budKey] = (budPerTierAddSum[key][budKey] || 0) + tierContribution;
            } else {
              perTierAddSum[key] += tierContribution;
            }
          });
        }
      } else {
        const contribution = bYieldAdd * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
        if (tiered) Object.keys(perTierAddSum).forEach(key => {
          if (budKey) {
            if (!budPerTierAddSum[key]) budPerTierAddSum[key] = {};
            budPerTierAddSum[key][budKey] = (budPerTierAddSum[key][budKey] || 0) + contribution;
          } else {
            perTierAddSum[key] += contribution;
          }
        });
      }
    }
    if (b.yieldMult) multBonusSum += (b.yieldMult - 1) * coverageFraction;
    if (b.timeMult) {
      if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
        limitedTimeFactors.push({
          timeMult: b.timeMult,
          remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
        });
      } else {
        alwaysTimeMult *= b.timeMult;
      }
    }
    if (b.toolCostMult) toolCostMult *= b.toolCostMult;
    if (b.noTool) noToolNeeded = true;
    if (b.materialSwap) materialSwaps.push(b.materialSwap);
  });
  const budAddValues = Object.values(budAddSum);
  if (budAddValues.length) addSum += Math.max(...budAddValues);
  if (tiered && budPerTierAddSum) {
    Object.keys(budPerTierAddSum).forEach(key => {
      const vals = Object.values(budPerTierAddSum[key]);
      if (vals.length) perTierAddSum[key] += Math.max(...vals);
    });
  }
  const totalBonusFraction = addSum / baseYield + multBonusSum;
  const yieldVal = baseYield * (1 + totalBonusFraction);
  let perTierYield = null;
  if (tiered) {
    perTierYield = {};
    Object.keys(perTierAddSum).forEach(key => {
      const frac = perTierAddSum[key] / baseYield + multBonusSum;
      perTierYield[key] = Math.max(1e-4, baseYield * (1 + frac));
    });
  }
  const cyclesForFactor = extraMult => 86400 / Math.max(1, baseTimeSec * alwaysTimeMult * extraMult);
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  const timeVal = blendedCyclesPerDay > 0 ? 86400 / blendedCyclesPerDay : Math.max(1, baseTimeSec * alwaysTimeMult);
  return {
    yieldVal: Math.max(1e-4, yieldVal),
    timeVal: Math.max(1, timeVal),
    toolCostMult: toolCostMult,
    noToolNeeded: noToolNeeded,
    materialSwaps: materialSwaps,
    activeBoosts: active,
    perTierYield: perTierYield
  };
}

function getActiveBoostsForFruit(fruitName) {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "fruits" && (b.scope === "global" || b.scope === "fruit" && (b.target || "").toLowerCase() === (fruitName || "").toLowerCase() || b.scope === "fruitList" && Array.isArray(b.fruits) && b.fruits.some(f => f.toLowerCase() === (fruitName || "").toLowerCase())));
}

function hasFreeCostBoostFruit(fruitName) {
  return getActiveBoostsForFruit(fruitName).some(b => b.freeCost);
}

function computeBoostedFruitStatsUncached(fruitName, baseYield, baseTimeSec, baseMinHarvest, nodeCountOverride, windowSec) {
  windowSec = windowSec || 86400;
  const active = getActiveBoostsForFruit(fruitName);
  let addSum = 0, multBonusSum = 0;
  let alwaysTimeMult = 1, minHarvestVal = baseMinHarvest || 1;
  let noWoodCost = false;
  let woodReturnPenalty = 0;
  let woodReturnAdd = 0;
  const totalNodes = nodeCountOverride != null ? nodeCountOverride : getFruitCount(fruitName);
  const limitedTimeFactors = [];
  const haveSyncData = hasLimitedBoostSyncData();
  const budAddSum = {};
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    const add = getEffectiveYieldAdd(b);
    const budKey = b.isBud && b.budId ? b.budId : null;
    if (add) {
      if (b.plotCap) {
        const fraction = totalNodes > 0 ? Math.min(totalNodes, b.plotCap) / totalNodes : 0;
        const contribution = add * fraction * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      } else {
        const contribution = add * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      }
    }
    if (b.yieldMult) multBonusSum += (b.yieldMult - 1) * coverageFraction;
    if (b.timeMult) {
      if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
        limitedTimeFactors.push({
          timeMult: b.timeMult,
          remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
        });
      } else {
        alwaysTimeMult *= b.timeMult;
      }
    }
    if (b.harvestAdd) minHarvestVal += b.harvestAdd;
    if (b.noWood) noWoodCost = true;
    if (b.woodReturnPenalty) woodReturnPenalty += b.woodReturnPenalty;
    if (b.woodReturnAdd) woodReturnAdd += b.woodReturnAdd;
  });
  const budAddValues = Object.values(budAddSum);
  if (budAddValues.length) addSum += Math.max(...budAddValues);
  const totalBonusFraction = addSum / baseYield + multBonusSum;
  const yieldVal = baseYield * (1 + totalBonusFraction);
  const cyclesForFactor = extraMult => 86400 / Math.max(1, baseTimeSec * alwaysTimeMult * extraMult);
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  const timeVal = blendedCyclesPerDay > 0 ? 86400 / blendedCyclesPerDay : Math.max(1, baseTimeSec * alwaysTimeMult);
  return {
    yieldVal: Math.max(1e-4, yieldVal),
    timeVal: Math.max(1, timeVal),
    minHarvestVal: Math.max(1, minHarvestVal),
    noWoodCost: noWoodCost,
    woodReturnPenalty: woodReturnPenalty,
    woodReturnAdd: woodReturnAdd,
    activeBoosts: active
  };
}

const GREENHOUSE_GLOBAL_EXCLUDED_FROM_GRAPE = new Set([ "tortoise_shrine", "skill_rice_and_shine" ]);

const CROPS_GLOBAL_EXCLUDED_FROM_GREENHOUSE = new Set([ "sir_goldensnout", "gnome", "sparrow_shrine", "faction_wings", "autumns_embrace", "frozen_heart", "solflare_aegis", "blossom_ward", "bee_swarm", "sunshower" ]);

const GRAPE_ONLY_CROPS_GLOBAL_BOOSTS = new Set([ "time_warp_totem", "super_totem", "bountiful_harvest" ]);

function getActiveBoostsForGreenhouse(name) {
  const lname = (name || "").toLowerCase();
  const isGrape = lname === "grape";
  let greenhouseOwn = BOOSTS.filter(b => isBoostActive(b.id) && b.category === "greenhouse" && (b.scope === "global" || b.scope === "greenhouse" && (b.target || "").toLowerCase() === lname));
  if (isGrape) {
    greenhouseOwn = greenhouseOwn.filter(b => !GREENHOUSE_GLOBAL_EXCLUDED_FROM_GRAPE.has(b.id));
  } else {
    greenhouseOwn = greenhouseOwn.filter(b => !b.isBud);
  }
  const coreCropGlobal = isGrape ? BOOSTS.filter(b => isBoostActive(b.id) && b.category === "crops" && b.scope === "global" && GRAPE_ONLY_CROPS_GLOBAL_BOOSTS.has(b.id)) : BOOSTS.filter(b => isBoostActive(b.id) && b.category === "crops" && b.scope === "global" && !b.composterFertilizer && !CROPS_GLOBAL_EXCLUDED_FROM_GREENHOUSE.has(b.id)).filter(b => b.id !== "hoot" || lname === "rice");
  return greenhouseOwn.concat(coreCropGlobal);
}

function hasFreeCostBoostGreenhouse(name) {
  return getActiveBoostsForGreenhouse(name).some(b => b.freeCost);
}

function computeBoostedGreenhouseStatsUncached(name, baseYield, baseTimeSec, nodeCountOverride, windowSec) {
  windowSec = windowSec || 86400;
  const active = getActiveBoostsForGreenhouse(name);
  let addSum = 0, multBonusSum = 0;
  let alwaysTimeMult = 1, seedQtyMult = 1, oilQtyMult = 1, oilFlatReduce = 0;
  const totalNodes = nodeCountOverride != null ? nodeCountOverride : getGreenhouseCount(name);
  const limitedTimeFactors = [];
  const haveSyncData = hasLimitedBoostSyncData();
  const budAddSum = {};
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    const budKey = b.isBud && b.budId ? b.budId : null;
    if (b.yieldAdd) {
      if (b.plotCap) {
        const fraction = totalNodes > 0 ? Math.min(totalNodes, b.plotCap) / totalNodes : 0;
        const contribution = b.yieldAdd * fraction * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      } else {
        const contribution = b.yieldAdd * coverageFraction;
        if (budKey) budAddSum[budKey] = (budAddSum[budKey] || 0) + contribution; else addSum += contribution;
      }
    }
    if (b.yieldMult) multBonusSum += (b.yieldMult - 1) * coverageFraction;
    if (b.timeMult) {
      if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
        limitedTimeFactors.push({
          timeMult: b.timeMult,
          remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
        });
      } else {
        alwaysTimeMult *= b.timeMult;
      }
    }
    if (b.seedQtyMult) seedQtyMult *= b.seedQtyMult;
    if (b.oilQtyMult) oilQtyMult *= b.oilQtyMult;
    if (b.oilFlatReduce) oilFlatReduce += b.oilFlatReduce;
  });
  const budAddValues = Object.values(budAddSum);
  if (budAddValues.length) addSum += Math.max(...budAddValues);
  const totalBonusFraction = addSum / baseYield + multBonusSum;
  const yieldVal = baseYield * (1 + totalBonusFraction);
  const cyclesForFactor = extraMult => 86400 / Math.max(1, baseTimeSec * alwaysTimeMult * extraMult);
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  const timeVal = blendedCyclesPerDay > 0 ? 86400 / blendedCyclesPerDay : Math.max(1, baseTimeSec * alwaysTimeMult);
  return {
    yieldVal: Math.max(1e-4, yieldVal),
    timeVal: Math.max(1, timeVal),
    activeBoosts: active,
    seedQtyMult: seedQtyMult,
    oilQtyMult: oilQtyMult,
    oilFlatReduce: oilFlatReduce
  };
}

function getActiveBoostsForCropMachine() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "cropmachine" && b.scope === "machineGlobal");
}

function computeBoostedMachineTimeSec(baseTimeSec, windowSec) {
  windowSec = windowSec || 86400;
  let alwaysTimeMult = 1;
  const limitedTimeFactors = [];
  const haveSyncData = hasLimitedBoostSyncData();
  getActiveBoostsForCropMachine().forEach(b => {
    if (!b.timeMult) return;
    if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
      limitedTimeFactors.push({
        timeMult: b.timeMult,
        remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
      });
    } else {
      alwaysTimeMult *= b.timeMult;
    }
  });
  const cyclesForFactor = extraMult => 86400 / Math.max(1, baseTimeSec * alwaysTimeMult * extraMult);
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  return blendedCyclesPerDay > 0 ? Math.max(1, 86400 / blendedCyclesPerDay) : Math.max(1, baseTimeSec * alwaysTimeMult);
}

function computeCropMachineOilMult() {
  let oilQtyMult = 1;
  let oilReducePct = 0;
  getActiveBoostsForCropMachine().forEach(b => {
    if (b.oilQtyMult) oilQtyMult *= b.oilQtyMult;
    if (b.oilReducePct) oilReducePct += b.oilReducePct;
  });
  return oilQtyMult * Math.max(0, 1 - oilReducePct);
}

function getCropMachineYieldMultiplier(name) {
  const base = BASE_CROPS[name];
  if (!base) return 1;
  const boosted = computeBoostedCropStats(name, 1, base.timeSec);
  return boosted.yieldVal;
}

function computeCropMachineBatch(name, qty) {
  const base = BASE_CROP_MACHINE[name];
  const cropBase = BASE_CROPS[name];
  if (!base || !cropBase) return null;
  qty = Math.max(0, qty || 0);
  const ratio = base.seedQty > 0 ? qty / base.seedQty : 0;
  const timeSec = computeBoostedMachineTimeSec(base.timeSec) * ratio;
  const oilQty = base.oilQty * ratio * computeCropMachineOilMult();
  const yieldMult = getCropMachineYieldMultiplier(name);
  const yieldQty = base.yieldQty * ratio * yieldMult;
  const seedCoinCost = (hasFreeCostBoost(name) ? 0 : cropBase.seedCost || 0) * qty;
  const oilCoinCost = oilQty * getItemCostByName("Oil");
  const costCoins = seedCoinCost + oilCoinCost;
  const costFlower = coinsToFlower(costCoins);
  const m = marketItems.find(x => (x.name || "").toLowerCase() === name.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const netSellFlower = sellFlower * (1 - feePercent / 100);
  const revenueFlower = netSellFlower * yieldQty;
  const profitFlower = revenueFlower - costFlower;
  return {
    name: name,
    qty: qty,
    timeSec: timeSec,
    oilQty: oilQty,
    yieldQty: yieldQty,
    seedCoinCost: seedCoinCost,
    oilCoinCost: oilCoinCost,
    costCoins: costCoins,
    costFlower: costFlower,
    sellFlower: sellFlower,
    netSellFlower: netSellFlower,
    revenueFlower: revenueFlower,
    profitFlower: profitFlower,
    yieldMult: yieldMult
  };
}

function computeMachineRestockGems(name, totalQty) {
  const baseStock = BASE_STOCK_CROPS[name];
  if (!baseStock || !totalQty) return {
    restocksNeeded: 0,
    gemsTotal: 0,
    flowerCost: 0
  };
  const boostedStock = computeBoostedStock(baseStock, "seed");
  if (!boostedStock) return {
    restocksNeeded: 0,
    gemsTotal: 0,
    flowerCost: 0
  };
  const restocksNeeded = totalQty / boostedStock;
  const gemCostPerRestock = typeof getRestockGemCostIndividual === "function" ? getRestockGemCostIndividual("seed") : RESTOCK_GEM_COST.seeds;
  const gemsTotal = restocksNeeded * gemCostPerRestock;
  const flowerCost = typeof gemsToFlower === "function" ? gemsToFlower(gemsTotal) : 0;
  return {
    restocksNeeded: restocksNeeded,
    boostedStock: boostedStock,
    gemCostPerRestock: gemCostPerRestock,
    gemsTotal: gemsTotal,
    flowerCost: flowerCost
  };
}

const CM_MODULE_SKILL_IDS = {
  I: "skill_crop_extension_module_1",
  II: "skill_crop_extension_module_2",
  III: "skill_crop_extension_module_3"
};

const CM_MODULE_SKILL_NAMES = {
  I: "Crop Extension Module I",
  II: "Crop Extension Module II",
  III: "Crop Extension Module III"
};

function isCropMachineUnlocked(name) {
  const d = BASE_CROP_MACHINE[name];
  if (!d) return false;
  if (d.module === "Base") return true;
  return isSkillActive(CM_MODULE_SKILL_IDS[d.module]);
}

function getActiveBoostsForHive() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "honey" && b.scope === "hiveGlobal");
}

function getActiveBoostsForFlower(flowerName) {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "honey" && (b.scope === "flowerGlobal" || b.scope === "flower" && (b.target || "").toLowerCase() === (flowerName || "").toLowerCase()));
}

function computeBoostedFlowerVarietyStats(varietyName, windowSec) {
  windowSec = windowSec || 86400;
  const v = FLOWER_VARIETIES[varietyName];
  const active = getActiveBoostsForFlower(varietyName);
  const seedData = FLOWER_SEEDS[v.seed];
  const baseTimeSec = seedData.timeSec;
  let alwaysTimeMult = 1;
  let expectedYield = 1;
  const limitedTimeFactors = [];
  const haveSyncData = hasLimitedBoostSyncData();
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    if (b.flowerTimeMult) {
      if (b.limitedBoostName && haveSyncData && getLimitedBoostRemainingSec(b.limitedBoostName) > 0) {
        limitedTimeFactors.push({
          timeMult: b.flowerTimeMult,
          remainingSec: getLimitedBoostRemainingSec(b.limitedBoostName)
        });
      } else {
        alwaysTimeMult *= b.flowerTimeMult;
      }
    }
    if (b.flowerExtraChance) expectedYield += b.flowerExtraChance * coverageFraction;
    if (b.flowerExtraFlat) expectedYield += b.flowerExtraFlat * coverageFraction;
  });
  const cyclesForFactor = extraMult => 86400 / Math.max(1, baseTimeSec * alwaysTimeMult * extraMult);
  const blendedCyclesPerDay = blendCyclesPerDayForExpiry(cyclesForFactor, limitedTimeFactors, windowSec);
  const timeVal = blendedCyclesPerDay > 0 ? 86400 / blendedCyclesPerDay : Math.max(1, baseTimeSec * alwaysTimeMult);
  return {
    timeVal: Math.max(60, timeVal),
    expectedYield: Math.max(.01, expectedYield),
    activeBoosts: active
  };
}

function getFlowerVarietyCostCoins(varietyName, visited) {
  visited = visited || new Set;
  const key = "flowerVariety_" + varietyName;
  if (visited.has(key)) return 0;
  visited.add(key);
  const v = FLOWER_VARIETIES[varietyName];
  if (!v) return 0;
  const seedCoinCost = getFlowerSeedTypeCost(v.seed);
  const ing = getVarietyIngredient(varietyName);
  const mode = getMaterialMode("FlowerVariety_" + varietyName, ing.name);
  const ingCoinCost = ing.name ? (ing.qty || 0) * getMaterialUnitCostCoins(ing.name, mode, visited) : 0;
  const boosted = computeBoostedFlowerVarietyStats(varietyName);
  return (seedCoinCost + ingCoinCost) / boosted.expectedYield;
}

function isFlowerVarietySeasonLocked(name) {
  const season = FLOWER_SEEDS[FLOWER_VARIETIES[name].seed].season;
  return !!(season && season !== previewSeason);
}

function computeHiveStats(windowSec) {
  windowSec = windowSec || 86400;
  const active = getActiveBoostsForHive();
  let speed = 1, honeyPerFill = 1, swarmChance = .1, swarmChanceMult = 1;
  const haveSyncData = hasLimitedBoostSyncData();
  active.forEach(b => {
    const coverageFraction = getBoostCoverageFraction(b, windowSec, haveSyncData);
    if (b.speedAdd) speed += b.speedAdd * coverageFraction;
    if (b.honeyYieldAdd) honeyPerFill += b.honeyYieldAdd * coverageFraction;
    if (b.swarmChanceMult) swarmChanceMult *= 1 + (b.swarmChanceMult - 1) * coverageFraction;
    if (b.swarmChanceAdd) swarmChance += b.swarmChanceAdd * coverageFraction;
  });
  swarmChance = Math.min(1, swarmChance * swarmChanceMult);
  const timeToFullSec = 86400 / speed;
  const honeyPerHiveDay = honeyPerFill * speed;
  return {
    speed: speed,
    honeyPerFill: honeyPerFill,
    timeToFullSec: timeToFullSec,
    honeyPerHiveDay: honeyPerHiveDay,
    swarmChance: swarmChance,
    activeBoosts: active
  };
}

function computeHiveEconomics(visited) {
  const hives = getHiveCount();
  const hiveStats = computeHiveStats();
  const flowerStats = computeBoostedFlowerVarietyStats(selectedHoneyFlower);
  const flowerCostCoins = getFlowerVarietyCostCoins(selectedHoneyFlower, visited);
  const flowerCostFlower = coinsToFlower(flowerCostCoins);
  const replantsPerDay = 86400 / flowerStats.timeVal;
  const costPerFlower = flowerCostFlower / flowerStats.expectedYield;
  const costPerHiveDay = replantsPerDay * costPerFlower;
  const honeyMarket = marketItems.find(x => (x.name || "").toLowerCase() === "honey");
  const honeySellFlower = honeyMarket ? honeyMarket.flowerPrice || 0 : 0;
  const netHoneySell = honeySellFlower * (1 - feePercent / 100);
  const revenuePerHiveDay = hiveStats.honeyPerHiveDay * netHoneySell;
  const grossRevenuePerHiveDay = hiveStats.honeyPerHiveDay * honeySellFlower;
  const SWARM_BASE_BONUS = .2;
  const cropPlots = getPlotCount();
  const cropData = BASE_CROPS[selectedSwarmCrop];
  const cropBoosted = cropData ? computeBoostedCropStats(selectedSwarmCrop, cropData.baseYield || 1, cropData.timeSec) : null;
  const cropMarket = marketItems.find(x => (x.name || "").toLowerCase() === (selectedSwarmCrop || "").toLowerCase());
  const cropSellFlowerGross = cropMarket ? cropMarket.flowerPrice || 0 : 0;
  const cropSellFlower = cropSellFlowerGross * (1 - feePercent / 100);
  const expectedSwarmsPerHiveDay = hiveStats.swarmChance * hiveStats.speed;
  const bonusCropYieldPerHiveDay = expectedSwarmsPerHiveDay * SWARM_BASE_BONUS * cropPlots;
  const bonusCropValuePerHiveDay = bonusCropYieldPerHiveDay * cropSellFlower;
  const bonusCropValueGrossPerHiveDay = bonusCropYieldPerHiveDay * cropSellFlowerGross;
  const bonusCropValuePerPlotPerHiveDay = cropPlots > 0 ? expectedSwarmsPerHiveDay * SWARM_BASE_BONUS * cropSellFlower : 0;
  const profitPerHiveDay = revenuePerHiveDay + bonusCropValuePerHiveDay - costPerHiveDay;
  const swarmTrialsPerDay = Math.max(0, Math.round(hives * hiveStats.speed));
  const p = hiveStats.swarmChance;
  const swarmDistribution = [];
  let coeff = 1;
  for (let k = 0; k <= swarmTrialsPerDay; k++) {
    const chance = coeff * Math.pow(p, k) * Math.pow(1 - p, swarmTrialsPerDay - k);
    const bonusCropYield = k * SWARM_BASE_BONUS * cropPlots;
    const flowerValue = bonusCropYield * cropSellFlower;
    swarmDistribution.push({
      k: k,
      chance: chance,
      bonusCropYield: bonusCropYield,
      flowerValue: flowerValue
    });
    coeff = coeff * (swarmTrialsPerDay - k) / (k + 1);
  }
  return {
    hives: hives,
    hiveStats: hiveStats,
    flowerStats: flowerStats,
    flowerCostFlower: flowerCostFlower,
    costPerFlower: costPerFlower,
    replantsPerDay: replantsPerDay,
    costPerHiveDay: costPerHiveDay,
    honeySellFlower: honeySellFlower,
    netHoneySell: netHoneySell,
    revenuePerHiveDay: revenuePerHiveDay,
    grossRevenuePerHiveDay: grossRevenuePerHiveDay,
    expectedSwarmsPerHiveDay: expectedSwarmsPerHiveDay,
    bonusCropYieldPerHiveDay: bonusCropYieldPerHiveDay,
    bonusCropValuePerHiveDay: bonusCropValuePerHiveDay,
    bonusCropValueGrossPerHiveDay: bonusCropValueGrossPerHiveDay,
    bonusCropValuePerPlotPerHiveDay: bonusCropValuePerPlotPerHiveDay,
    cropPlots: cropPlots,
    cropSellFlower: cropSellFlower,
    cropSellFlowerGross: cropSellFlowerGross,
    swarmTrialsPerDay: swarmTrialsPerDay,
    swarmDistribution: swarmDistribution,
    profitPerHiveDay: profitPerHiveDay,
    totalCostDay: costPerHiveDay * hives,
    totalRevenueDay: (revenuePerHiveDay + bonusCropValuePerHiveDay) * hives,
    totalRevenueGrossDay: (grossRevenuePerHiveDay + bonusCropValueGrossPerHiveDay) * hives,
    totalProfitDay: profitPerHiveDay * hives
  };
}

function computeResourceFigures(name, visited) {
  const data = RESOURCE_DATA[name];
  if (!data) return null;
  const boosted = computeBoostedResourceStats(name, data.yieldPer, data.timeSec);
  let materialsCost = 0;
  const breakdown = data.materials.map(mat => {
    const swap = boosted.materialSwaps.find(s => s.from.toLowerCase() === mat.name.toLowerCase());
    const matName = swap ? swap.to : mat.name;
    const matQty = swap ? swap.qty : mat.qty;
    const mode = getMaterialMode(name, matName);
    const unitCost = boosted.noToolNeeded ? 0 : getMaterialUnitCostCoins(matName, mode, visited);
    const lineCost = unitCost * matQty;
    materialsCost += lineCost;
    return {
      name: matName,
      qty: matQty,
      unitCost: unitCost,
      lineCost: lineCost,
      mode: mode
    };
  });
  const toolCoinCostMult = (typeof getActiveBoostsForTool === "function" ? getActiveBoostsForTool(data.tool).reduce((m, b) => b.coinCostMult ? m * b.coinCostMult : m, 1) : 1) * getArtistCoinCostMult();
  const toolCost = boosted.noToolNeeded ? 0 : (data.toolCoinCost || 0) * boosted.toolCostMult * toolCoinCostMult;
  const totalToolCost = materialsCost + toolCost;
  const costPerUnit = totalToolCost / boosted.yieldVal;
  const nodeCount = getNodeCount(name);
  const toolUsageTotal = getResourceToolUsageTotal(name);
  const totalYieldPerCycle = getResourceTieredYieldTotal(name, boosted.yieldVal, boosted.perTierYield);
  return {
    costPerUnit: costPerUnit,
    totalToolCost: totalToolCost,
    yieldPer: boosted.yieldVal,
    timeSec: boosted.timeVal,
    tool: data.tool,
    breakdown: breakdown,
    activeBoosts: boosted.activeBoosts,
    nodeCount: nodeCount,
    toolUsageTotal: toolUsageTotal,
    totalYieldPerCycle: totalYieldPerCycle,
    perTierYield: boosted.perTierYield
  };
}

function getActiveBoostsForLavaPit() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "resources" && b.scope === "lavaPit");
}

function computeBoostedLavaPitStatsUncached(baseTimeSec) {
  const active = getActiveBoostsForLavaPit();
  let yieldAddSum = 0, timeVal = baseTimeSec, qtyMult = 1;
  active.forEach(b => {
    if (b.yieldAdd) yieldAddSum += b.yieldAdd;
    if (b.timeMult) timeVal *= b.timeMult;
    if (b.materialQtyMult) qtyMult *= b.materialQtyMult;
  });
  return {
    yieldVal: Math.max(1e-4, 1 + yieldAddSum),
    timeVal: Math.max(1, timeVal),
    qtyMult: qtyMult,
    activeBoosts: active
  };
}

function computeLavaPitFigures(season) {
  season = season || previewSeason;
  const recipe = LAVA_PIT_RECIPES[season];
  const boosted = computeBoostedLavaPitStats(recipe.time);
  let materialsCost = 0;
  const breakdown = recipe.materials.map(mat => {
    const qty = mat.qty * boosted.qtyMult;
    const mode = getMaterialMode("Obsidian_" + season, mat.name);
    const unitCost = getMaterialUnitCostCoins(mat.name, mode);
    const lineCost = unitCost * qty;
    materialsCost += lineCost;
    return {
      name: mat.name,
      qty: qty,
      unitCost: unitCost,
      lineCost: lineCost,
      mode: mode
    };
  });
  const costPerUnit = materialsCost / boosted.yieldVal;
  return {
    costPerUnit: costPerUnit,
    totalMaterialsCost: materialsCost,
    timeSec: boosted.timeVal,
    yieldVal: boosted.yieldVal,
    breakdown: breakdown,
    activeBoosts: boosted.activeBoosts,
    season: season
  };
}

const OBSIDIAN_WEEKLY_SELL_CAP = 1;
const OBSIDIAN_WEEKLY_PURCHASE_CAP = 5;

const OBSIDIAN_WEEK_SEC = 7 * 24 * 60 * 60;

function computeObsidianWeeklyProduction(fig, manualCyclesPerWeek) {
  const nodeCount = getNodeCount("Lava Pit");
  const autoCyclesPerWeek = OBSIDIAN_WEEK_SEC / fig.timeSec;
  const cyclesPerWeek = manualCyclesPerWeek != null && manualCyclesPerWeek >= 0 ? manualCyclesPerWeek : autoCyclesPerWeek;
  return {
    produced: cyclesPerWeek * nodeCount * fig.yieldVal,
    cyclesPerWeek: cyclesPerWeek,
    autoCyclesPerWeek: autoCyclesPerWeek
  };
}

function computeObsidianWeeklyProfit(fig, sellFlower, manualCyclesPerWeek) {
  const netSellFlower = sellFlower * (1 - feePercent / 100);
  const prod = computeObsidianWeeklyProduction(fig, manualCyclesPerWeek);
  const produced = prod.produced;
  const sellable = Math.min(produced, OBSIDIAN_WEEKLY_SELL_CAP);
  const costFlower = coinsToFlower(fig.costPerUnit);
  const revenue = sellable * netSellFlower;
  const cost = sellable * costFlower;
  return {
    produced: produced,
    sellable: sellable,
    revenue: revenue,
    cost: cost,
    profit: revenue - cost,
    netSellFlower: netSellFlower,
    costFlower: costFlower,
    cyclesPerWeek: prod.cyclesPerWeek,
    autoCyclesPerWeek: prod.autoCyclesPerWeek
  };
}

