let ascensionRanks = safeLSJSON(localStorage.getItem("hl_ascension_ranks"), {});

let syncedSkillLevels = safeLSJSON(localStorage.getItem("hl_synced_skill_levels"), {});

function saveSyncedSkillLevels() {
  localStorage.setItem("hl_synced_skill_levels", JSON.stringify(syncedSkillLevels));
}

function saveAscensionState() {
  localStorage.setItem("hl_ascension_ranks", JSON.stringify(ascensionRanks));
}

function ascensionGetPath(obj, path) {
  return path.split(".").reduce((o, k) => o == null ? undefined : o[k], obj);
}

function ascensionSetPath(obj, path, val) {
  const parts = path.split(".");
  const last = parts.pop();
  let node = obj;
  parts.forEach(k => {
    if (node[k] === undefined) node[k] = {};
    node = node[k];
  });
  node[last] = val;
}

function getAscensionRank(id) {
  return ascensionRanks[id] || 1;
}

function setAscensionRank(id, rank) {
  if (rank <= 1) delete ascensionRanks[id]; else ascensionRanks[id] = rank;
  saveAscensionState();
  applyAscensionRanks();
  refreshAfterSkillChange();
}

function applyAscensionRanks() {
  Object.keys(ASCENSION_RANK_DATA).forEach(id => {
    const data = ASCENSION_RANK_DATA[id];
    const owned = isSkillActive(id);
    const rank = getAscensionRank(id);
    SKILL_BOOSTS.filter(s => s.id === id).forEach(entry => {
      if (!entry._ascBase) entry._ascBase = {};
      if (data.byTarget) {
        const f = data.field;
        if (!f) return;
        const valuesForTarget = data.values[entry.target];
        if (!valuesForTarget) return;
        if (entry._ascBase[f] === undefined) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, valuesForTarget[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (data.byScope) {
        const cfg = data.byScope[entry.scope];
        if (!cfg) return;
        const f = cfg.field;
        if (entry._ascBase[f] === undefined) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, cfg.values[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (data.byRole) {
        const cfg = data.byRole[entry._ascRole];
        if (!cfg) return;
        const f = cfg.field;
        if (entry._ascBase[f] === undefined) entry._ascBase[f] = ascensionGetPath(entry, f);
        if (owned) {
          ascensionSetPath(entry, f, cfg.values[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
        return;
      }
      if (!data.field) return;
      const fields = Array.isArray(data.field) ? data.field : [ data.field ];
      fields.forEach(f => {
        if (entry._ascBase[f] === undefined) entry._ascBase[f] = ascensionGetPath(entry, f);
        const valuesForField = Array.isArray(data.values) ? data.values : data.values[f];
        if (!valuesForField) return;
        if (owned) {
          ascensionSetPath(entry, f, valuesForField[rank - 1]);
        } else {
          ascensionSetPath(entry, f, entry._ascBase[f]);
        }
      });
    });
  });
}

function getAscensionTotals() {
  let points = 0, shards = 0;
  Object.keys(ASCENSION_RANK_DATA).forEach(id => {
    if (!isSkillActive(id)) return;
    const rank = getAscensionRank(id);
    if (rank <= 1) return;
    const skill = SKILL_BOOSTS.find(s => s.id === id);
    const cost = ASCENSION_UPGRADE_COST[skill && skill.skillTier || 1];
    const steps = rank - 1;
    points += cost.points * steps;
    shards += cost.shards * steps;
  });
  return {
    points: points,
    shards: shards
  };
}

function skillAoeNoteForRank(s, rank) {
  if (!s.aoeSizeByRank || !s.note) return s.note || "";
  const size = s.aoeSizeByRank[Math.min(Math.max(rank, 1), 3) - 1];
  const plots = size * size;
  return s.note.replace(/\d+x\d+ \(\d+ plots\)/, `${size}x${size} (${plots} plots)`);
}

function ascensionDescribeRank(id, rank) {
  const data = ASCENSION_RANK_DATA[id];
  if (!data) return "";
  let primaryValues;
  if (data.byScope) {
    const firstKey = Object.keys(data.byScope)[0];
    primaryValues = data.byScope[firstKey].values;
  } else if (data.byRole) {
    const firstKey = Object.keys(data.byRole)[0];
    primaryValues = data.byRole[firstKey].values;
  } else if (data.byTarget) {
    primaryValues = data.values[Object.keys(data.values)[0]];
  } else {
    primaryValues = Array.isArray(data.values) ? data.values : data.values[Object.keys(data.values)[0]];
  }
  const v = primaryValues[rank - 1];
  const unit = data.unit || "";
  const display = unit === "%" ? `${v}%` : unit === "×" ? `×${v}` : unit === "d" ? `${v}d` : unit === "h" ? `${v}h` : v > 0 ? `+${v}` : `${v}`;
  return `Rank ${[ "I", "II", "III" ][rank - 1]}: ${display}${data.note ? ` · ${data.note}` : ""}`;
}

function renderAscensionBar() {
  const totalsEl = $("ascensionTotals");
  if (!totalsEl) return;
  const {points: ascPoints, shards: ascShards} = getDraftAscensionTotals();
  const skillPoints = getDraftSkillPointsUsed();
  const skillPointsEl = $("skillPointsUsed");
  const ascPointsEl = $("ascensionPointsUsed");
  const ascShardsEl = $("ascensionShardsUsed");
  if (skillPointsEl) skillPointsEl.textContent = skillPoints;
  if (ascPointsEl) ascPointsEl.textContent = ascPoints;
  if (ascShardsEl) ascShardsEl.textContent = ascShards;
}

