function computeBudCropEffects(typeId, stemId, auraId) {
  const type = BUD_GREENHOUSE_TYPES.find(t => t.id === typeId) || BUD_GREENHOUSE_TYPES[0];
  const stem = BUD_GREENHOUSE_STEMS.find(s => s.id === stemId) || BUD_GREENHOUSE_STEMS[0];
  const aura = BUD_AURAS.find(a => a.id === auraId) || BUD_AURAS[0];
  const result = {};
  function addComponent(comp) {
    if (!comp || !comp.effects) return;
    comp.effects.forEach(eff => {
      eff.targets.forEach(crop => {
        if (!result[crop]) result[crop] = {
          yieldAdd: 0,
          timePct: 0
        };
        if (eff.yieldAdd) result[crop].yieldAdd += eff.yieldAdd * aura.mult;
        if (eff.timePct) result[crop].timePct += eff.timePct * aura.mult;
      });
    });
  }
  addComponent(type);
  addComponent(stem);
  Object.keys(result).forEach(crop => {
    if (result[crop].timePct > .95) result[crop].timePct = .95;
  });
  return result;
}

function budSummaryText(typeId, stemId, auraId) {
  const effects = computeBudCropEffects(typeId, stemId, auraId);
  const groups = {};
  Object.keys(effects).forEach(crop => {
    const e = effects[crop];
    if (!e.yieldAdd && !e.timePct) return;
    const key = e.timePct.toFixed(4) + "|" + e.yieldAdd.toFixed(4);
    if (!groups[key]) groups[key] = {
      timePct: e.timePct,
      yieldAdd: e.yieldAdd,
      crops: []
    };
    groups[key].crops.push(crop);
  });
  const parts = [];
  Object.values(groups).forEach(g => {
    const cropLabel = g.crops.join("/");
    if (g.timePct) parts.push(`-${Math.round(g.timePct * 100)}% time ${cropLabel}`);
    if (g.yieldAdd) parts.push(`+${fmt(g.yieldAdd)} ${cropLabel}`);
  });
  return parts.length ? parts.join(", ") : "No Greenhouse bonus";
}

function buildBudBoostEntries(budUID, typeId, stemId, auraId) {
  const effects = computeBudCropEffects(typeId, stemId, auraId);
  const name = budDisplayName(typeId, stemId, auraId);
  const entries = [];
  Object.keys(effects).forEach(crop => {
    const e = effects[crop];
    if (!e.yieldAdd && !e.timePct) return;
    const entry = {
      id: budUID + "_" + crop,
      name: name,
      category: "greenhouse",
      scope: "greenhouse",
      target: crop,
      custom: true,
      isBud: true,
      budId: budUID
    };
    if (e.yieldAdd) entry.yieldAdd = Math.round(e.yieldAdd * 1e4) / 1e4;
    if (e.timePct) entry.timeMult = Math.round((1 - e.timePct) * 1e4) / 1e4;
    entries.push(entry);
  });
  return entries;
}

function budDisplayName(typeId, stemId, auraId) {
  const typeName = (BUD_GREENHOUSE_TYPES.find(t => t.id === typeId) || {}).name || "None";
  const stemName = (BUD_GREENHOUSE_STEMS.find(s => s.id === stemId) || {}).name || "None";
  const auraName = (BUD_AURAS.find(a => a.id === auraId) || {}).name || "No Aura";
  return `BUD (${typeName} · ${stemName} · ${auraName})`;
}

