let spiceUsage = function() {
  const dflt = {
    saltLick: {
      active: false,
      chicken: false,
      sheep: false,
      cow: false
    },
    honeyTreat: {
      active: false,
      chicken: false,
      sheep: false,
      cow: false
    }
  };
  try {
    const saved = safeLSJSON(localStorage.getItem("hl_spice_usage"), null);
    if (!saved) return dflt;
    return {
      saltLick: {
        ...dflt.saltLick,
        ...saved.saltLick
      },
      honeyTreat: {
        ...dflt.honeyTreat,
        ...saved.honeyTreat
      }
    };
  } catch (e) {
    return dflt;
  }
}();

function saveSpiceUsage() {
  localStorage.setItem("hl_spice_usage", JSON.stringify(spiceUsage));
}

const SPICE_ANIMAL_TYPES = [ "chicken", "sheep", "cow" ];

function toggleSpiceMaster(key) {
  spiceUsage[key].active = !spiceUsage[key].active;
  saveSpiceUsage();
  refreshAfterSpiceChange();
}

function toggleSpiceAnimal(key, type) {
  const turningOn = !spiceUsage[key][type];
  if (turningOn) {
    const other = key === "saltLick" ? "honeyTreat" : "saltLick";
    if (spiceUsage[other][type]) {
      spiceUsage[other][type] = false;
      toast(`🧂 ${type[0].toUpperCase() + type.slice(1)} can only take one consumable at a time — switched off ${other === "saltLick" ? "Salt Lick" : "Honey Treat"} for ${type}`);
    }
  }
  spiceUsage[key][type] = turningOn;
  saveSpiceUsage();
  refreshAfterSpiceChange();
}

function refreshAfterSpiceChange() {
  setTimeout(() => {
    renderBoostPanel();
    renderAnimalsList();
    updateCalcSummary();
  }, 0);
}

function getSpiceCostPerUseFlower(key) {
  return key === "saltLick" ? refinedSaltUnitCostFlower() : refinedSaltUnitCostFlower() + honeyCostFlowerForSpiceRack();
}

function getSpiceEffectForAnimalType(type) {
  let yieldMultAll = 1, feedMultAll = 1, costFlowerPerCyclePerAnimal = 0, activeKey = null;
  const durationHarvests = getSpiceLickDurationHarvests();
  if (spiceUsage.saltLick.active && spiceUsage.saltLick[type]) {
    yieldMultAll = 1.05;
    costFlowerPerCyclePerAnimal = getSpiceCostPerUseFlower("saltLick") / durationHarvests;
    activeKey = "saltLick";
  } else if (spiceUsage.honeyTreat.active && spiceUsage.honeyTreat[type]) {
    feedMultAll = .75;
    costFlowerPerCyclePerAnimal = getSpiceCostPerUseFlower("honeyTreat") / durationHarvests;
    activeKey = "honeyTreat";
  }
  return {
    yieldMultAll: yieldMultAll,
    feedMultAll: feedMultAll,
    costFlowerPerCyclePerAnimal: costFlowerPerCyclePerAnimal,
    activeKey: activeKey
  };
}

function getSpiceHeadCost(key, type) {
  const qty = getAnimalCount(type).qty || 0;
  return getSpiceCostPerUseFlower(key) / getSpiceLickDurationHarvests() * qty;
}

