const SKILL_TREE_TIER_THRESHOLDS = {
  crops: {
    2: 3,
    3: 7
  },
  trees: {
    2: 2,
    3: 5
  },
  fishing: {
    2: 2,
    3: 5
  },
  mining: {
    2: 3,
    3: 7
  },
  cooking: {
    2: 2,
    3: 5
  },
  fruitpatch: {
    2: 2,
    3: 5
  },
  animals: {
    2: 4,
    3: 8
  },
  bees: {
    2: 2,
    3: 5
  },
  greenhouse: {
    2: 2,
    3: 5
  },
  machine: {
    2: 2,
    3: 5
  },
  compost: {
    2: 3,
    3: 7
  },
  aging: {
    2: 3,
    3: 7
  }
};

function getTreeUsedSkillPoints(ownedIds, category) {
  const seen = new Set();
  let points = 0;
  ownedIds.forEach(id => {
    if (seen.has(id)) return;
    seen.add(id);
    const skill = SKILL_BOOSTS.find(s => s.id === id);
    if (!skill || skill.skillCategory !== category) return;
    if (skill.skillTier === 3) return;
    points += skill.skillTier;
  });
  return points;
}

function getUnlockedTierForCategory(ownedIds, category) {
  const thresholds = SKILL_TREE_TIER_THRESHOLDS[category];
  if (!thresholds) return 1;
  const points = getTreeUsedSkillPoints(ownedIds, category);
  if (points >= thresholds[3]) return 3;
  if (points >= thresholds[2]) return 2;
  return 1;
}

function isSkillTierUnlocked(category, tier) {
  if (tier <= 1) return true;
  return getUnlockedTierForCategory(selectedSkills, category) >= tier;
}

let skillDraftSelectedSkills = selectedSkills.slice();

let skillDraftAscensionRanks = Object.assign({}, ascensionRanks);

function isSkillDraftActive(id) {
  return skillDraftSelectedSkills.includes(id);
}

function isSkillDraftTierUnlocked(category, tier) {
  if (tier <= 1) return true;
  return getUnlockedTierForCategory(skillDraftSelectedSkills, category) >= tier;
}

function getDraftAscensionRank(id) {
  return skillDraftAscensionRanks[id] || 1;
}

function getDraftAscensionTotals() {
  let points = 0, shards = 0;
  Object.keys(ASCENSION_RANK_DATA).forEach(id => {
    if (!isSkillDraftActive(id)) return;
    const rank = getDraftAscensionRank(id);
    if (rank <= 1) return;
    const skill = SKILL_BOOSTS.find(s => s.id === id);
    const cost = ASCENSION_UPGRADE_COST[skill && skill.skillTier || 1];
    const steps = rank - 1;
    points += cost.points * steps;
    shards += cost.shards * steps;
  });
  return {
    points: points,
    shards: shards
  };
}

function getDraftSkillPointsUsed() {
  const seen = new Set();
  let points = 0;
  skillDraftSelectedSkills.forEach(id => {
    if (seen.has(id)) return;
    seen.add(id);
    const skill = SKILL_BOOSTS.find(s => s.id === id);
    if (!skill || !skill.skillTier) return;
    points += skill.skillTier;
  });
  return points;
}

function resetSkillDraftFromSaved() {
  skillDraftSelectedSkills = selectedSkills.slice();
  skillDraftAscensionRanks = Object.assign({}, ascensionRanks);
  if (typeof renderSkillPanel === "function") renderSkillPanel();
  if (typeof renderAscensionBar === "function") renderAscensionBar();
  updateSkillSaveBarState();
}

function isSkillDraftDirty() {
  const a = selectedSkills.slice().sort();
  const b = skillDraftSelectedSkills.slice().sort();
  if (JSON.stringify(a) !== JSON.stringify(b)) return true;
  if (JSON.stringify(ascensionRanks) !== JSON.stringify(skillDraftAscensionRanks)) return true;
  return false;
}

function updateSkillSaveBarState() {
  const bar = $("skillSaveBar");
  if (!bar) return;
  const dirty = isSkillDraftDirty() || isBoostDraftDirty();
  bar.classList.toggle("dirty", dirty);
  const note = $("skillSaveNote");
  if (note) note.style.display = dirty ? "" : "none";
  const btn = $("skillSaveBtn");
  if (btn && !btn.classList.contains("saving")) {
    btn.disabled = !dirty;
  }
}

function tierUnlockHintText(category, tier, ownedIds) {
  const thresholds = SKILL_TREE_TIER_THRESHOLDS[category];
  if (!thresholds || tier <= 1) return "";
  const need = thresholds[tier];
  const have = getTreeUsedSkillPoints(ownedIds, category);
  return `${have}/${need} skill points invested in ${category} (Tier 1 & 2 skills)`;
}

function draftToggleSkill(id) {
  const skill = SKILL_BOOSTS.find(s => s.id === id);
  if (!skill) return;
  if (!isSkillDraftActive(id) && !isSkillDraftTierUnlocked(skill.skillCategory, skill.skillTier)) {
    toast(`🔒 Need Tier ${skill.skillTier} unlocked — ${tierUnlockHintText(skill.skillCategory, skill.skillTier, skillDraftSelectedSkills)}`);
    return;
  }
  if (isSkillDraftActive(id)) {
    skillDraftSelectedSkills = skillDraftSelectedSkills.filter(x => x !== id);
  } else {
    if (skill.group) {
      const groupIds = SKILL_BOOSTS.filter(s => s.group === skill.group).map(s => s.id);
      skillDraftSelectedSkills = skillDraftSelectedSkills.filter(x => !groupIds.includes(x));
    }
    skillDraftSelectedSkills.push(id);
  }
  renderSkillPanel();
  renderAscensionBar();
  updateSkillSaveBarState();
}

function getSkillUpgradeTierRequirement(tier, currentRank) {
  return Math.min(3, tier + currentRank);
}

function draftSetAscensionRank(id, rank) {
  const skill = SKILL_BOOSTS.find(s => s.id === id);
  if (rank > 1 && skill) {
    const requiredTier = getSkillUpgradeTierRequirement(skill.skillTier, rank - 1);
    if (!isSkillDraftTierUnlocked(skill.skillCategory, requiredTier)) {
      toast(`🔒 Rank ${rank} needs Tier ${requiredTier} unlocked — ${tierUnlockHintText(skill.skillCategory, requiredTier, skillDraftSelectedSkills)}`);
      return;
    }
  }
  if (rank <= 1) delete skillDraftAscensionRanks[id]; else skillDraftAscensionRanks[id] = rank;
  renderSkillPanel();
  renderAscensionBar();
  updateSkillSaveBarState();
}

function commitSkillDraft() {
  const btn = $("skillSaveBtn");
  if (!btn || btn.classList.contains("saving")) return;
  if (!isSkillDraftDirty() && !isBoostDraftDirty()) return;
  btn.classList.add("saving");
  btn.classList.remove("saved");
  btn.disabled = true;
  btn.innerHTML = `<span class="skill-save-spinner"></span> Saving…`;
  setTimeout(() => {
    selectedSkills = skillDraftSelectedSkills.slice();
    saveSkillState();
    ascensionRanks = Object.assign({}, skillDraftAscensionRanks);
    saveAscensionState();
    applyAscensionRanks();
    applySkillModifiers();
    selectedBoosts = boostDraftSelectedBoosts.slice();
    saveBoostState();
    if (typeof invalidateCostCache === "function") invalidateCostCache();
    refreshAfterSkillChange();
    renderAscensionBar();
    renderSkillPanel();
    btn.classList.remove("saving");
    btn.classList.add("saved");
    btn.innerHTML = "✅ Saved";
    updateSkillSaveBarState();
    setTimeout(() => {
      btn.classList.remove("saved");
      btn.innerHTML = "💾 Save Changes";
      updateSkillSaveBarState();
    }, 900);
  }, 400);
}

function refreshAfterSkillChange() {
  if (typeof invalidateCostCache === "function") invalidateCostCache();
  renderBoostPanel();
  renderSkillPanel();
  renderAscensionBar();
  renderLibraryLists();
  renderMarketList();
  renderResourceList();
  renderHoneyList();
  renderAnimalsList();
  renderMedicineCostDisplay();
  renderCropMachinePanel();
  if (typeof renderComposterList === "function") renderComposterList();
  if (typeof renderSaltList === "function") renderSaltList();
  if (typeof renderBettyShop === "function") renderBettyShop();
  if (typeof renderFarmPanelTabContent === "function") renderFarmPanelTabContent();
  if (typeof renderCookingPanel === "function") renderCookingPanel();
  if (typeof renderFishingPanel === "function") renderFishingPanel();
  if (typeof renderPetsPanel === "function") renderPetsPanel();
  updateCalcSummary();
}

let _cascadeScheduled = false;

let _cascadeFn = null;

function scheduleCascade(fn) {
  _cascadeFn = fn;
  if (_cascadeScheduled) return;
  _cascadeScheduled = true;
  const runner = () => {
    _cascadeScheduled = false;
    const toRun = _cascadeFn;
    _cascadeFn = null;
    if (toRun) toRun();
  };
  if (typeof requestIdleCallback === "function") {
    requestIdleCallback(runner, {
      timeout: 120
    });
  } else {
    setTimeout(runner, 0);
  }
}

function applySkillModifiers() {
  SKILL_BOOSTS.filter(s => s.modifiesId).forEach(s => {
    const target = BOOSTS.find(b => b.id === s.modifiesId);
    if (!target) return;
    if (target._baseAoE === undefined) target._baseAoE = target.plotCap;
    if (target._baseTimeMult === undefined) target._baseTimeMult = target.timeMult;
    if (target._baseYieldAdd === undefined) target._baseYieldAdd = target.yieldAdd;
    if (target._baseHarvestAdd === undefined) target._baseHarvestAdd = target.harvestAdd;
    const active = isSkillActive(s.id);
    let rankPlotCap = s.aoePlotCap;
    let ascensionAoeApplied = false;
    if (active && s.aoeSizeByRank) {
      const rank = getAscensionRank(s.id);
      if (rank > 1) {
        const size = s.aoeSizeByRank[Math.min(Math.max(rank, 1), 3) - 1];
        rankPlotCap = size * size;
        ascensionAoeApplied = true;
      }
    }
    target.plotCap = active && rankPlotCap ? rankPlotCap : target._baseAoE;
    target._ascensionAoeApplied = ascensionAoeApplied;
    target.timeMult = active && s.overrideTimeMult ? s.overrideTimeMult : target._baseTimeMult;
    target.yieldAdd = active && s.extraYieldAdd ? +((target._baseYieldAdd || 0) + s.extraYieldAdd).toFixed(4) : target._baseYieldAdd;
    target.harvestAdd = active && s.extraHarvestAdd ? +((target._baseHarvestAdd || 0) + s.extraHarvestAdd).toFixed(4) : target._baseHarvestAdd;
  });
}

applySkillModifiers();

(function ensureBudsActive() {
  let changed = false;
  BOOSTS.filter(b => b.isBud).forEach(b => {
    if (!selectedBoosts.includes(b.id)) {
      selectedBoosts.push(b.id);
      changed = true;
    }
  });
  if (changed) localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
})();

(function dedupeExclusiveGroups() {
  const seenGroup = {};
  const keep = [];
  for (let i = selectedBoosts.length - 1; i >= 0; i--) {
    const id = selectedBoosts[i];
    const boost = BOOSTS.find(b => b.id === id);
    if (boost && boost.group) {
      if (seenGroup[boost.group]) continue;
      seenGroup[boost.group] = true;
    }
    keep.unshift(id);
  }
  if (keep.length !== selectedBoosts.length) {
    selectedBoosts = keep;
    localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
  }
})();

(function dedupeExclusivePairs() {
  const keep = [];
  const dropped = new Set;
  for (const id of selectedBoosts) {
    if (dropped.has(id)) continue;
    const boost = BOOSTS.find(b => b.id === id);
    const exList = boost && boost.exclusiveWith ? Array.isArray(boost.exclusiveWith) ? boost.exclusiveWith : [ boost.exclusiveWith ] : [];
    if (exList.some(exId => keep.includes(exId))) {
      dropped.add(id);
      continue;
    }
    keep.push(id);
  }
  if (keep.length !== selectedBoosts.length) {
    selectedBoosts = keep;
    localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
  }
})();

function saveBoostState() {
  localStorage.setItem("hl_selected_boosts", JSON.stringify(selectedBoosts));
  if (typeof boostDraftSelectedBoosts !== "undefined") {
    boostDraftSelectedBoosts = selectedBoosts.slice();
    if (typeof updateBoostSaveBarState === "function") updateBoostSaveBarState();
  }
}

let fertilizerTierScope = safeLSJSON(localStorage.getItem("hl_fert_tier_scope"), [ "Medium", "Advanced" ]);

function saveFertilizerTierScope() {
  localStorage.setItem("hl_fert_tier_scope", JSON.stringify(fertilizerTierScope));
}

function isFertilizerTierEnabled(tier) {
  return fertilizerTierScope.includes(tier);
}

function toggleFertilizerTier(tier) {
  const idx = fertilizerTierScope.indexOf(tier);
  if (idx >= 0) {
    if (fertilizerTierScope.length === 1) {
      toast("At least one tier has to stay checked — Sprout Mix / Rapid Root need somewhere to apply.");
      return;
    }
    fertilizerTierScope.splice(idx, 1);
  } else {
    fertilizerTierScope.push(tier);
  }
  saveFertilizerTierScope();
  setTimeout(() => {
    renderBoostPanel();
    renderLibraryLists();
    renderMarketList();
    renderCropMachinePanel();
    updateCalcSummary();
  }, 0);
}

function isSeasonLocked(boost) {
  if (!boost) return false;
  if (boost.seasons && boost.seasons.length) return !boost.seasons.includes(previewSeason);
  return !!(boost.season && boost.season !== previewSeason);
}

function isBoostActive(id) {
  if (id === "gnome" && farmPanelGameState && !farmPanelGnomeComboPresent()) return false;
  if (ALWAYS_ON_BOOST_IDS.has(id)) return true;
  if (id === "bee_swarm") return beeSwarmActiveCount > 0;
  if (!selectedSkills.includes(id) && !selectedBoosts.includes(id)) return false;
  const boost = BOOSTS.find(b => b.id === id);
  if (boost && boost.source === "skill") {
    if (!selectedSkills.includes(id)) return false;
    if (isSeasonLocked(boost)) return false;
    return true;
  }
  if (!selectedBoosts.includes(id)) return false;
  if (isSeasonLocked(boost)) return false;
  return true;
}

let boostDraftSelectedBoosts = selectedBoosts.slice();

function isBoostDraftActive(id) {
  if (id === "gnome" && farmPanelGameState && !farmPanelGnomeComboPresent()) return false;
  if (ALWAYS_ON_BOOST_IDS.has(id)) return true;
  if (id === "bee_swarm") return beeSwarmActiveCount > 0;
  if (!selectedSkills.includes(id) && !boostDraftSelectedBoosts.includes(id)) return false;
  const boost = BOOSTS.find(b => b.id === id);
  if (boost && boost.source === "skill") {
    if (!selectedSkills.includes(id)) return false;
    if (isSeasonLocked(boost)) return false;
    return true;
  }
  if (!boostDraftSelectedBoosts.includes(id)) return false;
  if (isSeasonLocked(boost)) return false;
  return true;
}

function resetBoostDraftFromSaved() {
  boostDraftSelectedBoosts = selectedBoosts.slice();
  if (typeof renderBoostPanel === "function") renderBoostPanel();
  updateBoostSaveBarState();
}

function isBoostDraftDirty() {
  const a = selectedBoosts.slice().sort();
  const b = boostDraftSelectedBoosts.slice().sort();
  return JSON.stringify(a) !== JSON.stringify(b);
}

function updateBoostSaveBarState() {
  updateSkillSaveBarState();
}

function draftToggleBoost(id) {
  const boost = BOOSTS.find(b => b.id === id);
  if (id === "bee_swarm") {
    const perSwarm = getBeeSwarmPerSwarmYield();
    toast(beeSwarmActiveCount > 0 ? `🐝 Bee Swarm is auto-detected from your synced farm — ${beeSwarmActiveCount} active swarm${beeSwarmActiveCount === 1 ? "" : "s"} across ${beeSwarmAffectedPlots} plot${beeSwarmAffectedPlots === 1 ? "" : "s"} (+${fmt(perSwarm)} yield each) right now. It can't be toggled manually.` : `🐝 Bee Swarm turns on automatically when your synced farm has an active swarm — none detected right now.`);
    return;
  }
  if (boost && boost.isDebuff) {
    const remSec = getLimitedBoostRemainingSec(boost.limitedBoostName);
    toast(remSec > 0 ? `⚠️ ${boost.name} is auto-detected from your synced farm — active now, ${formatDuration(remSec)} remaining. It can't be toggled manually.` : `⚠️ ${boost.name} turns on automatically when your synced farm has it active — not detected right now. It can't be toggled manually.`);
    return;
  }
  if (ALWAYS_ON_BOOST_IDS.has(id)) {
    toast(`✅ ${boost ? boost.name : "This"} is a game default every player has — it's always on and can't be switched off`);
    return;
  }
  if (isSeasonLocked(boost)) {
    const seasonLabel = boost.seasons && boost.seasons.length ? boost.seasons.join(" & ") : boost.season;
    toast(`🔒 ${boost.name} only works in ${seasonLabel} — switch the season toggle above to turn it on`);
    return;
  }
  if (!isBoostDraftActive(id) && !hasPlotsNodesData()) {
    const missing = getMissingPlotNodeFields();
    let msg;
    if (missing.length === 1) {
      msg = `🧮 Fill in ${missing[0]} in Plots & Nodes first — then you can turn on boosts`;
    } else {
      const hasCropPlots = missing.includes("🌾 Crop plots");
      const resourceCount = missing.length - (hasCropPlots ? 1 : 0);
      const parts = [];
      if (hasCropPlots) parts.push("Crop plots");
      if (resourceCount > 0) parts.push(`${resourceCount} resource node count${resourceCount > 1 ? "s" : ""}`);
      msg = `🧮 Fill in ${parts.join(" and ")} in Plots & Nodes first — then you can turn on boosts`;
    }
    toast(msg);
    const plotsPanel = $("plotsPanel");
    if (plotsPanel) plotsPanel.classList.add("open");
    const cropInput = $("globalCropPlotInput");
    if (cropInput) {
      cropInput.scrollIntoView({
        behavior: "smooth",
        block: "center"
      });
      cropInput.focus();
    }
    renderBoostPanel();
    return;
  }
  if (isBoostDraftActive(id)) {
    boostDraftSelectedBoosts = boostDraftSelectedBoosts.filter(x => x !== id);
  } else {
    if (boost && boost.group) {
      const groupIds = BOOSTS.filter(b => b.group === boost.group).map(b => b.id);
      boostDraftSelectedBoosts = boostDraftSelectedBoosts.filter(x => !groupIds.includes(x));
    }
    if (boost && boost.exclusiveWith) {
      const exList = Array.isArray(boost.exclusiveWith) ? boost.exclusiveWith : [ boost.exclusiveWith ];
      exList.forEach(exId => {
        if (isBoostDraftActive(exId)) {
          const other = BOOSTS.find(b => b.id === exId);
          boostDraftSelectedBoosts = boostDraftSelectedBoosts.filter(x => x !== exId);
          if (other) toast(`${other.name} disabled — can't be active with ${boost.name} 🦀`);
        }
      });
    }
    boostDraftSelectedBoosts.push(id);
  }
  if (boost && boost.limitedBoostName) {
    const turnedOn = boostDraftSelectedBoosts.includes(id);
    BOOSTS.filter(b => b.id !== id && b.limitedBoostName === boost.limitedBoostName).forEach(sib => {
      boostDraftSelectedBoosts = boostDraftSelectedBoosts.filter(x => x !== sib.id);
      if (turnedOn) boostDraftSelectedBoosts.push(sib.id);
    });
  }
  const nowActive = isBoostDraftActive(id);
  const tappedRow = document.querySelector(`[data-boost-id="${id}"]`);
  if (tappedRow) {
    tappedRow.style.outline = nowActive ? "2px solid var(--profit)" : "";
    tappedRow.classList.toggle("boost-active", nowActive);
    const iconEl = tappedRow.querySelector(".lib-item-icon");
    if (iconEl && !tappedRow.classList.contains("season-locked")) iconEl.textContent = nowActive ? "✅" : "⬜";
  }
  updateBoostSaveBarState();
}

function commitBoostDraft() {
  commitSkillDraft();
}

