function stripBoostSuffix(name) {
  return (name || "").replace(/\s*\([^)]*\)\s*$/, "").trim();
}

BOOSTS.forEach(b => {
  const bare = stripBoostSuffix(b.name);
  if (LIMITED_TIME_BOOSTS_BY_NAME[bare]) b.limitedBoostName = bare;
});

let limitedBoostActiveState = {};

let calendarDebuffProtection = {};

const CALENDAR_SEASONAL_BOOSTS = [ {
  name: "Sunshower",
  calendarKey: "sunshower",
  durationMs: 24 * 60 * 60 * 1e3
}, {
  name: "Bountiful Harvest",
  calendarKey: "bountifulHarvest",
  durationMs: 24 * 60 * 60 * 1e3
}, {
  name: "Insect Plague",
  calendarKey: "insectPlague",
  durationMs: 24 * 60 * 60 * 1e3,
  isDebuff: true
}, {
  name: "Tsunami",
  calendarKey: "tsunami",
  durationMs: 24 * 60 * 60 * 1e3,
  isDebuff: true
}, {
  name: "Tornado",
  calendarKey: "tornado",
  durationMs: 24 * 60 * 60 * 1e3,
  isDebuff: true
}, {
  name: "Great Freeze",
  calendarKey: "greatFreeze",
  durationMs: 24 * 60 * 60 * 1e3,
  isDebuff: true
} ];

function isCalendarSeasonalBoost(boost) {
  return !!(boost && boost.limitedBoostName && CALENDAR_SEASONAL_BOOSTS.some(e => e.name === boost.limitedBoostName));
}

function farmSyncGetCalendarBoostStatus(g, calendarKey, durationMs) {
  const now = Date.now();
  const cal = g && typeof g.calendar === "object" && g.calendar ? g.calendar : null;
  const entry = cal ? cal[calendarKey] : null;
  const startedAt = entry && typeof entry.startedAt === "number" ? entry.startedAt : null;
  const protectedFlag = !!(entry && entry.protected === true);
  if (startedAt == null) return {
    active: false,
    remainingMs: 0,
    protectedFlag: protectedFlag
  };
  const remainingMs = startedAt + durationMs - now;
  return {
    active: remainingMs > 0,
    remainingMs: Math.max(0, remainingMs),
    protectedFlag: protectedFlag
  };
}

function isDestructiveCalendarEventActive(calendar, key) {
  if (!calendar) return false;
  const entry = calendar[key];
  if (!entry) return false;
  if (entry.protected === true) return false;
  if (key === "tornado") {
    const startedAt = typeof entry.startedAt === "number" ? entry.startedAt : null;
    return startedAt != null && Date.now() - startedAt < 24 * 60 * 60 * 1e3;
  }
  return !!entry.triggeredAt;
}

function getActiveDestructiveWeatherEvent(calendar) {
  if (isDestructiveCalendarEventActive(calendar, "tornado")) return "tornado";
  if (isDestructiveCalendarEventActive(calendar, "tsunami")) return "tsunami";
  if (isDestructiveCalendarEventActive(calendar, "greatFreeze")) return "greatFreeze";
  return null;
}

function computeDestroyedCropPlotIds(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const cropsBag = asObj(farmPanelField(g, "crops")) || {};
  const calendar = asObj(g && g.calendar);
  const activeEvent = getActiveDestructiveWeatherEvent(calendar);
  if (!activeEvent) return {
    activeEvent: null,
    destroyedIds: new Set
  };
  const ids = Object.keys(cropsBag).sort((a, b) => {
    const ca = cropsBag[a] && typeof cropsBag[a].createdAt === "number" ? cropsBag[a].createdAt : 0;
    const cb = cropsBag[b] && typeof cropsBag[b].createdAt === "number" ? cropsBag[b].createdAt : 0;
    return ca - cb;
  });
  const destroyedCount = Math.floor(ids.length / 2);
  return {
    activeEvent: activeEvent,
    destroyedIds: new Set(ids.slice(0, destroyedCount))
  };
}

function syncWeatherDestructionFromFarmData(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const cropsBag = asObj(farmPanelField(g, "crops")) || {};
  const {activeEvent: activeEvent, destroyedIds: destroyedIds} = computeDestroyedCropPlotIds(g);
  const byCrop = {};
  Object.entries(cropsBag).forEach(([plotId, plot]) => {
    const cropName = plot && plot.crop && plot.crop.name;
    if (!cropName) return;
    if (!byCrop[cropName]) byCrop[cropName] = {
      total: 0,
      destroyed: 0
    };
    byCrop[cropName].total++;
    if (destroyedIds.has(plotId)) byCrop[cropName].destroyed++;
  });
  const prevSig = JSON.stringify({
    activeEvent: weatherDestructionSync.activeEvent,
    byCrop: weatherDestructionSync.byCrop
  });
  const nextSig = JSON.stringify({
    activeEvent: activeEvent,
    byCrop: byCrop
  });
  weatherDestructionSync = {
    activeEvent: activeEvent,
    byCrop: byCrop
  };
  saveWeatherDestructionSync();
  return {
    changed: prevSig !== nextSig,
    destroyedIds: destroyedIds
  };
}

function farmSyncRefreshLimitedBoostActiveState(g) {
  const state = {};
  const protection = {};
  const now = Date.now();
  LIMITED_TIME_BOOSTS.forEach(entry => {
    const status = farmSyncGetLimitedTimeBoostStatus(g, entry.name, entry.durationMs);
    state[entry.name] = {
      active: status.activeCount > 0,
      expiresAt: status.activeCount > 0 ? now + status.remainingMs : 0,
      durationMs: entry.durationMs
    };
  });
  CALENDAR_SEASONAL_BOOSTS.forEach(entry => {
    const status = farmSyncGetCalendarBoostStatus(g, entry.calendarKey, entry.durationMs);
    const suppressed = entry.isDebuff && status.protectedFlag;
    protection[entry.name] = status.protectedFlag;
    state[entry.name] = {
      active: status.active && !suppressed,
      expiresAt: status.active && !suppressed ? now + status.remainingMs : 0,
      durationMs: entry.durationMs
    };
  });
  limitedBoostActiveState = state;
  calendarDebuffProtection = protection;
  return state;
}

function hasLimitedBoostSyncData() {
  return Object.keys(limitedBoostActiveState).length > 0;
}

function getLimitedBoostRemainingSec(bareName) {
  const st = limitedBoostActiveState[bareName];
  if (!st || !st.active) return 0;
  return Math.max(0, (st.expiresAt - Date.now()) / 1e3);
}

function limitedBoostCoverageFraction(bareName, windowSec) {
  windowSec = windowSec || 86400;
  const remainingSec = getLimitedBoostRemainingSec(bareName);
  if (remainingSec <= 0) return 0;
  return Math.max(0, Math.min(1, remainingSec / windowSec));
}

function getBoostCoverageFraction(b, windowSec, haveSyncData) {
  if (!b || !b.limitedBoostName || !haveSyncData) return 1;
  const remainingSec = getLimitedBoostRemainingSec(b.limitedBoostName);
  if (remainingSec > 0) return Math.max(0, Math.min(1, remainingSec / (windowSec || 86400)));
  return 1;
}

function blendCyclesPerDayForExpiry(cyclesForMultFn, limitedFactors, windowSec) {
  windowSec = windowSec || 86400;
  const active = (limitedFactors || []).filter(f => f && f.timeMult && f.remainingSec > 0).map(f => ({
    timeMult: f.timeMult,
    remainingSec: Math.min(f.remainingSec, windowSec)
  }));
  if (!active.length) return cyclesForMultFn(1);
  let t = 0;
  let cycles = 0;
  let guard = 0;
  while (t < windowSec && guard < 1e4) {
    guard++;
    const mult = active.filter(f => f.remainingSec > t).reduce((m, f) => m * f.timeMult, 1);
    const rate = cyclesForMultFn(mult);
    const cycleTime = rate > 0 ? 86400 / rate : Infinity;
    if (!isFinite(cycleTime) || cycleTime <= 0) break;
    const nextExpiry = active.reduce((min, f) => f.remainingSec > t && f.remainingSec < min ? f.remainingSec : min, windowSec);
    const stretch = Math.max(0, nextExpiry - t);
    const fullCyclesInStretch = Math.floor(stretch / cycleTime);
    if (fullCyclesInStretch > 0) {
      cycles += fullCyclesInStretch;
      t += fullCyclesInStretch * cycleTime;
    }
    const remainingWindow = windowSec - t;
    if (remainingWindow <= 0) break;
    if (cycleTime <= remainingWindow) {
      cycles += 1;
      t += cycleTime;
    } else {
      cycles += remainingWindow / cycleTime;
      t = windowSec;
    }
  }
  return cycles * (86400 / windowSec);
}

function getLimitedTimeBoostIcon(entry) {
  const imgSrc = IMAGE_ICONS[entry.name];
  if (imgSrc) return `<img src="${imgSrc}" alt="${escapeHtml(entry.name)}" style="width:18px;height:18px;image-rendering:pixelated;vertical-align:middle;">`;
  return `<span style="font-size:21.6px;line-height:1;">${entry.fallbackEmoji || "⏳"}</span>`;
}

let limitedTimeBoostRefreshTimer = null;

let shrineCostExpandedIds = new Set;

function getShrineAffectedItemsDetailed(shrineName) {
  const base = shrineBaseName(shrineName);
  const items = new Map;
  const add = (n, c) => {
    if (n && !items.has(n)) items.set(n, c);
  };
  if (base === "Trading Shrine") add("Obsidian", "resources");
  BOOSTS.forEach(b => {
    if (shrineBaseName(b.name) !== base) return;
    const cat = b.category || "crops";
    if (b.scope === "resourceList" && Array.isArray(b.resources)) {
      b.resources.forEach(r => add(r, cat));
    } else if (b.scope === "resource" && b.target) {
      add(b.target, cat);
    } else if (b.scope === "animalType" && b.target) {
      add(b.target, "animal");
    } else if (b.scope === "fruit" && b.target) {
      add(b.target, "fruit");
    } else if (b.scope === "fruitList" && Array.isArray(b.fruits)) {
      b.fruits.forEach(f => add(f, "fruit"));
    } else if (b.category === "fruits" && b.scope === "global") {
      FRUIT_TREE_NAMES.forEach(n => add(n, "fruit"));
    } else if (b.category === "greenhouse" && b.scope === "greenhouse" && b.target) {
      add(b.target, "greenhouse");
    } else if (b.category === "greenhouse" && b.scope === "global") {
      GREENHOUSE_CROP_NAMES.forEach(n => {
        if (n === "Grape" && GREENHOUSE_GLOBAL_EXCLUDED_FROM_GRAPE.has(b.id)) return;
        add(n, "greenhouse");
      });
    } else if ((b.category || "crops") === "crops" && b.scope === "global") {
      CORE_FIELD_CROP_NAMES.forEach(n => add(n, "crops"));
    } else if (b.category === "honey" && (b.scope === "hiveGlobal" || b.scope === "flowerGlobal")) {
      add("Honey", "honey");
    } else if (b.category === "pets") {
      add("Pets", "pets");
    } else {
      add("__unmodeled__" + (b.id || b.name), "unmodeled");
    }
  });
  return items;
}

function shrineNodeProfit24h_Crop(name) {
  const d = BASE_CROPS[name];
  if (!d) return null;
  const costFlower = coinsToFlower(getCropCostCoins(name));
  const m = marketItems.find(x => (x.name || "").toLowerCase() === name.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const boosted = computeBoostedCropStats(name, d.baseYield || 1, d.timeSec);
  const plotCount = getPlotCount(name);
  const manualCycle = getManualCycleOverride("crop_" + name);
  const proj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, plotCount, {
    baseStock: BASE_STOCK_CROPS[name],
    kind: "seed",
    itemName: name
  }, manualCycle);
  return proj.profit24h;
}

function shrineNodeProfit24h_Fruit(name) {
  const d = BASE_FRUITS[name];
  if (!d) return null;
  const costFlower = coinsToFlower(getFruitCostCoins(name));
  const m = marketItems.find(x => (x.name || "").toLowerCase() === name.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const boosted = computeBoostedFruitStats(name, d.yieldPerHarvest || 1, d.timeSec, d.minHarvest || 1);
  const fruitCount = getFruitCount(name);
  const manualCycle = getManualCycleOverride("fruit_" + name);
  const proj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, fruitCount, {
    baseStock: BASE_STOCK_FRUITS[name],
    kind: "seed",
    itemName: name,
    cyclesPerStockUnit: boosted.minHarvestVal,
    maxRestocksPerDay: d.moonOnly ? 1 / SYNODIC_MONTH_DAYS : undefined
  }, manualCycle);
  return proj.profit24h;
}

function shrineNodeProfit24h_Greenhouse(name) {
  const d = BASE_GREENHOUSE[name];
  if (!d) return null;
  const costFlower = coinsToFlower(getGreenhouseCostCoins(name));
  const m = marketItems.find(x => (x.name || "").toLowerCase() === name.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const boosted = computeBoostedGreenhouseStats(name, d.baseYield || 1, d.timeSec);
  const plotCount = getGreenhouseCount(name);
  const manualCycle = getManualCycleOverride("greenhouse_" + name);
  const proj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, plotCount, {
    baseStock: BASE_STOCK_GREENHOUSE[name],
    kind: "seed",
    itemName: name
  }, manualCycle);
  return proj.profit24h;
}

function shrineNodeProfit24h_Animal(type) {
  const fig = ANIMAL_DATA[type] ? computeAnimalTypeFigures(type) : null;
  if (!fig) return null;
  const qty = fig.qty;
  const totalCostFlower = coinsToFlower(fig.totalCostCoinsPerAnimal) * qty;
  let totalRevenueFlower = 0;
  fig.products.forEach((pname, idx) => {
    const m = marketItems.find(x => (x.name || "").toLowerCase() === pname.toLowerCase());
    const price = m ? m.flowerPrice || 0 : 0;
    const totalUnits = fig.yields[idx] * qty;
    totalRevenueFlower += totalUnits * price * (1 - feePercent / 100);
  });
  const profitFlower = totalRevenueFlower - totalCostFlower;
  const manualCycle = getManualCycleOverride("animal_day_" + type);
  const autoCyclesPerDay = ANIMAL_BASE_CYCLE_SEC / fig.cycleTimeSec;
  const cyclesPerDay = manualCycle != null ? manualCycle : autoCyclesPerDay;
  return profitFlower * cyclesPerDay;
}

function shrineNodeProfit24h_Honey() {
  const econ = computeHiveEconomics();
  return econ.totalProfitDay;
}

function shrineNodeProfit24h_Resource(name) {
  if (!RESOURCE_DATA[name]) return null;
  const fig = computeResourceFigures(name);
  if (!fig) return null;
  const m = marketItems.find(x => (x.name || "").toLowerCase() === name.toLowerCase());
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const manualCycle = getManualCycleOverride("resource_" + name);
  const proj = computeResourceProjection24h(fig, sellFlower, manualCycle);
  return proj.profit24h;
}

function shrineNodeProfit24h_Pets() {
  if (typeof petComputeResourceTotals !== "function" || typeof petsData === "undefined" || !petsData.length) return null;
  const totals = petComputeResourceTotals();
  return totals.reduce((sum, t) => sum + (t.net || 0), 0);
}

function shrineNodeProfit24h_Obsidian() {
  const fig = computeLavaPitFigures(currentSeason);
  if (!fig) return null;
  const m = marketItems.find(x => (x.name || "").toLowerCase() === "obsidian");
  const sellFlower = m ? m.flowerPrice || 0 : 0;
  const weekly = computeObsidianWeeklyProfit(fig, sellFlower);
  return weekly.profit / 7;
}

function computeShrineAffectedProfitability(shrineName) {
  const itemsMap = getShrineAffectedItemsDetailed(shrineName);
  let sum = 0, modeled = 0, unmodeled = 0;
  itemsMap.forEach((cat, name) => {
    let p = null;
    try {
      if (name === "Obsidian") p = shrineNodeProfit24h_Obsidian();
      else if (cat === "honey") p = shrineNodeProfit24h_Honey();
      else if (cat === "animal") p = shrineNodeProfit24h_Animal(name);
      else if (cat === "fruit") p = shrineNodeProfit24h_Fruit(name);
      else if (cat === "greenhouse") p = shrineNodeProfit24h_Greenhouse(name);
      else if (cat === "crops") p = shrineNodeProfit24h_Crop(name);
      else if (cat === "resources") p = shrineNodeProfit24h_Resource(name);
      else if (cat === "pets") p = shrineNodeProfit24h_Pets();
    } catch (e) {
      p = null;
    }
    if (p != null && isFinite(p)) {
      sum += p;
      modeled++;
    } else {
      unmodeled++;
    }
  });
  return {
    profit24h: sum,
    modeledCount: modeled,
    unmodeledCount: unmodeled
  };
}

function renderShrineProfitabilityBlock(b, cost) {
  const affected = computeShrineAffectedProfitability(b.name);
  if (affected.modeledCount === 0) {
    return `\n    <div class="lib-item-meta" style="margin-top:6px;padding-top:6px;border-top:1px dashed var(--sun-deep);font-weight:700;">📊 Profitability <span style="font-weight:500;opacity:.7;">(no priceable affected nodes found)</span></div>`;
  }
  const net24h = affected.profit24h - cost.dailyCost;
  const netDuration = affected.profit24h * cost.durationDays - cost.totalCost;
  const partialNote = affected.unmodeledCount > 0 ? ` <span style="font-weight:500;opacity:.7;">(+${affected.unmodeledCount} affected item${affected.unmodeledCount === 1 ? "" : "s"} not priced)</span>` : "";
  return `\n    <div class="lib-item-meta" style="margin-top:6px;padding-top:6px;border-top:1px dashed var(--sun-deep);font-weight:700;">📊 Profitability${partialNote}</div>\n    <div class="lib-item-meta" style="font-weight:700;">⏱️ 24hrs: <span class="${net24h >= 0 ? "is-profit" : "is-loss"}" style="color:${net24h >= 0 ? "var(--profit)" : "var(--loss)"};">${net24h >= 0 ? "+" : ""}${fmt(net24h)} ${FLOWER_ICON}</span> <span style="font-weight:500;opacity:.7;">(${fmt(affected.profit24h)} affected profit − ${fmt(cost.dailyCost)} daily cost)</span></div>\n    <div class="lib-item-meta" style="font-weight:700;">📅 Duration (${fmt(cost.durationDays)}d): <span class="${netDuration >= 0 ? "is-profit" : "is-loss"}" style="color:${netDuration >= 0 ? "var(--profit)" : "var(--loss)"};">${netDuration >= 0 ? "+" : ""}${fmt(netDuration)} ${FLOWER_ICON}</span></div>`;
}

function renderShrineCostBlock(b) {
  const cost = computeShrineCost(b.id);
  if (!cost) return "";
  const expanded = shrineCostExpandedIds.has(b.id);
  const ingredientRows = cost.ingredients.map(ing => `\n    <div class="lib-item-row" style="margin:0 0 4px;padding:4px 8px;">\n      <span class="lib-item-icon">${getPetResourceIcon(ing.name)}</span>\n      <div class="lib-item-main" style="display:flex;justify-content:space-between;align-items:center;">\n        <span>${escapeHtml(ing.name)} (x${fmt(ing.qty)})</span>\n        <span style="font-weight:700;">${fmt(ing.totalPrice)} ${FLOWER_ICON}</span>\n      </div>\n    </div>`).join("");
  return `\n    <div class="shrine-cost-toggle" data-shrine-cost-id="${b.id}" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;margin-top:4px;padding:4px 0;border-top:1px dashed var(--sun-deep);">\n      <div>\n        <div class="lib-item-meta" style="font-weight:700;">🧾 Total Cost: ${fmt(cost.totalCost)} ${FLOWER_ICON}</div>\n        <div class="lib-item-meta" style="font-weight:700;">📅 Daily Cost (${fmt(cost.durationDays)}d): ${fmt(cost.dailyCost)} ${FLOWER_ICON}</div>\n      </div>\n      <span class="shrine-cost-chev" style="font-size:12px;color:var(--ink-soft);transition:transform .25s ease;transform:rotate(${expanded ? 180 : 0}deg);">▾</span>\n    </div>\n    <div class="shrine-cost-details" style="display:${expanded ? "block" : "none"};margin-top:4px;">\n      ${ingredientRows}\n    </div>\n    ${renderShrineProfitabilityBlock(b, cost)}`;
}

function attachShrineCostToggles(wrap) {
  wrap.querySelectorAll(".shrine-cost-toggle").forEach(el => {
    el.onclick = () => {
      const id = el.getAttribute("data-shrine-cost-id");
      const details = el.nextElementSibling;
      const chev = el.querySelector(".shrine-cost-chev");
      const nowExpanded = shrineCostExpandedIds.has(id) ? (shrineCostExpandedIds.delete(id), 
      false) : (shrineCostExpandedIds.add(id), true);
      if (details) details.style.display = nowExpanded ? "block" : "none";
      if (chev) chev.style.transform = `rotate(${nowExpanded ? 180 : 0}deg)`;
    };
  });
}

function renderLimitedTimeBoostPanel(wrap, term) {
  const groupOrder = [ "Totem", "Hourglass", "Shrine", "Pet Shrine", "Animal Shrine" ];
  const groupLabels = {
    Totem: "⏳ Totems",
    Hourglass: "⌛ Hourglasses",
    Shrine: "🏛️ Shrines",
    "Pet Shrine": "🐾 Pet Shrines",
    "Animal Shrine": "🐄 Animal Shrines"
  };
  const g = farmPanelGameState ? farmSyncExtractGameState(farmPanelGameState) : null;
  const synced = !!g;
  const intro = synced ? `<div class="field-hint" style="background:#eef3fb;border:1.5px solid #33507a;padding:8px 10px;border-radius:8px;margin-bottom:10px;font-weight:600;">⏳ Reference list of every temporary/expiring boost, how long it lasts, how many you're holding in your chest, and the time left on any currently active one — pulled from your last farm sync. Data-only for now — not wired into your active boosts yet, this is the basis for a future expiry-timer feature.</div>` : `<div class="field-hint" style="background:#fdf1c8;border:1.5px solid var(--sun-deep);padding:8px 10px;border-radius:8px;margin-bottom:10px;font-weight:600;">⏳ Reference list of every temporary/expiring boost and how long it lasts. Sync your Farm ID (⚡ Boosts panel above) to also see how many you own and the time remaining on any currently active one.</div>`;
  const shrineModeToggleHtml = `\n    <div class="lib-section-title" style="margin-top:4px;">💰 Shrine Cost Basis</div>\n    <div style="display:flex;gap:6px;margin:4px 0 8px;">\n      <button type="button" class="seed-picker-btn" data-shrine-mode-btn="collect" style="flex:1;padding:6px 4px;${shrineCostMode === "collect" ? "outline:2px solid var(--profit);" : ""}">🧺 Collect</button>\n      <button type="button" class="seed-picker-btn" data-shrine-mode-btn="buy" style="flex:1;padding:6px 4px;${shrineCostMode === "buy" ? "outline:2px solid var(--profit);" : ""}">🪙 Buy</button>\n    </div>\n    <div class="field-hint" style="background:#f6efe0;border:1.5px solid var(--sun-deep);padding:6px 8px;border-radius:8px;margin-bottom:8px;font-size:11.4px;font-weight:600;">🧾 ${shrineCostMode === "collect" ? "Collect: each ingredient is valued at what it actually costs you to gather it (pet-fetch cost, Lava Pit cost) — automatically falls back to Marketplace Price if you have no pets or no cost data for an ingredient." : "Buy: every ingredient is valued at the shared Marketplace Price, as if bought from other players."}</div>`;
  const body = shrineModeToggleHtml + groupOrder.map(cat => {
    const rows = LIMITED_TIME_BOOSTS.filter(b => b.group === cat && (!term || b.name.toLowerCase().includes(term)));
    if (!rows.length) return "";
    return `<div class="lib-section-title">${groupLabels[cat]}</div>` + rows.map(b => {
      let statusHtml = "";
      if (synced) {
        const status = farmSyncGetLimitedTimeBoostStatus(g, b.name, b.durationMs);
        const qtyTxt = `🎒 ${fmt(status.quantity)} in inventory`;
        const activeTxt = status.activeCount ? ` · ⏳ ${formatDuration(status.remainingMs / 1e3)} left${status.activeCount > 1 ? ` (×${status.activeCount} active)` : ""}` : ` · 💤 not currently active`;
        statusHtml = `<div class="lib-item-meta">${qtyTxt}${activeTxt}</div>`;
      }
      return `<div class="lib-item-row" data-limited-boost-id="${b.id}" style="cursor:default;display:block;">\n        <div style="display:flex;align-items:flex-start;">\n          <span class="lib-item-icon">${getLimitedTimeBoostIcon(b)}</span>\n          <div class="lib-item-main">\n            <div class="lib-item-name">${escapeHtml(b.name)}</div>\n            <div class="lib-item-meta">⏱️ Lasts ${b.durationLabel}</div>\n            ${statusHtml}\n          </div>\n        </div>\n        ${renderShrineCostBlock(b)}\n      </div>`;
    }).join("");
  }).join("");
  wrap.innerHTML = intro + (body || `<div class="lib-empty">No boosts match your search.</div>`);
  attachShrineCostToggles(wrap);
  wrap.querySelectorAll("[data-shrine-mode-btn]").forEach(btn => {
    btn.onclick = () => {
      setShrineCostMode(btn.getAttribute("data-shrine-mode-btn"));
      renderLimitedTimeBoostPanel(wrap, term);
    };
  });
  clearInterval(limitedTimeBoostRefreshTimer);
  if (synced) {
    limitedTimeBoostRefreshTimer = setInterval(() => {
      if (boostCategory === "limitedtime" && document.getElementById("boostListWrap")) {
        renderLimitedTimeBoostPanel(wrap, term);
      } else {
        clearInterval(limitedTimeBoostRefreshTimer);
      }
    }, 3e4);
  }
}

