function getStockCount(itemName) {
  if (!itemName) return 0;
  const v = syncedItemStock[itemName];
  return typeof v === "number" && !isNaN(v) ? v : 0;
}

let restockGemMode = function() {
  const raw = localStorage.getItem("hl_restock_mode");
  if (!raw) return new Set([ "tools_only", "seeds_only" ]);
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed) && parsed.length) return new Set(parsed);
  } catch (e) {
    if (raw === "all") return new Set([ "all" ]);
    if (raw === "tools_only" || raw === "seeds_only") return new Set([ "tools_only", "seeds_only" ]);
  }
  return new Set([ "tools_only", "seeds_only" ]);
}();

