$("gemFlowerSpentInput").value = gemFlowerSpent;

$("gemsReceivedInput").value = gemsReceived;

function flowerPerGem() {
  return gemsReceived > 0 ? gemFlowerSpent / gemsReceived : 0;
}

function gemsToFlower(gems) {
  return gems * flowerPerGem();
}

function gemsToCoins(gems) {
  return gemsToFlower(gems) * coinPerFlower;
}

function updateGemRatioDisplay() {
  const fpg = flowerPerGem();
  const gemsPerFlower = fpg > 0 ? 1 / fpg : 0;
  $("gemRatioDisplay").innerHTML = `→ 1 ${FLOWER_ICON} FLOWER = ${fmt(gemsPerFlower)} ${GEM_ICON} Gems  ·  1 ${GEM_ICON} Gem = ${fmt(fpg)} ${FLOWER_ICON} FLOWER`;
}

