function setRestockCostMode(mode) {
  restockCostMode = mode === "shared" ? "shared" : "individual";
  localStorage.setItem("hl_restock_cost_mode", restockCostMode);
}

function isRestockItemExcluded(name) {
  return restockSharedExcluded.has(name);
}

function getRestockSharedPoolCount(kind) {
  const list = kind === "tool" ? RESTOCK_TOOLS_LIST : RESTOCK_SEED_POOL;
  let count = 0;
  for (let i = 0; i < list.length; i++) {
    if (!restockSharedExcluded.has(list[i])) count++;
  }
  return count;
}

function getSharedPoolDivisor(kind) {
  if (kind === "tool") {
    const c = getRestockSharedPoolCount(kind);
    return c > 0 ? c : 1;
  }
  if (restockCostMode !== "shared") return 1;
  const c = getRestockSharedPoolCount(kind);
  return c > 0 ? c : 1;
}

function getRestockExclusionNote(name) {
  if (!restockSharedExcluded.has(name)) return "";
  const isTool = RESTOCK_TOOLS_LIST.includes(name);
  if (isTool) return "Excluded";
  return restockCostMode === "shared" ? "Excluded" : "";
}

function getRestockGemCost(kind, itemName) {
  let base;
  if (restockGemMode.has("all")) base = kind === "tool" ? RESTOCK_GEM_COST.tools : RESTOCK_GEM_COST.all / 2; else if (kind === "tool") base = restockGemMode.has("tools_only") ? RESTOCK_GEM_COST.tools : 0; else base = restockGemMode.has("seeds_only") ? RESTOCK_GEM_COST.seeds : 0;
  if (base <= 0) return 0;
  if (kind === "tool") {
    if (itemName && restockSharedExcluded.has(itemName)) return 0;
    return base / getSharedPoolDivisor(kind);
  }
  if (restockCostMode === "shared") {
    if (itemName && restockSharedExcluded.has(itemName)) return 0;
    return base / getSharedPoolDivisor(kind);
  }
  return base;
}

function getRestockGemCostIndividual(kind) {
  let base;
  if (restockGemMode.has("all")) base = kind === "tool" ? RESTOCK_GEM_COST.tools : RESTOCK_GEM_COST.all / 2; else if (kind === "tool") base = restockGemMode.has("tools_only") ? RESTOCK_GEM_COST.tools : 0; else base = restockGemMode.has("seeds_only") ? RESTOCK_GEM_COST.seeds : 0;
  return base <= 0 ? 0 : base;
}

function updateRestockModeUI() {
  document.querySelectorAll(".restock-mode-btn").forEach(btn => {
    const active = restockGemMode.has(btn.dataset.mode);
    btn.style.borderColor = active ? "var(--profit)" : "";
    btn.style.color = active ? "var(--profit)" : "";
  });
  let hint;
  if (restockGemMode.has("all")) {
    hint = "Assuming: every restock bundles Seeds+Tools together (20 Gems) → Tools 10 Gems · Seeds 10 Gems (saves 5 Gems per seed restock, but only if you actually needed the tool restock too).";
  } else {
    const hasTools = restockGemMode.has("tools_only");
    const hasSeeds = restockGemMode.has("seeds_only");
    if (hasTools && hasSeeds) hint = "Assuming: Tools restocked alone (10 Gems) and Seeds restocked alone (15 Gems), separately — today's default rates."; else if (hasTools) hint = "Assuming: only Tools get restocked with Gems (10 Gems). Seed restock cost is excluded from the 24h calc — tap Seeds only too if you also gem-restock seeds."; else if (hasSeeds) hint = "Assuming: only Seeds get restocked with Gems (15 Gems). Tool restock cost is excluded from the 24h calc — tap Tools only too if you also gem-restock tools."; else hint = "Pick at least one restock option so the 24h calc knows what to charge.";
  }
  $("restockModeHint").textContent = hint;
}

document.querySelectorAll(".restock-mode-btn").forEach(btn => {
  btn.onclick = () => {
    const mode = btn.dataset.mode;
    if (mode === "all") {
      restockGemMode = new Set([ "all" ]);
    } else {
      restockGemMode.delete("all");
      if (restockGemMode.has(mode)) restockGemMode.delete(mode); else restockGemMode.add(mode);
      if (restockGemMode.size === 0) restockGemMode.add(mode);
    }
    localStorage.setItem("hl_restock_mode", JSON.stringify([ ...restockGemMode ]));
    updateRestockModeUI();
    renderLibraryLists();
    renderCropMachinePanel();
    if (typeof renderFarmPanelTabContent === "function") renderFarmPanelTabContent();
  };
});

