function findTool(id) {
  return toolRecipes.find(t => String(t.id) === String(id));
}

function getActiveBoostsForComposter(composterName) {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "composter" && (b.scope === "composterGlobal" || b.scope === "composter" && b.target === composterName));
}

function getActiveSaltYieldBonus() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "saltGlobal").reduce((sum, b) => sum + (b.saltYieldAdd || 0), 0);
}

function getActiveSaltRechargeMult() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "saltGlobal" && b.saltRechargeTimeMult).reduce((mult, b) => mult * b.saltRechargeTimeMult, 1);
}

function hasFreeSaltRakeCost() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "saltGlobal").some(b => b.freeCost);
}

function farmPanelGetSaltActiveBoosts() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "saltGlobal").map(b => ({
    name: b.name,
    yieldAdd: b.saltYieldAdd || 0,
    timeMult: b.saltRechargeTimeMult || undefined,
    freeCost: b.freeCost || undefined
  }));
}

function farmPanelGetHoneyActiveBoosts() {
  const active = typeof getActiveBoostsForHive === "function" ? getActiveBoostsForHive() : [];
  return active.map(b => ({
    name: b.name,
    yieldAdd: b.honeyYieldAdd || 0
  }));
}

function getActiveAgingSaltCostMult() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "agingGlobal" && b.agingSaltCostMult).reduce((mult, b) => mult * b.agingSaltCostMult, 1);
}

function getActiveSaltPrimeChanceBonus() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "agingGlobal").reduce((sum, b) => sum + (b.primeChanceAdd || 0), 0);
}

function getActiveFermentationSpiceDoubleChancePct() {
  return Math.min(100, BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "fermentationSpiceGlobal").reduce((sum, b) => sum + (b.doubleChancePct || 0), 0));
}

function getActiveFermentationSpiceExpectedMult() {
  return 1 + getActiveFermentationSpiceDoubleChancePct() / 100;
}

function getActiveAgedFishXpMult() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "fermentationSpiceGlobal" && b.agedFishXpMult).reduce((mult, b) => mult * b.agedFishXpMult, 1);
}

function getActiveSpiceRackOutputAdd() {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "salt" && b.scope === "spiceRackGlobal").reduce((sum, b) => sum + (b.spiceOutputAdd || 0), 0);
}

function getSpiceLickDurationHarvests() {
  return BOOSTS.some(b => isBoostActive(b.id) && b.id === "vibraphone") ? 6 : 3;
}

function computeComposterFigures(composterName, visited) {
  visited = visited || new Set;
  const d = BASE_COMPOSTERS[composterName];
  if (!d) return {
    fertilizer: "",
    outputQty: 0,
    timeVal: 0,
    wormName: "",
    wormAvg: 0,
    reqs: [],
    ingredientCostCoins: 0,
    costPerUnitCoins: 0,
    activeBoosts: []
  };
  const active = getActiveBoostsForComposter(composterName);
  let outputQty = d.output, timeVal = d.timeSec, wormAvg = d.wormAvg;
  active.forEach(b => {
    if (b.fertAdd) outputQty += b.fertAdd;
    if (b.timeMult) timeVal *= b.timeMult;
    if (b.wormAdd) wormAvg += b.wormAdd;
  });
  const reqs = SEASON_COMPOST_REQUIREMENTS[previewSeason] && SEASON_COMPOST_REQUIREMENTS[previewSeason][composterName] || [];
  const ingredientCostCoins = reqs.reduce((sum, r) => sum + (r.qty || 0) * getItemCostByName(r.item, visited ? new Set(visited) : visited), 0);
  const costPerUnitCoins = outputQty > 0 ? ingredientCostCoins / outputQty : 0;
  return {
    fertilizer: d.fertilizer,
    wormName: d.wormName,
    outputQty: outputQty,
    timeVal: timeVal,
    wormAvg: wormAvg,
    reqs: reqs,
    ingredientCostCoins: ingredientCostCoins,
    costPerUnitCoins: costPerUnitCoins,
    activeBoosts: active
  };
}

function getFertilizerCostCoins(fertName, visited) {
  visited = visited || new Set;
  const key = "fert:" + fertName;
  if (visited.has(key)) return 0;
  visited.add(key);
  const composterName = Object.keys(BASE_COMPOSTERS).find(k => BASE_COMPOSTERS[k].fertilizer === fertName);
  if (!composterName) return 0;
  return computeComposterFigures(composterName, visited).costPerUnitCoins;
}

function getCropCostCoins(cropName, visited) {
  visited = visited || new Set;
  const key = "crop:" + cropName;
  if (visited.has(key)) return 0;
  visited.add(key);
  const d = BASE_CROPS[cropName];
  if (!d) return 0;
  const boosted = computeBoostedCropStats(cropName, d.baseYield, d.timeSec);
  const seedCoinCost = (hasFreeCostBoost(cropName) ? 0 : d.seedCost || 0) * getArtistCoinCostMult();
  let fertCoinCost = 0;
  if (isFertilizerTierEnabled(d.tier)) {
    if (isBoostActive("apply_sprout_mix")) fertCoinCost += getFertilizerCostCoins("Sprout Mix", visited);
    if (isBoostActive("apply_rapid_root")) fertCoinCost += getFertilizerCostCoins("Rapid Root", visited);
  }
  return (seedCoinCost + fertCoinCost) / boosted.yieldVal;
}

function getFruitCostCoins(fruitName, visited) {
  visited = visited || new Set;
  const key = "fruit:" + fruitName;
  if (visited.has(key)) return 0;
  visited.add(key);
  const d = BASE_FRUITS[fruitName];
  if (!d) return 0;
  const boosted = computeBoostedFruitStats(fruitName, d.yieldPerHarvest || 1, d.timeSec, d.minHarvest || 1);
  const seedCoinCost = (hasFreeCostBoostFruit(fruitName) ? 0 : d.seedCost || 0) * getArtistCoinCostMult();
  const axeQty = d.axeQty || 0;
  const woodReturnQty = Math.max(0, (d.woodReturnQty || 0) - (boosted.woodReturnPenalty || 0) + (boosted.woodReturnAdd || 0));
  const axeCoinCost = boosted.noWoodCost ? 0 : axeQty * (RESOURCE_DATA.Wood.toolCoinCost || 0);
  const mode = getMaterialMode("Fruit_" + fruitName, "Wood");
  const woodRebateCoins = woodReturnQty * getMaterialUnitCostCoins("Wood", mode, visited);
  const totalYield = Math.max(1e-4, boosted.minHarvestVal * boosted.yieldVal);
  let fertCoinCost = 0;
  if (isBoostActive("apply_fruitful_blend")) fertCoinCost += getFertilizerCostCoins("Fruitful Blend", visited);
  return (seedCoinCost + axeCoinCost - woodRebateCoins + fertCoinCost) / totalYield;
}

function getGreenhouseCostCoins(name) {
  const d = BASE_GREENHOUSE[name];
  if (!d) return 0;
  const boosted = computeBoostedGreenhouseStats(name, d.baseYield || 1, d.timeSec);
  const seedCoinCost = (hasFreeCostBoostGreenhouse(name) ? 0 : (d.seedCost || 0) * (boosted.seedQtyMult || 1)) * getArtistCoinCostMult();
  const oilQty = Math.max(0, (d.oilQty || 0) * (boosted.oilQtyMult || 1) - (boosted.oilFlatReduce || 0));
  const oilCoinCost = oilQty * getItemCostByName("Oil");
  return (seedCoinCost + oilCoinCost) / boosted.yieldVal;
}

function getActiveBoostsForTool(toolName) {
  return BOOSTS.filter(b => isBoostActive(b.id) && b.category === "tools" && (b.scope === "toolGlobal" || b.scope === "tool" && (b.target || "").toLowerCase() === (toolName || "").toLowerCase()));
}

function getResourceForTool(toolName) {
  return Object.keys(RESOURCE_DATA).find(r => (RESOURCE_DATA[r].tool || "").toLowerCase() === (toolName || "").toLowerCase());
}

function getBoostedToolRecipe(item) {
  const producedName = item.producesName || item.name;
  const activeToolBoosts = getActiveBoostsForTool(producedName);
  let coinCostMultTotal = getArtistCoinCostMult(), materialQtyMultTotal = 1;
  const materialSwaps = [];
  const costAffectingBoosts = [];
  activeToolBoosts.forEach(b => {
    if (b.coinCostMult) coinCostMultTotal *= b.coinCostMult;
    if (b.materialQtyMult) materialQtyMultTotal *= b.materialQtyMult;
    if (b.materialSwap) materialSwaps.push(b.materialSwap);
    costAffectingBoosts.push(b);
  });
  const linkedResource = getResourceForTool(item.name);
  if (linkedResource) {
    getActiveBoostsForResource(linkedResource).forEach(b => {
      let affectsCraftCost = false;
      if (b.toolCostMult) {
        coinCostMultTotal *= b.toolCostMult;
        affectsCraftCost = true;
      }
      if (b.materialSwap) {
        materialSwaps.push(b.materialSwap);
        affectsCraftCost = true;
      }
      if (affectsCraftCost) costAffectingBoosts.push(b);
    });
  }
  const coinCost = (item.coinCost || 0) * coinCostMultTotal;
  const materials = (item.materials || []).map(m => {
    const swap = materialSwaps.find(s => s.from.toLowerCase() === m.name.toLowerCase());
    if (swap) return {
      name: swap.to,
      qty: swap.qty
    };
    return {
      name: m.name,
      qty: (m.qty || 0) * materialQtyMultTotal
    };
  });
  return {
    coinCost: coinCost,
    materials: materials,
    activeToolBoosts: costAffectingBoosts
  };
}

function getToolBaseCostCoins(id) {
  const item = findTool(id);
  if (!item) return 0;
  let total = item.coinCost || 0;
  (item.materials || []).forEach(m => {
    const mode = getMaterialMode("ToolLib_" + item.id, m.name);
    total += (m.qty || 0) * getMaterialUnitCostCoins(m.name, mode);
  });
  return total / (item.producesQty || 1);
}

function getToolCostCoins(id, visited) {
  const key = "tool_" + String(id);
  if (__toolCostMemo.has(key)) return __toolCostMemo.get(key);
  if (visited && visited.has(key)) return 0;
  const branchVisited = new Set(visited || []);
  branchVisited.add(key);
  const result = getToolCostCoinsUncached(id, branchVisited);
  __toolCostMemo.set(key, result);
  return result;
}

function getToolCostCoinsUncached(id, visited) {
  const item = findTool(id);
  if (!item) return 0;
  if (item.manualPrice != null && !item.locked) return item.manualPrice;
  const boosted = getBoostedToolRecipe(item);
  let total = boosted.coinCost;
  boosted.materials.forEach(m => {
    const mode = getMaterialMode("ToolLib_" + item.id, m.name);
    const unitCost = getMaterialUnitCostCoins(m.name, mode, visited);
    total += (m.qty || 0) * unitCost;
  });
  return total / (item.producesQty || 1);
}

function coinsToFlower(coins) {
  return coins / (coinPerFlower || 1);
}

function compute24hProjection(yieldPerCycle, cycleTimeSec, costPerUnit, sellPerUnit, count, restockInfo, manualCyclesPerDay) {
  count = count == null ? 1 : count;
  const autoCyclesPerDay = cycleTimeSec > 0 ? 86400 / cycleTimeSec : 0;
  const cyclesPerDay = manualCyclesPerDay != null && manualCyclesPerDay >= 0 ? manualCyclesPerDay : autoCyclesPerDay;
  const unitsPerDay = (yieldPerCycle || 0) * count * cyclesPerDay;
  const netSellPerUnit = (sellPerUnit || 0) * (1 - feePercent / 100);
  const revenue24h = netSellPerUnit * unitsPerDay;
  let cost24h = (costPerUnit || 0) * unitsPerDay;
  let restockCost24h = 0;
  if (restockInfo && restockInfo.baseStock) {
    restockCost24h = computeRestockCost24h(restockInfo.baseStock, restockInfo.kind || "seed", count, cyclesPerDay, restockInfo.cyclesPerStockUnit, restockInfo.maxRestocksPerDay, restockInfo.itemName);
    cost24h += restockCost24h;
  }
  const profit24h = revenue24h - cost24h;
  return {
    cyclesPerDay: cyclesPerDay,
    autoCyclesPerDay: autoCyclesPerDay,
    unitsPerDay: unitsPerDay,
    revenue24h: revenue24h,
    cost24h: cost24h,
    profit24h: profit24h,
    count: count,
    restockCost24h: restockCost24h
  };
}

function computeResourceProjection24h(fig, sellFlower, manualCyclesPerDay) {
  const autoCyclesPerDay = fig.timeSec > 0 ? 86400 / fig.timeSec : 0;
  const cyclesPerDay = manualCyclesPerDay != null && manualCyclesPerDay >= 0 ? manualCyclesPerDay : autoCyclesPerDay;
  const unitsPerDay = (fig.totalYieldPerCycle || 0) * cyclesPerDay;
  const netSellPerUnit = (sellFlower || 0) * (1 - feePercent / 100);
  const revenue24h = netSellPerUnit * unitsPerDay;
  const toolCostFlowerPerTool = coinsToFlower(fig.totalToolCost || 0);
  let cost24h = toolCostFlowerPerTool * (fig.toolUsageTotal || 0) * cyclesPerDay;
  let restockCost24h = 0;
  let restocksPerDay = 0;
  let boostedToolStock = 0;
  const baseToolStock = BASE_STOCK_TOOLS[fig.tool];
  const toolUsesPerDay = (fig.toolUsageTotal || 0) * cyclesPerDay;
  if (baseToolStock && toolUsesPerDay > 0) {
    boostedToolStock = computeBoostedStock(baseToolStock, "tool", fig.tool);
    if (boostedToolStock > 0) {
      restocksPerDay = toolUsesPerDay / boostedToolStock;
      const gemCost = typeof getRestockGemCost === "function" ? getRestockGemCost("tool", fig.tool) : RESTOCK_GEM_COST.tools;
      restockCost24h = typeof gemsToFlower === "function" ? gemsToFlower(restocksPerDay * gemCost) : 0;
      cost24h += restockCost24h;
    }
  }
  const profit24h = revenue24h - cost24h;
  return {
    cyclesPerDay: cyclesPerDay,
    autoCyclesPerDay: autoCyclesPerDay,
    unitsPerDay: unitsPerDay,
    revenue24h: revenue24h,
    cost24h: cost24h,
    profit24h: profit24h,
    count: fig.nodeCount,
    restockCost24h: restockCost24h,
    restocksPerDay: restocksPerDay,
    boostedToolStock: boostedToolStock
  };
}

function simulateStockCycles(computeStatsFn, totalPlots, stockQty) {
  totalPlots = Math.max(0, totalPlots || 0);
  stockQty = Math.max(0, stockQty || 0);
  if (totalPlots <= 0 || stockQty <= 0) return {
    cycles: 0,
    totalUnits: 0,
    totalTimeSec: 0,
    lastCyclePlots: 0
  };
  let remaining = stockQty;
  let cycles = 0;
  let totalUnits = 0;
  let totalTimeSec = 0;
  let lastCyclePlots = 0;
  const MAX_CYCLES = 2e4;
  while (remaining > 0 && cycles < MAX_CYCLES) {
    const plotsThisCycle = Math.min(remaining, totalPlots);
    const stats = computeStatsFn(plotsThisCycle);
    totalUnits += plotsThisCycle * (stats.yieldVal || 0);
    totalTimeSec += stats.timeVal || 0;
    remaining -= plotsThisCycle;
    lastCyclePlots = plotsThisCycle;
    cycles++;
  }
  return {
    cycles: cycles,
    totalUnits: totalUnits,
    totalTimeSec: totalTimeSec,
    lastCyclePlots: lastCyclePlots
  };
}

function renderTotalsBreakdown(opts) {
  opts = opts || {};
  const title = opts.title || "24HRS PROFIT/LOSS";
  const gross = opts.gross || 0;
  const baseCost = opts.baseCost || 0;
  const restockCost = opts.restockCost || 0;
  const restockNote = opts.restockNote || "";
  const shrineCost = opts.shrineCost || 0;
  const shrineNames = opts.shrineNames || [];
  const sellFee = opts.sellFee || 0;
  const net = gross - baseCost - restockCost - shrineCost - sellFee;
  const isProfit = net >= 0;
  const hasYield = opts.totalYield != null;
  const yieldRow = hasYield ? `<div class="stat"><span class="label">Total Yield</span><span class="value">${fmt(opts.totalYield)}${opts.yieldLabel ? ` <span style="opacity:.65;font-weight:500;">${opts.yieldLabel}</span>` : ""}</span></div>` : opts.yieldLabel ? `<div class="stat"><span class="label">Total Yield</span><span class="value">${opts.yieldLabel}</span></div>` : "";
  const unitRow = opts.unitLabel != null ? `<div class="stat"><span class="label">${opts.unitLabel}</span><span class="value">${fmt(opts.unitCount)}</span></div>` : "";
  const yieldPerCycleRow = opts.yieldPerCycle != null ? `<div class="stat"><span class="label">Yield per Cycle</span><span class="value">${fmt(opts.yieldPerCycle)}</span></div>` : "";
  const totalCyclesRow = opts.totalCycles != null ? `<div class="stat"><span class="label">Total Cycles</span><span class="value">${fmt(opts.totalCycles)}${opts.totalCyclesSuffix != null ? opts.totalCyclesSuffix : "/day"}</span></div>` : "";
  const manualCycleRow = opts.manualCycleKey ? `\n        <div class="stat manual-cycle-stat" style="grid-column:1 / -1;flex-direction:column;align-items:stretch;gap:3px;background:rgba(255,193,7,.22);border:1.25px solid rgba(217,119,6,.55);border-radius:8px;padding:6px 7px;">\n          <span class="label" style="color:#8a5a00;">Manual Cycle <span style="opacity:.75;font-weight:500;">(override${opts.totalCyclesSuffix != null ? " " + opts.totalCyclesSuffix : "/day"} — leave blank for auto)</span></span>\n          <input type="text" inputmode="decimal" pattern="[0-9]*\.?[0-9]*" autocomplete="off" class="manual-cycle-input" data-cycle-key="${escapeHtml(opts.manualCycleKey)}" data-cycle-refresh="${escapeHtml(opts.manualCycleRefresh || "")}" placeholder="Type Manual Cycle here" value="${opts.manualCycleValue != null && opts.manualCycleValue !== "" ? escapeHtml(String(opts.manualCycleValue)) : ""}" style="width:100%;font-family:'JetBrains Mono',monospace;font-size:12.6px;border:1.25px solid var(--line);border-radius:6px;padding:5px 6px;background:#fffdf5;">\n        </div>` : "";
  const feedRow = opts.feedQty != null ? `<div class="stat"><span class="label">${opts.feedIcon || ""} Feed Consumed</span><span class="value">${fmt(opts.feedQty)} ${opts.feedName || ""}${opts.headsCount != null ? ` <span style="opacity:.65;font-weight:500;">(${fmt(opts.headsCount)} heads)</span>` : ""}</span></div>` : "";
  const perSeedHtml = opts.perSeedLabel ? `\n      <div class="profit-banner per-seed-banner">\n        <span class="plabel">${opts.perSeedLabel}</span>\n        <span><span class="pvalue ${opts.perSeedIsProfit ? "is-profit" : "is-loss"}">${opts.perSeedIsProfit ? "+" : ""}${fmt(opts.perSeedValue)} ${FLOWER_ICON} FLOWER</span>${opts.perSeedRoi != null ? `<span class="proi">(${opts.perSeedRoi.toFixed(1)}% ROI)</span>` : ""}</span>\n      </div>` : "";
  const totalDeductions = baseCost + restockCost + shrineCost + sellFee;
  return `\n      ${perSeedHtml}\n      <div class="lib-section-title totals-breakdown-title" style="margin-top:10px;">${title}</div>\n      <div class="totals-breakdown totals-breakdown-box">\n      <div class="card-grid">\n        ${manualCycleRow}\n        ${unitRow}\n        ${yieldPerCycleRow}\n        ${totalCyclesRow}\n        ${feedRow}\n        ${yieldRow}\n        <div class="stat"><span class="label">Gross</span><span class="value">${fmt(gross)} ${FLOWER_ICON} FLOWER${feePercent > 0 ? ` <span style="opacity:.65;font-weight:500;">(before fee)</span>` : ""}</span></div>\n      </div>\n      <div class="deductions-box">\n        <div class="totals-deductions-label">Total Deductions</div>\n        <div class="card-grid">\n          ${opts.feedCostFlower != null ? `<div class="stat stat-sub"><span class="label">${opts.feedIcon || ""} Feed Cost</span><span class="value">-${fmt(opts.feedCostFlower)} ${FLOWER_ICON} FLOWER</span></div>` : ""}\n          ${opts.otherCostItems && opts.otherCostItems.length ? `\n          <div class="stat stat-sub" style="flex-direction:column;align-items:stretch;">\n            <div class="label" style="margin-bottom:2px;">Consumable Cost</div>\n            <div style="margin-left:10px;">\n              ${opts.otherCostItems.map(item => `\n              <div style="display:flex;justify-content:space-between;font-size:11.4px;opacity:.8;padding:1px 0;">\n                <span>${item.label}${item.note ? ` <span style="opacity:.7;">(${item.note})</span>` : ""}</span>\n                <span>-${fmt(item.value)} ${FLOWER_ICON}</span>\n              </div>`).join("")}\n            </div>\n            <div style="display:flex;justify-content:space-between;margin-top:3px;padding-top:2px;border-top:1px dashed var(--line);"><span class="label">Total</span><span class="value">-${fmt(opts.otherCostItems.reduce((s, i) => s + i.value, 0))} ${FLOWER_ICON} FLOWER</span></div>\n          </div>` : opts.feedCostFlower != null && baseCost - opts.feedCostFlower > 1e-4 ? `<div class="stat stat-sub"><span class="label">Other Costs</span><span class="value">-${fmt(baseCost - opts.feedCostFlower)} ${FLOWER_ICON} FLOWER</span></div>` : ""}\n          ${opts.feedCostFlower == null ? `<div class="stat stat-sub"><span class="label">Total Cost</span><span class="value">-${fmt(baseCost)} ${FLOWER_ICON} FLOWER</span></div>` : ""}\n          <div class="stat stat-sub"><span class="label">Restock Cost</span><span class="value">${restockCost > 0 ? `-${fmt(restockCost)}` : `0`} ${FLOWER_ICON} FLOWER${restockNote ? ` <span style="opacity:.65;font-weight:500;">${restockNote}</span>` : ""}</span></div>\n          <div class="stat stat-sub"><span class="label">Shrine Cost</span><span class="value" style="${shrineCost > 0 ? "color:#b45309;" : ""}">${shrineCost > 0 ? `-${fmt(shrineCost)}` : `0`} ${FLOWER_ICON} FLOWER${shrineNames.length ? ` <span style="opacity:.65;font-weight:500;">(${shrineNames.join(", ")})</span>` : ""}</span></div>\n          <div class="stat stat-sub"><span class="label">Sell Fee${feePercent > 0 ? ` (${feePercent}%)` : ""}</span><span class="value">${sellFee > 0 ? `-${fmt(sellFee)}` : `0`} ${FLOWER_ICON} FLOWER</span></div>\n          <div class="stat stat-total-deduction"><span class="label">Total Deduction</span><span class="value">-${fmt(totalDeductions)} ${FLOWER_ICON} FLOWER</span></div>\n        </div>\n      </div>\n      <div class="card-grid" style="margin-top:5px;">\n        <div class="stat stat-net"><span class="label">Net</span><span class="value ${isProfit ? "is-profit" : "is-loss"}">${isProfit ? "+" : ""}${fmt(net)} ${FLOWER_ICON} FLOWER</span></div>\n      </div>\n      </div>`;
}

function render24hTotalsGrid(cost24h, grossRevenue24h, netRevenue24h, profit24h, opts) {
  opts = opts || {};
  const restockCost24h = opts.restockCost24h || 0;
  const shrineCost24h = opts.shrineCost24h || 0;
  const shrineNames = opts.shrineNames || [];
  const baseCost24h = cost24h - restockCost24h;
  const sellFee24h = grossRevenue24h - netRevenue24h;
  return renderTotalsBreakdown({
    title: opts.title || "24HRS PROFIT/LOSS",
    totalYield: opts.totalYield,
    yieldLabel: opts.yieldLabel,
    gross: grossRevenue24h,
    baseCost: baseCost24h,
    restockCost: restockCost24h,
    restockNote: opts.restockNote,
    shrineCost: shrineCost24h,
    shrineNames: shrineNames,
    sellFee: sellFee24h,
    unitLabel: opts.unitLabel,
    unitCount: opts.unitCount,
    yieldPerCycle: opts.yieldPerCycle,
    totalCycles: opts.totalCycles,
    manualCycleKey: opts.manualCycleKey,
    manualCycleValue: opts.manualCycleValue,
    manualCycleAuto: opts.manualCycleAuto,
    manualCycleRefresh: opts.manualCycleRefresh,
    perSeedLabel: opts.perSeedLabel,
    perSeedValue: opts.perSeedValue,
    perSeedIsProfit: opts.perSeedIsProfit,
    perSeedRoi: opts.perSeedRoi
  });
}

function render24hBadge(profit24h, cost24h, cyclesPerDay, cyclesLabel, restockCost24h, yieldLabel, extraLines, stockCtx) {
  if (profitDisplayMode === "stock" && stockCtx && stockCtx.itemName) {
    const stockQty = stockCtx.restockBaseStock != null ? computeBoostedStock(stockCtx.restockBaseStock, stockCtx.restockKind || "seed", stockCtx.restockBoostName || stockCtx.itemName) : getStockCount(stockCtx.itemName);
    const unitCost = stockCtx.unitCost || 0;
    const unitNetSell = stockCtx.unitNetSell || 0;
    let stockUnits, cyclesInfoHtml = "";
    if (stockCtx.simulateStock && stockCtx.plotCount != null) {
      const sim = stockCtx.simulateStock(stockQty);
      stockUnits = sim.totalUnits;
      if (sim.cycles > 0) {
        cyclesInfoHtml = `<div class="card-24h-line">🔁 ${fmt(sim.cycles)} cycle${sim.cycles === 1 ? "" : "s"} needed to use all stock <span class="card-24h-sub">(${fmt(stockCtx.plotCount)} plots/cycle${sim.lastCyclePlots && sim.lastCyclePlots !== stockCtx.plotCount ? `, last cycle ${fmt(sim.lastCyclePlots)}` : ""})</span></div>`;
      }
    } else if (stockCtx.toolsPerCycle) {
      const fullCycles = Math.floor(stockQty / stockCtx.toolsPerCycle);
      const fractionalCycles = stockQty / stockCtx.toolsPerCycle;
      stockUnits = fractionalCycles * (stockCtx.yieldPerCycle || 0);
      if (fractionalCycles > 0) {
        cyclesInfoHtml = `<div class="card-24h-line">🔁 ${fmt(fractionalCycles)} harvest cycle${fractionalCycles === 1 ? "" : "s"} from 1 restock <span class="card-24h-sub">(${fmt(stockCtx.toolsPerCycle)} tools/cycle, ${fmt(fullCycles)} full cycle${fullCycles === 1 ? "" : "s"})</span></div>`;
      }
    } else {
      const unitYield = stockCtx.unitYield || 0;
      stockUnits = unitYield * stockQty;
    }
    const econItemName = stockCtx.restockItemName || stockCtx.itemName;
    const econ = !stockCtx.toolsPerCycle && typeof farmPanelComputeEconomics === "function" ? farmPanelComputeEconomics(econItemName, 1, stockUnits) : null;
    let stockCost, oneRestockCost, stockGross, stockRevenue, stockSellFee;
    if (econ) {
      stockCost = econ.seedCost;
      oneRestockCost = econ.restockCost;
      stockGross = econ.grossRevenue;
      stockRevenue = econ.netRevenue;
      stockSellFee = econ.feeAmount;
    } else {
      stockCost = unitCost * stockQty;
      stockRevenue = stockUnits * unitNetSell;
      const grossPerUnit = feePercent < 100 ? unitNetSell / (1 - feePercent / 100) : unitNetSell;
      stockGross = stockUnits * grossPerUnit;
      stockSellFee = stockGross - stockRevenue;
      oneRestockCost = stockQty > 0 && typeof getRestockGemCost === "function" && typeof gemsToFlower === "function" ? gemsToFlower(getRestockGemCost(stockCtx.restockKind || "seed", stockCtx.restockItemName || stockCtx.itemName)) : 0;
    }
    const noStock = stockQty <= 0;
    const stockNet = stockGross - stockCost - oneRestockCost - stockSellFee;
    const isStockProfit = stockNet >= 0;
    const stockRestockNote = typeof getRestockExclusionNote === "function" ? getRestockExclusionNote(stockCtx.restockItemName || stockCtx.itemName) : "";
    return `<div class="card-24h-box ${isStockProfit ? "is-profit" : "is-loss"}">\n    <div class="card-24h-box-label">📦 ${fmt(stockQty)} ${stockCtx.itemName} <span class="card-24h-sub">from 1 restock</span></div>\n    ${cyclesInfoHtml}\n    ${noStock ? `<div class="card-24h-line" style="opacity:.7;">No restock stock configured for ${stockCtx.itemName} — it shows 0.</div>` : ""}\n    ${renderTotalsBreakdown({
      title: "Stock Total",
      totalYield: stockUnits,
      yieldLabel: stockCtx.itemName,
      gross: stockGross,
      baseCost: stockCost,
      restockCost: oneRestockCost,
      restockNote: stockRestockNote ? stockRestockNote : "(1 cycle)",
      shrineCost: 0,
      sellFee: stockSellFee
    })}\n  </div>`;
  }
  return "";
}

function getMarketPrice(marketId) {
  const m = marketItems.find(x => String(x.id) === String(marketId));
  return m ? m.flowerPrice || 0 : 0;
}

function getMarketItemCostCoins(marketId) {
  const m = marketItems.find(x => String(x.id) === String(marketId));
  if (!m) return 0;
  return getItemCostByName(m.name);
}

function isMarketItemMissing(marketId) {
  return false;
}

function getFeedIngredientUnitCostCoins(cropName, visited) {
  const mode = getMaterialMode("AnimalFeed", cropName);
  return getMaterialUnitCostCoins(cropName, mode, visited);
}

const KALE_MIX_RANKS = [ 3, 2.5, 2 ];

function getKaleMixKaleQty() {
  if (!isSkillActive("skill_kale_mix")) return null;
  const rank = getAscensionRank("skill_kale_mix");
  return KALE_MIX_RANKS[Math.min(Math.max(rank, 1), 3) - 1];
}

function getFeedUnitCost(feedKey, visited) {
  const kaleQty = feedKey === "mixedGrain" ? getKaleMixKaleQty() : null;
  const recipe = kaleQty != null ? [ {
    crop: "Kale",
    qty: kaleQty
  } ] : FEED_RECIPE[feedKey] || [];
  let cost = 0;
  const breakdown = [];
  recipe.forEach(r => {
    const mode = getMaterialMode("AnimalFeed", r.crop);
    const unitCost = getFeedIngredientUnitCostCoins(r.crop, visited);
    cost += r.qty * unitCost;
    breakdown.push({
      name: r.crop,
      qty: r.qty,
      unitCost: unitCost,
      mode: mode
    });
  });
  return {
    cost: cost,
    missing: false,
    missingCrops: [],
    breakdown: breakdown
  };
}

function getOmnifeedUnitCostCoins() {
  return flowerPerGem() * coinPerFlower;
}

function getOmnifeedInfo() {
  const unitCost = getOmnifeedUnitCostCoins();
  return {
    cost: unitCost,
    missing: false,
    missingCrops: [],
    breakdown: [ {
      name: "Omnifeed",
      qty: 1,
      unitCost: unitCost,
      mode: "gem"
    } ]
  };
}

function getActiveFeedInfo(feedKey, visited) {
  return omnifeedEnabled ? getOmnifeedInfo() : getFeedUnitCost(feedKey, visited);
}

function getActiveAnimalBoosts(type) {
  const active = BOOSTS.filter(b => isBoostActive(b.id) && b.category === "animals" && (b.scope === "animalGlobal" || b.scope === "animalType" && b.target === type));
  if ((type === "sheep" || type === "cow") && isBoostActive("bale") && isSkillActive("skill_bale_economy")) {
    const bale = BOOSTS.find(b => b.id === "bale");
    if (bale && bale.yieldAdd) {
      active.push({
        id: "bale_economy_" + type,
        name: "Bale Economy",
        productIndex: 0,
        yieldAdd: bale.yieldAdd
      });
    }
  }
  return active;
}

const ANIMAL_BASE_CYCLE_SEC = 86400;

function computeAnimalTypeFigures(type, visited) {
  const cfg = ANIMAL_DATA[type];
  const counts = getAnimalCount(type);
  const level = Math.min(15, Math.max(1, parseInt(counts.level) || 1));
  const qty = Math.max(0, parseFloat(counts.qty) || 0);
  const lvlData = cfg.levels[level - 1];
  const active = getActiveAnimalBoosts(type);
  let feedMultTotal = 1, yieldMultAllTotal = 1, timeMultTotal = 1, freeFeed = false, cureFree = false, cureCostMult = 1;
  const yieldAdd = [ 0, 0 ];
  const budAddSum = [ {}, {} ];
  active.forEach(b => {
    if (b.feedMult) feedMultTotal *= b.feedMult;
    if (b.feedMultAll) feedMultTotal *= b.feedMultAll;
    if (b.yieldMultAll) yieldMultAllTotal *= b.yieldMultAll;
    if (b.yieldAddAll) {
      yieldAdd[0] += b.yieldAddAll;
      yieldAdd[1] += b.yieldAddAll;
    }
    if (b.timeMult) timeMultTotal *= b.timeMult;
    if (b.timeMultAll) timeMultTotal *= b.timeMultAll;
    if (b.productIndex != null && b.yieldAdd) {
      const budKey = b.isBud && b.budId ? b.budId : null;
      if (budKey) {
        budAddSum[b.productIndex][budKey] = (budAddSum[b.productIndex][budKey] || 0) + b.yieldAdd;
      } else {
        yieldAdd[b.productIndex] += b.yieldAdd;
      }
    }
    if (b.freeFeed) freeFeed = true;
    if (b.freeCure) cureFree = true;
    if (b.cureCostMult) cureCostMult *= b.cureCostMult;
  });
  budAddSum.forEach((sums, idx) => {
    const vals = Object.values(sums);
    if (vals.length) yieldAdd[idx] += Math.max(...vals);
  });
  const spice = getSpiceEffectForAnimalType(type);
  feedMultTotal *= spice.feedMultAll;
  yieldMultAllTotal *= spice.yieldMultAll;
  const feedFig = computeAnimalFeedFigures(type, level);
  const feedKeyUsed = feedFig.feedKeyUsed;
  const feedNameUsed = FEED_LABELS[feedKeyUsed];
  const feedIconUsed = getIcon(feedNameUsed);
  const feedInfo = getActiveFeedInfo(feedFig.favouriteFoodKey, visited);
  const requiredQtyPerFeed = REQUIRED_FOOD_QTY_MAP[type];
  const effectiveFeedQty = freeFeed ? 0 : Math.max(0, feedFig.noOfFeeds * requiredQtyPerFeed * feedMultTotal);
  const feedCostCoins = effectiveFeedQty * feedInfo.cost;
  const yields = [ Math.max(0, (lvlData.y[0] + yieldAdd[0]) * yieldMultAllTotal), Math.max(0, (lvlData.y[1] + yieldAdd[1]) * yieldMultAllTotal) ];
  const totalYieldUnits = yields[0] + yields[1];
  const curesPerLevel = getCuresPerLevelForType(type);
  const costPerCureFlower = cureFree ? 0 : computeMedicineCostFlower(visited) * cureCostMult;
  const medicineFlowerPerLevel = cureFree ? 0 : costPerCureFlower * curesPerLevel;
  const consumablesFlowerPerLevel = spice.costFlowerPerCyclePerAnimal;
  const sickHeads = getEffectiveSickHeads(type);
  const extraCoinsPerLevel = (medicineFlowerPerLevel + consumablesFlowerPerLevel) * coinPerFlower;
  const totalCostCoinsPerAnimal = feedCostCoins + extraCoinsPerLevel;
  const costPerUnit = totalYieldUnits > 0 ? totalCostCoinsPerAnimal / totalYieldUnits : 0;
  const cycleTimeSec = Math.max(1, ANIMAL_BASE_CYCLE_SEC * timeMultTotal);
  return {
    type: type,
    level: level,
    qty: qty,
    lvlData: lvlData,
    feedInfo: feedInfo,
    effectiveFeedQty: effectiveFeedQty,
    feedCostCoins: feedCostCoins,
    yields: yields,
    totalYieldUnits: totalYieldUnits,
    costPerUnit: costPerUnit,
    totalCostCoinsPerAnimal: totalCostCoinsPerAnimal,
    cycleTimeSec: cycleTimeSec,
    products: cfg.products,
    emoji: cfg.emoji,
    label: cfg.label,
    activeBoosts: active,
    medicineFlowerPerLevel: medicineFlowerPerLevel,
    consumablesFlowerPerLevel: consumablesFlowerPerLevel,
    spiceActiveKey: spice.activeKey,
    costPerCureFlower: costPerCureFlower,
    sickHeads: sickHeads,
    feedKeyUsed: feedKeyUsed,
    feedNameUsed: feedNameUsed,
    feedIconUsed: feedIconUsed
  };
}

function loadBaseAnimalProduceIfNeeded() {
  const names = [ "Egg", "Feather", "Wool", "Merino Wool", "Milk", "Leather" ];
  let added = false;
  names.forEach(n => {
    const exists = marketItems.some(m => (m.name || "").toLowerCase() === n.toLowerCase());
    if (!exists) {
      marketItems.push({
        id: "animal_" + n.replace(/\s+/g, "_").toLowerCase(),
        name: n,
        flowerPrice: 0,
        sourceLibId: null,
        isAutoAnimal: true
      });
      added = true;
    }
  });
  if (added) {
    saveMarketState();
    autoFillLivePricesForNewEntries();
  }
}

function computeAnimalProfit(fig) {
  const qty = fig.qty;
  const totalCostFlower = coinsToFlower(fig.totalCostCoinsPerAnimal) * qty;
  let totalRevenueFlower = 0;
  let totalRevenueGrossFlower = 0;
  fig.products.forEach((pname, idx) => {
    const m = marketItems.find(x => (x.name || "").toLowerCase() === pname.toLowerCase());
    const price = m ? m.flowerPrice || 0 : 0;
    const totalUnits = fig.yields[idx] * qty;
    const grossValue = totalUnits * price;
    totalRevenueGrossFlower += grossValue;
    totalRevenueFlower += grossValue * (1 - feePercent / 100);
  });
  return {
    totalCostFlower: totalCostFlower,
    totalRevenueFlower: totalRevenueFlower,
    totalRevenueGrossFlower: totalRevenueGrossFlower,
    profitFlower: totalRevenueFlower - totalCostFlower
  };
}

function computeAnimalWeeklyFigures(type, manualCyclesPerWeek) {
  const figWith = computeAnimalTypeFigures(type);
  const usingSpice = !!figWith.spiceActiveKey;
  const savedSalt = spiceUsage.saltLick[type], savedHoney = spiceUsage.honeyTreat[type];
  spiceUsage.saltLick[type] = false;
  spiceUsage.honeyTreat[type] = false;
  const figBase = computeAnimalTypeFigures(type);
  spiceUsage.saltLick[type] = savedSalt;
  spiceUsage.honeyTreat[type] = savedHoney;
  const withP = computeAnimalProfit(figWith);
  const baseP = computeAnimalProfit(figBase);
  const autoCyclesPerDay = ANIMAL_BASE_CYCLE_SEC / figWith.cycleTimeSec;
  const autoCyclesPerWeek = autoCyclesPerDay * 7;
  const cyclesPerWeek = manualCyclesPerWeek != null && manualCyclesPerWeek >= 0 ? manualCyclesPerWeek : autoCyclesPerWeek;
  const boostedCycles = usingSpice ? Math.min(getSpiceLickDurationHarvests(), cyclesPerWeek) : 0;
  const unboostedCycles = Math.max(0, cyclesPerWeek - boostedCycles);
  const profitWeekWithSpice = boostedCycles * withP.profitFlower + unboostedCycles * baseP.profitFlower;
  const costWeekWithSpice = boostedCycles * withP.totalCostFlower + unboostedCycles * baseP.totalCostFlower;
  const netRevenueWeekWithSpice = boostedCycles * withP.totalRevenueFlower + unboostedCycles * baseP.totalRevenueFlower;
  const grossRevenueWeekWithSpice = boostedCycles * withP.totalRevenueGrossFlower + unboostedCycles * baseP.totalRevenueGrossFlower;
  const profitWeekNoSpice = cyclesPerWeek * baseP.profitFlower;
  const feedQtyPerCycleWith = figWith.effectiveFeedQty * figWith.qty;
  const feedQtyPerCycleBase = figBase.effectiveFeedQty * figBase.qty;
  const feedCostFlowerPerCycleWith = coinsToFlower(figWith.feedCostCoins) * figWith.qty;
  const feedCostFlowerPerCycleBase = coinsToFlower(figBase.feedCostCoins) * figBase.qty;
  const feedQtyWeek = boostedCycles * feedQtyPerCycleWith + unboostedCycles * feedQtyPerCycleBase;
  const feedCostFlowerWeek = boostedCycles * feedCostFlowerPerCycleWith + unboostedCycles * feedCostFlowerPerCycleBase;
  const totalYieldUnitsWeek = boostedCycles * figWith.totalYieldUnits * figWith.qty + unboostedCycles * figBase.totalYieldUnits * figBase.qty;
  const medicineCostFlowerPerCycleWith = figWith.medicineFlowerPerLevel * figWith.qty;
  const medicineCostFlowerPerCycleBase = figBase.medicineFlowerPerLevel * figBase.qty;
  const medicineCostFlowerWeek = boostedCycles * medicineCostFlowerPerCycleWith + unboostedCycles * medicineCostFlowerPerCycleBase;
  const consumablesCostFlowerPerCycleWith = figWith.consumablesFlowerPerLevel * figWith.qty;
  const consumablesCostFlowerWeek = boostedCycles * consumablesCostFlowerPerCycleWith;
  return {
    usingSpice: usingSpice,
    spiceActiveKey: figWith.spiceActiveKey,
    cyclesPerWeek: cyclesPerWeek,
    autoCyclesPerWeek: autoCyclesPerWeek,
    boostedCycles: boostedCycles,
    unboostedCycles: unboostedCycles,
    profitWeekWithSpice: profitWeekWithSpice,
    costWeekWithSpice: costWeekWithSpice,
    netRevenueWeekWithSpice: netRevenueWeekWithSpice,
    grossRevenueWeekWithSpice: grossRevenueWeekWithSpice,
    profitWeekNoSpice: profitWeekNoSpice,
    deltaWeek: profitWeekWithSpice - profitWeekNoSpice,
    feedQtyWeek: feedQtyWeek,
    feedCostFlowerWeek: feedCostFlowerWeek,
    totalYieldUnitsWeek: totalYieldUnitsWeek,
    medicineCostFlowerWeek: medicineCostFlowerWeek,
    consumablesCostFlowerWeek: consumablesCostFlowerWeek,
    costPerCureFlower: figWith.costPerCureFlower,
    sickHeads: figWith.sickHeads,
    spiceCostPerUseFlower: figWith.consumablesFlowerPerLevel * getSpiceLickDurationHarvests(),
    feedKey: figWith.feedKeyUsed,
    feedLabel: figWith.feedNameUsed
  };
}

function renderAnimalFeedByLevelBlock(type, currentLevel) {
  const cfg = ANIMAL_DATA[type];
  const expanded = expandedAnimalFeedByLevel.has(type);
  const active = getActiveAnimalBoosts(type);
  let feedMultTotal = 1;
  active.forEach(b => {
    if (b.feedMult) feedMultTotal *= b.feedMult;
    if (b.feedMultAll) feedMultTotal *= b.feedMultAll;
  });
  const spice = getSpiceEffectForAnimalType(type);
  feedMultTotal *= spice.feedMultAll;
  const requiredQtyPerFeed = REQUIRED_FOOD_QTY_MAP[type];
  const rows = cfg.levels.map((lvlData, idx) => {
    const level = idx + 1;
    const isCurrent = level === currentLevel;
    const feedFig = computeAnimalFeedFigures(type, level);
    const feedName = FEED_LABELS[feedFig.feedKeyUsed];
    const boostedQty = Math.max(0, feedFig.noOfFeeds * requiredQtyPerFeed * feedMultTotal);
    return `\n    <div class="lib-item-row" style="margin:0 0 3px;padding:4px 8px;${isCurrent ? "border:1.5px solid var(--sun-deep);background:var(--paper-dim);" : ""}">\n      <span class="lib-item-icon">${getIcon(feedName)}</span>\n      <div class="lib-item-main">\n        <div class="lib-item-name">Lv${level}${isCurrent ? " (current)" : ""} — ${feedName}</div>\n      </div>\n      <div class="lib-item-price">×${fmt(boostedQty)}</div>\n    </div>`;
  }).join("");
  return `\n    <div class="anim-lvl-toggle" data-anim-lvl-type="${type}" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;margin-top:8px;padding:6px 0;border-top:1px dashed var(--line);">\n      <div class="lib-section-title" style="margin:0;">🌾 Feed by Level (1–15)</div>\n      <span class="anim-lvl-chev" style="font-size:12px;color:var(--ink-soft);transition:transform .25s ease;transform:rotate(${expanded ? 180 : 0}deg);">▾</span>\n    </div>\n    <div class="anim-lvl-details" style="display:${expanded ? "block" : "none"};margin-top:4px;">\n      ${rows}\n    </div>`;
}

function attachAnimalFeedByLevelToggles(wrap) {
  wrap.querySelectorAll(".anim-lvl-toggle").forEach(el => {
    el.onclick = e => {
      e.stopPropagation();
      const type = el.getAttribute("data-anim-lvl-type");
      const details = el.nextElementSibling;
      const chev = el.querySelector(".anim-lvl-chev");
      const nowExpanded = expandedAnimalFeedByLevel.has(type) ? (expandedAnimalFeedByLevel.delete(type), 
      false) : (expandedAnimalFeedByLevel.add(type), true);
      if (details) details.style.display = nowExpanded ? "block" : "none";
      if (chev) chev.style.transform = `rotate(${nowExpanded ? 180 : 0}deg)`;
    };
  });
}

function renderAnimalFeedConsumptionBlock(type, opts) {
  const expanded = expandedAnimalFeedConsumption.has(type);
  const icon = opts.feedIcon;
  const rows = [ {
    label: "24 Hours",
    qty: opts.feedQty24h,
    cost: opts.feedCostFlower24h,
    yieldLabel: opts.yieldLabel24h
  }, {
    label: "7 Days",
    qty: opts.feedQty7d,
    cost: opts.feedCostFlower7d,
    yieldLabel: opts.yieldLabel7d
  } ].map(r => `\n    <div class="lib-item-row">\n      <span class="lib-item-icon">${icon}</span>\n      <div class="lib-item-main">\n        <div class="lib-item-name">${r.label} — ${fmt(opts.headsCount)} heads × ${opts.feedName}</div>\n        <div class="lib-item-meta">${fmt(r.qty)} ${opts.feedName} consumed${r.yieldLabel ? ` · yields ${r.yieldLabel}` : ""}</div>\n      </div>\n      <div class="lib-item-price is-flower">${fmt(r.cost)}<small>FLOWER</small></div>\n    </div>`).join("");
  return `\n    <div class="anim-feedcon-toggle" data-anim-feedcon-type="${type}" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;margin-top:8px;padding:6px 0;border-top:1px dashed var(--line);">\n      <div class="lib-section-title" style="margin:0;">${icon} Total Feed Consumed (${fmt(opts.headsCount)} heads)</div>\n      <span class="anim-feedcon-chev" style="font-size:12px;color:var(--ink-soft);transition:transform .25s ease;transform:rotate(${expanded ? 180 : 0}deg);">▾</span>\n    </div>\n    <div class="anim-feedcon-details" style="display:${expanded ? "block" : "none"};margin-top:4px;">\n      ${rows}\n    </div>`;
}

function attachAnimalFeedConsumptionToggles(wrap) {
  wrap.querySelectorAll(".anim-feedcon-toggle").forEach(el => {
    el.onclick = e => {
      e.stopPropagation();
      const type = el.getAttribute("data-anim-feedcon-type");
      const details = el.nextElementSibling;
      const chev = el.querySelector(".anim-feedcon-chev");
      const nowExpanded = expandedAnimalFeedConsumption.has(type) ? (expandedAnimalFeedConsumption.delete(type), 
      false) : (expandedAnimalFeedConsumption.add(type), true);
      if (details) details.style.display = nowExpanded ? "block" : "none";
      if (chev) chev.style.transform = `rotate(${nowExpanded ? 180 : 0}deg)`;
    };
  });
}

function renderAnimalCard(type) {
  const fig = computeAnimalTypeFigures(type);
  const qty = fig.qty;
  const totalCostFlower = coinsToFlower(fig.totalCostCoinsPerAnimal) * qty;
  let totalRevenueFlower = 0;
  let totalRevenueGrossFlower = 0;
  const productRows = fig.products.map((pname, idx) => {
    const m = marketItems.find(x => (x.name || "").toLowerCase() === pname.toLowerCase());
    const price = m ? m.flowerPrice || 0 : 0;
    const unitsPerAnimal = fig.yields[idx];
    const totalUnits = unitsPerAnimal * qty;
    const grossValue = totalUnits * price;
    const netValue = grossValue * (1 - feePercent / 100);
    totalRevenueGrossFlower += grossValue;
    totalRevenueFlower += netValue;
    return {
      pname: pname,
      price: price,
      unitsPerAnimal: unitsPerAnimal,
      totalUnits: totalUnits,
      grossValue: grossValue,
      netValue: netValue
    };
  });
  const profitFlower = totalRevenueFlower - totalCostFlower;
  const isProfit = profitFlower >= 0;
  const roi = totalCostFlower > 0 ? profitFlower / totalCostFlower * 100 : 0;
  const isExpanded = expandedAnimalCards.has(type);
  const animalDayManualCycleKey = "animal_day_" + type;
  const animalWeekManualCycleKey = "animal_week_" + type;
  const animalDayManualCycle = getManualCycleOverride(animalDayManualCycleKey);
  const animalWeekManualCycle = getManualCycleOverride(animalWeekManualCycleKey);
  const autoCyclesPerDay = ANIMAL_BASE_CYCLE_SEC / fig.cycleTimeSec;
  const cyclesPerDay = animalDayManualCycle != null ? animalDayManualCycle : autoCyclesPerDay;
  const profit24h = profitFlower * cyclesPerDay;
  const cost24h = totalCostFlower * cyclesPerDay;
  const cycleChanged = Math.abs(fig.cycleTimeSec - ANIMAL_BASE_CYCLE_SEC) > .5;
  const animalYieldLabel = productRows.map(r => `${fmt(r.totalUnits * cyclesPerDay)} ${r.pname}`).join(" · ");
  const weekly = computeAnimalWeeklyFigures(type, animalWeekManualCycle);
  const spiceLabel = fig.spiceActiveKey === "saltLick" ? "Salt Lick" : fig.spiceActiveKey === "honeyTreat" ? "Honey Treat" : null;
  const feedName = fig.feedNameUsed;
  const feedIcon = fig.feedIconUsed;
  const feedQtyPerCycleAllHeads = fig.effectiveFeedQty * qty;
  const feedCostFlowerPerCycleAllHeads = coinsToFlower(fig.feedCostCoins) * qty;
  const feedQty24h = feedQtyPerCycleAllHeads * cyclesPerDay;
  const feedCostFlower24h = feedCostFlowerPerCycleAllHeads * cyclesPerDay;
  const weeklyYieldTotalLabel = productRows.map(r => `${fmt(r.totalUnits * weekly.cyclesPerWeek)} ${r.pname}`).join(" · ");
  const cycleYieldLabel = productRows.map(r => `${fmt(r.totalUnits)} ${r.pname}`).join(" · ");
  const oneHeadYieldLabel = fig.products.map((pname, idx) => `${fmt(fig.yields[idx])} ${pname}`).join(" · ");
  const ingredientRows = fig.feedInfo.breakdown.map(row => {
    if (row.mode === "gem") {
      return `\n      <div class="lib-item-row">\n        <span class="lib-item-icon">${getIcon(row.name)}</span>\n        <div class="lib-item-main">\n          <div class="lib-item-name">${row.name} ×${fmt(row.qty)}</div>\n          <div class="lib-item-meta">Cost @ 1${GEM_ICON}/u ≈ ${fmt(row.unitCost / coinPerFlower)}${FLOWER_ICON}/u</div>\n        </div>\n        <span style="font-size:9.6px;opacity:.6;">${GEM_ICON} gem-only</span>\n      </div>`;
    }
    const displayPrice = row.mode === "buy" ? row.unitCost / coinPerFlower : row.unitCost;
    const displayUnit = row.mode === "buy" ? FLOWER_ICON : COIN_ICON;
    return `\n    <div class="lib-item-row">\n      <span class="lib-item-icon">${getIcon(row.name)}</span>\n      <div class="lib-item-main">\n        <div class="lib-item-name">${row.name} ×${fmt(row.qty)}</div>\n        <div class="lib-item-meta">${row.mode === "collect" ? "Collect" : "Buy"} @ ${fmt(displayPrice)}${displayUnit}/u</div>\n      </div>\n      <div style="display:flex;gap:2px;">\n        <button class="btn btn-ghost animal-mode-btn" data-mat="${row.name}" data-mode="collect" style="padding:4px 6px;font-size:9.6px;${row.mode === "collect" ? "border-color:var(--profit);color:var(--profit);" : ""}">Collect</button>\n        <button class="btn btn-ghost animal-mode-btn" data-mat="${row.name}" data-mode="buy" style="padding:4px 6px;font-size:9.6px;${row.mode === "buy" ? "border-color:var(--flower);color:var(--flower);" : ""}">Buy</button>\n      </div>\n    </div>`;
  }).join("");
  const productRowsHtml = `<div class="animal-detail-grid">` + productRows.map(r => renderCardProductDetailRow(getIcon(r.pname), r.pname, r.totalUnits, r.grossValue, r.grossValue - r.netValue)).join("") + `</div>`;
  return `\n  <div class="card ${isProfit ? "is-profit" : "is-loss"}${isExpanded ? " expanded" : ""}" data-search="${type}">\n    <div class="card-toggle">\n      <div class="card-name-row">\n        <span class="card-icon">${getIcon(fig.label)}</span>\n        <div>\n          <div class="card-name">${fig.label} · Lv${fig.level}</div>\n          <div class="card-type">${fmt(fig.totalCostCoinsPerAnimal)}${COIN_ICON} feed cost / animal</div>\n          <div class="card-type" style="margin-top:2px;">${feedIcon} ${fmt(qty)} heads consumes ${fmt(feedQtyPerCycleAllHeads)} ${feedName}/cycle → yields ${cycleYieldLabel}</div>\n        </div>\n      </div>\n      <div class="card-collapsed-profit">\n        ${fig.activeBoosts.length ? `<span class="boost-badge">⚡${fig.activeBoosts.length}</span>` : ""}\n        <span class="pvalue-mini ${isProfit ? "is-profit" : "is-loss"}">${isProfit ? "+" : ""}${fmt(profitFlower)} ${FLOWER_ICON} FLOWER</span>\n        <span class="chev">▾</span>\n      </div>\n    </div>\n    ${render24hBadge(profit24h, cost24h, cyclesPerDay, `${fmt(qty)} heads · ${fmt(cyclesPerDay)} cycles/day`, null, animalYieldLabel, [ `${fmt(qty)} HEADS · ${fmt(fig.effectiveFeedQty)} ${fig.feedNameUsed} EACH`, `<b>Total Cost (24H):</b> ${fmt(cost24h)} ${FLOWER_ICON} FLOWER`, `<b>Gross Revenue (24H):</b> ${fmt(totalRevenueGrossFlower * cyclesPerDay)} ${FLOWER_ICON} FLOWER${feePercent > 0 ? ` <span style="opacity:.65;">(before ${feePercent}% sell fee)</span>` : ""}`, `<b>Net Revenue (24H):</b> <span style="color:var(--flower);">${fmt(cost24h + profit24h)} ${FLOWER_ICON} FLOWER</span>${feePercent > 0 ? ` <span style="opacity:.65;">(after fee)</span>` : ""}` ])}\n    <div class="card-details">\n      <div class="lib-section-title">📦 Produce &amp; Yield${feePercent > 0 ? ` <span style="font-weight:500;opacity:.7;">(value shown after ${feePercent}% sell fee)</span>` : ""}</div>\n      ${productRowsHtml}\n      <div class="lib-section-title" style="margin-top:10px;">⏱ Per-Cycle Basics <span style="font-weight:500;opacity:.7;">(${formatDuration(fig.cycleTimeSec)}${cycleChanged ? ` — ${formatDuration(ANIMAL_BASE_CYCLE_SEC)} base` : ""} · ${fmt(qty)} heads)</span></div>\n      <div class="lib-item-row" style="margin-top:8px;">\n        <span class="lib-item-icon">${feedIcon}</span>\n        <div class="lib-item-main">\n          <div class="lib-item-name">1 head (Lv${fig.level}) consumes ${fmt(fig.effectiveFeedQty)} ${feedName}</div>\n          <div class="lib-item-meta">yields ${oneHeadYieldLabel} per cycle</div>\n        </div>\n        <div class="lib-item-price">${fmt(coinsToFlower(fig.feedCostCoins))}<small>FLOWER</small></div>\n      </div>\n      <div class="card-grid" style="margin-top:8px;">\n        <div class="stat"><span class="label">Feed cost / animal</span><span class="value">${fmt(coinsToFlower(fig.feedCostCoins))} ${FLOWER_ICON} FLOWER</span></div>\n        <div class="stat"><span class="label">Consumable Cost</span><span class="value">${fmt(fig.medicineFlowerPerLevel + fig.consumablesFlowerPerLevel)} ${FLOWER_ICON} FLOWER</span></div>\n      </div>\n      ${(() => {
    const s = getActiveShrineDailyCost(fig.activeBoosts);
    const otherCostItems24h = [];
    if (fig.medicineFlowerPerLevel > 1e-6) {
      otherCostItems24h.push({
        label: `${getIcon("Barn Delight")} Barn Delight`,
        value: fig.costPerCureFlower * fig.sickHeads * cyclesPerDay,
        note: `${fmt(fig.costPerCureFlower)} ${FLOWER_ICON}/cure × ${fmt(fig.sickHeads)} heads sick${cyclesPerDay !== 1 ? ` × ${fmt(cyclesPerDay)}/day` : ""}`
      });
    }
    if (fig.consumablesFlowerPerLevel > 1e-6) {
      const spiceCostPerUse = fig.consumablesFlowerPerLevel * 3;
      otherCostItems24h.push({
        label: `${getIcon(spiceLabel)} ${spiceLabel}`,
        value: fig.consumablesFlowerPerLevel * qty * cyclesPerDay,
        note: `${fmt(spiceCostPerUse)} ${FLOWER_ICON}/use ÷3 cycles × ${fmt(qty)} heads × ${fmt(cyclesPerDay)}/day`
      });
    }
    return renderTotalsBreakdown({
      title: "24HRS PROFIT/LOSS",
      totalYield: productRows.length === 1 ? productRows[0].totalUnits * cyclesPerDay : null,
      yieldLabel: animalYieldLabel,
      gross: totalRevenueGrossFlower * cyclesPerDay,
      baseCost: cost24h,
      restockCost: 0,
      shrineCost: s.total,
      shrineNames: s.shrines.map(x => x.name),
      sellFee: (totalRevenueGrossFlower - totalRevenueFlower) * cyclesPerDay,
      totalCycles: cyclesPerDay,
      totalCyclesSuffix: "/day",
      manualCycleKey: animalDayManualCycleKey,
      manualCycleValue: getManualCycleRawValue(animalDayManualCycleKey),
      manualCycleAuto: autoCyclesPerDay,
      manualCycleRefresh: "renderAnimalsList",
      feedQty: feedQty24h,
      feedName: feedName,
      feedIcon: feedIcon,
      headsCount: qty,
      feedCostFlower: feedCostFlower24h,
      otherCostItems: otherCostItems24h
    });
  })()}\n      ${(() => {
    const s = getActiveShrineDailyCost(fig.activeBoosts);
    const otherCostItemsWeek = [];
    if (weekly.medicineCostFlowerWeek > 1e-6) {
      otherCostItemsWeek.push({
        label: `${getIcon("Barn Delight")} Barn Delight`,
        value: weekly.medicineCostFlowerWeek,
        note: `${fmt(weekly.costPerCureFlower)} ${FLOWER_ICON}/cure × ${fmt(weekly.sickHeads)} heads sick × ${fmt(weekly.cyclesPerWeek)} cycles/wk`
      });
    }
    if (weekly.consumablesCostFlowerWeek > 1e-6) {
      otherCostItemsWeek.push({
        label: `${getIcon(spiceLabel)} ${spiceLabel}`,
        value: weekly.consumablesCostFlowerWeek,
        note: `${fmt(weekly.spiceCostPerUseFlower)} ${FLOWER_ICON}/use ÷${getSpiceLickDurationHarvests()} cycles × ${fmt(qty)} heads × ${fmt(weekly.boostedCycles)} boosted cycles`
      });
    }
    return renderTotalsBreakdown({
      title: `7 Days Total <span style="font-weight:500;opacity:.7;">(${fmt(qty)} heads)</span>`,
      totalYield: productRows.length === 1 ? productRows[0].totalUnits * weekly.cyclesPerWeek : null,
      yieldLabel: weeklyYieldTotalLabel,
      gross: weekly.grossRevenueWeekWithSpice,
      baseCost: weekly.costWeekWithSpice,
      restockCost: 0,
      shrineCost: s.total * 7,
      shrineNames: s.shrines.map(x => x.name),
      sellFee: weekly.grossRevenueWeekWithSpice - weekly.netRevenueWeekWithSpice,
      totalCycles: weekly.cyclesPerWeek,
      totalCyclesSuffix: "/week",
      manualCycleKey: animalWeekManualCycleKey,
      manualCycleValue: getManualCycleRawValue(animalWeekManualCycleKey),
      manualCycleAuto: weekly.autoCyclesPerWeek,
      manualCycleRefresh: "renderAnimalsList",
      feedQty: weekly.feedQtyWeek,
      feedName: weekly.feedLabel,
      feedIcon: getIcon(weekly.feedLabel),
      headsCount: qty,
      feedCostFlower: weekly.feedCostFlowerWeek,
      otherCostItems: otherCostItemsWeek
    });
  })()}\n      ${spiceLabel ? `<div class="stat" style="margin-top:4px;"><span class="label">vs no ${spiceLabel} (7d)</span><span class="value ${weekly.deltaWeek >= 0 ? "is-profit" : "is-loss"}">${weekly.deltaWeek >= 0 ? "+" : ""}${fmt(weekly.deltaWeek)} ${FLOWER_ICON} FLOWER</span></div>` : ""}\n      ${spiceLabel ? `<div class="field-hint" style="margin-top:6px;background:#fdf1c8;border:1.5px solid var(--sun-deep);">🧂 ${spiceLabel} only lasts <b>${getSpiceLickDurationHarvests()} harvests</b> per item — this week's ${fmt(weekly.boostedCycles)} of ${fmt(weekly.cyclesPerWeek)} cycles get the boost, the rest run at base rate. That's why 7-Day Profit isn't just 24h × 7.</div>` : ""}\n      ${renderBoostAppliedList(fig.activeBoosts)}\n      <div class="profit-banner">\n        <span class="plabel">Net Profit — per cycle</span>\n        <span><span class="pvalue ${isProfit ? "is-profit" : "is-loss"}">${isProfit ? "+" : ""}${fmt(profitFlower)} ${FLOWER_ICON} FLOWER</span>\n        <span class="proi">(${roi.toFixed(1)}% ROI)</span></span>\n      </div>\n      <div class="lib-section-title">🌾 Feed ingredients (${feedName})</div>\n      ${ingredientRows}\n      ${renderAnimalFeedConsumptionBlock(type, {
    feedName: feedName,
    feedIcon: feedIcon,
    headsCount: qty,
    feedQty24h: feedQty24h,
    feedCostFlower24h: feedCostFlower24h,
    yieldLabel24h: animalYieldLabel,
    feedQty7d: weekly.feedQtyWeek,
    feedCostFlower7d: weekly.feedCostFlowerWeek,
    yieldLabel7d: weeklyYieldTotalLabel
  })}\n      ${renderAnimalFeedByLevelBlock(type, fig.level)}\n      <div class="field-hint" style="margin-top:6px;">Set level, heads and sickness estimate in ⚡ Boosts → Plots &amp; Nodes.</div>\n    </div>\n  </div>`;
}

function renderAnimalsList() {
  const wrap = $("animalsItemList");
  if (!wrap) return;
  invalidateCostCache();
  loadBaseAnimalProduceIfNeeded();
  withPreservedCardScrolls(wrap, () => {
    wrap.innerHTML = Object.keys(ANIMAL_DATA).map(renderAnimalCard).join("");
  });
  wrap.querySelectorAll(".card-toggle, .card-24h-box").forEach(el => {
    el.onclick = () => {
      const card = el.closest(".card");
      const type = card.dataset.search;
      if (expandedAnimalCards.has(type)) expandedAnimalCards.delete(type); else expandedAnimalCards.add(type);
      card.classList.toggle("expanded");
    };
  });
  wrap.querySelectorAll(".animal-mode-btn").forEach(btn => {
    btn.onclick = e => {
      e.stopPropagation();
      setMaterialMode("AnimalFeed", btn.dataset.mat, btn.dataset.mode);
      withPreservedScroll(wrap, renderAnimalsList);
    };
  });
  attachAnimalFeedByLevelToggles(wrap);
  attachAnimalFeedConsumptionToggles(wrap);
}

function syncToolMarketEntry(tool) {
  const name = tool.producesName || tool.name;
  const idx = marketItems.findIndex(m => String(m.id) === String(tool.id));
  if (idx >= 0) {
    marketItems[idx].name = name;
  } else {
    marketItems.push({
      id: tool.id,
      name: name,
      flowerPrice: 0
    });
  }
  saveMarketState();
  autoFillLivePricesForNewEntries();
}

function removeToolMarketEntry(toolId) {
  marketItems = marketItems.filter(m => String(m.id) !== String(toolId));
  saveMarketState();
}

