const SFL_PROXY_BASE = "https://sfl-proxy.bossweki.workers.dev/proxy";

const SFL_PRICE_API = SFL_PROXY_BASE + "/api/v1/prices";

const SFL_NFT_PRICE_API = SFL_PROXY_BASE + "/api/v1/nfts";

let livePrices = safeLSJSON(localStorage.getItem("hl_live_prices"), {});

let livePricesUpdatedAt = parseInt(localStorage.getItem("hl_live_prices_updated") || "0") || null;

let liveNftPrices = safeLSJSON(localStorage.getItem("hl_live_nft_prices"), {});

let liveSyncInFlight = false;

function normalizeItemName(name) {
  return (name || "").trim().toLowerCase().replace(/\bseeds?\b/g, "").replace(/\bcrop\b/g, "").replace(/\bfruit\b/g, "").replace(/[^a-z0-9]/g, "");
}

const _priceIndexCache = new WeakMap();

function getPoolIndex(pool) {
  let idx = _priceIndexCache.get(pool);
  if (idx) return idx;
  const exact = new Map();
  const norm = new Map();
  Object.keys(pool).forEach(k => {
    const lower = k.trim().toLowerCase();
    if (!exact.has(lower)) exact.set(lower, k);
    const n = normalizeItemName(k);
    if (n && !norm.has(n)) norm.set(n, k);
  });
  idx = { exact: exact, norm: norm };
  _priceIndexCache.set(pool, idx);
  return idx;
}

function findPriceInPool(pool, name) {
  if (!name) return null;
  const isRealPrice = v => typeof v === "number" && isFinite(v) && v > 0;
  if (isRealPrice(pool[name])) return pool[name];
  const idx = getPoolIndex(pool);
  const lower = name.trim().toLowerCase();
  const exactKey = idx.exact.get(lower);
  if (exactKey != null && isRealPrice(pool[exactKey])) return pool[exactKey];
  const target = normalizeItemName(name);
  if (!target) return null;
  const fuzzyKey = idx.norm.get(target);
  return fuzzyKey != null && isRealPrice(pool[fuzzyKey]) ? pool[fuzzyKey] : null;
}

function findLivePriceForName(name) {
  return findPriceInPool(livePrices, name);
}

function findLiveNftPriceForName(name) {
  return findPriceInPool(liveNftPrices, name);
}

function findLivePriceForItem(m) {
  if (m && (m.isNftCollectible || m.isWearable)) return findLiveNftPriceForName(m.name);
  return findLivePriceForName(m.name);
}

function timeAgo(ts) {
  if (!ts) return "never";
  const diffMs = Date.now() - ts;
  const mins = Math.floor(diffMs / 6e4);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins} min ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  return `${Math.floor(hrs / 24)}d ago`;
}

function updateLiveSyncStatus() {
  const count = Object.keys(livePrices).length + Object.keys(liveNftPrices).length;
  const el = $("liveSyncStatus");
  if (!count) {
    el.innerHTML = `⚠️ No live prices loaded yet. Tap Sync, or paste the API response below.`;
    return;
  }
  if (!marketItems.length) {
    el.innerHTML = `✅ <b>${count}</b> live prices loaded · updated ${timeAgo(livePricesUpdatedAt)} · add a seed/tool/animal to your library to start matching them`;
    return;
  }
  const matched = marketItems.filter(m => findLivePriceForItem(m) != null).length;
  el.innerHTML = `✅ <b>${count}</b> live prices loaded · updated ${timeAgo(livePricesUpdatedAt)} · matching <b>${matched}/${marketItems.length}</b> of your items`;
}

function setLivePrices(p2p, updatedAt, nft) {
  livePrices = p2p || {};
  livePricesUpdatedAt = updatedAt || Date.now();
  localStorage.setItem("hl_live_prices", JSON.stringify(livePrices));
  localStorage.setItem("hl_live_prices_updated", String(livePricesUpdatedAt));
  if (nft) {
    liveNftPrices = nft;
    localStorage.setItem("hl_live_nft_prices", JSON.stringify(liveNftPrices));
  }
  if (typeof __profileTradableRowsCacheG !== "undefined") {
    __profileTradableRowsCacheG = null;
    __profileTradableRowsCacheByTab = {};
  }
  updateLiveSyncStatus();
  if (typeof renderBettyShop === "function") renderBettyShop();
}

function applyLivePricesToMarket(overwriteExisting) {
  let updated = 0;
  const unmatched = [];
  marketItems.forEach(m => {
    const price = findLivePriceForItem(m);
    if (price == null) {
      unmatched.push(m.name);
      return;
    }
    if (overwriteExisting || !m.flowerPrice) {
      m.flowerPrice = price;
      updated++;
    }
  });
  if (updated) {
    saveMarketState();
    renderMarketList();
    renderCropsList();
    renderFruitsList();
    renderGreenhouseList();
    renderHoneyList();
    if (typeof renderCookingPanel === "function") renderCookingPanel();
    updateCalcSummary();
  }
  if (unmatched.length) console.warn("Goblin Calculator: no live price match for:", unmatched);
  return {
    updated: updated,
    total: marketItems.length,
    unmatched: unmatched
  };
}

function autoFillLivePricesForNewEntries() {
  if (!Object.keys(livePrices).length && !Object.keys(liveNftPrices).length) return;
  applyLivePricesToMarket(false);
}

async function fetchNftFloorPrices() {
  const res = await fetch(SFL_NFT_PRICE_API, {
    cache: "no-store"
  });
  if (!res.ok) throw new Error("Bad response " + res.status);
  const json = await res.json();
  const out = {};
  const collectGroup = list => {
    (list || []).forEach(item => {
      if (item && typeof item.name === "string" && item.name.trim() && typeof item.floor === "number" && item.floor > 0) {
        out[item.name] = item.floor;
      }
    });
  };
  collectGroup(json && json.collectibles);
  collectGroup(json && json.wearables);
  return out;
}

async function fetchLivePrices() {
  const res = await fetch(SFL_PRICE_API, {
    cache: "no-store"
  });
  if (!res.ok) throw new Error("Bad response " + res.status);
  const json = await res.json();
  const p2p = json && json.data && json.data.p2p || {};
  const updatedAt = json && json.updatedAt || Date.now();
  let nftPrices = {};
  try {
    nftPrices = await fetchNftFloorPrices();
  } catch (e) {
    console.warn("NFT price fetch failed:", e);
  }
  return {
    p2p: p2p,
    nft: nftPrices,
    updatedAt: updatedAt
  };
}

async function performLiveSync() {
  if (liveSyncInFlight) return null;
  liveSyncInFlight = true;
  const btns = document.querySelectorAll(".js-sync-live-prices-btn");
  btns.forEach((btn) => {
    btn.classList.add("is-loading");
    btn.textContent = "🔄 Syncing...";
  });
  try {
    const {p2p: p2p, nft: nft, updatedAt: updatedAt} = await fetchLivePrices();
    setLivePrices(p2p, updatedAt, nft);
    const result = applyLivePricesToMarket(true);
    return {
      ok: true,
      result: result
    };
  } catch (e) {
    console.error("Live price sync failed:", e);
    return {
      ok: false,
      error: e
    };
  } finally {
    liveSyncInFlight = false;
    btns.forEach((btn) => {
      btn.classList.remove("is-loading");
      btn.textContent = "🔄 Sync live prices";
    });
  }
}

$("syncLivePricesBtn").onclick = async () => {
  const r = await performLiveSync();
  if (!r) return;
  if (r.ok) toast(describeSyncResult(r.result)); else toast("⚠️ Couldn't reach sfl.world directly (blocked by file:// or CORS). Try the paste option below.");
};

if ($("tradeShopSyncBtn")) {
  $("tradeShopSyncBtn").onclick = async () => {
    const r = await performLiveSync();
    if (!r) return;
    if (r.ok) toast(describeSyncResult(r.result)); else toast("⚠️ Couldn't reach sfl.world directly (blocked by file:// or CORS). Try the paste option below.");
  };
}

performLiveSync();

$("livePasteToggleBtn").onclick = () => {
  $("livePasteWrap").classList.toggle("show");
};

$("livePasteImportBtn").onclick = () => {
  const raw = $("livePasteInput").value.trim();
  if (!raw) {
    toast("Paste the JSON response first 📋");
    return;
  }
  try {
    const json = JSON.parse(raw);
    const p2p = json && json.data && json.data.p2p || json.p2p || json;
    if (!p2p || typeof p2p !== "object" || !Object.keys(p2p).length) {
      toast("Couldn't find price data in that JSON ⚠️");
      return;
    }
    const updatedAt = json && json.updatedAt || Date.now();
    setLivePrices(p2p, updatedAt);
    const result = applyLivePricesToMarket(true);
    toast(describeSyncResult(result, true));
    $("livePasteInput").value = "";
    $("livePasteWrap").classList.remove("show");
  } catch (e) {
    console.error("Paste JSON parse error:", e);
    toast("Invalid JSON: " + e.message);
  }
};

function describeSyncResult(result, isImport) {
  const verb = isImport ? "Imported" : "Synced";
  if (result.total === 0) {
    return `${verb} ${Object.keys(livePrices).length} live prices, but your Marketplace is empty — add a seed/tool/animal to your library first, then sync again.`;
  }
  if (result.updated === 0) {
    const sample = result.unmatched.slice(0, 3).join(", ");
    return `${verb}, but 0 of ${result.total} of your items matched by name. Check your library's "produces" names match sfl.world exactly (e.g. "Corn" not "Corn Seed"). Unmatched: ${sample}${result.unmatched.length > 3 ? "..." : ""}`;
  }
  return `${verb} ${result.updated} of ${result.total} live prices 💰`;
}

async function initLivePricesOnLoad() {
  updateLiveSyncStatus();
  if (Object.keys(livePrices).length) applyLivePricesToMarket(false);
  try {
    const {p2p: p2p, nft: nft, updatedAt: updatedAt} = await fetchLivePrices();
    setLivePrices(p2p, updatedAt, nft);
    autoFillLivePricesForNewEntries();
  } catch (e) {
    console.warn("Background live price fetch failed (likely CORS):", e);
  }
}

const SFL_LAND_API_BASE = SFL_PROXY_BASE + "/api/v1.1/land/";

const SFL_LAND_INFO_BASE = SFL_PROXY_BASE + "/api/v1/land/info/farm_id/";

const FARM_SYNC_FETCH_TIMEOUT_MS = 2e4;

async function fetchWithTimeout(url, options, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs || FARM_SYNC_FETCH_TIMEOUT_MS);
  try {
    return await fetch(url, Object.assign({}, options, {
      signal: controller.signal
    }));
  } catch (e) {
    if (e && e.name === "AbortError") throw new Error("Request timed out — the server took too long to respond");
    throw e;
  } finally {
    clearTimeout(timer);
  }
}

async function fetchFarmUsername(farmId) {
  try {
    const res = await fetchWithTimeout(SFL_LAND_INFO_BASE + encodeURIComponent(farmId), {
      cache: "no-store"
    });
    if (!res.ok) return null;
    const json = await res.json();
    const name = json && (json.username || json.Username || json.name || json.data && (json.data.username || json.data.name));
    return typeof name === "string" && name.trim() ? name.trim() : null;
  } catch (e) {
    console.warn("Land info (username) lookup failed — non-fatal:", e);
    return null;
  }
}

let farmPanelSyncInFlight = false;

async function fetchFarmSnapshotRaw(farmId) {
  const res = await fetchWithTimeout(SFL_LAND_API_BASE + encodeURIComponent(farmId), {
    cache: "no-store"
  });
  if (!res.ok) throw new Error("Bad response " + res.status);
  return await res.json();
}

const SFL_COMMUNITY_PROXY_BASE = "https://sfl-community-proxy.bossweki.workers.dev/";

const SFL_COMMUNITY_API_BASE = SFL_COMMUNITY_PROXY_BASE + "community/farms/";

async function fetchCommunityFarmData(farmId) {
  if (SFL_COMMUNITY_PROXY_BASE.includes("REPLACE-ME")) {
    throw new Error("Proxy not deployed yet — see sfl-community-proxy-worker.js");
  }
  const res = await fetchWithTimeout(SFL_COMMUNITY_API_BASE + encodeURIComponent(farmId), {
    cache: "no-store"
  });
  let json = null;
  try {
    json = await res.json();
  } catch (e) {}
  if (!res.ok) {
    const msg = json && json.error ? json.error : `Bad response ${res.status}`;
    throw new Error(msg);
  }
  return json;
}

function farmSyncExtractGameState(json) {
  if (!json || typeof json !== "object") return {};
  return json.game || json.farm || json.gameState || json.state || json.data && (json.data.game || json.data.farm || json.data.gameState) || json;
}

function farmSyncGetApiUsername(farmId) {
  const map = safeLSJSON(localStorage.getItem("hl_farm_api_names"), {});
  return map[farmId] || null;
}

function farmSyncSetApiUsername(farmId, name) {
  const map = safeLSJSON(localStorage.getItem("hl_farm_api_names"), {});
  if (name) {
    map[farmId] = name;
  } else {
    delete map[farmId];
  }
  localStorage.setItem("hl_farm_api_names", JSON.stringify(map));
}

function farmSyncGetBumpkinLevel(json, g) {
  const b = g && g.bumpkin;
  if (b) {
    if (typeof b.level === "number") return b.level;
    if (typeof b.level === "string" && b.level.trim() && !isNaN(Number(b.level))) return Number(b.level);
  }
  if (json && typeof json.level === "number") return json.level;
  return null;
}

function farmSyncGetAscensionLevel(json, g) {
  const raw = g && g.island && g.island.ascensionLevel;
  const n = Number(raw);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 0;
}

function farmSyncGetBumpkinExperience(json, g) {
  const raw = g && g.bumpkin && g.bumpkin.experience;
  const n = Number(raw);
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

function farmPanelGetLastInfo() {
  return {
    id: localStorage.getItem("hl_farm_panel_id") || "",
    level: localStorage.getItem("hl_farm_panel_level") || "",
    experience: parseFloat(localStorage.getItem("hl_farm_panel_experience")) || 0,
    ascensionLevel: parseInt(localStorage.getItem("hl_farm_panel_ascension_level"), 10) || 0,
    time: parseFloat(localStorage.getItem("hl_farm_panel_time")) || 0,
    vipActive: localStorage.getItem("hl_farm_panel_vip_active") === "1",
    vipExpiresAt: parseFloat(localStorage.getItem("hl_farm_panel_vip_expires")) || null,
    vipLifetime: localStorage.getItem("hl_farm_panel_vip_lifetime") === "1",
    factionName: localStorage.getItem("hl_farm_panel_faction_name") || null,
    factionIsMember: localStorage.getItem("hl_farm_panel_faction_is_member") === "1",
    factionHasPetData: localStorage.getItem("hl_farm_panel_faction_has_pet") === "1",
    factionTotalXP: parseFloat(localStorage.getItem("hl_farm_panel_faction_total_xp")) || 0,
    factionGoalXP: parseFloat(localStorage.getItem("hl_farm_panel_faction_goal_xp")) || 0,
    factionStreak: parseInt(localStorage.getItem("hl_farm_panel_faction_streak"), 10) || 0,
    factionIsContributing: localStorage.getItem("hl_farm_panel_faction_is_contributing") === "1"
  };
}

function farmPanelSaveLastInfo(id, level, vipStatus, factionInfo, experience, ascensionLevel) {
  localStorage.setItem("hl_farm_panel_id", id);
  localStorage.setItem("hl_farm_panel_level", level != null ? String(level) : "");
  localStorage.setItem("hl_farm_panel_experience", experience != null ? String(experience) : "");
  localStorage.setItem("hl_farm_panel_ascension_level", ascensionLevel != null ? String(ascensionLevel) : "0");
  localStorage.setItem("hl_farm_panel_time", String(Date.now()));
  localStorage.setItem("hl_farm_panel_vip_active", vipStatus && vipStatus.active ? "1" : "0");
  localStorage.setItem("hl_farm_panel_vip_expires", vipStatus && vipStatus.expiresAt != null ? String(vipStatus.expiresAt) : "");
  localStorage.setItem("hl_farm_panel_vip_lifetime", vipStatus && vipStatus.lifetime ? "1" : "0");
  const fi = factionInfo || {};
  localStorage.setItem("hl_farm_panel_faction_name", fi.factionName || "");
  localStorage.setItem("hl_farm_panel_faction_is_member", fi.isMember ? "1" : "0");
  localStorage.setItem("hl_farm_panel_faction_has_pet", fi.hasPetData ? "1" : "0");
  localStorage.setItem("hl_farm_panel_faction_total_xp", String(fi.totalXP || 0));
  localStorage.setItem("hl_farm_panel_faction_goal_xp", String(fi.goalXP || 0));
  localStorage.setItem("hl_farm_panel_faction_streak", String(fi.streak || 0));
  localStorage.setItem("hl_farm_panel_faction_is_contributing", fi.isContributingMember ? "1" : "0");
  if (fi.hasPetData) {
    localStorage.setItem("hl_faction_pet_week_streak", String(fi.streak || 0));
  }
}

function renderFarmPanelInfo() {
  const {id: id, level: level, time: time, vipActive: vipActive, vipExpiresAt: vipExpiresAt, vipLifetime: vipLifetime, factionName: factionName, factionIsMember: factionIsMember, experience: experience, ascensionLevel: ascensionLevel} = farmPanelGetLastInfo();
  const displayName = id ? farmSyncGetApiUsername(id) : null;
  $("farmPanelName").textContent = displayName ? displayName.toUpperCase() : id ? `Farm #${id}` : "No farm synced";
  $("farmPanelId").textContent = `Farm Id: ${id || "—"}`;
  if (!id) {
    $("farmPanelLevel").textContent = "Bumpkin Level: —";
  } else {
    const levelInfo = cookGetLevelInfo(experience);
    $("farmPanelLevel").textContent = levelInfo.isMax ? `Bumpkin Level: ${level || levelInfo.level} (MAX)` : `Bumpkin Level: ${level || levelInfo.level} — ${fmt(levelInfo.progress)} XP/${fmt(levelInfo.span)} XP`;
  }
  const ascEl = $("farmPanelAscension");
  if (ascEl) {
    if (!id) {
      ascEl.textContent = "Ascension [0]";
    } else {
      const ascInfo = getAscensionLevelInfo(experience, ascensionLevel);
      const badgeText = ascensionLevelBadgeText(ascensionLevel, ascInfo.level, ascInfo.isReadyToAscend);
      ascEl.textContent = ascensionLevel && !ascInfo.isReadyToAscend ? `${badgeText} — ${fmt(ascInfo.currentExperienceProgress)} XP/${fmt(ascInfo.experienceToNextLevel)} XP` : badgeText;
    }
  }
  const factionEl = $("farmPanelFaction");
  if (factionEl) {
    if (!id) {
      factionEl.innerHTML = `Faction: —`;
    } else if (factionIsMember && factionName && FACTION_BANNER_ICONS[factionName]) {
      factionEl.innerHTML = `Faction: <img class="farm-panel-faction-icon" src="${FACTION_BANNER_ICONS[factionName]}" alt="${escapeHtml(FACTION_DISPLAY_NAMES[factionName])}"> ${escapeHtml(FACTION_DISPLAY_NAMES[factionName])}`;
    } else {
      factionEl.innerHTML = `Faction: No Faction`;
    }
  }
  const vipEl = $("farmPanelVip");
  if (vipEl) {
    if (!id) {
      vipEl.textContent = "";
    } else if (vipActive) {
      const expiryNote = vipLifetime ? ` (Lifetime)` : vipExpiresAt ? ` (until ${new Date(vipExpiresAt).toLocaleDateString()})` : "";
      vipEl.textContent = `👑 VIP Access active${expiryNote}`;
      vipEl.style.color = "var(--profit)";
    } else {
      vipEl.textContent = "No active VIP";
      vipEl.style.color = "var(--ink-soft)";
    }
  }
  $("farmPanelStatus").textContent = time ? `Last synced ${new Date(time).toLocaleString()}` : "Not synced yet";
  if (typeof renderFactionPetHeader === "function") renderFactionPetHeader();
}

function applyFarmSkillsOnly(json, fallbackJson) {
  let g = farmSyncExtractGameState(json);
  const gFallback = fallbackJson ? farmSyncExtractGameState(fallbackJson) : null;
  if (gFallback) {
    const primaryAsc = farmSyncGetAscensionLevel(json, g);
    const fallbackAsc = farmSyncGetAscensionLevel(fallbackJson, gFallback);
    if (fallbackAsc > primaryAsc) g = gFallback;
  }
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const skillsFallback = gFallback && gFallback.bumpkin && asObj(gFallback.bumpkin.skills) || null;
  const skillsPrimary = g.bumpkin && asObj(g.bumpkin.skills);
  const skills = skillsPrimary || skillsFallback ? {
    ...(skillsFallback || {}),
    ...(skillsPrimary || {})
  } : null;
  let matched = 0;
  if (skills) {
    const freshSkillIds = [];
    const freshRanks = {};
    const freshLevels = {};
    Object.keys(skills).forEach(sn => {
      const norm = sn.trim().toLowerCase();
      const skill = SKILL_BOOSTS.find(s => s.name.trim().toLowerCase() === norm);
      if (!skill) return;
      if (!freshSkillIds.includes(skill.id)) freshSkillIds.push(skill.id);
      const rawLevel = Number(skills[sn]);
      if (Number.isFinite(rawLevel) && rawLevel >= 1) {
        freshLevels[skill.id] = Math.min(Math.max(Math.round(rawLevel), 1), 3);
      }
      if (ASCENSION_RANK_DATA[skill.id] && Number.isFinite(rawLevel) && rawLevel > 1) {
        freshRanks[skill.id] = Math.min(Math.max(Math.round(rawLevel), 1), 3);
      }
    });
    matched = freshSkillIds.length;
    syncedSkillLevels = freshLevels;
    saveSyncedSkillLevels();
    __lastSkillsSig = JSON.stringify([ freshSkillIds.slice().sort(), freshRanks ]);
    const toAddSkills = freshSkillIds.filter(id => !selectedSkills.includes(id));
    const toRemoveSkills = selectedSkills.filter(id => !freshSkillIds.includes(id) && SKILL_BOOSTS.some(s => s.id === id));
    const skillsChanged = toAddSkills.length > 0 || toRemoveSkills.length > 0;
    if (skillsChanged) {
      const dropSet = new Set(toRemoveSkills);
      selectedSkills = selectedSkills.filter(id => !dropSet.has(id)).concat(toAddSkills);
      saveSkillState();
    }
    const ranksChanged = JSON.stringify(ascensionRanks) !== JSON.stringify(freshRanks);
    if (ranksChanged) {
      ascensionRanks = freshRanks;
      saveAscensionState();
    }
    if (skillsChanged || ranksChanged) {
      __saveSyncSigs();
      applyAscensionRanks();
      if (typeof applySkillModifiers === "function") applySkillModifiers();
      if (typeof resetSkillDraftFromSaved === "function") resetSkillDraftFromSaved();
      if (typeof renderSkillPanel === "function") renderSkillPanel();
      if (typeof renderBoostPanel === "function") renderBoostPanel();
      if (typeof renderAscensionBar === "function") renderAscensionBar();
      if (typeof updateCalcSummary === "function") updateCalcSummary();
    } else if (typeof renderSkillPanel === "function") {
      renderSkillPanel();
    }
  }
  return {
    matched: matched,
    level: farmSyncGetBumpkinLevel(json, g),
    experience: farmSyncGetBumpkinExperience(json, g),
    ascensionLevel: farmSyncGetAscensionLevel(json, g)
  };
}

function farmSyncGetInteriorBagSources(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const home = asObj(g && g.home);
  const interior = asObj(g && g.interior);
  const levels = interior ? Object.keys(interior).map(k => asObj(interior[k])) : [];
  return [ home ].concat(levels).filter(Boolean);
}

function farmSyncGetInteriorCollectiblesMerged(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const merged = {};
  farmSyncGetInteriorBagSources(g).forEach(bagSource => {
    const bag = asObj(bagSource.collectibles != null ? bagSource.collectibles : bagSource.land && bagSource.land.collectibles);
    if (!bag) return;
    Object.entries(bag).forEach(([name, arr]) => {
      if (!Array.isArray(arr)) return;
      merged[name] = (merged[name] || []).concat(arr);
    });
  });
  return merged;
}

const INVENTORY_OWNED_BOOST_NAMES = [ "Green Amulet", "Coder", "Gold Rush", "Prospector", "Wrangler", "Barn Manager", "Seed Specialist", "Lumberjack", "Logger", "Discord Mod", "Artist" ];

function farmSyncCollectEquippedAndPlacedNames(g) {
  const names = new Set;
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const addEquippedFrom = bumpkin => {
    const equipped = bumpkin && asObj(bumpkin.equipped);
    if (!equipped) return;
    Object.values(equipped).forEach(v => {
      if (typeof v === "string" && v.trim()) names.add(v.trim());
    });
  };
  addEquippedFrom(g && g.bumpkin);
  const farmHands = g && g.farmHands;
  const farmHandsBumpkins = farmHands && (asObj(farmHands.bumpkins) || (Array.isArray(farmHands.bumpkins) ? farmHands.bumpkins : null));
  if (farmHandsBumpkins) {
    const list = Array.isArray(farmHandsBumpkins) ? farmHandsBumpkins : Object.values(farmHandsBumpkins);
    list.forEach(addEquippedFrom);
  } else if (Array.isArray(farmHands)) {
    farmHands.forEach(addEquippedFrom);
  } else if (asObj(farmHands) && !("bumpkins" in farmHands)) {
    Object.values(farmHands).forEach(addEquippedFrom);
  }
  const home = g && asObj(g.home);
  [ g, home ].concat(farmSyncGetInteriorBagSources(g)).forEach(bagSource => {
    if (!bagSource) return;
    [ "collectibles", "buildings" ].forEach(key => {
      const bag = asObj(bagSource[key] != null ? bagSource[key] : bagSource.land && bagSource.land[key]);
      if (!bag) return;
      Object.entries(bag).forEach(([name, arr]) => {
        if (!Array.isArray(arr) || !arr.length) return;
        const stillPlaced = arr.some(inst => {
          if (!inst || typeof inst !== "object") return true;
          const readyAt = typeof inst.readyAt === "number" ? inst.readyAt : 0;
          return readyAt <= Date.now() && !!inst.coordinates && !inst.used;
        });
        if (stillPlaced) names.add(name);
      });
    });
  });
  const inv = asObj(g && g.inventory);
  if (inv) {
    INVENTORY_OWNED_BOOST_NAMES.forEach(name => {
      const raw = inv[name];
      const qty = typeof raw === "string" ? parseFloat(raw) : Number(raw);
      if (!isNaN(qty) && qty > 0) names.add(name);
    });
  }
  return names;
}

function farmSyncHasLifetimeFarmerBanner(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const home = g && asObj(g.home);
  for (const bagSource of [ g, home ].concat(farmSyncGetInteriorBagSources(g))) {
    if (!bagSource) continue;
    const bag = asObj(bagSource.collectibles != null ? bagSource.collectibles : bagSource.land && bagSource.land.collectibles);
    const arr = bag && bag["Lifetime Farmer Banner"];
    if (!Array.isArray(arr)) continue;
    if (arr.some(inst => !inst || typeof inst !== "object" || !inst.removedAt)) return true;
  }
  return false;
}

function farmSyncGetVipStatus(g) {
  if (farmSyncHasLifetimeFarmerBanner(g)) return {
    active: true,
    expiresAt: null,
    lifetime: true
  };
  const expiresAt = g && g.vip && typeof g.vip.expiresAt === "number" ? g.vip.expiresAt : null;
  const active = expiresAt != null && expiresAt > Date.now();
  return {
    active: active,
    expiresAt: expiresAt,
    lifetime: false
  };
}

const TRADING_SHRINE_COOLDOWN_MS = 30 * 24 * 60 * 60 * 1e3;

function farmSyncIsTradingShrineActive(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const home = g && asObj(g.home);
  const now = Date.now();
  for (const bagSource of [ g, home ].concat(farmSyncGetInteriorBagSources(g))) {
    if (!bagSource) continue;
    const bag = asObj(bagSource.collectibles != null ? bagSource.collectibles : bagSource.land && bagSource.land.collectibles);
    const arr = bag && bag["Trading Shrine"];
    if (!Array.isArray(arr)) continue;
    for (const inst of arr) {
      if (!inst || typeof inst !== "object" || inst.removedAt) continue;
      const createdAt = typeof inst.createdAt === "number" ? inst.createdAt : 0;
      if (createdAt + TRADING_SHRINE_COOLDOWN_MS > now) return true;
    }
  }
  return false;
}

function farmSyncGetLimitedTimeBoostStatus(g, name, durationMs) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const status = {
    quantity: 0,
    activeCount: 0,
    remainingMs: 0
  };
  if (!g) return status;
  const now = Date.now();
  const inv = asObj(farmPanelField(g, "inventory"));
  if (inv && inv[name] != null) {
    const q = typeof inv[name] === "string" ? parseFloat(inv[name]) : Number(inv[name]);
    if (!isNaN(q)) status.quantity = q;
  }
  const home = asObj(g.home);
  for (const bagSource of [ g, home ].concat(farmSyncGetInteriorBagSources(g))) {
    if (!bagSource) continue;
    const bag = asObj(bagSource.collectibles != null ? bagSource.collectibles : bagSource.land && bagSource.land.collectibles);
    const arr = bag && bag[name];
    if (!Array.isArray(arr)) continue;
    for (const inst of arr) {
      if (!inst || typeof inst !== "object" || inst.removedAt) continue;
      const createdAt = typeof inst.createdAt === "number" ? inst.createdAt : 0;
      const remaining = createdAt + durationMs - now;
      if (remaining > 0) {
        status.activeCount++;
        if (remaining > status.remainingMs) status.remainingMs = remaining;
      }
    }
  }
  return status;
}

function farmSyncGetResourceFeePercent(g) {
  const islandType = g && g.island && typeof g.island.type === "string" ? g.island.type : null;
  if (!islandType || !(islandType in ISLAND_RESOURCE_TAXES)) return null;
  let tax = ISLAND_RESOURCE_TAXES[islandType];
  if (farmSyncGetVipStatus(g).active) tax *= .5;
  if (farmSyncIsTradingShrineActive(g)) tax -= .025;
  tax = Math.max(0, tax);
  return Math.round(tax * 1e4) / 100;
}

function applyFarmFeeOnly(json) {
  const g = farmSyncExtractGameState(json);
  const detected = farmSyncGetResourceFeePercent(g);
  if (detected == null) return {
    applied: false,
    feePercent: null,
    changed: false
  };
  __lastFeeSig = String(detected);
  if (detected === feePercent) return {
    applied: true,
    feePercent: detected,
    changed: false
  };
  __saveSyncSigs();
  feePercent = detected;
  if ($("feeInput")) $("feeInput").value = feePercent;
  if (typeof saveState === "function") saveState();
  if (typeof updateSettingsSummary === "function") updateSettingsSummary();
  return {
    applied: true,
    feePercent: feePercent,
    changed: true
  };
}

