const FACTION_QUIVER_NAMES = [ "Sunflorian Quiver", "Bumpkin Quiver", "Goblin Quiver", "Nightshade Quiver" ];

const FACTION_SHIELD_NAMES = [ "Sunflorian Shield", "Bumpkin Shield", "Goblin Shield", "Nightshade Shield" ];

const FACTION_MEDALLION_NAMES = [ "Sunflorian Medallion", "Bumpkin Medallion", "Goblin Medallion", "Nightshade Medallion" ];

const FACTION_QUIVER_BOOST_IDS = [ "faction_wings", "faction_quiver", "faction_quiver_greenhouse" ];

const FACTION_SHIELD_BOOST_IDS = [ "faction_shield_res" ];

const FACTION_MEDALLION_BOOST_IDS = [ "faction_medallion_cook" ];

function applyFarmAnimalAffectionToolsOnly(json) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const g = farmSyncExtractGameState(json);
  const inv = asObj(g && g.inventory) || {};
  let changed = false;
  Object.keys(ANIMAL_LOVE_TOOL_LABELS).forEach(key => {
    const label = ANIMAL_LOVE_TOOL_LABELS[key];
    const qty = parseFloat(inv[label]) || 0;
    const owned = qty > 0;
    if (animalAffectionTools[key] !== owned) changed = true;
    animalAffectionTools[key] = owned;
  });
  if (changed) saveAnimalAffectionTools();
  return {
    ok: true,
    changed: changed,
    tools: Object.assign({}, animalAffectionTools)
  };
}

function applyFarmGreenThumbLegacyOnly(json) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const g = farmSyncExtractGameState(json);
  const inv = asObj(g && g.inventory) || {};
  const raw = inv["Green Thumb"];
  const qty = typeof raw === "string" ? parseFloat(raw) : Number(raw);
  const owned = !isNaN(qty) && qty > 0;
  const changed = bettyGreenThumbOn !== owned;
  if (changed) {
    bettyGreenThumbOn = owned;
    localStorage.setItem("hl_betty_green_thumb", JSON.stringify(bettyGreenThumbOn));
    if ($("bettyGreenThumbToggle")) $("bettyGreenThumbToggle").classList.toggle("on", bettyGreenThumbOn);
    if (typeof renderBettyShop === "function") renderBettyShop();
  }
  return {
    ok: true,
    changed: changed,
    owned: owned
  };
}

function applyFarmBoostsOnly(json) {
  const g = farmSyncExtractGameState(json);
  farmSyncRefreshLimitedBoostActiveState(g);
  const placedNames = farmSyncCollectEquippedAndPlacedNames(g);
  const normPlaced = new Set(Array.from(placedNames, n => n.trim().toLowerCase()));
  const freshBoostIds = [];
  BOOSTS.forEach(b => {
    if (b.source === "skill") return;
    if (b.limitedBoostName) {
      if (getLimitedBoostRemainingSec(b.limitedBoostName) > 0 && !freshBoostIds.includes(b.id)) freshBoostIds.push(b.id);
      return;
    }
    const bareName = (b.name || "").replace(/\s*\([^)]*\)\s*$/, "").trim().toLowerCase();
    if (bareName && normPlaced.has(bareName) && !freshBoostIds.includes(b.id)) freshBoostIds.push(b.id);
  });
  const hasFactionQuiver = FACTION_QUIVER_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  if (hasFactionQuiver) {
    FACTION_QUIVER_BOOST_IDS.forEach(id => {
      if (!freshBoostIds.includes(id)) freshBoostIds.push(id);
    });
  }
  const hasFactionShield = FACTION_SHIELD_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  if (hasFactionShield) {
    FACTION_SHIELD_BOOST_IDS.forEach(id => {
      if (!freshBoostIds.includes(id)) freshBoostIds.push(id);
    });
  }
  const hasFactionMedallion = FACTION_MEDALLION_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  if (hasFactionMedallion) {
    FACTION_MEDALLION_BOOST_IDS.forEach(id => {
      if (!freshBoostIds.includes(id)) freshBoostIds.push(id);
    });
  }
  const vipStatus = farmSyncGetVipStatus(g);
  const ISLAND_PROGRESSION_ORDER = [ "basic", "spring", "desert", "volcano", "swamp", "spooky", "crystal", "galaxy", "marble" ];
  const syncedIslandType = g && g.island && typeof g.island.type === "string" ? g.island.type : null;
  const syncedIslandIndex = syncedIslandType ? ISLAND_PROGRESSION_ORDER.indexOf(syncedIslandType) : -1;
  const hasReachedVolcano = syncedIslandIndex >= ISLAND_PROGRESSION_ORDER.indexOf("volcano");
  if (hasReachedVolcano && !freshBoostIds.includes("volcano_gnome")) freshBoostIds.push("volcano_gnome");
  const matched = freshBoostIds.length;
  __lastBoostsSig = JSON.stringify([ freshBoostIds.slice().sort(), vipStatus.active ]);
  const boostDomainIds = new Set(freshBoostIds);
  BOOSTS.forEach(b => {
    if (b.source !== "skill" && !b.isBud && !b.composterFertilizer) boostDomainIds.add(b.id);
  });
  [].concat(FACTION_QUIVER_BOOST_IDS, FACTION_SHIELD_BOOST_IDS, FACTION_MEDALLION_BOOST_IDS, [ "volcano_gnome" ]).forEach(id => boostDomainIds.add(id));
  const toAddBoosts = freshBoostIds.filter(id => !selectedBoosts.includes(id));
  const toRemoveBoosts = selectedBoosts.filter(id => !freshBoostIds.includes(id) && boostDomainIds.has(id));
  let changed = false;
  if (toAddBoosts.length || toRemoveBoosts.length) {
    changed = true;
    const dropSet = new Set(toRemoveBoosts);
    selectedBoosts = selectedBoosts.filter(id => !dropSet.has(id)).concat(toAddBoosts);
    saveBoostState();
  }
  if (changed) __saveSyncSigs();
  return {
    matched: matched,
    vipStatus: vipStatus,
    changed: changed
  };
}

function detectBeeSwarmFromCrops(g) {
  const cropsBag = g && typeof g.crops === "object" && g.crops ? g.crops : {};
  let totalCount = 0;
  let affectedPlots = 0;
  const byCrop = {};
  Object.values(cropsBag).forEach(plot => {
    const bs = plot && plot.beeSwarm;
    if (!bs) return;
    const rawCount = typeof bs.count === "number" ? bs.count : typeof bs.count === "string" && bs.count.trim() && !isNaN(Number(bs.count)) ? Number(bs.count) : null;
    const count = rawCount != null && rawCount > 0 ? rawCount : bs ? 1 : 0;
    if (count > 0) {
      totalCount += count;
      affectedPlots += 1;
      const plotCropName = plot && plot.crop && plot.crop.name;
      if (plotCropName) {
        if (!byCrop[plotCropName]) byCrop[plotCropName] = {
          totalCount: 0,
          affectedPlots: 0
        };
        byCrop[plotCropName].totalCount += count;
        byCrop[plotCropName].affectedPlots += 1;
      }
    }
  });
  return {
    totalCount: totalCount,
    affectedPlots: affectedPlots,
    byCrop: byCrop
  };
}

function applyFarmPlotsNodesOnly(json, hasFullData) {
  if (!hasFullData) return {
    touched: false
  };
  const g = farmSyncExtractGameState(json);
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const plotsBags = [ g.crops, g.trees, g.stones, g.iron, g.gold, g.crimstones, g.oilReserves, g.lavaPits, g.saltFarm, g.sculptures, g.stock, g.flowers, g.fruitPatches, g.greenhouse, farmPanelField(g, "henHouse"), farmPanelField(g, "barn") ];
  const basicLandVal = asObj(g.inventory) ? g.inventory["Basic Land"] : undefined;
  const plotsLenSig = plotsBags.map(v => asObj(v) ? Object.keys(v).length : 0).join(",") + "|" + basicLandVal;
  let plotsSig;
  if (plotsLenSig === __lastPlotsLenSig) {
    plotsSig = JSON.stringify({
      crops: g.crops,
      trees: g.trees,
      stones: g.stones,
      iron: g.iron,
      gold: g.gold,
      crimstones: g.crimstones,
      oilReserves: g.oilReserves,
      lavaPits: g.lavaPits,
      saltFarm: g.saltFarm,
      sculptures: g.sculptures,
      stock: g.stock,
      flowers: g.flowers,
      fruitPatches: g.fruitPatches,
      greenhouse: g.greenhouse,
      henHouse: farmPanelField(g, "henHouse"),
      barn: farmPanelField(g, "barn"),
      basicLand: basicLandVal
    });
    if (plotsSig === __lastPlotsSig) return {
      touched: false
    };
  } else {
    plotsSig = null;
  }
  __lastPlotsLenSig = plotsLenSig;
  __lastPlotsSig = plotsSig;
  __saveSyncSigs();
  let touched = false;
  globalPlotCount = Object.keys(asObj(g.crops) || {}).length;
  saveGlobalPlotCount();
  globalPlotCountTouched = true;
  saveGlobalPlotCountTouched();
  touched = true;
  {
    const {totalCount: beeSwarmTotalCount, affectedPlots: beeSwarmTotalPlots, byCrop: beeSwarmTotalByCrop} = detectBeeSwarmFromCrops(g);
    beeSwarmActiveCount = beeSwarmTotalCount;
    beeSwarmAffectedPlots = beeSwarmTotalPlots;
    beeSwarmByCrop = beeSwarmTotalByCrop || {};
    saveBeeSwarmState();
    if (beeSwarmActiveCount > 0 && !selectedBoosts.includes("bee_swarm")) {
      selectedBoosts.push("bee_swarm");
      saveBoostState();
    } else if (beeSwarmActiveCount <= 0 && selectedBoosts.includes("bee_swarm")) {
      selectedBoosts = selectedBoosts.filter(x => x !== "bee_swarm");
      saveBoostState();
    }
  }
  {
    const inv = asObj(g.inventory) || {};
    const basicLandRaw = inv["Basic Land"];
    const basicLand = typeof basicLandRaw === "string" ? parseFloat(basicLandRaw) : Number(basicLandRaw);
    if (!isNaN(basicLand)) {
      const questSlots = basicLand >= 14 ? 5 : basicLand >= 12 ? 4 : basicLand >= 8 ? 3 : basicLand >= 5 ? 2 : 1;
      localStorage.setItem("hl_ticket_quest_slots", String(questSlots));
    }
  }
  const resourceBagKeys = {
    Wood: "trees",
    Stone: "stones",
    Iron: "iron",
    Gold: "gold",
    Crimstone: "crimstones"
  };
  Object.entries(resourceBagKeys).forEach(([resName, bagKey]) => {
    const bag = asObj(g[bagKey]) || {};
    if (isTieredResource(resName)) {
      const t = getNodeTierCounts(resName);
      t.base = 0;
      t.tier1 = 0;
      t.tier2 = 0;
      Object.values(bag).forEach(node => {
        const tierMatch = farmPanelDetectNodeTier(resName, node);
        const key = tierMatch ? tierMatch.key : "base";
        t[key] = (t[key] || 0) + 1;
      });
      saveNodeCounts();
      nodeCountsTouched.add(resName);
      saveNodeCountsTouched();
    } else {
      setNodeCount(resName, Object.keys(bag).length);
    }
  });
  setNodeCount("Oil", Object.keys(asObj(g.oilReserves) || {}).length);
  setNodeCount("Lava Pit", Object.keys(asObj(g.lavaPits) || {}).length);
  {
    const saltFarmObj = asObj(g.saltFarm);
    const level = saltFarmObj && (typeof saltFarmObj.level === "number" ? saltFarmObj.level : typeof saltFarmObj.level === "string" && saltFarmObj.level.trim() && !isNaN(Number(saltFarmObj.level)) ? Number(saltFarmObj.level) : null);
    if (level != null && typeof setSaltFarmLevel === "function") {
      setSaltFarmLevel(level);
      if (typeof farmLevelMaxNodes === "function") setNodeCount("Salt", farmLevelMaxNodes());
    }
  }
  {
    const sculpturesObj = asObj(g.sculptures);
    const saltSculptureObj = sculpturesObj && asObj(sculpturesObj["Salt Sculpture"]);
    const sculptLevelRaw = saltSculptureObj && saltSculptureObj.level;
    const sculptLevel = typeof sculptLevelRaw === "number" ? sculptLevelRaw : typeof sculptLevelRaw === "string" && sculptLevelRaw.trim() && !isNaN(Number(sculptLevelRaw)) ? Number(sculptLevelRaw) : null;
    if (sculptLevel != null && typeof setSculptureLevel === "function") {
      setSculptureLevel(sculptLevel);
    }
  }
  {
    const stockObj = asObj(g.stock);
    if (stockObj) {
      const parsed = {};
      Object.keys(stockObj).forEach(k => {
        const v = stockObj[k];
        const num = typeof v === "number" ? v : typeof v === "string" && v.trim() && !isNaN(Number(v)) ? Number(v) : null;
        if (num != null) parsed[k] = num;
      });
      if (Object.keys(parsed).length) {
        syncedItemStock = parsed;
        localStorage.setItem("hl_item_stock", JSON.stringify(syncedItemStock));
      }
    }
  }
  {
    const flowers = asObj(g.flowers);
    const bedsBag = flowers && asObj(flowers.flowerBeds) || {};
    setHiveCount(Object.keys(bedsBag).length);
  }
  {
    const fruitBag = asObj(g.fruitPatches) || {};
    const freshFruitCounts = {};
    Object.keys(BASE_FRUITS).forEach(n => {
      freshFruitCounts[n] = 0;
    });
    Object.values(fruitBag).forEach(patch => {
      const fname = patch && patch.fruit && patch.fruit.name;
      if (fname && freshFruitCounts.hasOwnProperty(fname)) freshFruitCounts[fname]++;
    });
    fruitCounts = freshFruitCounts;
    saveFruitCounts();
  }
  {
    const greenhouse = asObj(g.greenhouse);
    const potsBag = greenhouse && asObj(greenhouse.pots) || {};
    const freshGreenhouseCounts = {};
    Object.keys(BASE_GREENHOUSE).forEach(n => {
      freshGreenhouseCounts[n] = 0;
    });
    Object.values(potsBag).forEach(pot => {
      const pname = pot && pot.plant && pot.plant.name;
      if (pname && freshGreenhouseCounts.hasOwnProperty(pname)) freshGreenhouseCounts[pname]++;
    });
    greenhouseCounts = freshGreenhouseCounts;
    saveGreenhouseCounts();
  }
  const ANIMAL_TYPES_TO_SYNC = [ "chicken", "sheep", "cow" ];
  ANIMAL_TYPES_TO_SYNC.forEach(type => {
    const bag = asObj(farmSyncGetAnimalRecords(g, type)) || {};
    if (!animalCounts[type]) animalCounts[type] = {
      level: 1,
      qty: 0
    };
    animalCounts[type].qty = Object.keys(bag).length;
    let sickCount = 0;
    let levelSum = 0, levelSampleCount = 0;
    Object.values(bag).forEach(animal => {
      if (!animal || typeof animal !== "object") return;
      const stateStr = typeof animal.state === "string" ? animal.state.toLowerCase() : "";
      const isSick = animal.sick === true || stateStr === "sick" || typeof animal.sickenedAt === "number";
      if (isSick) sickCount++;
      const xpRaw = animal.experience ?? animal.exp ?? animal.xp;
      const xp = typeof xpRaw === "number" ? xpRaw : typeof xpRaw === "string" && xpRaw.trim() && !isNaN(Number(xpRaw)) ? Number(xpRaw) : null;
      const lvl = getAnimalLevelFromXp(type, xp);
      if (lvl != null) {
        levelSum += lvl;
        levelSampleCount++;
      }
    });
    animalSicknessEstimate[type] = {
      sickHeads: sickCount
    };
    if (levelSampleCount > 0) {
      animalCounts[type].level = Math.min(15, Math.max(1, Math.round(levelSum / levelSampleCount)));
    }
  });
  saveAnimalCounts();
  saveAnimalSicknessEstimate();
  return {
    touched: touched
  };
}

function openFarmPanel() {
  $("farmSidePanel").classList.add("open");
  $("farmPanelOverlay").classList.add("show");
  $("farmPanelToggleArrow").textContent = "‹";
  $("farmPanelToggle").setAttribute("aria-label", "Close farm sync panel");
  if (farmPanelTabContentDirty && typeof renderFarmPanelTabContent === "function") renderFarmPanelTabContent();
}

function closeFarmPanel() {
  $("farmSidePanel").classList.remove("open");
  $("farmPanelOverlay").classList.remove("show");
  $("farmPanelToggleArrow").textContent = "›";
  $("farmPanelToggle").setAttribute("aria-label", "Open farm sync panel");
}

$("farmPanelToggle").onclick = () => {
  $("farmSidePanel").classList.contains("open") ? closeFarmPanel() : openFarmPanel();
};

$("farmPanelOverlay").onclick = closeFarmPanel;

function positionFarmPanelTab() {
  const tab = $("farmPanelToggle");
  const ratioCard = $("settingsPanel");
  const sidePanel = $("farmSidePanel");
  if (!tab || !ratioCard || !sidePanel) return;
  const profileOverlay = $("profileOverlay");
  if (profileOverlay && profileOverlay.classList.contains("show")) return;
  const cardRect = ratioCard.getBoundingClientRect();
  const sideRect = sidePanel.getBoundingClientRect();
  const gap = 8;
  const desiredTop = cardRect.top - sideRect.top - tab.offsetHeight - gap;
  const newTop = Math.max(8, desiredTop) + "px";
  if (tab.style.top !== newTop) tab.style.top = newTop;
}

positionFarmPanelTab();
let __farmPanelTabRepositionScheduled = false;
function schedulePositionFarmPanelTab() {
  if (__farmPanelTabRepositionScheduled) return;
  __farmPanelTabRepositionScheduled = true;
  requestAnimationFrame(() => {
    __farmPanelTabRepositionScheduled = false;
    positionFarmPanelTab();
  });
}
window.addEventListener("load", () => setTimeout(positionFarmPanelTab, 0));
window.addEventListener("resize", schedulePositionFarmPanelTab);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(positionFarmPanelTab);

