function farmPanelCropTierLabel(cropName) {
  const sec = CROP_HARVEST_SEC[cropName];
  if (sec == null) return null;
  if (sec <= CROP_HARVEST_SEC.Pumpkin) return "Basic";
  if (sec >= CROP_HARVEST_SEC.Eggplant) return "Advanced";
  return "Medium";
}

function isOvernightGroundCrop(cropName) {
  const sec = CROP_HARVEST_SEC[cropName];
  if (sec != null) return sec >= CROP_HARVEST_SEC.Radish;
  const gh = BASE_GREENHOUSE[cropName];
  if (gh && typeof gh.timeSec === "number") return gh.timeSec >= 86400 && gh.timeSec <= 129600;
  return false;
}

function farmPanelSumCatalogBoosts(matchFn, excludeIds) {
  let add = 0, mult = 1;
  const boosts = [];
  const budGroups = {};
  BOOSTS.forEach(b => {
    if (!b || excludeIds.has(b.id) || !matchFn(b)) return;
    const active = b.skillTier ? isSkillActive(b.id) : isBoostActive(b.id);
    if (!active) return;
    if (typeof b.yieldMult === "number") {
      mult *= b.yieldMult;
      boosts.push(b);
    }
    if (typeof b.yieldAdd !== "number") return;
    if (b.isBud && b.budId) {
      if (!budGroups[b.budId]) budGroups[b.budId] = {
        total: 0,
        entries: []
      };
      budGroups[b.budId].total += b.yieldAdd;
      budGroups[b.budId].entries.push(b);
    } else {
      add += b.yieldAdd;
      boosts.push(b);
    }
  });
  const budGroupList = Object.values(budGroups);
  if (budGroupList.length) {
    const winner = budGroupList.reduce((best, g) => g.total > best.total ? g : best, budGroupList[0]);
    add += winner.total;
    boosts.push(...winner.entries);
  }
  return {
    add: add,
    mult: mult,
    boosts: boosts
  };
}

function renderExactBoostAppliedList(boosts) {
  if (!boosts || !boosts.length) return "";
  const rows = boosts.map(b => `<div class="boost-applied-row is-yield">Boost: ${getBoostIcon(b.name)}<b>${escapeHtml(b.name)}</b> ${escapeHtml(b.valueText)}</div>`).join("");
  return `<div class="section-badge is-boost-label">🎯 Applied Boost (this yield)</div><div class="boost-applied-list">${rows}</div>`;
}

