const farmPanelDebugTreeDataBtnEl = $("farmPanelDebugTreeDataBtn");

if (farmPanelDebugTreeDataBtnEl) farmPanelDebugTreeDataBtnEl.onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const trees = farmPanelField(g, "trees") || {};
  const treeEntries = Object.entries(trees);
  const farmActivity = farmPanelField(g, "farmActivity");
  const lastInfo = farmPanelGetLastInfo();
  const relevantActivityKeys = farmActivity ? Object.keys(farmActivity).filter(k => /Chopped$/.test(k)) : null;
  const perTree = treeEntries.map(([id, node]) => {
    const job = node && node.wood;
    return {
      treeId: id,
      name: node && node.name ? node.name : "Tree (base)",
      hasWoodAmount: !!(job && typeof job.amount === "number"),
      woodAmount: job && typeof job.amount === "number" ? job.amount : null,
      hasWoodReward: !!(job && job.reward),
      woodReward: job && job.reward || null,
      allWoodKeys: job ? Object.keys(job) : []
    };
  });
  const inProgress = farmPanelComputeInProgress(farmPanelGameState);
  const woodCard = inProgress.find(r => r.name === "Wood");
  const typesInFarm = [ ...new Set(treeEntries.map(([, node]) => farmPanelTreeTypeForNode(node))) ];
  const perTypeRolls = {};
  typesInFarm.forEach(t => {
    const typeEntries = treeEntries.filter(([, node]) => farmPanelTreeTypeForNode(node) === t);
    const readyEntries = typeEntries.filter(([, node]) => farmPanelIsNodeReadyNow("Wood", node, "wood", Date.now()));
    const chains = farmPanelBuildSequentialWoodRollChains(farmPanelGameState, t, readyEntries.length);
    const activityKey = `${t === "Tree" ? "Basic Tree" : t} Chopped`;
    let sequentialSum = 0;
    const perReadyNodeBreakdown = readyEntries.map(([id, node], i) => {
      const chain = chains && chains[i] ? chains[i] : null;
      const critRolls = chain && chain.length ? chain[0] : null;
      
      
      const amount = chain && chain.length ? chain.reduce((sum, roll) => sum + farmPanelComputeExactWoodYieldForNode(node, t, roll), 0) : null;
      if (typeof amount === "number") sequentialSum += amount;
      return {
        treeId: id,
        counterUsed: farmActivity ? (farmActivity[activityKey] ?? 0) + i : null,
        critRolls: critRolls,
        chain: chain,
        chainLength: chain ? chain.length : null,
        amount: amount
      };
    });
    perTypeRolls[t] = {
      turnaroundPredicted: perReadyNodeBreakdown.some(n => n.chainLength > 1),
      turnaroundPredictedNodeIds: perReadyNodeBreakdown.filter(n => n.chainLength > 1).map(n => n.treeId),
      moneyTreePredicted: farmPanelPredictMoneyTreeForType(farmPanelGameState, t),
      moneyTreeBatchPredicted: farmPanelPredictMoneyTreeBatchForType(farmPanelGameState, t, typeEntries.length, typeEntries.length ? typeof typeEntries[0][1].multiplier === "number" ? typeEntries[0][1].multiplier : 1 : 1),
      baseActivityCounter: farmActivity ? farmActivity[activityKey] ?? 0 : null,
      readyNodeCount: readyEntries.length,
      totalNodesOfThisType: typeEntries.length,
      sequentialSumForReadyNodes: readyEntries.length ? Number(sequentialSum.toFixed(4)) : null,
      perReadyNodeBreakdown: perReadyNodeBreakdown
    };
  });
  const out = {
    "farmId used for PRNG (farmPanelGetLastInfo().id)": lastInfo.id,
    "farmActivity present on merged state?": !!farmActivity,
    "farmActivity '*Chopped' keys found": relevantActivityKeys,
    "Tree Turnaround owned (isSkillActive)": isSkillActive("skill_tree_turnaround"),
    "Tree Turnaround rank (getAscensionRank)": getAscensionRank("skill_tree_turnaround"),
    "Money Tree owned (isSkillActive)": isSkillActive("skill_money_tree"),
    "Money Tree rank (getAscensionRank)": getAscensionRank("skill_money_tree"),
    "Total tree nodes": treeEntries.length,
    "Nodes with a real stored wood.amount": perTree.filter(t => t.hasWoodAmount).length,
    "Nodes with a real stored wood.reward": perTree.filter(t => t.hasWoodReward).length,
    "Per-TYPE roll (one shared result per type, NOT per node — see farmPanelPredictTreeTypeRoll)": perTypeRolls,
    "Per-tree raw wood field dump": perTree,
    "farmPanelDetectMoneyTreeBonus() result": farmPanelDetectMoneyTreeBonus(farmPanelGameState),
    "Wood card from farmPanelComputeInProgress() — actualYieldCount / turnaroundTypesPredicted": woodCard ? {
      actualYieldCount: woodCard.actualYieldCount,
      turnaroundTypesPredicted: woodCard.turnaroundTypesPredicted,
      turnaroundBonusYieldEstimate: woodCard.turnaroundBonusYieldEstimate
    } : "(no Wood card — sync a farm with trees first)",
    "Manually-entered Bud yield boost for Wood (resourceBuds panel)": farmPanelGetBudYieldForResource("Wood"),
    resourceBudsConfigured: resourceBuds
  };
  box.style.display = "block";
  box.value = JSON.stringify(out, null, 2);
  box.focus();
  box.select();
};

const farmPanelDebugMiningBtnEl = $("farmPanelDebugMiningBtn");

if (farmPanelDebugMiningBtnEl) farmPanelDebugMiningBtnEl.onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const farmActivity = farmPanelField(g, "farmActivity");
  const lastInfo = farmPanelGetLastInfo();
  function boostFlags(ids) {
    const out = {};
    ids.forEach(id => {
      if (id.startsWith("skill_")) {
        out[id] = isSkillActive(id) ? {
          owned: true,
          rank: getAscensionRank(id)
        } : {
          owned: false
        };
      } else {
        out[id] = isBoostActive(id);
      }
    });
    return out;
  }
  function buildSection(resourceLabel, bagKey, knownIds, defaultName, buildRollsFn, computeFn, boostIds) {
    const bag = farmPanelField(g, bagKey);
    if (!bag || typeof bag !== "object") return {
      present: false
    };
    const entries = Object.entries(bag);
    const typesInFarm = [ ...new Set(entries.map(([, node]) => farmPanelRockNameForNode(node, knownIds, defaultName))) ];
    const flags = boostFlags(boostIds);
    const perType = {};
    typesInFarm.forEach(t => {
      const typeEntries = entries.filter(([, node]) => farmPanelRockNameForNode(node, knownIds, defaultName) === t);
      const readyEntries = typeEntries.filter(([, node]) => farmPanelIsNodeReadyNow(resourceLabel, node, "stone", Date.now()));
      const rolls = buildRollsFn(farmPanelGameState, t, readyEntries.length);
      const activityKey = `${t} Mined`;
      let sequentialSum = 0;
      const perNodeBreakdown = readyEntries.map(([id, node], i) => {
        const rollOrChain = rolls && rolls[i] ? rolls[i] : null;
        const isChain = Array.isArray(rollOrChain);
        const critRolls = isChain ? (rollOrChain.length ? rollOrChain[0] : null) : rollOrChain;
        const amount = isChain ? (rollOrChain.length ? rollOrChain.reduce((sum, roll) => sum + (computeFn(farmPanelGameState, node, t, roll) || 0), 0) : null) : (critRolls ? computeFn(farmPanelGameState, node, t, critRolls) : null);
        if (typeof amount === "number") sequentialSum += amount;
        return {
          nodeId: id,
          counterUsed: farmActivity ? (farmActivity[activityKey] ?? 0) + i : null,
          critRolls: critRolls,
          chain: isChain ? rollOrChain : null,
          chainLength: isChain ? rollOrChain.length : null,
          amount: amount
        };
      });
      perType[t] = {
        itemId: knownIds[t],
        baseActivityCounter: farmActivity ? farmActivity[activityKey] ?? 0 : null,
        readyNodeCount: readyEntries.length,
        totalNodesOfThisType: typeEntries.length,
        sequentialSumForReadyNodes: readyEntries.length ? Number(sequentialSum.toFixed(4)) : null,
        perReadyNodeBreakdown: perNodeBreakdown
      };
    });
    return {
      present: true,
      totalNodes: entries.length,
      boostFlags: flags,
      perType: perType
    };
  }
  const out = {
    "farmId used for PRNG (farmPanelGetLastInfo().id)": lastInfo.id,
    "farmActivity present on merged state?": !!farmActivity,
    Stone: buildSection("Stone", "stones", STONE_KNOWN_IDS, "Stone Rock", farmPanelBuildSequentialStoneRolls, farmPanelComputeExactStoneYieldForNode, [ "rock_golem", "prospector", "tunnel_mole", "stone_beetle", "skill_rocknroll", "skill_rocky_favor", "skill_ferrous_favor", "emerald_turtle", "tin_turtle", "faction_shield_res", "legendary_shrine_res", "volcano_gnome" ]),
    Iron: buildSection("Iron", "iron", IRON_KNOWN_IDS, "Iron Rock", farmPanelBuildSequentialIronRolls, farmPanelComputeExactIronYieldForNode, [ "rocky_the_mole", "radiant_ray", "iron_idol", "iron_beetle", "skill_iron_bumpkin", "skill_rocky_favor", "skill_ferrous_favor", "emerald_turtle", "faction_shield_res", "volcano_gnome" ]),
    Gold: buildSection("Gold", "gold", GOLD_KNOWN_IDS, "Gold Rock", farmPanelBuildSequentialGoldRollChains, farmPanelComputeExactGoldYieldForNode, [ "gold_rush", "skill_golden_touch", "nugget", "gilded_swordfish", "gold_beetle", "emerald_turtle", "faction_shield_res", "pickaxe_shark", "volcano_gnome" ]),
    "aoe object present on merged state?": !!farmPanelField(g, "aoe"),
    "collectibles present on merged state?": !!farmPanelField(g, "collectibles"),
    "Emerald Turtle position found": farmPanelGetCollectiblePosition(g, "Emerald Turtle"),
    "Tin Turtle position found": farmPanelGetCollectiblePosition(g, "Tin Turtle"),
    "Manually-entered Bud yield boosts (resourceBuds panel)": {
      Stone: farmPanelGetBudYieldForResource("Stone"),
      Iron: farmPanelGetBudYieldForResource("Iron"),
      Gold: farmPanelGetBudYieldForResource("Gold"),
      resourceBudsConfigured: resourceBuds
    }
  };
  box.style.display = "block";
  box.value = JSON.stringify(out, null, 2);
  box.focus();
  box.select();
};

$("farmPanelDebugCrowBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const mainCollectibles = asObj(farmPanelField(g, "collectibles")) || {};
  const home = asObj(g && g.home);
  const homeCollectibles = farmSyncGetInteriorCollectiblesMerged(g);
  const cropsBag = asObj(farmPanelField(g, "crops")) || {};
  const skills = asObj(g && g.bumpkin && g.bumpkin.skills) || {};
  const hasSkill = name => Object.keys(skills).some(sn => sn.trim().toLowerCase() === name.trim().toLowerCase());
  const lines = [];
  Object.entries(CROW_AOE_DEFS).forEach(([boostId, def]) => {
    lines.push(`\n===== ${def.collectibleName} (tier: ${def.tier}, skill: ${def.skillName}) =====`);
    const a = mainCollectibles[def.collectibleName];
    const b = homeCollectibles[def.collectibleName];
    const rawInstances = [ ...Array.isArray(a) ? a : [], ...Array.isArray(b) ? b : [] ];
    lines.push(`Raw placed instances found (before placement filter): ${rawInstances.length}`);
    rawInstances.forEach((inst, i) => {
      lines.push(`  [${i}] RAW OBJECT: ${JSON.stringify(inst)}`);
    });
    const instances = farmSyncPickActivePlacedInstances(rawInstances);
    const crowCoords = instances.map(farmSyncGetCoords).filter(Boolean);
    lines.push(`Active (placed on farm) instances: ${instances.length} | with parseable coords: ${crowCoords.length}`);
    crowCoords.forEach((c, i) => lines.push(`  crowCoords[${i}] = x:${c.x}, y:${c.y}`));
    const skillOn = hasSkill(def.skillName);
    const radius = skillOn ? 3 : 1;
    const size = radius * 2 + 1;
    lines.push(`hasSkill("${def.skillName}") = ${skillOn}  →  radius = ${radius} (box size ${size}x${size} = ${size * size} cells, positioned BELOW the crow per sfl.world's own item pages — crow's own row excluded)`);
    if (!crowCoords.length) {
      lines.push("No usable crow coordinates — skipping plot scan for this crow.");
      return;
    }
    const allCropEntries = Object.entries(cropsBag);
    lines.push(`Total plots in crops bag: ${allCropEntries.length}`);
    let tierMatchCount = 0, inRangeCount = 0, noCoordsCount = 0, noCropCount = 0;
    allCropEntries.forEach(([plotId, plot]) => {
      if (!plot || typeof plot !== "object") return;
      const cropName = plot.crop && plot.crop.name;
      if (!cropName) {
        noCropCount++;
        return;
      }
      const cropDef = BASE_CROPS[cropName];
      const tierOk = cropDef && cropDef.tier === def.tier;
      if (!tierOk) return;
      tierMatchCount++;
      const plotCoords = farmSyncGetCoords(plot);
      if (!plotCoords) {
        noCoordsCount++;
        lines.push(`  plot #${plotId}: crop=${cropName} (tier OK) — NO PARSEABLE COORDS. Raw plot object: ${JSON.stringify(plot)}`);
        return;
      }
      let bestDx = null, bestDy = null, bestCrowIdx = -1, inRangeAny = false;
      crowCoords.forEach((c, i) => {
        const dx = plotCoords.x - c.x;
        const dy = plotCoords.y - c.y;
        const inR = Math.abs(dx) <= radius && dy <= -1 && dy >= -size;
        if (inR) inRangeAny = true;
        if (bestDx === null || Math.abs(dx) + Math.abs(dy) < Math.abs(bestDx) + Math.abs(bestDy)) {
          bestDx = dx;
          bestDy = dy;
          bestCrowIdx = i;
        }
      });
      if (inRangeAny) inRangeCount++;
      lines.push(`  plot #${plotId}: crop=${cropName}, coords=(${plotCoords.x},${plotCoords.y}), nearest crow=[${bestCrowIdx}], dx=${bestDx}, dy=${bestDy} → ${inRangeAny ? "IN RANGE ✅" : "out of range ❌"}`);
    });
    lines.push(`\nSUMMARY for ${def.collectibleName}: ${allCropEntries.length} total plots · ${tierMatchCount} planted with a "${def.tier}" tier crop · ${noCoordsCount} of those had no parseable coords · ${inRangeCount} counted as IN RANGE by this tool's logic.`);
    lines.push(`(Current live override stored: aoeSyncOverrides["${boostId}"] = ${JSON.stringify(aoeSyncOverrides[boostId])})`);
    if (rawInstances[0]) {
      lines.push(`\nFull field list on the crow instance itself (check for width/height/footprint fields beyond coordinates): ${Object.keys(rawInstances[0]).join(", ")}`);
    }
    const firstTierPlotEntry = allCropEntries.find(([, plot]) => plot && plot.crop && BASE_CROPS[plot.crop.name] && BASE_CROPS[plot.crop.name].tier === def.tier);
    if (firstTierPlotEntry) {
      lines.push(`Full field list on a matching-tier plot (check for width/height/footprint fields beyond x/y): ${Object.keys(firstTierPlotEntry[1]).join(", ")}`);
    }
  });
  box.style.display = "block";
  box.value = lines.join("\n");
  box.focus();
  box.select();
};

$("farmPanelDebugCrowCooldownBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const cropsBag = farmPanelField(g, "crops") || {};
  const aoeState = farmPanelField(g, "aoe") || {};
  const now = Date.now();
  const lines = [];
  Object.entries(CROW_AOE_DEFS).forEach(([boostId, def]) => {
    lines.push(`\n===== ${def.collectibleName} (tier: ${def.tier}) =====`);
    const pos = farmPanelGetCollectiblePosition(g, def.collectibleName);
    lines.push(`Crow position: ${JSON.stringify(pos)}`);
    lines.push(`isBoostActive("${boostId}") = ${isBoostActive(boostId)}`);
    lines.push(`isSkillActive("skill_${boostId === "laurie_chuckle_crow" ? "lauries_gains" : boostId === "scary_mike" ? "horror_mike" : "chonky_scarecrow"}") = ${isSkillActive(boostId === "laurie_chuckle_crow" ? "skill_lauries_gains" : boostId === "scary_mike" ? "skill_horror_mike" : "skill_chonky_scarecrow")}`);
    if (!pos) {
      lines.push("No crow position — skipping.");
      return;
    }
    Object.entries(cropsBag).forEach(([plotId, plot]) => {
      if (!plot || typeof plot !== "object") return;
      const job = plot.crop;
      const cropName = job && job.name;
      if (!cropName) return;
      const cropDef = BASE_CROPS[cropName];
      if (!cropDef || cropDef.tier !== def.tier) return;
      if (typeof plot.x !== "number" || typeof plot.y !== "number") return;
      const dims = { width: 1, height: 1 };
      const rankSkillId = boostId === "laurie_chuckle_crow" ? "skill_lauries_gains" : boostId === "scary_mike" ? "skill_horror_mike" : "skill_chonky_scarecrow";
      const e = farmPanelAOEExtent(rankSkillId);
      const px = plot.x, py = plot.y;
      const within = px >= pos.x - e.xLeft && px <= pos.x + e.xRight && py <= pos.y - dims.height && py >= pos.y - dims.height - (e.depth - 1);
      if (!within) return;
      const dx = px - pos.x, dy = py - pos.y;
      const lastUsed = aoeState[def.collectibleName] && aoeState[def.collectibleName][dx] && typeof aoeState[def.collectibleName][dx][dy] === "number" ? aoeState[def.collectibleName][dx][dy] : 0;
      const idleMs = now - lastUsed;
      const baseSec = farmPanelGrowTimeSec(cropName);
      const baseMs = (typeof baseSec === "number" ? baseSec : 0) * 1e3;
      const rawBaseDurationMs = job && typeof job.baseDurationMs === "number" ? job.baseDurationMs : null;
      const boostedTimeMs = job && typeof job.boostedTime === "number" ? job.boostedTime : null;
      const newCooldownMs = farmPanelGetCropGrowDurationMsFromSync(job, cropName);
      const passesNow = idleMs >= newCooldownMs;
      lines.push(`  plot #${plotId}: crop=${cropName}, x=${px}, y=${py}, dx=${dx}, dy=${dy}`);
      lines.push(`    job.baseDurationMs = ${rawBaseDurationMs}  |  job.boostedTime = ${boostedTimeMs}  |  base crop time (ms) = ${baseMs}`);
      lines.push(`    computed cooldownMs (current logic) = ${newCooldownMs}  (${(newCooldownMs / 1e3 / 3600).toFixed(2)}h)`);
      lines.push(`    aoe last used at = ${lastUsed} (${lastUsed ? new Date(lastUsed).toISOString() : "never"})`);
      lines.push(`    idleMs since last use = ${idleMs}  (${(idleMs / 1e3 / 3600).toFixed(2)}h)`);
      lines.push(`    idleMs >= cooldownMs → bonus applies now = ${passesNow}`);
    });
  });
  box.style.display = "block";
  box.value = lines.join("\n");
  box.focus();
  box.select();
};

$("farmPanelDebugGnomeBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const lines = [];
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const mainCollectibles = asObj(farmPanelField(g, "collectibles")) || {};
  [ "Gnome", "Cobalt", "Clementine" ].forEach(name => {
    lines.push(`\n===== ${name} =====`);
    const arr = mainCollectibles[name];
    if (!Array.isArray(arr) || !arr.length) {
      lines.push("Not found in g.collectibles at all.");
      return;
    }
    lines.push(`Raw instances found: ${arr.length}`);
    arr.forEach((inst, i) => {
      lines.push(`  [${i}] RAW OBJECT: ${JSON.stringify(inst)}`);
    });
    const pos = farmPanelGetCollectiblePosition(g, name);
    lines.push(`farmPanelGetCollectiblePosition(g, "${name}") = ${JSON.stringify(pos)}`);
  });
  const gnomePos = farmPanelGetCollectiblePosition(g, "Gnome");
  const cobaltPos = farmPanelGetCollectiblePosition(g, "Cobalt");
  const clementinePos = farmPanelGetCollectiblePosition(g, "Clementine");
  lines.push("\n===== Combo geometry check =====");
  lines.push(`gnomePos = ${JSON.stringify(gnomePos)}, cobaltPos = ${JSON.stringify(cobaltPos)}, clementinePos = ${JSON.stringify(clementinePos)}`);
  const isCobaltLeftOfGnome = !!gnomePos && !!cobaltPos && cobaltPos.y === gnomePos.y && cobaltPos.x + 1 === gnomePos.x;
  const isClementineRightOfGnome = !!gnomePos && !!clementinePos && clementinePos.y === gnomePos.y && clementinePos.x - 1 === gnomePos.x;
  lines.push(`isCobaltLeftOfGnome (cobalt.y === gnome.y && cobalt.x + 1 === gnome.x) = ${isCobaltLeftOfGnome}`);
  lines.push(`isClementineRightOfGnome (clementine.y === gnome.y && clementine.x - 1 === gnome.x) = ${isClementineRightOfGnome}`);
  lines.push(`farmPanelGnomeComboPresent() = ${farmPanelGnomeComboPresent()}`);
  lines.push(`isBoostActive("gnome") = ${isBoostActive("gnome")}`);
  if (gnomePos) {
    lines.push("\n===== Plot directly above Gnome (the only plot the boost can ever apply to) =====");
    lines.push(`Expected plot coordinates: x:${gnomePos.x}, y:${gnomePos.y - 1}`);
    const cropsBag = asObj(farmPanelField(g, "crops")) || {};
    const match = Object.entries(cropsBag).find(([, plot]) => plot && plot.x === gnomePos.x && plot.y === gnomePos.y - 1);
    if (!match) {
      lines.push("No crop plot found at that exact coordinate — either nothing is planted there, or the plot's own x/y in your sync data doesn't match the Gnome's x/y-1.");
    } else {
      const [plotId, plot] = match;
      const cropName = plot.crop && plot.crop.name;
      lines.push(`Found plot #${plotId}: crop=${cropName || "(none planted)"}, raw plot object: ${JSON.stringify(plot)}`);
      if (cropName) {
        const tierLabel = farmPanelCropTierLabel(cropName);
        lines.push(`Tier of "${cropName}" = ${tierLabel} (Gnome only boosts Medium/Advanced tier crops)`);
        const cropAoeCooldownSec = farmPanelGetCropGrowDurationMsFromSync(plot.crop, cropName) / 1e3;
        const bonus = farmPanelGnomeAOEBonus(g, plot, cropAoeCooldownSec, Date.now());
        lines.push(`farmPanelGnomeAOEBonus(g, plot, ${cropAoeCooldownSec}, now) = ${bonus}`);
        const aoeState = asObj(farmPanelField(g, "aoe")) || {};
        lines.push(`g.aoe["Gnome"] raw = ${JSON.stringify(aoeState["Gnome"])}`);
      }
    }
  } else {
    lines.push("\nGnome position could not be resolved — see the raw object dump above for why (no coordinates, or readyAt still in the future).");
  }
  box.style.display = "block";
  box.value = lines.join("\n");
  box.focus();
  box.select();
};

$("farmPanelDebugTurtleBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const lines = [];
  const now = Date.now();
  [ [ "Tin Turtle", "tin_turtle", "stones", "Stone" ], [ "Emerald Turtle", "emerald_turtle", "stones", "Stone" ] ].forEach(([turtleName, boostId, bagKey, resourceLabel]) => {
    lines.push(`\n===== ${turtleName} =====`);
    lines.push(`isBoostActive("${boostId}") = ${isBoostActive(boostId)}`);
    const pos = farmPanelGetCollectiblePosition(g, turtleName);
    lines.push(`farmPanelGetCollectiblePosition(g, "${turtleName}") = ${JSON.stringify(pos)}`);
    const rawCollectibles = farmPanelField(g, "collectibles");
    const rawArr = rawCollectibles && rawCollectibles[turtleName];
    lines.push(`Raw collectibles["${turtleName}"] array (via farmPanelField): ${rawArr ? JSON.stringify(rawArr) : "not found"}`);
    if (!pos) {
      lines.push("No usable position — AoE bonus cannot apply anywhere for this collectible. Skipping node scan.");
      return;
    }
    const bag = farmPanelField(g, bagKey) || {};
    const nodeEntries = Object.entries(bag);
    lines.push(`Total ${resourceLabel} nodes in "${bagKey}" bag: ${nodeEntries.length}`);
    let withCoords = 0, inRange = 0, bonusActiveNow = 0;
    nodeEntries.forEach(([nodeId, node]) => {
      const hasCoords = node && typeof node.x === "number" && typeof node.y === "number";
      if (hasCoords) withCoords++;
      const inRangeNow = hasCoords && farmPanelIsWithinTurtleAOE(pos, { x: node.x, y: node.y });
      if (inRangeNow) inRange++;
      const bonus = farmPanelCheckTurtleAOEBonus(g, turtleName, node, 14400, now, resourceLabel);
      if (bonus) bonusActiveNow++;
      lines.push(`  node #${nodeId}: x=${hasCoords ? node.x : "MISSING"}, y=${hasCoords ? node.y : "MISSING"} → inRange=${inRangeNow} → bonusAppliesRightNow=${bonus}`);
    });
    lines.push(`\nSUMMARY for ${turtleName}: ${nodeEntries.length} total nodes · ${withCoords} had parseable x/y coords · ${inRange} fell within AoE range · ${bonusActiveNow} would get the bonus applied right now (range + off cooldown).`);
    if (nodeEntries[0]) {
      lines.push(`Full field list on a node object (check whether x/y actually exist): ${Object.keys(nodeEntries[0][1] || {}).join(", ")}`);
    }
  });
  box.style.display = "block";
  box.value = lines.join("\n");
  box.focus();
  box.select();
};

$("farmPanelDebugFactionBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const lines = [];
  const equipped = g && g.bumpkin && asObj(g.bumpkin.equipped);
  lines.push("===== g.bumpkin.equipped (raw) =====");
  lines.push(equipped ? JSON.stringify(equipped, null, 2) : "(missing — g.bumpkin.equipped is not an object)");
  lines.push("\n===== g.farmHands (raw shape check) =====");
  const farmHandsRaw = g && g.farmHands;
  if (!farmHandsRaw) {
    lines.push("(missing — g.farmHands is not present on this payload)");
  } else {
    const fhBumpkinsObj = asObj(farmHandsRaw.bumpkins);
    const fhBumpkinsArr = Array.isArray(farmHandsRaw.bumpkins) ? farmHandsRaw.bumpkins : null;
    let fhList = [];
    if (fhBumpkinsObj) {
      fhList = Object.entries(fhBumpkinsObj);
      lines.push(`g.farmHands.bumpkins is an OBJECT with ${fhList.length} entr${fhList.length === 1 ? "y" : "ies"}.`);
    } else if (fhBumpkinsArr) {
      fhList = fhBumpkinsArr.map((b, i) => [ String(i), b ]);
      lines.push(`g.farmHands.bumpkins is an ARRAY with ${fhList.length} entr${fhList.length === 1 ? "y" : "ies"}.`);
    } else if (Array.isArray(farmHandsRaw)) {
      fhList = farmHandsRaw.map((b, i) => [ String(i), b ]);
      lines.push(`g.farmHands itself is an ARRAY with ${fhList.length} entr${fhList.length === 1 ? "y" : "ies"}.`);
    } else if (asObj(farmHandsRaw)) {
      fhList = Object.entries(farmHandsRaw);
      lines.push(`g.farmHands itself is an OBJECT (no .bumpkins key) with ${fhList.length} entr${fhList.length === 1 ? "y" : "ies"}.`);
    } else {
      lines.push("g.farmHands is present but not an object/array this tool recognizes: " + typeof farmHandsRaw);
    }
    fhList.forEach(([id, bumpkin]) => {
      const eq = bumpkin && asObj(bumpkin.equipped);
      lines.push(`  farm hand [${id}] equipped: ${eq ? JSON.stringify(eq) : "(no .equipped object)"}`);
    });
  }
  const inv = asObj(g && g.inventory);
  lines.push('\n===== g.inventory["Green Amulet"] (raw) =====');
  if (!inv) {
    lines.push("(missing — g.inventory is not an object)");
  } else if (!("Green Amulet" in inv)) {
    lines.push('(key "Green Amulet" not present in inventory at all)');
    const amuletLikeKeys = Object.keys(inv).filter(k => k.toLowerCase().includes("amulet"));
    lines.push(amuletLikeKeys.length ? `Inventory keys containing "amulet": ${JSON.stringify(amuletLikeKeys)}` : 'No inventory keys containing "amulet" found at all.');
  } else {
    const raw = inv["Green Amulet"];
    lines.push(`typeof = ${typeof raw}, raw value = ${JSON.stringify(raw)}`);
    const amuletQty = typeof raw === "string" ? parseFloat(raw) : Number(raw);
    lines.push(`Parsed qty = ${amuletQty}  →  ${!isNaN(amuletQty) && amuletQty > 0 ? "PASSES the >0 check ✅" : "FAILS the >0 check ❌"}`);
  }
  const placedNames = farmSyncCollectEquippedAndPlacedNames(g);
  lines.push("\n===== Full set returned by farmSyncCollectEquippedAndPlacedNames() =====");
  lines.push(JSON.stringify(Array.from(placedNames).sort(), null, 2));
  lines.push(`"Green Amulet" in that set: ${placedNames.has("Green Amulet") ? "YES ✅" : "NO ❌"}`);
  lines.push("\n===== Faction Quiver / Shield check =====");
  lines.push(`Quiver names this tool looks for: ${JSON.stringify(FACTION_QUIVER_NAMES)}`);
  const normPlaced = new Set(Array.from(placedNames, n => n.trim().toLowerCase()));
  FACTION_QUIVER_NAMES.forEach(n => {
    lines.push(`  "${n}" → ${normPlaced.has(n.toLowerCase()) ? "FOUND ✅" : "not found"}`);
  });
  const hasFactionQuiver = FACTION_QUIVER_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  lines.push(`hasFactionQuiver = ${hasFactionQuiver} → maps to: ${JSON.stringify(FACTION_QUIVER_BOOST_IDS)}`);
  lines.push(`\nShield names this tool looks for: ${JSON.stringify(FACTION_SHIELD_NAMES)}`);
  FACTION_SHIELD_NAMES.forEach(n => {
    lines.push(`  "${n}" → ${normPlaced.has(n.toLowerCase()) ? "FOUND ✅" : "not found"}`);
  });
  const hasFactionShield = FACTION_SHIELD_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  lines.push(`hasFactionShield = ${hasFactionShield} → maps to: ${JSON.stringify(FACTION_SHIELD_BOOST_IDS)}`);
  lines.push(`\nMedallion names this tool looks for: ${JSON.stringify(FACTION_MEDALLION_NAMES)}`);
  FACTION_MEDALLION_NAMES.forEach(n => {
    lines.push(`  "${n}" → ${normPlaced.has(n.toLowerCase()) ? "FOUND ✅" : "not found"}`);
  });
  const hasFactionMedallion = FACTION_MEDALLION_NAMES.some(n => normPlaced.has(n.toLowerCase()));
  lines.push(`hasFactionMedallion = ${hasFactionMedallion} → maps to: ${JSON.stringify(FACTION_MEDALLION_BOOST_IDS)}`);
  applyFarmBoostsOnly(farmPanelGameState);
  lines.push("\n===== applyFarmBoostsOnly() result on this synced payload =====");
  [ ...FACTION_QUIVER_BOOST_IDS, ...FACTION_SHIELD_BOOST_IDS, ...FACTION_MEDALLION_BOOST_IDS ].forEach(id => {
    lines.push(`selectedBoosts includes "${id}": ${selectedBoosts.includes(id) ? "YES ✅" : "NO ❌"}`);
  });
  lines.push(`selectedBoosts includes "green_amulet": ${selectedBoosts.includes("green_amulet") ? "YES ✅" : "NO ❌"}`);
  lines.push(`Full selectedBoosts after sync: ${JSON.stringify(selectedBoosts)}`);
  box.style.display = "block";
  box.value = lines.join("\n");
  box.focus();
  box.select();
};

$("farmPanelDebugCropsBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const farmActivity = farmPanelField(g, "farmActivity") || {};
  const lastInfo = farmPanelGetLastInfo();
  function boostFlags(ids) {
    const out = {};
    ids.forEach(id => {
      if (id.startsWith("skill_")) {
        out[id] = isSkillActive(id) ? {
          owned: true,
          rank: getAscensionRank(id)
        } : {
          owned: false
        };
      } else {
        out[id] = isBoostActive(id);
      }
    });
    return out;
  }
  function buildPlantedSection(bag, subKey, kind, boostIds) {
    if (!bag || typeof bag !== "object") return {
      present: false
    };
    const flags = boostFlags(boostIds);
    const perPlant = {};
    const sequentialCounterBaseByName = {};
    const sequentialIndexByName = {};
    if (kind === "crop" || kind === "fruit" || kind === "greenhouse") {
      Object.values(bag).forEach(plot => {
        const job = plot && plot[subKey];
        const name = job && job.name;
        if (!name) return;
        const growSec = farmPanelGrowTimeSec(name);
        const plantedAt = job.plantedAt;
        const refTime = job.harvestedAt && job.harvestedAt > plantedAt ? job.harvestedAt : plantedAt;
        const remainingSec = growSec != null && refTime ? Math.max(0, growSec - (Date.now() - refTime) / 1e3) : null;
        const ready = remainingSec != null ? remainingSec <= 0 : false;
        if (ready && typeof job.amount !== "number" && !(name in sequentialCounterBaseByName)) {
          sequentialCounterBaseByName[name] = farmActivity[`${name} Harvested`] || 0;
          sequentialIndexByName[name] = 0;
        }
      });
    }
    Object.entries(bag).forEach(([plotId, plot]) => {
      const job = plot && plot[subKey];
      const name = job && job.name;
      if (!name) return;
      const growSec = farmPanelGrowTimeSec(name);
      const plantedAt = job.plantedAt;
      const refTime = job.harvestedAt && job.harvestedAt > plantedAt ? job.harvestedAt : plantedAt;
      const remainingSec = growSec != null && refTime ? Math.max(0, growSec - (Date.now() - refTime) / 1e3) : null;
      const ready = remainingSec != null ? remainingSec <= 0 : false;
      let counter = farmActivity[`${name} Harvested`] || 0;
      if (ready && typeof job.amount !== "number" && (kind === "crop" || kind === "fruit" || kind === "greenhouse")) {
        const idx = sequentialIndexByName[name] || 0;
        counter = (sequentialCounterBaseByName[name] || 0) + idx;
        sequentialIndexByName[name] = idx + 1;
      }
      let exactAmount = null;
      let exactBoostNames = null;
      if (ready && typeof job.amount !== "number") {
        try {
          let r = null;
          if (kind === "crop") r = farmPanelComputeExactCropYield(farmPanelGameState, g, name, plot, counter); else if (kind === "fruit") r = farmPanelComputeExactFruitYield(farmPanelGameState, g, name, counter, false, plot && plot.fertiliser && plot.fertiliser.name); else if (kind === "greenhouse") r = farmPanelComputeExactGreenhouseYield(farmPanelGameState, g, name, counter, plot && plot.fertiliser && plot.fertiliser.name); else if (kind === "flower") r = farmPanelComputeExactFlowerYield(job);
          if (r) {
            exactAmount = r.amount;
            exactBoostNames = r.boosts.map(b => `${b.name} (${b.valueText})`);
          }
        } catch (e) {
          exactAmount = null;
        }
      }
      if (!perPlant[name]) perPlant[name] = [];
      perPlant[name].push({
        plotId: plotId,
        ready: ready,
        storedAmount: typeof job.amount === "number" ? job.amount : null,
        counterUsed: kind === "flower" ? null : counter,
        exactAmount: exactAmount,
        exactBoosts: exactBoostNames,
        criticalHit: kind === "flower" ? job.criticalHit || null : undefined,
        plotXY: kind === "crop" && plot && typeof plot.x === "number" ? {
          x: plot.x,
          y: plot.y
        } : undefined
      });
    });
    return {
      present: true,
      boostFlags: flags,
      perPlant: perPlant
    };
  }
  const out = {
    "farmId used for PRNG (farmPanelGetLastInfo().id)": lastInfo.id,
    "farmActivity present on merged state?": !!farmPanelField(g, "farmActivity"),
    Crimstone: (() => {
      const bag = farmPanelField(g, "crimstones");
      if (!bag || typeof bag !== "object") return {
        present: false
      };
      const flags = boostFlags([ "crimson_carp", "crim_peckster", "crimstone_armor", "crimstone_hammer", "skill_fire_kissed" ]);
      const perNode = Object.entries(bag).map(([id, rock]) => {
        const r = farmPanelComputeExactCrimstoneYield(g, rock);
        return {
          nodeId: id,
          minesLeft: rock && typeof rock.minesLeft === "number" ? rock.minesLeft : 5,
          exactAmount: r.amount,
          exactBoosts: r.boosts.map(b => `${b.name} (${b.valueText})`)
        };
      });
      return {
        present: true,
        boostFlags: flags,
        perNode: perNode
      };
    })(),
    Crops: buildPlantedSection(farmPanelField(g, "crops"), "crop", "crop", [ "green_amulet", "golden_cauliflower", "easter_bunny", "victoria_sisters", "beetroot_amulet", "sunflower_amulet", "scarecrow", "kuebiko", "coder", "peeled_potato", "potent_potato", "stellar_sunflower", "radical_radish", "skill_chonky_scarecrow", "scary_mike", "skill_horror_mike", "sir_goldensnout", "laurie_chuckle_crow", "skill_lauries_gains", "queen_cornelia", "skill_acre_farm", "skill_hectare_farm", "bountiful_harvest", "sunshower", "summer_guardian", "autumn_guardian", "winter_guardian", "spring_guardian", "insect_plague" ]),
    "Fruit Patches": buildPlantedSection(farmPanelField(g, "fruitPatches"), "fruit", "fruit", [ "skill_generous_orchard", "lady_bug", "black_bearry", "macaw", "skill_loyal_macaw", "camel_onesie", "fruit_picker_apron", "skill_fruitful_fumble", "banana_amulet", "banana_chicken", "lemon_shark", "lemon_shield", "reveling_lemon", "tomato_bombard", "bountiful_harvest", "summer_guardian", "autumn_guardian", "winter_guardian", "spring_guardian", "moon_hair", "faction_quiver", "skill_zesty_vibes" ]),
    "Flower Beds": buildPlantedSection((farmPanelField(g, "flowers") || {}).flowerBeds, "flower", "flower", [ "humming_bird", "butterfly", "desert_rose", "chicory", "salt_crystal_flower", "moth_shrine", "skill_petalled_perk", "legendary_shrine_flower" ]),
    Greenhouse: (() => {
      const gh = farmPanelField(g, "greenhouse");
      if (!gh || !gh.pots) return {
        present: false
      };
      return buildPlantedSection(gh.pots, "plant", "greenhouse", [ "skill_glass_room", "skill_seeded_bounty", "skill_greenhouse_gamble", "skill_greasy_plants", "grape_granny", "vinny", "grape_pants", "non_la_hat", "rice_panda", "olive_shield", "olive_royalty_shirt" ]);
    })(),
    "aoe object present on merged state?": !!farmPanelField(g, "aoe"),
    "collectibles present on merged state?": !!farmPanelField(g, "collectibles"),
    "Scary Mike position found": farmPanelGetCollectiblePosition(g, "Scary Mike"),
    "Basic Scarecrow position found": farmPanelGetCollectiblePosition(g, "Basic Scarecrow"),
    "Sir Goldensnout position found": farmPanelGetCollectiblePosition(g, "Sir Goldensnout"),
    "Laurie the Chuckle Crow position found": farmPanelGetCollectiblePosition(g, "Laurie the Chuckle Crow"),
    "Queen Cornelia position found": farmPanelGetCollectiblePosition(g, "Queen Cornelia"),
    "Gnome position found": farmPanelGetCollectiblePosition(g, "Gnome"),
    "Cobalt position found": farmPanelGetCollectiblePosition(g, "Cobalt"),
    "Clementine position found": farmPanelGetCollectiblePosition(g, "Clementine"),
    "Manually-entered Bud yield boosts (resourceBuds panel)": {
      resourceBudsConfigured: resourceBuds
    },
    "Known approximation": "AOE yield-boost cooldowns (Scary Mike/Sir Goldensnout/Laurie's Gains/Queen Cornelia/Chonky Scarecrow) use each specific plot's own synced boosted grow duration (baseDurationMs / boostedTime), same as the Turtle mining AOE fix — not a re-derivation of every active game-wide speed window, so a boost placed/removed mid-grow after the plot's last sync could shift the exact cooldown edge slightly."
  };
  box.style.display = "block";
  box.value = JSON.stringify(out, null, 2);
  box.focus();
  box.select();
};

$("farmPanelDebugBeeSwarmBtn").onclick = () => {
  const box = $("farmPanelDebugOutput");
  if (!farmPanelGameState) {
    box.style.display = "block";
    box.value = "Sync a Farm ID first, then tap this again.";
    return;
  }
  const g = farmSyncExtractGameState(farmPanelGameState);
  const cropsBag = farmPanelField(g, "crops") || {};
  const perPlotDetail = {};
  Object.entries(cropsBag).forEach(([plotId, plot]) => {
    const bs = plot && plot.beeSwarm;
    if (!bs) return;
    const cropName = plot && plot.crop && plot.crop.name || "(no crop planted)";
    if (!perPlotDetail[cropName]) perPlotDetail[cropName] = [];
    perPlotDetail[cropName].push({
      plotId: plotId,
      swarmCount: bs.count,
      swarmActivatedAt: bs.swarmActivatedAt
    });
  });
  const byCropSummary = {};
  Object.entries(perPlotDetail).forEach(([cropName, rows]) => {
    const totalCount = rows.reduce((sum, r) => sum + (typeof r.swarmCount === "number" ? r.swarmCount : 0), 0);
    byCropSummary[cropName] = {
      affectedPlots: rows.length,
      totalSwarmCount: totalCount,
      avgSwarmPerPlot: rows.length > 0 ? totalCount / rows.length : 0
    };
  });
  const out = {
    "beeSwarmActiveCount (farm-wide, from last sync)": beeSwarmActiveCount,
    "beeSwarmAffectedPlots (farm-wide, from last sync)": beeSwarmAffectedPlots,
    "farm-wide avg swarm/plot": beeSwarmAffectedPlots > 0 ? beeSwarmActiveCount / beeSwarmAffectedPlots : 0,
    "beeSwarmByCrop (stored, from last sync)": beeSwarmByCrop,
    "getBeeSwarmPerSwarmYield()": getBeeSwarmPerSwarmYield(),
    "isSkillActive('skill_pollen_power_up')": isSkillActive("skill_pollen_power_up"),
    "getBeeSwarmStatsForCrop('Barley')": typeof getBeeSwarmStatsForCrop === "function" ? getBeeSwarmStatsForCrop("Barley") : "(getBeeSwarmStatsForCrop not found — old app.js still loaded)",
    "live re-scan of raw synced data, byCropSummary": byCropSummary,
    "live re-scan of raw synced data, perPlotDetail": perPlotDetail
  };
  box.style.display = "block";
  box.value = JSON.stringify(out, null, 2);
  box.focus();
  box.select();
};

(function() {
  const debugButtonIds = [ "farmPanelDebugBtn", "farmPanelDebugBoostsBtn", "farmPanelDebugNodesBtn", "farmPanelDebugFertBtn", "farmPanelDebugCrowBtn", "farmPanelDebugCrowCooldownBtn", "farmPanelDebugGnomeBtn", "farmPanelDebugFactionBtn", "farmPanelDebugPetsBtn", "farmPanelDebugMutantsBtn", "farmPanelDebugTreeDataBtn", "farmPanelDebugMiningBtn", "farmPanelDebugCropsBtn", "farmPanelDebugBeeSwarmBtn" ];
  const outputBox = $("farmPanelDebugOutput");
  if (!outputBox) return;
  let openButtonId = null;
  debugButtonIds.forEach(id => {
    const el = $(id);
    if (!el || typeof el.onclick !== "function") return;
    const originalHandler = el.onclick;
    el.onclick = () => {
      if (openButtonId === id && outputBox.style.display !== "none") {
        outputBox.style.display = "none";
        openButtonId = null;
        return;
      }
      originalHandler();
      openButtonId = id;
    };
  });
})();

const GAMESTATE_SECTION_KEYS = [ "crops", "trees", "stones", "iron", "gold", "crimstones", "oilReserves", "lavaPits", "saltFarm", "sculptures", "stock", "flowers", "fruitPatches", "greenhouse", "henHouse", "barn", "buds", "bumpkin", "inventory", "collectibles", "home" ];

function farmPanelSectionStorageKey(name) {
  return "hl_fpgs__" + name;
}

function farmPanelSectionLenSig(v) {
  if (Array.isArray(v)) return "a" + v.length;
  if (v && typeof v === "object") return "o" + Object.keys(v).length;
  return "p" + typeof v + String(v);
}

let __gameStateSectionLenSigs = {};

let __farmPanelSaveGameStateHandle = null;

function farmPanelSaveGameState(json) {
  farmPanelGameState = json || null;
  
  farmPanelHoneySnapshotMs = Date.now();
  const toStore = farmPanelGameState;
  if (__farmPanelSaveGameStateHandle !== null) {
    if (typeof cancelIdleCallback === "function") cancelIdleCallback(__farmPanelSaveGameStateHandle); else clearTimeout(__farmPanelSaveGameStateHandle);
  }
  const write = () => {
    __farmPanelSaveGameStateHandle = null;
    farmPanelWriteGameStateSharded(toStore);
  };
  if (typeof requestIdleCallback === "function") __farmPanelSaveGameStateHandle = requestIdleCallback(write, {
    timeout: 1500
  }); else __farmPanelSaveGameStateHandle = setTimeout(write, 0);
}

function farmPanelWriteGameStateSharded(toStore) {
  try {
    if (!toStore || typeof toStore !== "object") {
      localStorage.setItem("hl_farm_panel_gamestate", JSON.stringify(toStore));
      localStorage.removeItem("hl_fpgs_meta");
      return;
    }
    const g = farmSyncExtractGameState(toStore);
    let containerKey = null;
    if (g !== toStore) {
      [ "game", "farm", "gameState", "state" ].some(k => {
        if (toStore[k] === g) {
          containerKey = k;
          return true;
        }
        return false;
      });
    }
    const hasGame = !!(g && typeof g === "object");
    const rootRest = {};
    Object.keys(toStore).forEach(k => {
      if (k !== containerKey) rootRest[k] = toStore[k];
    });
    const writeSection = (name, value) => {
      const lenSig = farmPanelSectionLenSig(value);
      if (__gameStateSectionLenSigs[name] === lenSig) return;
      __gameStateSectionLenSigs[name] = lenSig;
      try {
        localStorage.setItem(farmPanelSectionStorageKey(name), JSON.stringify(value));
      } catch (e) {}
    };
    writeSection("__rootRest", rootRest);
    if (hasGame) {
      const gameRest = {};
      Object.keys(g).forEach(k => {
        if (!GAMESTATE_SECTION_KEYS.includes(k)) gameRest[k] = g[k];
      });
      writeSection("__gameRest", gameRest);
      GAMESTATE_SECTION_KEYS.forEach(k => {
        if (Object.prototype.hasOwnProperty.call(g, k)) {
          writeSection(k, g[k]);
        } else if (__gameStateSectionLenSigs[k] !== undefined) {
          delete __gameStateSectionLenSigs[k];
          localStorage.removeItem(farmPanelSectionStorageKey(k));
        }
      });
    }
    localStorage.setItem("hl_fpgs_meta", JSON.stringify({
      containerKey: containerKey,
      hasGame: hasGame
    }));
    localStorage.removeItem("hl_farm_panel_gamestate");
  } catch (e) {}
}

function farmPanelLoadCachedGameState() {
  
  
  farmPanelHoneySnapshotMs = Date.now();
  try {
    const metaRaw = localStorage.getItem("hl_fpgs_meta");
    if (!metaRaw) {
      const raw = localStorage.getItem("hl_farm_panel_gamestate");
      if (raw) farmPanelGameState = JSON.parse(raw);
      return;
    }
    const meta = JSON.parse(metaRaw);
    const rootRest = JSON.parse(localStorage.getItem(farmPanelSectionStorageKey("__rootRest")) || "{}");
    __gameStateSectionLenSigs = {
      __rootRest: farmPanelSectionLenSig(rootRest)
    };
    let g = null;
    if (meta.hasGame) {
      g = JSON.parse(localStorage.getItem(farmPanelSectionStorageKey("__gameRest")) || "{}");
      __gameStateSectionLenSigs.__gameRest = farmPanelSectionLenSig(g);
      GAMESTATE_SECTION_KEYS.forEach(k => {
        const raw = localStorage.getItem(farmPanelSectionStorageKey(k));
        if (raw !== null) {
          try {
            g[k] = JSON.parse(raw);
            __gameStateSectionLenSigs[k] = farmPanelSectionLenSig(g[k]);
          } catch (e) {}
        }
      });
    }
    if (meta.containerKey && g) {
      const full = Object.assign({}, rootRest);
      full[meta.containerKey] = g;
      farmPanelGameState = full;
    } else if (g) {
      farmPanelGameState = g;
    } else {
      farmPanelGameState = rootRest;
    }
  } catch (e) {
    farmPanelGameState = null;
  }
}

function farmSyncNormalizeName(s) {
  return (s == null ? "" : String(s)).trim().toLowerCase();
}

function farmSyncFindIdByName(list, name) {
  if (!name || !Array.isArray(list)) return "none";
  const norm = farmSyncNormalizeName(name);
  const found = list.find(x => farmSyncNormalizeName(x.name) === norm);
  return found ? found.id : "none";
}

function farmSyncExtractBudTraits(bud) {
  if (!bud || typeof bud !== "object") return null;
  let type = bud.type || bud.Type || null;
  let stem = bud.stem || bud.Stem || null;
  let aura = bud.aura || bud.Aura || null;
  const attrs = Array.isArray(bud.attributes) ? bud.attributes : Array.isArray(bud.traits) ? bud.traits : null;
  if (attrs) {
    attrs.forEach(a => {
      if (!a) return;
      const key = farmSyncNormalizeName(a.trait_type || a.type || a.key);
      const val = a.value != null ? a.value : a.val;
      if (val == null) return;
      if (key === "type" && !type) type = val; else if (key === "stem" && !stem) stem = val; else if (key === "aura" && !aura) aura = val;
    });
  }
  return {
    type: type,
    stem: stem,
    aura: aura
  };
}

const BUD_SYNC_CATEGORIES = [ {
  prefix: "bud_sync_",
  types: () => BUD_GREENHOUSE_TYPES,
  stems: () => BUD_GREENHOUSE_STEMS,
  build: buildBudBoostEntries,
  get: () => greenhouseBuds,
  set: v => {
    greenhouseBuds = v;
  },
  save: () => saveGreenhouseBuds()
}, {
  prefix: "abud_sync_",
  types: () => BUD_ANIMAL_TYPES,
  stems: () => BUD_ANIMAL_STEMS,
  build: buildAnimalBudBoostEntries,
  get: () => animalBuds,
  set: v => {
    animalBuds = v;
  },
  save: () => saveAnimalBuds()
}, {
  prefix: "fbud_sync_",
  types: () => BUD_FRUIT_TYPES,
  stems: () => BUD_FRUIT_STEMS,
  build: buildFruitBudBoostEntries,
  get: () => fruitBuds,
  set: v => {
    fruitBuds = v;
  },
  save: () => saveFruitBuds()
}, {
  prefix: "cbud_sync_",
  types: () => BUD_CROP_TYPES,
  stems: () => BUD_CROP_STEMS,
  build: buildCropBudBoostEntries,
  get: () => cropBuds,
  set: v => {
    cropBuds = v;
  },
  save: () => saveCropBuds()
}, {
  prefix: "rbud_sync_",
  types: () => BUD_RESOURCE_TYPES,
  stems: () => BUD_RESOURCE_STEMS,
  build: buildResourceBudBoostEntries,
  get: () => resourceBuds,
  set: v => {
    resourceBuds = v;
  },
  save: () => saveResourceBuds()
} ];

function clearManualBudsAndPets() {
  BUD_SYNC_CATEGORIES.forEach(cat => {
    const manualIds = [];
    const kept = [];
    cat.get().forEach(b => {
      if (b && typeof b.id === "string" && b.id.indexOf(cat.prefix) === 0) {
        kept.push(b);
      } else if (b) {
        manualIds.push(b.id);
      }
    });
    if (!manualIds.length) return;
    const removeSet = new Set(manualIds);
    const dropBoostIds = new Set;
    BOOSTS = BOOSTS.filter(x => {
      if (x.budId && removeSet.has(x.budId)) {
        dropBoostIds.add(x.id);
        return false;
      }
      return true;
    });
    if (dropBoostIds.size) selectedBoosts = selectedBoosts.filter(id => !dropBoostIds.has(id));
    cat.set(kept);
    cat.save();
  });
  if (typeof petsData !== "undefined" && Array.isArray(petsData)) {
    const keptPets = petsData.filter(p => p && typeof p.id === "string" && p.id.indexOf(PET_SYNC_PREFIX) === 0);
    if (keptPets.length !== petsData.length) {
      petsData = keptPets;
      savePetsData();
      if (typeof __petCardMemo !== "undefined") __petCardMemo.clear();
    }
  }
}

function syncBudsFromFarmData(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const budsBag = asObj(farmPanelField(g, "buds")) || {};
  const realBudIds = Object.keys(budsBag);
  const touched = {
    greenhouse: false,
    animal: false,
    fruit: false,
    crop: false,
    resource: false
  };
  const catKeyByPrefix = {
    bud_sync_: "greenhouse",
    abud_sync_: "animal",
    fbud_sync_: "fruit",
    cbud_sync_: "crop",
    rbud_sync_: "resource"
  };
  const budsSig = realBudIds.length + "|" + JSON.stringify(budsBag);
  if (budsSig === __lastBudsSig && __lastBudsResult) {
    return {
      matched: __lastBudsResult.matched,
      budCount: __lastBudsResult.budCount,
      touched: touched
    };
  }
  __lastBudsSig = budsSig;
  let matched = 0;
  const sameTraits = (a, b) => a.typeId === b.typeId && a.stemId === b.stemId && a.auraId === b.auraId;
  BUD_SYNC_CATEGORIES.forEach(cat => {
    const catKey = catKeyByPrefix[cat.prefix];
    const existingSynced = new Map;
    const keptManual = [];
    cat.get().forEach(b => {
      if (b && typeof b.id === "string" && b.id.indexOf(cat.prefix) === 0) {
        existingSynced.set(b.id, b);
      } else {
        keptManual.push(b);
      }
    });
    const freshEntries = new Map;
    realBudIds.forEach(realId => {
      const traits = farmSyncExtractBudTraits(budsBag[realId]);
      if (!traits) return;
      const typeId = farmSyncFindIdByName(cat.types(), traits.type);
      const stemId = farmSyncFindIdByName(cat.stems(), traits.stem);
      const auraId = farmSyncFindIdByName(BUD_AURAS, traits.aura);
      if (typeId === "none" && stemId === "none") return;
      const budUID = cat.prefix + realId;
      freshEntries.set(budUID, {
        id: budUID,
        typeId: typeId,
        stemId: stemId,
        auraId: auraId,
        synced: true
      });
    });
    matched += freshEntries.size;
    const toRemove = [];
    existingSynced.forEach((old, id) => {
      const fresh = freshEntries.get(id);
      if (!fresh || !sameTraits(old, fresh)) toRemove.push(id);
    });
    const toAdd = [];
    freshEntries.forEach((fresh, id) => {
      const old = existingSynced.get(id);
      if (!old || !sameTraits(old, fresh)) toAdd.push(fresh);
    });
    if (!toRemove.length && !toAdd.length) return;
    touched[catKey] = true;
    if (toRemove.length) {
      const removeSet = new Set(toRemove);
      const dropBoostIds = new Set;
      BOOSTS = BOOSTS.filter(x => {
        if (x.budId && removeSet.has(x.budId)) {
          dropBoostIds.add(x.id);
          return false;
        }
        return true;
      });
      if (dropBoostIds.size) {
        selectedBoosts = selectedBoosts.filter(id => !dropBoostIds.has(id));
      }
      toRemove.forEach(id => existingSynced.delete(id));
    }
    toAdd.forEach(fresh => {
      const entries = cat.build(fresh.id, fresh.typeId, fresh.stemId, fresh.auraId);
      if (!entries.length) return;
      existingSynced.set(fresh.id, fresh);
      entries.forEach(e => {
        BOOSTS.push(e);
        if (!selectedBoosts.includes(e.id)) selectedBoosts.push(e.id);
      });
    });
    cat.set(keptManual.concat(Array.from(existingSynced.values())));
    cat.save();
  });
  if (matched || realBudIds.length) saveBoostState();
  __lastBudsResult = {
    matched: matched,
    budCount: realBudIds.length
  };
  __saveSyncSigs();
  return {
    matched: matched,
    budCount: realBudIds.length,
    touched: touched
  };
}

const FERTILIZER_SYNC_MAP = {
  "sprout mix": "apply_sprout_mix",
  "rapid root": "apply_rapid_root",
  "sproutroot surprise": "apply_sproutroot_surprise",
  "fruitful blend": "apply_fruitful_blend",
  "turbofruit mix": "apply_turbofruit_mix"
};

function farmSyncExtractFertName(v) {
  if (!v) return null;
  if (typeof v === "string") return v;
  if (typeof v === "object") {
    if (typeof v.name === "string") return v.name;
    if (typeof v.type === "string") return v.type;
  }
  return null;
}

function farmSyncGetPlotFertName(plot, subKey) {
  if (!plot || typeof plot !== "object") return null;
  const job = plot[subKey];
  const candidates = [ job && job.fertiliser, job && job.fertilizer, plot.fertiliser, plot.fertilizer ];
  for (const c of candidates) {
    const name = farmSyncExtractFertName(c);
    if (name) return name;
  }
  return null;
}

function syncFertilizersFromFarmData(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const foundIds = new Set;
  const scanBag = (bag, subKey) => {
    const obj = asObj(bag);
    if (!obj) return;
    Object.values(obj).forEach(plot => {
      const fertName = farmSyncGetPlotFertName(plot, subKey);
      if (!fertName) return;
      const boostId = FERTILIZER_SYNC_MAP[farmSyncNormalizeName(fertName)];
      if (boostId) foundIds.add(boostId);
    });
  };
  scanBag(farmPanelField(g, "crops"), "crop");
  scanBag(farmPanelField(g, "fruitPatches"), "fruit");
  let matched = 0;
  foundIds.forEach(id => {
    const boost = BOOSTS.find(b => b.id === id);
    if (!boost) return;
    if (selectedBoosts.includes(id)) {
      matched++;
      return;
    }
    if (boost.exclusiveWith) {
      const exList = Array.isArray(boost.exclusiveWith) ? boost.exclusiveWith : [ boost.exclusiveWith ];
      selectedBoosts = selectedBoosts.filter(x => !exList.includes(x));
    }
    selectedBoosts.push(id);
    matched++;
  });
  if (matched) saveBoostState();
  return {
    matched: matched
  };
}

function farmSyncFindConsumableName(obj, targets, depth, seen) {
  if (!obj || typeof obj !== "object" || depth > 3) return null;
  if (seen.has(obj)) return null;
  seen.add(obj);
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    if (typeof v === "string") {
      const norm = farmSyncNormalizeName(v);
      if (targets.includes(norm)) return v;
    } else if (v && typeof v === "object") {
      const nameField = typeof v.name === "string" ? v.name : typeof v.type === "string" ? v.type : null;
      if (nameField && targets.includes(farmSyncNormalizeName(nameField))) return nameField;
      const found = farmSyncFindConsumableName(v, targets, depth + 1, seen);
      if (found) return found;
    }
  }
  return null;
}

const SPICE_SYNC_ANIMAL_BAGS = {
  chicken: "chickens",
  sheep: "sheep",
  cow: "cows"
};

const SPICE_SYNC_TARGETS = [ "salt lick", "honey treat" ];

function syncSpiceFromFarmData(g, gFallback) {
  
  
  
  
  
  
  
  
  
  
  
  
  
  let matched = 0;
  let touched = false;
  SPICE_ANIMAL_TYPES.forEach(type => {
    let bag = farmSyncGetAnimalRecords(g, type);
    const bagHasAnyFeedBuff = Object.values(bag || {}).some(a => a && typeof a === "object" && a.feedBuff && a.feedBuff.name);
    if (!bagHasAnyFeedBuff && gFallback) {
      const fallbackBag = farmSyncGetAnimalRecords(gFallback, type);
      const fallbackHasAnyFeedBuff = Object.values(fallbackBag || {}).some(a => a && typeof a === "object" && a.feedBuff && a.feedBuff.name);
      if (fallbackHasAnyFeedBuff || (!bag || !Object.keys(bag).length)) bag = fallbackBag;
    }
    let hasSaltLick = false;
    let hasHoneyTreat = false;
    Object.values(bag || {}).forEach(animal => {
      if (!animal || typeof animal !== "object") return;
      const buff = animal.feedBuff;
      if (!buff || typeof buff !== "object" || !buff.name) return;
      const stillActive = typeof buff.harvestsRemaining !== "number" || buff.harvestsRemaining > 0;
      if (!stillActive) return;
      if (buff.name === "Salt Lick") {
        hasSaltLick = true;
        matched++;
      } else if (buff.name === "Honey Treat") {
        hasHoneyTreat = true;
        matched++;
      }
    });
    if (hasSaltLick !== !!spiceUsage.saltLick[type]) {
      spiceUsage.saltLick[type] = hasSaltLick;
      touched = true;
    }
    if (hasSaltLick && !spiceUsage.saltLick.active) {
      spiceUsage.saltLick.active = true;
      touched = true;
    }
    if (hasHoneyTreat !== !!spiceUsage.honeyTreat[type]) {
      spiceUsage.honeyTreat[type] = hasHoneyTreat;
      touched = true;
    }
    if (hasHoneyTreat && !spiceUsage.honeyTreat.active) {
      spiceUsage.honeyTreat.active = true;
      touched = true;
    }
    
    
    if (hasSaltLick && spiceUsage.honeyTreat[type]) {
      spiceUsage.honeyTreat[type] = false;
      touched = true;
    }
  });
  if (touched) saveSpiceUsage();
  return {
    matched: matched
  };
}

const CROW_AOE_DEFS = {
  basic_scarecrow: {
    collectibleName: "Basic Scarecrow",
    tier: "Basic",
    skillName: "Chonky Scarecrow"
  },
  scary_mike: {
    collectibleName: "Scary Mike",
    tier: "Medium",
    skillName: "Horror Mike"
  },
  laurie_chuckle_crow: {
    collectibleName: "Laurie the Chuckle Crow",
    tier: "Advanced",
    skillName: "Laurie's Gains"
  }
};

function farmSyncGetCoords(obj) {
  if (!obj || typeof obj !== "object") return null;
  const c = obj.coordinates && typeof obj.coordinates === "object" ? obj.coordinates : obj;
  const x = typeof c.x === "number" ? c.x : typeof c.x === "string" && c.x.trim() !== "" ? parseFloat(c.x) : NaN;
  const y = typeof c.y === "number" ? c.y : typeof c.y === "string" && c.y.trim() !== "" ? parseFloat(c.y) : NaN;
  if (isNaN(x) || isNaN(y)) return null;
  return {
    x: x,
    y: y
  };
}

function syncCrowAoeOverrides(g) {
  const asObj = v => v && typeof v === "object" && !Array.isArray(v) ? v : null;
  const mainCollectibles = asObj(farmPanelField(g, "collectibles")) || {};
  const home = asObj(g && g.home);
  const homeCollectibles = farmSyncGetInteriorCollectiblesMerged(g);
  const cropsBag = asObj(farmPanelField(g, "crops")) || {};
  const skills = asObj(g && g.bumpkin && g.bumpkin.skills) || {};
  const hasSkill = name => Object.keys(skills).some(sn => sn.trim().toLowerCase() === name.trim().toLowerCase());
  let anyChange = false;
  Object.entries(CROW_AOE_DEFS).forEach(([boostId, def]) => {
    const a = mainCollectibles[def.collectibleName];
    const b = homeCollectibles[def.collectibleName];
    const instances = farmSyncPickActivePlacedInstances([ ...Array.isArray(a) ? a : [], ...Array.isArray(b) ? b : [] ]);
    if (!instances.length) {
      if (aoeSyncOverrides[boostId] !== undefined) {
        delete aoeSyncOverrides[boostId];
        anyChange = true;
      }
      return;
    }
    const crowCoords = instances.map(farmSyncGetCoords).filter(Boolean);
    if (!crowCoords.length) return;
    const radius = hasSkill(def.skillName) ? 3 : 1;
    const size = radius * 2 + 1;
    const {destroyedIds: destroyedIds} = computeDestroyedCropPlotIds(g);
    let count = 0;
    Object.entries(cropsBag).forEach(([plotId, plot]) => {
      if (!plot || typeof plot !== "object") return;
      if (destroyedIds.has(plotId)) return;
      const cropName = plot.crop && plot.crop.name;
      if (!cropName) return;
      const cropDef = BASE_CROPS[cropName];
      if (!cropDef || cropDef.tier !== def.tier) return;
      const plotCoords = farmSyncGetCoords(plot);
      if (!plotCoords) return;
      const inRange = crowCoords.some(c => {
        const dx = plotCoords.x - c.x;
        const dy = plotCoords.y - c.y;
        return Math.abs(dx) <= radius && dy <= -1 && dy >= -size;
      });
      if (inRange) count++;
    });
    if (aoeSyncOverrides[boostId] !== count) {
      aoeSyncOverrides[boostId] = count;
      anyChange = true;
    }
  });
  if (anyChange) saveAoeSyncOverrides();
  return {
    changed: anyChange
  };
}

let __lastSyncTiming = null;

let __syncMark = null;

function __markSub(label) {
  if (typeof __syncMark === "function") __syncMark(label);
}

let __syncTimingPanelOpen = false;

function renderSyncTimingPanelBody() {
  let panel = document.getElementById("syncTimingPanel");
  if (!panel) {
    panel = document.createElement("div");
    panel.id = "syncTimingPanel";
    panel.style.cssText = "position:fixed;left:8px;right:8px;bottom:8px;max-height:60vh;overflow:auto;" + "background:#12121a;color:#e8e8f0;border:1px solid #444;border-radius:10px;padding:10px;" + "font:12px/1.5 monospace;z-index:99999;box-shadow:0 4px 18px rgba(0,0,0,.5);white-space:pre-wrap;";
    document.body.appendChild(panel);
  }
  if (!__lastSyncTiming) {
    panel.innerHTML = "";
    const empty = document.createElement("div");
    empty.style.cssText = "display:flex;justify-content:space-between;align-items:center;gap:8px;";
    const msg = document.createElement("span");
    msg.textContent = "⏱️ No sync timing yet — sync a farm first.";
    const closeBtn0 = document.createElement("button");
    closeBtn0.textContent = "✕";
    closeBtn0.style.cssText = "padding:4px 10px;border-radius:6px;border:1px solid #666;background:#222;color:#fff;font:12px sans-serif;";
    closeBtn0.onclick = () => closeSyncTimingPanel();
    empty.appendChild(msg);
    empty.appendChild(closeBtn0);
    panel.appendChild(empty);
    return;
  }
  const {farmId: farmId, marks: marks, errorMsg: errorMsg} = __lastSyncTiming;
  let prev = 0;
  const lines = marks.map(m => {
    const step = (m.at - prev).toFixed(0);
    prev = m.at;
    return `${m.label.padEnd(38)} +${step}ms  (t=${m.at.toFixed(0)}ms)`;
  });
  const text = `Sync timing — Farm #${farmId}${errorMsg ? " (FAILED: " + errorMsg + ")" : ""}\n` + lines.join("\n");
  panel.innerHTML = "";
  const header = document.createElement("div");
  header.style.cssText = "display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;gap:8px;";
  const title = document.createElement("strong");
  title.textContent = `⏱️ Sync timing — Farm #${farmId}`;
  title.style.color = errorMsg ? "#ff8a8a" : "#8fffb0";
  const btnRow = document.createElement("div");
  const copyBtn = document.createElement("button");
  copyBtn.textContent = "Copy";
  copyBtn.style.cssText = "margin-right:6px;padding:4px 10px;border-radius:6px;border:1px solid #666;background:#222;color:#fff;font:12px sans-serif;";
  copyBtn.onclick = () => {
    const finish = ok => {
      copyBtn.textContent = ok ? "Copied!" : "Copy failed";
      setTimeout(() => copyBtn.textContent = "Copy", 1200);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => finish(true)).catch(() => finish(false));
    } else {
      try {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.focus();
        ta.select();
        const ok = document.execCommand("copy");
        document.body.removeChild(ta);
        finish(ok);
      } catch (e) {
        finish(false);
      }
    }
  };
  const closeBtn = document.createElement("button");
  closeBtn.textContent = "✕";
  closeBtn.style.cssText = "padding:4px 10px;border-radius:6px;border:1px solid #666;background:#222;color:#fff;font:12px sans-serif;";
  closeBtn.onclick = () => closeSyncTimingPanel();
  btnRow.appendChild(copyBtn);
  btnRow.appendChild(closeBtn);
  header.appendChild(title);
  header.appendChild(btnRow);
  panel.appendChild(header);
  const body = document.createElement("div");
  body.textContent = lines.join("\n") + (errorMsg ? `\n\n⚠️ Sync failed: ${errorMsg}` : "");
  panel.appendChild(body);
  if (errorMsg) {
    const errNote = document.createElement("div");
    errNote.style.cssText = "color:#ff8a8a;margin-top:6px;";
    errNote.textContent = "⚠️ Sync failed partway — timings above still show where it got to.";
    panel.appendChild(errNote);
  }
}

function closeSyncTimingPanel() {
  __syncTimingPanelOpen = false;
  const panel = document.getElementById("syncTimingPanel");
  if (panel) panel.remove();
  const toggle = document.getElementById("syncTimingToggle");
  if (toggle) toggle.classList.remove("open");
}

