function saveBoosts() {
  localStorage.setItem("hl_ticket_v2_boosts", JSON.stringify(ticketBoosts));
}

function readFarmVipEnabled() {
  return localStorage.getItem("hl_ticket_vip_enabled") === "1";
}

function readFarmSyncedId() {
  return localStorage.getItem("hl_farm_panel_id") || "";
}

if (readFarmVipEnabled()) ticketBoosts.vip.enabled = true;

function refreshTicketCalcVipFromSync() {
  if (readFarmVipEnabled() && !ticketBoosts.vip.enabled) {
    ticketBoosts.vip.enabled = true;
    saveBoosts();
  }
  if (typeof renderTicketCalc === "function" && $("ticketCalcBody") && $("ticketCalcBody").dataset.ticketCalcInit) renderTicketCalc();
}

let undeliveredLastSeason = parseFloat(localStorage.getItem("hl_ticket_v2_undelivered")) || 0;

function setUndelivered(v) {
  undeliveredLastSeason = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_undelivered", String(undeliveredLastSeason));
}

let seasonDays = parseFloat(localStorage.getItem("hl_ticket_v2_season_days"));

if (isNaN(seasonDays)) seasonDays = 90;

function setSeasonDays(v) {
  seasonDays = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_season_days", String(seasonDays));
}

let npcDeliverToggle = safeParse(localStorage.getItem("hl_ticket_v2_npc_deliver"), {});

function setNpcDeliver(npc, val) {
  npcDeliverToggle[npc] = !!val;
  localStorage.setItem("hl_ticket_v2_npc_deliver", JSON.stringify(npcDeliverToggle));
}

let npcSkipDays = safeParse(localStorage.getItem("hl_ticket_v2_npc_skip"), {});

function setNpcSkip(npc, val) {
  npcSkipDays[npc] = Math.max(0, parseFloat(val) || 0);
  localStorage.setItem("hl_ticket_v2_npc_skip", JSON.stringify(npcSkipDays));
}

let animalWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_animal_weekly")) || 0;

function setAnimalWeekly(v) {
  animalWeekly = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_animal_weekly", String(animalWeekly));
}

let bountyToggle = localStorage.getItem("hl_ticket_v2_bounty_toggle") === "1";

function setBountyToggle(v) {
  bountyToggle = !!v;
  localStorage.setItem("hl_ticket_v2_bounty_toggle", bountyToggle ? "1" : "0");
}

let bountyWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_bounty_weekly")) || 0;

function setBountyWeekly(v) {
  bountyWeekly = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_bounty_weekly", String(bountyWeekly));
}

let megastoreTickets = parseFloat(localStorage.getItem("hl_ticket_v2_megastore")) || 0;

function setMegastore(v) {
  megastoreTickets = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_megastore", String(megastoreTickets));
}

let dailyRewardTickets = parseFloat(localStorage.getItem("hl_ticket_v2_daily_reward")) || 0;

let dailyRewardManual = localStorage.getItem("hl_ticket_v2_daily_reward_manual") === "1";

function setDailyReward(v) {
  dailyRewardTickets = Math.max(0, parseFloat(v) || 0);
  dailyRewardManual = true;
  localStorage.setItem("hl_ticket_v2_daily_reward", String(dailyRewardTickets));
  localStorage.setItem("hl_ticket_v2_daily_reward_manual", "1");
}

function getEffectiveDailyReward() {
  return !dailyRewardManual && ticketBoosts.vip.enabled ? seasonDays : dailyRewardTickets;
}

let choresWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_chores_weekly")) || 0;

function setChoresWeekly(v) {
  choresWeekly = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_chores_weekly", String(choresWeekly));
}

let npcFlowerCost = safeParse(localStorage.getItem("hl_ticket_v2_npc_flower"), {});

function setNpcFlower(npc, val) {
  npcFlowerCost[npc] = Math.max(0, parseFloat(val) || 0);
  localStorage.setItem("hl_ticket_v2_npc_flower", JSON.stringify(npcFlowerCost));
}

let animalFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_animal_flower")) || 0;

function setAnimalFlower(v) {
  animalFlowerCost = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_animal_flower", String(animalFlowerCost));
}

let bountyFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_bounty_flower")) || 0;

function setBountyFlower(v) {
  bountyFlowerCost = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_bounty_flower", String(bountyFlowerCost));
}

let choresFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_chores_flower")) || 0;

function setChoresFlower(v) {
  choresFlowerCost = Math.max(0, parseFloat(v) || 0);
  localStorage.setItem("hl_ticket_v2_chores_flower", String(choresFlowerCost));
}

function safeParse(raw, fallback) {
  try {
    const v = JSON.parse(raw || "null");
    return v && typeof v === "object" ? v : fallback;
  } catch (e) {
    return fallback;
  }
}

function computeAll() {
  const activeBoostCount = BOOST_TIERS.filter(t => ticketBoosts[t].enabled).length;
  const vipBonus = ticketBoosts.vip.enabled ? 2 : 0;
  const totalBoostBonus = activeBoostCount + vipBonus;
  const boostCostTotal = BOOST_TIERS.reduce((sum, t) => {
    const b = ticketBoosts[t];
    return sum + (b.enabled && b.costMode === "cost" ? parseFloat(b.cost) || 0 : 0);
  }, 0);
  const firstWeekDeduction = Math.min(7, seasonDays);
  const remainingDeliveryDays = Math.max(0, seasonDays - firstWeekDeduction);
  const doubleDeliveryWeeks = Math.floor(remainingDeliveryDays / 7);
  const totalSeasonWeeks = Math.floor(seasonDays / 7);
  const animalBountyEligibleWeeks = Math.max(0, totalSeasonWeeks - 2);
  let npcTotal = 0;
  let npcDoubleBonus = 0;
  let npcFlowerTotal = 0;
  const npcRows = NPC_KEYS.map(npc => {
    const base = TICKET_REWARDS_APP[npc];
    const perDelivery = base + totalBoostBonus;
    const on = !!npcDeliverToggle[npc];
    const skip = Math.min(remainingDeliveryDays, npcSkipDays[npc] || 0);
    const days = on ? Math.max(0, remainingDeliveryDays - skip) : 0;
    const doubleWeeksForThis = on ? Math.floor(days / 7) : 0;
    const total = perDelivery * days + perDelivery * doubleWeeksForThis;
    const flowerCost = npcFlowerCost[npc] || 0;
    const flowerTotal = flowerCost * days;
    npcTotal += total;
    npcDoubleBonus += perDelivery * doubleWeeksForThis;
    npcFlowerTotal += flowerTotal;
    return {
      npc: npc,
      base: base,
      perDelivery: perDelivery,
      on: on,
      skip: skip,
      days: days,
      total: total,
      flowerCost: flowerCost,
      flowerTotal: flowerTotal
    };
  });
  const animalTotal = animalWeekly * animalBountyEligibleWeeks;
  const bountyItemTotal = bountyWeekly * animalBountyEligibleWeeks;
  const bountyCompletionBonus = bountyToggle ? BOUNTY_WEEKLY_BONUS * animalBountyEligibleWeeks : 0;
  const bountyTotal = bountyItemTotal + bountyCompletionBonus;
  const choresTotal = choresWeekly * animalBountyEligibleWeeks;
  const animalFlowerTotal = animalFlowerCost * animalBountyEligibleWeeks;
  const bountyFlowerTotal = bountyFlowerCost * animalBountyEligibleWeeks;
  const choresFlowerTotal = choresFlowerCost * animalBountyEligibleWeeks;
  const grandFlowerTotal = npcFlowerTotal + animalFlowerTotal + bountyFlowerTotal + choresFlowerTotal;
  const dailyRewardTotal = getEffectiveDailyReward();
  const grandTotal = npcTotal + undeliveredLastSeason + animalTotal + bountyTotal + choresTotal + megastoreTickets + dailyRewardTotal - boostCostTotal;
  return {
    activeBoostCount: activeBoostCount,
    vipBonus: vipBonus,
    totalBoostBonus: totalBoostBonus,
    boostCostTotal: boostCostTotal,
    firstWeekDeduction: firstWeekDeduction,
    remainingDeliveryDays: remainingDeliveryDays,
    doubleDeliveryWeeks: doubleDeliveryWeeks,
    totalSeasonWeeks: totalSeasonWeeks,
    animalBountyEligibleWeeks: animalBountyEligibleWeeks,
    npcRows: npcRows,
    npcTotal: npcTotal,
    npcDoubleBonus: npcDoubleBonus,
    npcFlowerTotal: npcFlowerTotal,
    animalTotal: animalTotal,
    bountyTotal: bountyTotal,
    bountyItemTotal: bountyItemTotal,
    bountyCompletionBonus: bountyCompletionBonus,
    choresTotal: choresTotal,
    animalFlowerTotal: animalFlowerTotal,
    bountyFlowerTotal: bountyFlowerTotal,
    choresFlowerTotal: choresFlowerTotal,
    grandFlowerTotal: grandFlowerTotal,
    dailyRewardTotal: dailyRewardTotal,
    grandTotal: grandTotal
  };
}

function renderTicketCalc() {
  const el = $("ticketCalcBody");
  if (!el) return;
  const c = computeAll();
  const vip = ticketBoosts.vip;
  const vipFarmId = readFarmSyncedId();
  const vipIsLifetime = farmPanelGetLastInfo().vipLifetime;
  const vipDetected = readFarmVipEnabled();
  const vipSourceNote = !vipFarmId ? "No farm synced — toggle manually" : vipDetected ? `Synced from Farm ${vipFarmId} — VIP active${vipIsLifetime ? " (Lifetime)" : ""} · auto-enabled` : `Synced from Farm ${vipFarmId} — no active VIP · toggle manually if needed`;
  const vipCardHtml = `\n      <div class="tc-boost-card" style="border-color:var(--sun-deep);background:linear-gradient(135deg, rgba(217,112,31,.14), var(--paper-dim));">\n        <div class="tc-boost-head">\n          <div>\n            <div class="tc-boost-name">⭐ VIP Access</div>\n            <div class="tc-boost-tag">+2 ticket per delivery when active</div>\n          </div>\n          <div class="tc-seg" style="width:120px;">\n            <button type="button" class="tc-seg-btn boost-enable-btn ${vip.enabled ? "active" : "active off"}" data-tier="vip">\n              ${vip.enabled ? "ON" : "OFF"}\n            </button>\n          </div>\n        </div>\n        <div class="tc-field-note" style="margin-top:2px;">🔄 ${vipSourceNote}</div>\n      </div>`;
  const boostCardsHtml = BOOST_TIERS.map(t => {
    const b = ticketBoosts[t];
    return `\n      <div class="tc-boost-card">\n        <div class="tc-boost-head">\n          <div>\n            <div class="tc-boost-name">${BOOST_LABELS[t]}</div>\n            <div class="tc-boost-tag">+1 ticket per delivery when active</div>\n          </div>\n          <div class="tc-seg" style="width:120px;">\n            <button type="button" class="tc-seg-btn boost-enable-btn ${b.enabled ? "active" : "active off"}" data-tier="${t}">\n              ${b.enabled ? "ON" : "OFF"}\n            </button>\n          </div>\n        </div>\n        ${b.enabled ? `\n        <div class="tc-seg">\n          <button type="button" class="tc-seg-btn cost-mode-btn ${b.costMode === "cost" ? "active danger" : ""}" data-tier="${t}" data-mode="cost">Cost Ticket</button>\n          <button type="button" class="tc-seg-btn cost-mode-btn ${b.costMode === "nocost" ? "active" : ""}" data-tier="${t}" data-mode="nocost">No Cost</button>\n        </div>\n        ${b.costMode === "cost" ? `\n        <div class="tc-boost-cost-row">\n          <label>Ticket cost to activate</label>\n          <input type="number" min="0" step="1" class="boost-cost-input" data-tier="${t}" value="${b.cost}" />\n        </div>` : ""}` : ""}\n      </div>`;
  }).join("");
  const npcRowsHtml = c.npcRows.map(r => {
    const s = slug(r.npc);
    const skipVal = npcSkipDays[r.npc] || 0;
    const flowerVal = npcFlowerCost[r.npc] || 0;
    return `\n      <div class="tc-npc-row" style="flex-wrap:wrap;">\n        <img class="tc-npc-icon" src="${NPC_ICONS[r.npc]}" alt="${TICKET_NPC_DISPLAY_NAMES[r.npc]}" />\n        <div style="flex:1;min-width:120px;">\n          <div class="tc-npc-name">${TICKET_NPC_DISPLAY_NAMES[r.npc]}</div>\n          <div class="tc-npc-meta" id="npcMeta-${s}">base ${fmt(r.base)} → ${fmt(r.perDelivery)}/delivery${c.totalBoostBonus ? ` (+${c.totalBoostBonus} boost)` : ""}${r.skip ? ` − ${fmt(r.skip)} skipped` : ""}</div>\n        </div>\n        <div class="tc-npc-toggle">\n          <button type="button" class="npc-deliver-btn ${r.on ? "active" : ""}" data-npc="${r.npc}" data-val="1">Deliver it</button>\n          <button type="button" class="npc-deliver-btn ${!r.on ? "active off-state" : ""}" data-npc="${r.npc}" data-val="0">Do not deliver</button>\n        </div>\n        <div class="tc-npc-total" id="npcTotal-${s}">${fmt(r.total)}</div>\n        <div class="tc-npc-skip" style="flex-basis:100%;display:flex;align-items:center;gap:8px;margin-top:6px;">\n          <label style="font-size:11.4px;color:var(--ink-soft);flex:1;">Skip days (days not delivered)</label>\n          <input type="number" min="0" step="1" class="npc-skip-input" data-npc="${r.npc}" value="${skipVal}"\n            style="width:64px;text-align:center;font-family:'JetBrains Mono',monospace;font-size:13.2px;border:2px solid var(--ink);border-radius:0;padding:5px 2px;background:#fff;color:var(--ink);" />\n        </div>\n        <div class="tc-npc-flower" style="flex-basis:100%;display:flex;align-items:center;gap:8px;margin-top:6px;">\n          <label style="font-size:11.4px;color:var(--ink-soft);flex:1;">${FLOWER_ICON} FLOWER cost per delivery</label>\n          <input type="number" min="0" step="1" class="npc-flower-input" data-npc="${r.npc}" value="${flowerVal}"\n            style="width:64px;text-align:center;font-family:'JetBrains Mono',monospace;font-size:13.2px;border:2px solid var(--ink);border-radius:0;padding:5px 2px;background:#fff;color:var(--ink);" />\n        </div>\n      </div>\n    `;
  }).join("");
  el.innerHTML = `\n      <div class="tc-intro">\n        🎟️ Project how many <b>Seasonal Tickets</b> you'll earn from deliveries, boosts, animals, Bounty Board, and the Megastore over the whole season — same purpose every season (buying SFT/NFTs in Stella Megastore and bidding in the Auction House), just a new label each time.\n      </div>\n\n      <div class="tc-section">\n        <div class="tc-section-title">🚀 TICKET BOOSTS (Stella Megastore)</div>\n        <div class="tc-section-sub">Tier boosts are off by default and toggled manually; each adds +1 ticket per NPC delivery. VIP Access also adds +2 — it's auto-enabled when your synced farm has active VIP/Lifetime Farmer Banner, but you can toggle it manually too. Bonuses stack and also apply to animal sales.</div>\n        ${vipCardHtml}\n        ${boostCardsHtml}\n      </div>\n\n      <div class="tc-section">\n        <div class="tc-section-title">📦 UNDELIVERED LAST SEASON</div>\n        <div class="tc-section-sub">If you held a delivery back from the end of last season, it carries over and can be delivered on day 1 of the new season. Enter it here and it's added straight to your total.</div>\n        <div class="tc-field">\n          <label>Undelivered tickets from last season</label>\n          <input type="number" min="0" step="1" id="undeliveredInput" value="${undeliveredLastSeason}" />\n        </div>\n      </div>\n\n      <div class="tc-section">\n        <div class="tc-section-title">📅 SEASON LENGTH &amp; DOUBLE DELIVERY</div>\n        <div class="tc-section-sub">Find the day countdown in the Stella Megastore and enter it here.</div>\n        <div class="tc-field">\n          <label>Days the season will last</label>\n          <input type="number" min="0" step="1" id="seasonDaysInput" value="${seasonDays}" />\n        </div>\n        <div class="tc-breakdown">\n          <div class="tc-breakdown-line"><span>Week 1 deducted (no deliveries allowed at season start)</span><b id="bd-firstweek">−${fmt(c.firstWeekDeduction)} days</b></div>\n          <div class="tc-breakdown-line"><span>Delivery-eligible days remaining</span><b id="bd-remaining">${fmt(c.remainingDeliveryDays)} days</b></div>\n          <div class="tc-breakdown-line"><span>Double Delivery days (×2 reward, once per week)</span><b id="bd-doubleweeks">${fmt(c.doubleDeliveryWeeks)} days</b></div>\n          <div class="tc-breakdown-line"><span>Auction Week (Animals &amp; Bounty Board pay 0 that week; deliveries + Megastore still pay)</span><b>1 week</b></div>\n          <div class="tc-breakdown-line"><span>Weeks Animals, Bounty Board &amp; Chores actually pay out</span><b id="bd-eligibleweeks">${fmt(c.animalBountyEligibleWeeks)} wk</b></div>\n        </div>\n      </div>\n\n      <div class="tc-section">\n        <div class="tc-section-title">🧑‍🌾 NPC DELIVERIES</div>\n        <div class="tc-section-sub">Toggle "Deliver it" for every NPC you'll deliver to daily for the rest of the season. Off by default.</div>\n        ${npcRowsHtml}\n      </div>\n\n      <div class="tc-estimate-panel">\n        <div class="tc-section-title">🐔 ANIMALS &amp; 🐾 BOUNTY BOARD (POPPY TRADE)</div>\n        <div class="tc-estimate-disclaimer">⚠️ Unlike NPC deliveries and Megastore rewards, Animal and Bounty Board reward tables are random — these two figures are estimates, averaged across every eligible week until the season ends.</div>\n\n        <div class="tc-field-tag">ANIMAL BOUNTY</div>\n        <div class="tc-field">\n          <label>Average tickets from Animal selling, per week</label>\n          <input type="number" min="0" step="1" id="animalWeeklyInput" value="${animalWeekly}" />\n        </div>\n        <div class="tc-field-note">This should be the actual weekly total you see in-game — if a boost is active, the game already adds its bonus to each animal sale, so don't add anything extra here.</div>\n        <div class="tc-field" style="margin-top:8px;">\n          <label>${FLOWER_ICON} FLOWER cost from Animal selling, per week</label>\n          <input type="number" min="0" step="1" id="animalFlowerInput" value="${animalFlowerCost}" />\n        </div>\n\n        <div class="tc-field-tag" style="margin-top:12px;">POPPY TRADE</div>\n        <div class="tc-field">\n          <label>Average tickets from selling items to Poppy Trade, per week</label>\n          <input type="number" min="0" step="1" id="bountyWeeklyInput" value="${bountyWeekly}" />\n        </div>\n        <div class="tc-field-note">Selling items to Poppy for tickets, separate from the completion bonus below.</div>\n        <div class="tc-field" style="margin-top:8px;">\n          <label>${FLOWER_ICON} FLOWER cost from selling items to Poppy Trade, per week</label>\n          <input type="number" min="0" step="1" id="bountyFlowerInput" value="${bountyFlowerCost}" />\n        </div>\n\n        <div class="tc-field-tag" style="margin-top:12px;">WEEKLY CHORES</div>\n        <div class="tc-field">\n          <label>Weekly Chores — average tickets per week</label>\n          <input type="number" min="0" step="1" id="choresWeeklyInput" value="${choresWeekly}" />\n        </div>\n        <div class="tc-field-note" id="chores-note">Off during the season's first week and during Auction Week — only ${fmt(c.animalBountyEligibleWeeks)} of the ${fmt(c.totalSeasonWeeks)} weeks in a ${fmt(seasonDays)}-day season actually pay out.</div>\n        <div class="tc-field" style="margin-top:8px;">\n          <label>${FLOWER_ICON} FLOWER cost from Weekly Chores, per week</label>\n          <input type="number" min="0" step="1" id="choresFlowerInput" value="${choresFlowerCost}" />\n        </div>\n\n        <div class="tc-boost-card" style="margin-top:12px;background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.3);">\n          <div class="tc-boost-head">\n            <div>\n              <div class="tc-boost-name">Poppy Trade (Bounty Board)</div>\n              <div class="tc-boost-tag" style="color:#c8ded8;">+${BOUNTY_WEEKLY_BONUS} tickets/week if fully completed</div>\n            </div>\n            <div class="tc-seg" style="width:150px;">\n              <button type="button" id="bountyToggleBtn" class="tc-seg-btn ${bountyToggle ? "active" : "active off"}">\n                ${bountyToggle ? "I deliver it all" : "OFF"}\n              </button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class="tc-section">\n        <div class="tc-section-title">🏪 MEGASTORE REWARDS</div>\n        <div class="tc-section-sub">Flat, deterministic tickets you expect from Megastore reward claims over the whole season.</div>\n        <div class="tc-field">\n          <label>Tickets from Megastore over the season</label>\n          <input type="number" min="0" step="1" id="megastoreInput" value="${megastoreTickets}" />\n        </div>\n        <div class="tc-field" style="margin-top:8px;">\n          <label>Daily Reward (VIP Access — 1 ticket/day)</label>\n          <input type="number" min="0" step="1" id="dailyRewardInput" value="${getEffectiveDailyReward()}" />\n        </div>\n        <div class="tc-field-note">Auto-fills to match Days the season will last while VIP Access is On — edit it yourself to override.</div>\n      </div>\n\n      <div class="tc-summary">\n        <div class="tc-summary-line"><span>NPC deliveries<span style="opacity:.7;" id="sum-npc-note"> (incl. +${fmt(c.npcDoubleBonus)} from Double Delivery)</span></span><b id="sum-npc">${fmt(c.npcTotal)}</b></div>\n        <div class="tc-summary-line"><span>Undelivered last season</span><b id="sum-undelivered">${fmt(undeliveredLastSeason)}</b></div>\n        <div class="tc-summary-line"><span>Animal selling (estimate)</span><b id="sum-animal">${fmt(c.animalTotal)}</b></div>\n        <div class="tc-summary-line"><span>Bounty Board / Poppy Trade<span style="opacity:.7;" id="sum-bounty-note">${bountyToggle ? ` (incl. +${fmt(c.bountyCompletionBonus)} completion bonus)` : ""}</span></span><b id="sum-bounty">${fmt(c.bountyTotal)}</b></div>\n        <div class="tc-summary-line"><span>Weekly Chores</span><b id="sum-chores">${fmt(c.choresTotal)}</b></div>\n        <div class="tc-summary-line"><span>Megastore rewards</span><b id="sum-megastore">${fmt(megastoreTickets)}</b></div>\n        <div class="tc-summary-line"><span>Daily Reward (VIP)</span><b id="sum-dailyreward">${fmt(c.dailyRewardTotal)}</b></div>\n        <div class="tc-summary-line" id="sum-boostcost-line" style="color:var(--loss);display:${c.boostCostTotal > 0 ? "" : "none"};"><span>Boost activation cost</span><b id="sum-boostcost" style="color:var(--loss);">−${fmt(c.boostCostTotal)}</b></div>\n        <div class="tc-summary-total">\n          <span class="tc-label" id="sum-total-label">🎟️ TOTAL / ${fmt(seasonDays)} DAYS</span>\n          <span class="tc-value" id="sum-total">${fmt(c.grandTotal)}</span>\n        </div>\n        <div class="tc-summary-total" style="margin-top:10px;padding-top:8px;border-top:2px dashed var(--line);">\n          <span class="tc-label" style="color:var(--loss);">${FLOWER_ICON} TOTAL FLOWER COST</span>\n          <span class="tc-value" style="color:var(--loss);" id="sum-flower-total">${fmt(c.grandFlowerTotal)}</span>\n        </div>\n      </div>\n\n      <div class="tc-footer">The total tickets above are purely estimates because of the Bounty Board and Animal mechanic when selling for tickets.</div>\n    `;
  wireEvents();
}

function updateDynamicValues() {
  const c = computeAll();
  setText("bd-firstweek", `−${fmt(c.firstWeekDeduction)} days`);
  setText("bd-remaining", `${fmt(c.remainingDeliveryDays)} days`);
  setText("bd-doubleweeks", `${fmt(c.doubleDeliveryWeeks)} days`);
  setText("bd-eligibleweeks", `${fmt(c.animalBountyEligibleWeeks)} wk`);
  setText("chores-note", `Off during the season's first week and during Auction Week — only ${fmt(c.animalBountyEligibleWeeks)} of the ${fmt(c.totalSeasonWeeks)} weeks in a ${fmt(seasonDays)}-day season actually pay out.`);
  c.npcRows.forEach(r => {
    const s = slug(r.npc);
    setText(`npcMeta-${s}`, `base ${fmt(r.base)} → ${fmt(r.perDelivery)}/delivery${c.totalBoostBonus ? ` (+${c.totalBoostBonus} boost)` : ""}${r.skip ? ` − ${fmt(r.skip)} skipped` : ""}`);
    setText(`npcTotal-${s}`, fmt(r.total));
  });
  setText("sum-npc", fmt(c.npcTotal));
  setText("sum-npc-note", ` (incl. +${fmt(c.npcDoubleBonus)} from Double Delivery)`);
  setText("sum-undelivered", fmt(undeliveredLastSeason));
  setText("sum-animal", fmt(c.animalTotal));
  setText("sum-bounty", fmt(c.bountyTotal));
  setText("sum-bounty-note", bountyToggle ? ` (incl. +${fmt(c.bountyCompletionBonus)} completion bonus)` : "");
  setText("sum-chores", fmt(c.choresTotal));
  setText("sum-megastore", fmt(megastoreTickets));
  setText("sum-dailyreward", fmt(c.dailyRewardTotal));
  const dailyRewardInp = $("dailyRewardInput");
  if (dailyRewardInp && !dailyRewardManual) dailyRewardInp.value = getEffectiveDailyReward();
  const boostCostLine = $("sum-boostcost-line");
  if (boostCostLine) boostCostLine.style.display = c.boostCostTotal > 0 ? "" : "none";
  setText("sum-boostcost", `−${fmt(c.boostCostTotal)}`);
  setText("sum-total-label", `🎟️ TOTAL / ${fmt(seasonDays)} DAYS`);
  setText("sum-total", fmt(c.grandTotal));
  setText("sum-flower-total", fmt(c.grandFlowerTotal));
}

function wireEvents() {
  document.querySelectorAll(".boost-enable-btn").forEach(btn => {
    btn.onclick = () => {
      const t = btn.dataset.tier;
      ticketBoosts[t].enabled = !ticketBoosts[t].enabled;
      saveBoosts();
      renderTicketCalc();
    };
  });
  document.querySelectorAll(".cost-mode-btn").forEach(btn => {
    btn.onclick = () => {
      const t = btn.dataset.tier;
      ticketBoosts[t].costMode = btn.dataset.mode;
      saveBoosts();
      renderTicketCalc();
    };
  });
  document.querySelectorAll(".npc-deliver-btn").forEach(btn => {
    btn.onclick = () => {
      setNpcDeliver(btn.dataset.npc, btn.dataset.val === "1");
      renderTicketCalc();
    };
  });
  const bountyBtn = $("bountyToggleBtn");
  if (bountyBtn) bountyBtn.onclick = () => {
    setBountyToggle(!bountyToggle);
    renderTicketCalc();
  };
  document.querySelectorAll(".npc-skip-input").forEach(inp => {
    inp.oninput = () => {
      setNpcSkip(inp.dataset.npc, inp.value);
      updateDynamicValues();
    };
  });
  document.querySelectorAll(".boost-cost-input").forEach(inp => {
    inp.oninput = () => {
      const t = inp.dataset.tier;
      ticketBoosts[t].cost = Math.max(0, parseFloat(inp.value) || 0);
      saveBoosts();
      updateDynamicValues();
    };
  });
  const undeliveredInp = $("undeliveredInput");
  if (undeliveredInp) undeliveredInp.oninput = () => {
    setUndelivered(undeliveredInp.value);
    updateDynamicValues();
  };
  const seasonDaysInp = $("seasonDaysInput");
  if (seasonDaysInp) seasonDaysInp.oninput = () => {
    setSeasonDays(seasonDaysInp.value);
    updateDynamicValues();
  };
  const animalInp = $("animalWeeklyInput");
  if (animalInp) animalInp.oninput = () => {
    setAnimalWeekly(animalInp.value);
    updateDynamicValues();
  };
  const bountyWeeklyInp = $("bountyWeeklyInput");
  if (bountyWeeklyInp) bountyWeeklyInp.oninput = () => {
    setBountyWeekly(bountyWeeklyInp.value);
    updateDynamicValues();
  };
  const megastoreInp = $("megastoreInput");
  if (megastoreInp) megastoreInp.oninput = () => {
    setMegastore(megastoreInp.value);
    updateDynamicValues();
  };
  const dailyRewardInp = $("dailyRewardInput");
  if (dailyRewardInp) dailyRewardInp.oninput = () => {
    setDailyReward(dailyRewardInp.value);
    updateDynamicValues();
  };
  const choresWeeklyInp = $("choresWeeklyInput");
  if (choresWeeklyInp) choresWeeklyInp.oninput = () => {
    setChoresWeekly(choresWeeklyInp.value);
    updateDynamicValues();
  };
  document.querySelectorAll(".npc-flower-input").forEach(inp => {
    inp.oninput = () => {
      setNpcFlower(inp.dataset.npc, inp.value);
      updateDynamicValues();
    };
  });
  const animalFlowerInp = $("animalFlowerInput");
  if (animalFlowerInp) animalFlowerInp.oninput = () => {
    setAnimalFlower(animalFlowerInp.value);
    updateDynamicValues();
  };
  const bountyFlowerInp = $("bountyFlowerInput");
  if (bountyFlowerInp) bountyFlowerInp.oninput = () => {
    setBountyFlower(bountyFlowerInp.value);
    updateDynamicValues();
  };
  const choresFlowerInp = $("choresFlowerInput");
  if (choresFlowerInp) choresFlowerInp.oninput = () => {
    setChoresFlower(choresFlowerInp.value);
    updateDynamicValues();
  };
}

window.addEventListener("storage", e => {
  if (!$("ticketCalcBody")) return;
  const relevant = e.key && (e.key.startsWith("hl_ticket_v2_") || e.key === "hl_ticket_vip_enabled" || e.key === "hl_farm_panel_id");
  if (!relevant) return;
  ticketBoosts = safeParse(localStorage.getItem("hl_ticket_v2_boosts"), {});
  BOOST_TIERS.forEach(t => {
    if (!ticketBoosts[t]) ticketBoosts[t] = {
      enabled: false,
      costMode: "nocost",
      cost: 0
    };
  });
  if (!ticketBoosts.vip) ticketBoosts.vip = {
    enabled: false,
    costMode: "nocost",
    cost: 0
  };
  if (readFarmVipEnabled()) ticketBoosts.vip.enabled = true;
  undeliveredLastSeason = parseFloat(localStorage.getItem("hl_ticket_v2_undelivered")) || 0;
  const sd = parseFloat(localStorage.getItem("hl_ticket_v2_season_days"));
  seasonDays = isNaN(sd) ? 90 : sd;
  npcDeliverToggle = safeParse(localStorage.getItem("hl_ticket_v2_npc_deliver"), {});
  npcSkipDays = safeParse(localStorage.getItem("hl_ticket_v2_npc_skip"), {});
  animalWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_animal_weekly")) || 0;
  bountyToggle = localStorage.getItem("hl_ticket_v2_bounty_toggle") === "1";
  bountyWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_bounty_weekly")) || 0;
  megastoreTickets = parseFloat(localStorage.getItem("hl_ticket_v2_megastore")) || 0;
  choresWeekly = parseFloat(localStorage.getItem("hl_ticket_v2_chores_weekly")) || 0;
  npcFlowerCost = safeParse(localStorage.getItem("hl_ticket_v2_npc_flower"), {});
  animalFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_animal_flower")) || 0;
  bountyFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_bounty_flower")) || 0;
  choresFlowerCost = parseFloat(localStorage.getItem("hl_ticket_v2_chores_flower")) || 0;
  renderTicketCalc();
});

function openTicketCalc() {
  const body = $("ticketCalcBody");
  if (body && !body.dataset.ticketCalcInit) {
    body.dataset.ticketCalcInit = "1";
    renderTicketCalc();
  }
  $("ticketCalcOverlay").classList.add("show");
}

function closeTicketCalc() {
  $("ticketCalcOverlay").classList.remove("show");
}

$("openTicketCalcBtn").onclick = () => { closeMoreMenu(); openTicketCalc(); };

$("ticketCalcCloseBtn").onclick = closeTicketCalc;

$("ticketCalcOverlay").addEventListener("click", e => {
  if (e.target.id === "ticketCalcOverlay") closeTicketCalc();
});

