function renderGunterShop() {
  gunterRenderTop();
  gunterRenderSunstoneInput();
  gunterRenderMid();
  gunterRenderBottom();
  document.querySelectorAll(".gunter-tab-btn").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.gunterTab === gunterActiveTab);
  });
  const cardEl = $("gunterShopCard");
  if (cardEl) cardEl.classList.toggle("is-chapter-tab", gunterActiveTab === "chapter");
}

const gunterSunstoneRockInputEl = $("gunterSunstoneRockInput");
if (gunterSunstoneRockInputEl) {
  gunterSunstoneRockInputEl.value = String(gunterSunstoneRockCount);
  gunterSunstoneRockInputEl.addEventListener("input", e => {
    const val = parseInt(e.target.value, 10);
    gunterSunstoneRockCount = Number.isFinite(val) && val >= 0 ? val : 0;
    localStorage.setItem(GUNTER_SUNSTONE_ROCKS_LS_KEY, String(gunterSunstoneRockCount));
    gunterRenderMid();
  });
}

const gunterFlowerCostModeRowEl = $("gunterFlowerCostModeRow");
if (gunterFlowerCostModeRowEl) {
  gunterFlowerCostModeRowEl.addEventListener("click", e => {
    const btn = e.target.closest(".gunter-fc-mode-btn");
    if (!btn) return;
    gunterFlowerCostMode = btn.dataset.gunterFcMode === "collect" ? "collect" : "buy";
    localStorage.setItem(GUNTER_FLOWER_COST_MODE_LS_KEY, gunterFlowerCostMode);
    gunterRenderFlowerCost();
  });
}

const gunterFlowerCostNoteToggleEl = $("gunterFlowerCostNoteToggle");
if (gunterFlowerCostNoteToggleEl) {
  gunterFlowerCostNoteToggleEl.addEventListener("click", () => {
    gunterFlowerCostNoteOpen = !gunterFlowerCostNoteOpen;
    gunterRenderFlowerCost();
  });
}

const gunterBottomBodyChangeEl = $("gunterBottomBody");
if (gunterBottomBodyChangeEl) {
  gunterBottomBodyChangeEl.addEventListener("change", e => {
    const input = e.target.closest("[data-mutant-boost-check]");
    if (!input) return;
    const name = input.dataset.mutantBoostCheck;
    gunterMutantBoosts[name] = input.checked;
    gunterMutantSaveBoosts();
    gunterRenderChapterBottom();
    gunterRenderChapterTop();
  });
}

$("gunterTabs").addEventListener("click", e => {
  const btn = e.target.closest(".gunter-tab-btn");
  if (!btn) return;
  gunterActiveTab = btn.dataset.gunterTab;
  renderGunterShop();
});

$("gunterShopTop").addEventListener("click", e => {
  const toggleBtn = e.target.closest("[data-gunter-top-toggle]");
  if (!toggleBtn) return;
  if (toggleBtn.dataset.gunterTopToggle === "nodes") {
    gunterTopNodesOpen = !gunterTopNodesOpen;
  } else if (toggleBtn.dataset.gunterTopToggle === "upgrade") {
    gunterTopUpgradeOpen = !gunterTopUpgradeOpen;
  }
  gunterRenderTop();
});

$("gunterBottomBody").addEventListener("click", e => {
  const stepBtn = e.target.closest("[data-gunter-buy-step], [data-gunter-upgrade-step]");
  if (stepBtn) {
    if (stepBtn.dataset.gunterBuyStep) {
      const name = stepBtn.dataset.gunterBuyName;
      const delta = parseInt(stepBtn.dataset.gunterBuyStep, 10);
      const current = gunterBuyCounts[name] || 1;
      gunterBuyCounts[name] = Math.max(1, current + delta);
    } else if (stepBtn.dataset.gunterUpgradeStep) {
      const name = stepBtn.dataset.gunterUpgradeName;
      const delta = parseInt(stepBtn.dataset.gunterUpgradeStep, 10);
      const current = gunterUpgradeCounts[name] || 1;
      gunterUpgradeCounts[name] = Math.max(1, current + delta);
    }
    gunterRenderMid();
    gunterRenderBottom();
    return;
  }

  const buyBox = e.target.closest("[data-gunter-buy]");
  if (buyBox) {
    const name = buyBox.dataset.gunterBuy;
    gunterSelectedBuy = gunterSelectedBuy === name ? gunterSelectedBuy : name;
    if (!gunterBuyCounts[name]) gunterBuyCounts[name] = 1;
    gunterRenderMid();
    gunterRenderBottom();
    return;
  }

  const upgradeBox = e.target.closest("[data-gunter-upgrade]");
  if (upgradeBox) {
    const name = upgradeBox.dataset.gunterUpgrade;
    gunterSelectedUpgrade = gunterSelectedUpgrade === name ? gunterSelectedUpgrade : name;
    if (!gunterUpgradeCounts[name]) gunterUpgradeCounts[name] = 1;
    gunterRenderMid();
    gunterRenderBottom();
    return;
  }
});

