function openMarketPriceEdit(id) {
  if (id === "budFloor" || id === "petFloor") {
    marketPriceEditId = id;
    const label = id === "budFloor" ? "Bud" : "Pet";
    $("marketPriceEditSub").textContent = `Cheapest currently-listed ${label} NFT price in the game's own Marketplace — applied to every ${label} NFT you own`;
    const currentFloor = id === "budFloor" ? budFloorPrice : petFloorPrice;
    $("marketPriceInput").value = currentFloor != null ? currentFloor : "";
    $("marketPriceEditOverlay").classList.add("show");
    return;
  }
  if (String(id).indexOf("petcost_") === 0) {
    const name = PET_COST_TRACK_RESOURCES.find(n => "petcost_" + n.replace(/\s+/g, "_").toLowerCase() === String(id));
    if (!name) return;
    marketPriceEditId = id;
    $("marketPriceEditSub").textContent = `Cost per unit to fetch "${name}" (override — leave blank to go back to auto)`;
    $("marketPriceInput").value = petResourceCostPerUnit(name);
    $("marketPriceEditOverlay").classList.add("show");
    return;
  }
  const m = marketItems.find(x => String(x.id) === String(id));
  if (!m) return;
  marketPriceEditId = id;
  $("marketPriceEditSub").textContent = `Price per unit of "${m.name}"`;
  $("marketPriceInput").value = m.flowerPrice || 0;
  $("marketPriceEditOverlay").classList.add("show");
}

$("marketPriceCancelBtn").onclick = () => $("marketPriceEditOverlay").classList.remove("show");

$("marketPriceSaveBtn").onclick = () => {
  if (marketPriceEditId === "budFloor" || marketPriceEditId === "petFloor") {
    const raw = $("marketPriceInput").value;
    const v = raw === "" || raw == null || isNaN(parseFloat(raw)) ? null : parseFloat(raw);
    if (marketPriceEditId === "budFloor") {
      budFloorPrice = v;
      saveBudFloorPrice();
      if (typeof profileClearTradableCacheTab === "function") profileClearTradableCacheTab("bud");
    } else {
      petFloorPrice = v;
      savePetFloorPrice();
      if (typeof profileClearTradableCacheTab === "function") profileClearTradableCacheTab("pet");
    }
    if (typeof renderProfileTradable === "function" && profileState.view === "tradable") renderProfileTradable();
    $("marketPriceEditOverlay").classList.remove("show");
    toast(`${marketPriceEditId === "budFloor" ? "Bud" : "Pet"} floor price updated 💰`);
    return;
  }
  if (String(marketPriceEditId).indexOf("petcost_") === 0) {
    const name = PET_COST_TRACK_RESOURCES.find(n => "petcost_" + n.replace(/\s+/g, "_").toLowerCase() === String(marketPriceEditId));
    if (name) {
      const raw = $("marketPriceInput").value;
      if (raw === "" || raw == null || isNaN(parseFloat(raw))) {
        delete petResourceCostOverride[name];
      } else {
        petResourceCostOverride[name] = parseFloat(raw);
      }
      savePetResourceCostOverride();
      if (typeof renderPetsPanel === "function") renderPetsPanel();
    }
    $("marketPriceEditOverlay").classList.remove("show");
    toast("Pet resource cost/unit updated 💰");
    return;
  }
  const m = marketItems.find(x => String(x.id) === String(marketPriceEditId));
  if (m) {
    m.flowerPrice = parseFloat($("marketPriceInput").value) || 0;
    saveMarketState();
    renderMarketList();
    renderResourceList();
    renderCropsList();
    renderFruitsList();
    renderGreenhouseList();
    if (typeof renderCookingPanel === "function") renderCookingPanel();
    updateCalcSummary();
  }
  $("marketPriceEditOverlay").classList.remove("show");
  toast("Marketplace price updated 💰");
};

$("closeMaterialPicker").onclick = () => $("materialPickerOverlay").classList.remove("show");

function getAllMaterialCandidates(excludeToolId) {
  const list = [];
  Object.keys(RESOURCE_DATA).forEach(name => list.push({
    name: name,
    kindLabel: "Resource"
  }));
  Object.keys(BASE_CROPS).forEach(name => list.push({
    name: name,
    kindLabel: "Crop"
  }));
  Object.keys(BASE_FRUITS).forEach(name => list.push({
    name: name,
    kindLabel: "Fruit"
  }));
  Object.keys(BASE_GREENHOUSE).forEach(name => list.push({
    name: name,
    kindLabel: "Greenhouse"
  }));
  const animalNames = [];
  Object.values(ANIMAL_DATA).forEach(cfg => cfg.products.forEach(p => {
    if (!animalNames.includes(p)) animalNames.push(p);
  }));
  animalNames.forEach(name => list.push({
    name: name,
    kindLabel: "Animal produce"
  }));
  toolRecipes.forEach(t => {
    if (String(t.id) === String(excludeToolId)) return;
    if (!t.producesName) return;
    list.push({
      name: t.producesName,
      kindLabel: `Tool product (${t.name})`
    });
  });
  return list;
}

function renderPickerList() {
  const wrap = $("pickerList");
  if (pickerTarget === "craft") {
    const list = getAllMaterialCandidates(editingLibId);
    wrap.innerHTML = list.length ? list.map((item, idx) => {
      const priceCoins = getItemCostByName(item.name);
      return `<div class="picker-item" data-idx="${idx}" data-search="${escapeHtml(item.name.toLowerCase())}">\n        <div>\n          <div class="pname">${getIcon(item.name)} ${escapeHtml(item.name)}</div>\n          <div class="pmeta">${escapeHtml(item.kindLabel)}</div>\n        </div>\n        <div class="pprice">${fmt(priceCoins)}${COIN_ICON}/u</div>\n      </div>`;
    }).join("") : `<div class="lib-empty">Nothing available yet.</div>`;
    wrap.querySelectorAll(".picker-item").forEach(el => {
      el.onclick = () => {
        const item = list[parseInt(el.dataset.idx)];
        if (!item) return;
        craftMaterialRows.push({
          rid: craftMaterialIdSeq++,
          name: item.name,
          qty: 1
        });
        renderMaterialRows();
        updateLibCraftTotal();
        $("materialPickerOverlay").classList.remove("show");
      };
    });
  } else {
    const list = marketItems.filter(m => !m.isNftCollectible && !m.isWearable);
    wrap.innerHTML = list.length ? list.map(m => {
      const costPerUnit = coinsToFlower(getMarketItemCostCoins(m.id));
      return `<div class="picker-item" data-id="${m.id}" data-search="${escapeHtml((m.name || "").toLowerCase())}">\n        <div>\n          <div class="pname">${getIcon(m.name)} ${escapeHtml(m.name)}</div>\n          <div class="pmeta">Cost ${fmt(costPerUnit)} ${FLOWER_ICON}/u · Sells ${fmt(m.flowerPrice || 0)} ${FLOWER_ICON}/u</div>\n        </div>\n        <div class="pprice">${fmt(m.flowerPrice || 0)} ${FLOWER_ICON}</div>\n      </div>`;
    }).join("") : `<div class="lib-empty">No items yet — add a tool recipe, or check Crops/Fruits/Animals.</div>`;
    wrap.querySelectorAll(".picker-item").forEach(el => {
      el.onclick = () => {
        harvestSelectedLibId = el.dataset.id;
        updateCalcSelectedDisplay();
        updateCalcSummary();
        $("materialPickerOverlay").classList.remove("show");
      };
    });
  }
  applyPickerSearchFilter();
}

function updateCalcSelectedDisplay() {
  if (harvestSelectedLibId) {
    const m = marketItems.find(x => String(x.id) === String(harvestSelectedLibId));
    $("calcSelectedEmpty").classList.add("hidden");
    $("calcSelectedWrap").classList.remove("hidden");
    $("calcSelectedIcon").innerHTML = getIcon(m ? m.name : "");
    $("calcSelectedName").textContent = m ? m.name : "Unknown (missing)";
    if (calcMode === "bought" && m) {
      $("calcBSSellPrice").value = m.flowerPrice || 0;
    }
  } else {
    $("calcSelectedEmpty").classList.remove("hidden");
    $("calcSelectedWrap").classList.add("hidden");
  }
  renderCalcIngredients();
}

function renderCalcIngredients() {
  const wrap = $("calcIngredientsWrap");
  const list = $("calcIngredientsList");
  if (calcMode !== "harvest" || !harvestSelectedLibId) {
    wrap.classList.add("hidden");
    list.innerHTML = "";
    return;
  }
  const m = marketItems.find(x => String(x.id) === String(harvestSelectedLibId));
  if (!m) {
    wrap.classList.add("hidden");
    list.innerHTML = "";
    return;
  }
  let rows = [];
  let animalCalcInfo = null;
  const tool = toolRecipes.find(t => (t.producesName || "").toLowerCase() === (m.name || "").toLowerCase());
  if (tool) {
    rows = (tool.materials || []).map(mat => {
      const key = "ToolLib_" + tool.id;
      const mode = getMaterialMode(key, mat.name);
      const unitCost = getMaterialUnitCostCoins(mat.name, mode);
      return {
        key: key,
        name: mat.name,
        qty: mat.qty,
        unitCost: unitCost,
        mode: mode
      };
    });
  } else if (BASE_FRUITS[m.name]) {
    const baseFruit = BASE_FRUITS[m.name];
    if (baseFruit.woodReturnQty) {
      const key = "Fruit_" + m.name;
      const mode = getMaterialMode(key, "Wood");
      const unitCost = getMaterialUnitCostCoins("Wood", mode);
      rows = [ {
        key: key,
        name: "Wood",
        qty: baseFruit.woodReturnQty,
        unitCost: unitCost,
        mode: mode,
        isRebate: true
      } ];
    }
  } else if (m.isAutoAnimal) {
    const animalType = Object.keys(ANIMAL_DATA).find(t => ANIMAL_DATA[t].products.some(p => p.toLowerCase() === (m.name || "").toLowerCase()));
    if (animalType) {
      const fig = computeAnimalTypeFigures(animalType);
      const productIdx = fig.products.findIndex(p => p.toLowerCase() === (m.name || "").toLowerCase());
      const unitsPerHeadPerCycle = productIdx >= 0 ? fig.yields[productIdx] : 0;
      const targetQty = parseFloat($("calcHarvestQty").value) || 0;
      const headCyclesNeeded = unitsPerHeadPerCycle > 0 ? targetQty / unitsPerHeadPerCycle : 0;
      const feedUnitsNeeded = headCyclesNeeded * fig.effectiveFeedQty;
      const cyclesWithOwnedHeads = fig.qty > 0 ? headCyclesNeeded / fig.qty : 0;
      animalCalcInfo = {
        fig: fig,
        animalType: animalType,
        unitsPerHeadPerCycle: unitsPerHeadPerCycle,
        headCyclesNeeded: headCyclesNeeded,
        feedUnitsNeeded: feedUnitsNeeded,
        headsOwned: fig.qty,
        cyclesWithOwnedHeads: cyclesWithOwnedHeads,
        feedName: fig.feedNameUsed,
        feedIcon: fig.feedIconUsed
      };
      rows = fig.feedInfo.breakdown.map(r => ({
        key: "AnimalFeed",
        name: r.name,
        qty: r.qty * feedUnitsNeeded,
        unitCost: r.unitCost,
        mode: r.mode
      }));
    }
  }
  if (!rows.length) {
    wrap.classList.add("hidden");
    list.innerHTML = "";
    return;
  }
  wrap.classList.remove("hidden");
  const animalSummaryHtml = animalCalcInfo ? `\n    <div class="field-hint" style="margin-bottom:6px;">\n      ${animalCalcInfo.feedIcon} <b>${fmt(animalCalcInfo.headsOwned)} heads</b> at Lv${animalCalcInfo.fig.level} each yield <b>${fmt(animalCalcInfo.unitsPerHeadPerCycle)} ${escapeHtml(m.name)}/cycle</b> —\n      reaching this quantity needs <b>${fmt(animalCalcInfo.feedUnitsNeeded)} ${animalCalcInfo.feedName}</b>\n      ${animalCalcInfo.headsOwned > 0 ? `(≈ ${fmt(animalCalcInfo.cyclesWithOwnedHeads)} cycle${animalCalcInfo.cyclesWithOwnedHeads === 1 ? "" : "s"} with your current heads)` : "(set your head count in ⚡ Boosts → Plots &amp; Nodes)"}\n    </div>` : "";
  list.innerHTML = animalSummaryHtml + rows.map(r => {
    if (r.mode === "gem") {
      return `\n      <div class="calc-ingredient-row">\n        <span class="calc-ing-icon">${getIcon(r.name)}</span>\n        <div class="calc-ing-main">\n          <div class="calc-ing-name">${escapeHtml(r.name)} ×${fmt(r.qty)}</div>\n          <div class="calc-ing-meta">Cost @ 1${GEM_ICON}/u ≈ ${fmt(coinsToFlower(r.unitCost))}${FLOWER_ICON}/u</div>\n        </div>\n        <div class="calc-ing-toggle">\n          <span style="font-size:9.6px;opacity:.6;">${GEM_ICON} gem-only</span>\n        </div>\n      </div>`;
    }
    const displayPrice = r.mode === "buy" ? coinsToFlower(r.unitCost) : r.unitCost;
    const displayUnit = r.mode === "buy" ? FLOWER_ICON : COIN_ICON;
    return `\n    <div class="calc-ingredient-row">\n      <span class="calc-ing-icon">${getIcon(r.name)}</span>\n      <div class="calc-ing-main">\n        <div class="calc-ing-name">${escapeHtml(r.name)} ×${fmt(r.qty)}${r.isRebate ? " (recovered)" : ""}</div>\n        <div class="calc-ing-meta">${r.mode === "collect" ? "Collect" : "Buy"} @ ${fmt(displayPrice)}${displayUnit}/u</div>\n      </div>\n      <div class="calc-ing-toggle">\n        ${r.name.toLowerCase() === "oil" ? `<span style="font-size:9.6px;opacity:.6;">🚫 not tradable</span>` : `<button type="button" class="calc-mode-btn" data-key="${r.key}" data-mat="${escapeHtml(r.name)}" data-mode="collect" style="${r.mode === "collect" ? "border-color:var(--profit);color:var(--profit);" : ""}">Collect</button>\n        <button type="button" class="calc-mode-btn" data-key="${r.key}" data-mat="${escapeHtml(r.name)}" data-mode="buy" style="${r.mode === "buy" ? "border-color:var(--flower);color:var(--flower);" : ""}">Buy</button>`}\n      </div>\n    </div>`;
  }).join("");
  list.querySelectorAll(".calc-mode-btn").forEach(btn => {
    btn.onclick = () => {
      setMaterialMode(btn.dataset.key, btn.dataset.mat, btn.dataset.mode);
      renderCalcIngredients();
      updateCalcSummary();
      renderLibraryLists();
      renderMarketList();
    };
  });
}

function computeQtyRestockGems(marketId, qty) {
  if (!marketId || !qty) return null;
  const id = String(marketId);
  let name, baseStock, unitsPerRestockItem, moonOnly = false, stockKind;
  if (id.startsWith("crop_")) {
    name = id.slice(5);
    const d = BASE_CROPS[name];
    if (!d) return null;
    const boosted = computeBoostedCropStats(name, d.baseYield || 1, d.timeSec);
    unitsPerRestockItem = boosted.yieldVal;
    baseStock = BASE_STOCK_CROPS[name];
    stockKind = "seed";
  } else if (id.startsWith("fruit_")) {
    name = id.slice(6);
    const d = BASE_FRUITS[name];
    if (!d) return null;
    const boosted = computeBoostedFruitStats(name, d.yieldPerHarvest || 1, d.timeSec, d.minHarvest || 1);
    unitsPerRestockItem = boosted.minHarvestVal * boosted.yieldVal;
    baseStock = BASE_STOCK_FRUITS[name];
    moonOnly = !!d.moonOnly;
    stockKind = "seed";
  } else if (id.startsWith("greenhouse_")) {
    name = id.slice(11);
    const d = BASE_GREENHOUSE[name];
    if (!d) return null;
    const boosted = computeBoostedGreenhouseStats(name, d.baseYield || 1, d.timeSec);
    unitsPerRestockItem = boosted.yieldVal;
    baseStock = BASE_STOCK_GREENHOUSE[name];
    stockKind = "seed";
  } else if (id.startsWith("resource_")) {
    name = id.slice(9);
    const d = RESOURCE_DATA[name];
    if (!d) return null;
    const boosted = computeBoostedResourceStats(name, d.yieldPer, d.timeSec);
    if (boosted.noToolNeeded) return null;
    unitsPerRestockItem = boosted.yieldVal / (boosted.toolCostMult || 1);
    baseStock = BASE_STOCK_TOOLS[d.tool];
    stockKind = "tool";
  } else {
    return null;
  }
  if (!baseStock || !unitsPerRestockItem) return null;
  const toolNameForStock = stockKind === "tool" ? (RESOURCE_DATA[name] || {}).tool : null;
  const restockItemName = stockKind === "tool" ? toolNameForStock : name;
  const boostedStock = computeBoostedStock(baseStock, stockKind, restockItemName);
  if (!boostedStock) return null;
  const itemsNeeded = qty / unitsPerRestockItem;
  const restocksNeeded = itemsNeeded / boostedStock;
  const gemCostPerRestock = typeof getRestockGemCost === "function" ? getRestockGemCost(stockKind, restockItemName) : stockKind === "tool" ? RESTOCK_GEM_COST.tools : RESTOCK_GEM_COST.seeds;
  const gemsTotal = restocksNeeded * gemCostPerRestock;
  const flowerCost = computeRestockCost24h(baseStock, stockKind, itemsNeeded, 1, 1, null, restockItemName);
  return {
    name: name,
    stockKind: stockKind,
    itemsNeeded: itemsNeeded,
    boostedStock: boostedStock,
    restocksNeeded: restocksNeeded,
    gemCostPerRestock: gemCostPerRestock,
    gemsTotal: gemsTotal,
    flowerCost: flowerCost,
    moonOnly: moonOnly
  };
}

function getGenericPlotOrNodeCount(name) {
  if (BASE_CROPS[name]) return typeof getPlotCount === "function" ? getPlotCount(name) : 0;
  if (BASE_FRUITS[name]) return typeof getFruitCount === "function" ? getFruitCount(name) : 0;
  if (BASE_GREENHOUSE[name]) return typeof getGreenhouseCount === "function" ? getGreenhouseCount(name) : 0;
  return 0;
}

function computeCalcShrineCost(name, totalYield) {
  if (!name || !totalYield) return {
    cost: 0,
    names: []
  };
  const boosted = typeof farmPanelGetBoostedYieldStats === "function" ? farmPanelGetBoostedYieldStats(name) : null;
  if (!boosted || !boosted.activeBoosts || !boosted.activeBoosts.length) return {
    cost: 0,
    names: []
  };
  const shrineInfo = typeof getActiveShrineDailyCost === "function" ? getActiveShrineDailyCost(boosted.activeBoosts) : null;
  if (!shrineInfo || !(shrineInfo.total > 0)) return {
    cost: 0,
    names: []
  };
  const shrineCost24h = shrineInfo.total;
  const cycleTimeSec = boosted.timeVal || (typeof farmPanelGrowTimeSec === "function" ? farmPanelGrowTimeSec(name) : 0);
  const cyclesPerDay = cycleTimeSec > 0 ? 86400 / cycleTimeSec : 0;
  const count = getGenericPlotOrNodeCount(name);
  const yieldVal = boosted.yieldVal || 0;
  const unitsPerDay = yieldVal * count * cyclesPerDay;
  const names = shrineInfo.shrines.map(x => x.name);
  if (!(unitsPerDay > 0)) return {
    cost: 0,
    names: names
  };
  return {
    cost: shrineCost24h * (totalYield / unitsPerDay),
    names: names
  };
}

function computeCalcFigures() {
  let cost = 0, gross = 0, restockInfo = null, shrineCost = 0, shrineNames = [];
  if (calcMode === "bought") {
    const qty = parseFloat($("calcBSQty").value) || 0;
    const buyPrice = parseFloat($("calcBSBuyPrice").value) || 0;
    const sellPrice = parseFloat($("calcBSSellPrice").value) || 0;
    cost = buyPrice * qty;
    gross = sellPrice * qty;
  } else {
    const qty = parseFloat($("calcHarvestQty").value) || 0;
    const m = harvestSelectedLibId ? marketItems.find(x => String(x.id) === String(harvestSelectedLibId)) : null;
    if (m) {
      const econ = farmPanelComputeEconomics(m.name, 1, qty);
      cost = econ.totalCost;
      gross = econ.grossRevenue;
      restockInfo = econ.restockInfo;
      const shrine = computeCalcShrineCost(m.name, qty);
      shrineCost = shrine.cost;
      shrineNames = shrine.names;
      cost += shrineCost;
    }
  }
  const netRevenue = gross * (1 - feePercent / 100);
  const profit = netRevenue - cost;
  const roi = cost > 0 ? profit / cost * 100 : profit > 0 ? Infinity : 0;
  return {
    cost: cost,
    netRevenue: netRevenue,
    profit: profit,
    roi: roi,
    restockInfo: restockInfo,
    shrineCost: shrineCost,
    shrineNames: shrineNames
  };
}

function updateCalcSummary() {
  invalidateCostCache();
  const fig = computeCalcFigures();
  $("calcCost").textContent = fmt(fig.cost);
  $("calcRevenue").textContent = fmt(fig.netRevenue);
  $("calcProfit").textContent = (fig.profit >= 0 ? "+" : "") + fmt(fig.profit);
  $("calcProfit").style.color = fig.profit >= 0 ? "#8fffb0" : "#ff8a8a";
  $("calcRoi").textContent = isFinite(fig.roi) ? fig.roi.toFixed(1) + "%" : "∞";
  const noteEl = $("calcRestockNote");
  if (noteEl) {
    const ri = fig.restockInfo;
    const lines = [];
    if (ri && ri.flowerCost > 0) {
      const noun = ri.stockKind === "tool" ? "tool" : "seed";
      let txt = `${GEM_ICON} ~${fmt(ri.restocksNeeded)} ${noun} restock${ri.restocksNeeded === 1 ? "" : "s"} needed for this qty · ${fmt(ri.gemsTotal)} ${GEM_ICON} Gems ≈ ${fmt(ri.flowerCost)} ${FLOWER_ICON} (already added to COST above)`;
      if (ri.moonOnly) {
        const minDays = Math.ceil(ri.restocksNeeded) * SYNODIC_MONTH_DAYS;
        const moonStock = fullMoonSeedStockQty(ri.name);
        txt += `<br>🌕 Moon-fruit: Betty sells ${fmt(moonStock)} seed${moonStock === 1 ? "" : "s"} per real Full Moon${moonStock > 1 ? " (Moon Hair equipped)" : ""} — even with unlimited Gems this qty needs ~${fmt(minDays)} days minimum.`;
      }
      lines.push(txt);
    }
    if (fig.shrineCost > 0) {
      lines.push(`⛩️ Shrine cost ≈ ${fmt(fig.shrineCost)} ${FLOWER_ICON}${fig.shrineNames && fig.shrineNames.length ? ` (${fig.shrineNames.join(", ")})` : ""} (already added to COST above)`);
    }
    if (lines.length) {
      noteEl.innerHTML = lines.join("<br>");
      noteEl.classList.remove("hidden");
    } else {
      noteEl.innerHTML = "";
      noteEl.classList.add("hidden");
    }
  }
}

