function openDeleteConfirm(id, type) {
  const tool = findTool(id);
  if (tool && tool.locked) {
    toast("This is a built-in tool and can't be removed 🔒");
    return;
  }
  pendingDeleteId = id;
  pendingDeleteType = "library";
  $("confirmSub").textContent = "This will also remove its price entry from Marketplace Prices, and any tool that used it as a material will show a 0-cost placeholder until you update it.";
  $("confirmOverlay").classList.add("show");
}

$("confirmCancelBtn").onclick = () => {
  pendingDeleteId = null;
  $("confirmOverlay").classList.remove("show");
};

$("confirmDeleteBtn").onclick = () => {
  toolRecipes = toolRecipes.filter(t => String(t.id) !== String(pendingDeleteId));
  saveToolRecipes();
  removeToolMarketEntry(pendingDeleteId);
  renderLibraryLists();
  renderMarketList();
  renderResourceList();
  renderFruitsList();
  updateCalcSummary();
  toast("Tool removed 🗑");
  $("confirmOverlay").classList.remove("show");
};






