(function initOmnifeedToggle() {
  const input = $("omnifeedToggleInput");
  const row = $("omnifeedToggleRow");
  if (!input || !row) return;
  input.checked = omnifeedEnabled;
  row.classList.toggle("is-active", omnifeedEnabled);
  const applyToggle = val => {
    setOmnifeedEnabled(val);
    input.checked = omnifeedEnabled;
    row.classList.toggle("is-active", omnifeedEnabled);
    invalidateCostCache();
    scheduleCascade(refreshAfterSkillChange);
    renderCalcIngredients();
  };
  input.onchange = () => applyToggle(input.checked);
  row.onclick = e => {
    if (e.target.closest(".switch")) return;
    applyToggle(!input.checked);
  };
})();

