function gatherTop10ProfitItems() {
  const marketByLowerName = new Map;
  (marketItems || []).forEach(x => {
    const k = (x.name || "").toLowerCase();
    if (!marketByLowerName.has(k)) marketByLowerName.set(k, x);
  });
  const items = [];
  Object.keys(BASE_CROPS).forEach(name => {
    const d = BASE_CROPS[name];
    const costFlower = coinsToFlower(getCropCostCoins(name));
    const m = marketByLowerName.get(name.toLowerCase());
    const sellFlower = m ? m.flowerPrice || 0 : 0;
    const boosted = computeBoostedCropStats(name, d.baseYield || 1, d.timeSec);
    const count = getPlotCount(name);
    const restockInfo = {
      baseStock: BASE_STOCK_CROPS[name],
      kind: "seed",
      itemName: name
    };
    const unitProj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, 1, restockInfo);
    const holdingProj = count > 0 ? compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, count, restockInfo) : null;
    items.push({
      name: name,
      category: "Crop",
      icon: getIcon(name),
      countLabel: "Plot",
      count: count,
      cyclesPerDay: unitProj.cyclesPerDay,
      unitCost24h: unitProj.cost24h,
      unitRevenue24h: unitProj.revenue24h,
      unitProfit24h: unitProj.profit24h,
      unitRestockCost24h: unitProj.restockCost24h || 0,
      holdingUnitsPerDay: holdingProj ? holdingProj.unitsPerDay : 0,
      holdingCost24h: holdingProj ? holdingProj.cost24h : 0,
      holdingRevenue24h: holdingProj ? holdingProj.revenue24h : 0,
      holdingRestockCost24h: holdingProj ? holdingProj.restockCost24h || 0 : 0,
      holdingProfit24h: holdingProj ? holdingProj.profit24h : 0
    });
  });
  Object.keys(BASE_FRUITS).forEach(name => {
    const d = BASE_FRUITS[name];
    const costFlower = coinsToFlower(getFruitCostCoins(name));
    const m = marketByLowerName.get(name.toLowerCase());
    const sellFlower = m ? m.flowerPrice || 0 : 0;
    const boosted = computeBoostedFruitStats(name, d.yieldPerHarvest || 1, d.timeSec, d.minHarvest || 1);
    const count = getFruitCount(name);
    const restockInfo = {
      baseStock: BASE_STOCK_FRUITS[name],
      kind: "seed",
      itemName: name,
      cyclesPerStockUnit: boosted.minHarvestVal,
      maxRestocksPerDay: d.moonOnly ? 1 / SYNODIC_MONTH_DAYS : undefined
    };
    const unitProj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, 1, restockInfo);
    const holdingProj = count > 0 ? compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, count, restockInfo) : null;
    items.push({
      name: name,
      category: "Fruit",
      icon: getIcon(name),
      countLabel: "Tree",
      count: count,
      cyclesPerDay: unitProj.cyclesPerDay,
      unitCost24h: unitProj.cost24h,
      unitRevenue24h: unitProj.revenue24h,
      unitProfit24h: unitProj.profit24h,
      unitRestockCost24h: unitProj.restockCost24h || 0,
      holdingUnitsPerDay: holdingProj ? holdingProj.unitsPerDay : 0,
      holdingCost24h: holdingProj ? holdingProj.cost24h : 0,
      holdingRevenue24h: holdingProj ? holdingProj.revenue24h : 0,
      holdingRestockCost24h: holdingProj ? holdingProj.restockCost24h || 0 : 0,
      holdingProfit24h: holdingProj ? holdingProj.profit24h : 0
    });
  });
  Object.keys(BASE_GREENHOUSE).forEach(name => {
    const d = BASE_GREENHOUSE[name];
    const costFlower = coinsToFlower(getGreenhouseCostCoins(name));
    const m = marketByLowerName.get(name.toLowerCase());
    const sellFlower = m ? m.flowerPrice || 0 : 0;
    const boosted = computeBoostedGreenhouseStats(name, d.baseYield || 1, d.timeSec);
    const count = getGreenhouseCount(name);
    const restockInfo = {
      baseStock: BASE_STOCK_GREENHOUSE[name],
      kind: "seed",
      itemName: name
    };
    const unitProj = compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, 1, restockInfo);
    const holdingProj = count > 0 ? compute24hProjection(boosted.yieldVal, boosted.timeVal, costFlower, sellFlower, count, restockInfo) : null;
    items.push({
      name: name,
      category: "Greenhouse",
      icon: getIcon(name),
      countLabel: "Plot",
      count: count,
      cyclesPerDay: unitProj.cyclesPerDay,
      unitCost24h: unitProj.cost24h,
      unitRevenue24h: unitProj.revenue24h,
      unitProfit24h: unitProj.profit24h,
      unitRestockCost24h: unitProj.restockCost24h || 0,
      holdingUnitsPerDay: holdingProj ? holdingProj.unitsPerDay : 0,
      holdingCost24h: holdingProj ? holdingProj.cost24h : 0,
      holdingRevenue24h: holdingProj ? holdingProj.revenue24h : 0,
      holdingRestockCost24h: holdingProj ? holdingProj.restockCost24h || 0 : 0,
      holdingProfit24h: holdingProj ? holdingProj.profit24h : 0
    });
  });
  Object.keys(RESOURCE_DATA).forEach(name => {
    if (name.toLowerCase() === "oil") return;
    const fig = computeResourceFigures(name);
    const costFlower = coinsToFlower(fig.costPerUnit);
    const m = marketByLowerName.get(name.toLowerCase());
    const sellFlower = m ? m.flowerPrice || 0 : 0;
    const count = fig.nodeCount;
    const perNodeToolUsage = count > 0 ? fig.toolUsageTotal / count : 1;
    const unitFig = Object.assign({}, fig, {
      nodeCount: 1,
      toolUsageTotal: perNodeToolUsage,
      totalYieldPerCycle: fig.yieldPer
    });
    const unitProj = computeResourceProjection24h(unitFig, sellFlower);
    const holdingProj = count > 0 ? computeResourceProjection24h(fig, sellFlower) : null;
    items.push({
      name: name,
      category: "Resource",
      icon: getIcon(name),
      countLabel: "Node",
      count: count,
      cyclesPerDay: unitProj.cyclesPerDay,
      unitCost24h: unitProj.cost24h,
      unitRevenue24h: unitProj.revenue24h,
      unitProfit24h: unitProj.profit24h,
      unitRestockCost24h: unitProj.restockCost24h || 0,
      holdingUnitsPerDay: holdingProj ? holdingProj.unitsPerDay : 0,
      holdingCost24h: holdingProj ? holdingProj.cost24h : 0,
      holdingRevenue24h: holdingProj ? holdingProj.revenue24h : 0,
      holdingRestockCost24h: holdingProj ? holdingProj.restockCost24h || 0 : 0,
      holdingProfit24h: holdingProj ? holdingProj.profit24h : 0
    });
  });
  loadBaseHoneyIfNeeded();
  {
    const econ = computeHiveEconomics();
    const hives = getHiveCount();
    items.push({
      name: "Honey",
      category: "Honey",
      icon: getIcon("Honey"),
      countLabel: "Hive",
      count: hives,
      cyclesPerDay: econ.hiveStats.speed,
      unitCost24h: econ.costPerHiveDay,
      unitRevenue24h: econ.revenuePerHiveDay + econ.bonusCropValuePerHiveDay,
      unitProfit24h: econ.profitPerHiveDay,
      holdingUnitsPerDay: hives > 0 ? econ.hiveStats.honeyPerHiveDay * hives : 0,
      holdingCost24h: hives > 0 ? econ.costPerHiveDay * hives : 0,
      holdingRevenue24h: hives > 0 ? (econ.revenuePerHiveDay + econ.bonusCropValuePerHiveDay) * hives : 0,
      holdingProfit24h: hives > 0 ? econ.totalProfitDay : 0
    });
  }
  Object.keys(ANIMAL_DATA).forEach(type => {
    const fig = computeAnimalTypeFigures(type);
    const qty = fig.qty;
    const costPerAnimalFlower = coinsToFlower(fig.totalCostCoinsPerAnimal);
    let revenuePerAnimalFlower = 0;
    fig.products.forEach((pname, idx) => {
      const m = marketByLowerName.get(pname.toLowerCase());
      const price = m ? m.flowerPrice || 0 : 0;
      revenuePerAnimalFlower += fig.yields[idx] * price * (1 - feePercent / 100);
    });
    const cyclesPerDay = ANIMAL_BASE_CYCLE_SEC / fig.cycleTimeSec;
    const unitProfit24h = (revenuePerAnimalFlower - costPerAnimalFlower) * cyclesPerDay;
    items.push({
      name: fig.label,
      category: "Animal",
      icon: getIcon(fig.label) || `<span style="font-size:16.8px;">${fig.emoji}</span>`,
      countLabel: "Head",
      count: qty,
      cyclesPerDay: cyclesPerDay,
      unitCost24h: costPerAnimalFlower * cyclesPerDay,
      unitRevenue24h: revenuePerAnimalFlower * cyclesPerDay,
      unitProfit24h: unitProfit24h,
      holdingUnitsPerDay: qty > 0 ? fig.totalYieldUnits * qty * cyclesPerDay : 0,
      holdingCost24h: qty > 0 ? costPerAnimalFlower * cyclesPerDay * qty : 0,
      holdingRevenue24h: qty > 0 ? revenuePerAnimalFlower * cyclesPerDay * qty : 0,
      holdingProfit24h: qty > 0 ? unitProfit24h * qty : 0
    });
  });
  {
    const saltFig = computeSaltFarmFigures();
    const cyclesPerDay = saltFig.chargesPerDayPerNode;
    const unitProfit24h = saltFig.profitPerUnit * saltFig.yieldPerCharge * cyclesPerDay;
    items.push({
      name: "Salt",
      category: "Salt",
      icon: getIcon("Salt"),
      countLabel: "Node",
      count: saltFig.nodeCount,
      cyclesPerDay: cyclesPerDay,
      unitCost24h: saltFig.costPerUnitFlower * saltFig.yieldPerCharge * cyclesPerDay,
      unitRevenue24h: saltFig.netSell * saltFig.yieldPerCharge * cyclesPerDay,
      unitProfit24h: unitProfit24h,
      holdingUnitsPerDay: saltFig.saltPerDay,
      holdingCost24h: saltFig.costPerUnitFlower * saltFig.saltPerDay,
      holdingRevenue24h: saltFig.netSell * saltFig.saltPerDay,
      holdingProfit24h: saltFig.dailyProfit
    });
    Object.keys(BAIT_RECIPES).forEach(name => {
      const bf = computeBaitFigures(name);
      items.push({
        name: name,
        category: "Salt Bait",
        icon: getIcon(name),
        countLabel: "Batch",
        count: 0,
        cyclesPerDay: 0,
        unitCost24h: bf.unitCostExpected,
        unitRevenue24h: bf.netSell,
        unitProfit24h: bf.profitPerUnitExpected,
        holdingUnitsPerDay: 0,
        holdingProfit24h: 0
      });
    });
  }
  const coveredNames = new Set(items.map(it => (it.name || "").toLowerCase()));
  (marketItems || []).forEach(m => {
    const name = m && m.name;
    if (!name) return;
    const lname = name.toLowerCase();
    if (coveredNames.has(lname) || lname === "oil") return;
    coveredNames.add(lname);
    const sellFlower = m.flowerPrice || 0;
    const netSell = sellFlower * (1 - feePercent / 100);
    if (lname === "obsidian") {
      const fig = computeLavaPitFigures(currentSeason);
      const weekly = computeObsidianWeeklyProfit(fig, sellFlower);
      const costFlowerPerUnit = coinsToFlower(fig.costPerUnit || 0);
      items.push({
        name: name,
        category: "Obsidian",
        icon: getIcon(name),
        countLabel: "Lava Pit",
        count: 0,
        cyclesPerDay: null,
        unitCost24h: costFlowerPerUnit * (weekly.sellable / 7),
        unitRevenue24h: netSell * (weekly.sellable / 7),
        unitProfit24h: weekly.profit / 7,
        holdingUnitsPerDay: 0,
        holdingProfit24h: 0,
        unitRestockCost24h: 0,
        rateNote: `daily avg · capped ${OBSIDIAN_WEEKLY_SELL_CAP}/week`
      });
      return;
    }
    let costCoins = null;
    if (FLOWER_VARIETIES[name]) costCoins = getFlowerVarietyCostCoins(name); else {
      const tool = (typeof toolRecipes !== "undefined" ? toolRecipes : []).find(t => (t.producesName || "").toLowerCase() === lname);
      if (tool) costCoins = getToolCostCoins(tool.id);
    }
    const costFlower = costCoins != null ? coinsToFlower(costCoins) : null;
    const margin = costFlower != null ? netSell - costFlower : null;
    items.push({
      name: name,
      category: "Other",
      icon: getIcon(name),
      countLabel: "Unit",
      count: 0,
      cyclesPerDay: null,
      unitCost24h: costFlower,
      unitRevenue24h: netSell,
      unitProfit24h: margin,
      holdingUnitsPerDay: 0,
      holdingProfit24h: 0,
      unitRestockCost24h: 0,
      rateNote: costFlower == null ? "cost unknown — sell price only" : "per unit · one-off craft, no farm cycle",
      costUnknown: costFlower == null
    });
  });
  items.sort((a, b) => (b.unitProfit24h ?? -Infinity) - (a.unitProfit24h ?? -Infinity));
  return items.slice(0, 10);
}

function renderTop10Row(item, index) {
  const rank = index + 1;
  const rankClass = rank <= 3 ? `rank-${rank}` : "rank-rest";
  const costUnknown = !!item.costUnknown;
  const isProfit = !costUnknown && item.unitProfit24h >= 0;
  const ordinal = rank === 1 ? "1st" : rank === 2 ? "2nd" : rank === 3 ? "3rd" : `${rank}th`;
  const unitLabel = item.countLabel.toLowerCase();
  const periodPhrase = item.rateNote ? item.rateNote : `/ ${unitLabel} / 24h`;
  const hasHoldingTotals = item.count > 0 && item.holdingCost24h !== undefined;
  const ownedLine = item.count > 0 ? `${fmt(item.count)} ${item.countLabel}${item.count === 1 ? "" : "s"} owned · ${fmt(item.holdingUnitsPerDay)} units/24h` : item.rateNote ? item.rateNote : `Not tracked yet — showing per-${unitLabel} rate`;
  const holdingRestockNote = item.holdingRestockCost24h > 0 ? ` <span class="top10-restock-note">(incl. ${fmt(item.holdingRestockCost24h)} ${FLOWER_ICON} restock)</span>` : "";
  const grossLine = hasHoldingTotals ? `<div class="top10-gross-line" style="margin-top:2px;">Total 24h: Cost ${fmt(item.holdingCost24h)} ${FLOWER_ICON}${holdingRestockNote} &nbsp;→&nbsp; Rev ${fmt(item.holdingRevenue24h)} ${FLOWER_ICON} &nbsp;→&nbsp; <strong class="top10-net-value ${item.holdingProfit24h >= 0 ? "is-profit" : "is-loss"}">Net ${item.holdingProfit24h >= 0 ? "+" : ""}${fmt(item.holdingProfit24h)} ${FLOWER_ICON}</strong></div>` : "";
  const restockNote = item.unitRestockCost24h > 0 ? ` <span class="top10-restock-note">(incl. ${fmt(item.unitRestockCost24h)} ${FLOWER_ICON} restock)</span>` : "";
  const costLine = costUnknown ? `Cost unknown &nbsp;·&nbsp; Rev ${fmt(item.unitRevenue24h)} ${FLOWER_ICON} FLOWER <span style="opacity:.65;">${periodPhrase}</span>` : `Cost ${fmt(item.unitCost24h)} ${FLOWER_ICON} FLOWER${restockNote} &nbsp;·&nbsp; Rev ${fmt(item.unitRevenue24h)} ${FLOWER_ICON} FLOWER <span style="opacity:.65;">${periodPhrase}</span>`;
  const profitLine = costUnknown ? `<span style="opacity:.75;">Can't rank profit — no known cost basis for this item</span>` : `${isProfit ? "+" : ""}${fmt(item.unitProfit24h)} ${FLOWER_ICON} FLOWER ${item.rateNote ? "" : `per ${unitLabel} / 24h`}`;
  const metaLine = item.cyclesPerDay != null ? `${ownedLine} · ${fmt(item.cyclesPerDay)} cycles/day` : ownedLine;
  return `\n  <div class="top10-row ${rankClass}">\n    <div class="top10-rank-badge">${ordinal}</div>\n    <div class="top10-main">\n      <div class="top10-name-line">\n        <span class="top10-icon">${item.icon}</span>\n        <span class="top10-name">${escapeHtml(item.name)}</span>\n        <span class="top10-cat">${item.category}</span>\n      </div>\n      <div class="top10-fig-line">${costLine}</div>\n      <div class="top10-profit-line ${costUnknown ? "" : isProfit ? "is-profit" : "is-loss"}">${profitLine}</div>\n      <div class="top10-meta-line">${metaLine}</div>\n      ${grossLine}\n    </div>\n  </div>`;
}

function renderTop10Card() {
  const body = $("top10Body");
  const sub = $("top10Sub");
  if (!body) return;
  const items = gatherTop10ProfitItems();
  if (!items.length) {
    sub.textContent = "Ranked by per-unit 24h profit across crops, resources, fruits & animals";
    body.innerHTML = `<div class="top10-empty">🌱 No items found.</div>`;
    return;
  }
  sub.textContent = `Ranked by per-unit 24h profit across every tradable item — works even at 0 owned`;
  body.innerHTML = items.map(renderTop10Row).join("") + `<div class="top10-footer-note">Ranked purely by profit-per-unit, independent of how many you own. Items with no repeating farm cycle (crafted flowers, tools, Obsidian) show a one-off or capped daily-average margin instead. Items with no known cost basis anywhere in the app are shown with sell price only and can't be ranked by profit. Reopen or refresh to refresh the ranking as prices move.</div>`;
}

function showTop10Card() {
  const body = $("top10Body");
  const sub = $("top10Sub");
  if (body) body.innerHTML = `<div class="top10-empty">⏳ Crunching the numbers…</div>`;
  if (sub) sub.textContent = "Ranked by per-unit 24h profit across every tradable item";
  $("top10Overlay").classList.add("show");
  requestAnimationFrame(() => requestAnimationFrame(renderTop10Card));
  $("top10Overlay").classList.add("show");
}

function hideTop10Card() {
  $("top10Overlay").classList.remove("show");
}

$("top10CloseBtn").onclick = hideTop10Card;

$("openTop10HeaderBtn").onclick = () => { closeMoreMenu(); showTop10Card(); };

$("top10Overlay").addEventListener("click", e => {
  if (e.target.id === "top10Overlay") hideTop10Card();
});

let dailyProfitCardsCache = [];

const dailyProfitExpandedNames = new Set;

const dailyProfitCycleOverrides = new Map;

function dailyProfitDefaultCycles(card) {
  const v = card.cyclesPerDay;
  return typeof v === "number" && isFinite(v) && v > 0 ? v : 1;
}

function dailyProfitGetCycleCount(card) {
  const key = card.name.toLowerCase();
  return dailyProfitCycleOverrides.has(key) ? dailyProfitCycleOverrides.get(key) : dailyProfitDefaultCycles(card);
}

function computeDailyProfitProjection(card, cycleCount) {
  const marketId = farmPanelGetMarketId(card.name);
  const yieldPerCycle = card.totalYield || 0;
  const totalYield24h = yieldPerCycle * cycleCount;
  const grossPerCycle = (card.price || 0) * yieldPerCycle;
  const gross24h = (card.price || 0) * totalYield24h;
  const coinCostPerCycle = (card.costPerUnit || 0) * yieldPerCycle;
  const coinCost24h = (card.costPerUnit || 0) * totalYield24h;
  const restockInfo24h = marketId && totalYield24h > 0 ? computeQtyRestockGems(marketId, totalYield24h) : null;
  const restockCost24h = restockInfo24h ? restockInfo24h.flowerCost || 0 : 0;
  const shrineCost24h = (card.shrineCostPerCycle || 0) * cycleCount;
  const feeAmount24h = gross24h * ((feePercent || 0) / 100);
  const totalDeductions24h = coinCost24h + restockCost24h + shrineCost24h + feeAmount24h;
  const netProfit24h = gross24h - totalDeductions24h;
  return {
    yieldPerCycle: yieldPerCycle,
    totalYield24h: totalYield24h,
    grossPerCycle: grossPerCycle,
    gross24h: gross24h,
    coinCostPerCycle: coinCostPerCycle,
    coinCost24h: coinCost24h,
    restockCost24h: restockCost24h,
    shrineCost24h: shrineCost24h,
    feeAmount24h: feeAmount24h,
    totalDeductions24h: totalDeductions24h,
    netProfit24h: netProfit24h
  };
}

function fmtCycleInputValue(n) {
  if (!isFinite(n)) return "0";
  const r = Math.round(n * 100) / 100;
  return String(r);
}

function computeDailyProfitSummaryTotals() {
  let totalGross = 0, totalProfit = 0, totalDeductions = 0;
  dailyProfitCardsCache.forEach(card => {
    const cycleCount = dailyProfitGetCycleCount(card);
    const proj = computeDailyProfitProjection(card, cycleCount);
    if (proj.netProfit24h >= 0) {
      totalGross += proj.gross24h;
      totalProfit += proj.netProfit24h;
      totalDeductions += proj.totalDeductions24h;
    }
  });
  return {
    totalGross: totalGross,
    totalProfit: totalProfit,
    totalDeductions: totalDeductions
  };
}

function updateDailyProfitSummary() {
  const wrap = $("dailyProfitSummary");
  if (!wrap) return;
  if (!dailyProfitCardsCache.length) {
    wrap.innerHTML = "";
    return;
  }
  const {totalGross: totalGross, totalProfit: totalProfit, totalDeductions: totalDeductions} = computeDailyProfitSummaryTotals();
  wrap.innerHTML = `\n    <div class="dprofit-summary-row"><span class="dprofit-summary-label">Total Daily Gross</span><span class="dprofit-summary-value">${fmt(totalGross)} ${FLOWER_ICON}</span></div>\n    <div class="dprofit-summary-row"><span class="dprofit-summary-label">Total Deductions</span><span class="dprofit-summary-value is-loss">-${fmt(totalDeductions)} ${FLOWER_ICON}</span></div>\n    <div class="dprofit-summary-row"><span class="dprofit-summary-label">Total Daily Profit</span><span class="dprofit-summary-value is-profit">+${fmt(totalProfit)} ${FLOWER_ICON}</span></div>`;
}

function renderDailyProfitCardHtml(card) {
  const key = card.name.toLowerCase();
  const cycleCount = dailyProfitGetCycleCount(card);
  const proj = computeDailyProfitProjection(card, cycleCount);
  const isProfit = proj.netProfit24h >= 0;
  const expandedCls = dailyProfitExpandedNames.has(key) ? " expanded" : "";
  const nodeIcon = getNodeIconHtml(card.name);
  const nodeLabel = getNodeLabel(card.name);
  const shrineRow = proj.shrineCost24h > 0 ? `<div class="dprofit-stat dprofit-stat-sub"><span class="label">Shrine Cost${card.shrineNames && card.shrineNames.length ? ` (${card.shrineNames.map(escapeHtml).join(", ")})` : ""}</span><span class="value" data-role="shrine">-${fmt(proj.shrineCost24h)} ${FLOWER_ICON}</span></div>` : "";
  return `\n  <div class="dprofit-node-card${isProfit ? " is-profit" : " is-loss"}${expandedCls}" data-node="${escapeHtml(key)}">\n    <div class="dprofit-node-toggle">\n      <span class="dprofit-node-icon">${nodeIcon}</span>\n      <div class="dprofit-node-name-wrap">\n        <div class="dprofit-node-name">${escapeHtml(nodeLabel)}</div>\n        <div class="dprofit-node-sub">${card.displayNodeCount} node${card.displayNodeCount === 1 ? "" : "s"}</div>\n      </div>\n      <div class="dprofit-node-profit-wrap">\n        <div class="dprofit-node-24h ${isProfit ? "is-profit" : "is-loss"}" data-role="profit-value">${isProfit ? "+" : ""}${fmt(proj.netProfit24h)} ${FLOWER_ICON}</div>\n        <span class="dprofit-chev">▾</span>\n      </div>\n    </div>\n    <div class="dprofit-cycle-row">\n      <label>Cycles / 24h</label>\n      <input type="number" class="dprofit-cycle-input" inputmode="decimal" min="0" step="0.1" value="${fmtCycleInputValue(cycleCount)}" data-node="${escapeHtml(key)}">\n    </div>\n    <div class="dprofit-node-details">\n      <div class="dprofit-detail-grid">\n        <div class="dprofit-stat"><span class="label">Market Sell Price</span><span class="value">${fmt(card.price || 0)} ${FLOWER_ICON}</span></div>\n        <div class="dprofit-stat"><span class="label">Total Nodes</span><span class="value">${card.displayNodeCount}</span></div>\n        <div class="dprofit-stat"><span class="label">Yield / Cycle (Total)</span><span class="value" data-role="yield-cycle">${fmt(proj.yieldPerCycle)}</span></div>\n        <div class="dprofit-stat"><span class="label">24hr Total Yield</span><span class="value" data-role="yield-24h">${fmt(proj.totalYield24h)}</span></div>\n        <div class="dprofit-stat"><span class="label">Gross (1 Cycle)</span><span class="value" data-role="gross-cycle">${fmt(proj.grossPerCycle)} ${FLOWER_ICON}</span></div>\n        <div class="dprofit-stat"><span class="label">Gross (24hr)</span><span class="value" data-role="gross-24h">${fmt(proj.gross24h)} ${FLOWER_ICON}</span></div>\n      </div>\n      <div class="dprofit-deductions-title">Deductions</div>\n      <div class="dprofit-detail-grid">\n        <div class="dprofit-stat dprofit-stat-sub"><span class="label">Coin Cost / Cycle</span><span class="value" data-role="coin-cycle">-${fmt(proj.coinCostPerCycle)} ${FLOWER_ICON}</span></div>\n        <div class="dprofit-stat dprofit-stat-sub"><span class="label">Coin Cost (24hr)</span><span class="value" data-role="coin-24h">-${fmt(proj.coinCost24h)} ${FLOWER_ICON}</span></div>\n        <div class="dprofit-stat dprofit-stat-sub"><span class="label">Restock Cost</span><span class="value" data-role="restock">${proj.restockCost24h > 0 ? `-${fmt(proj.restockCost24h)}` : "0"} ${FLOWER_ICON}</span></div>\n        ${shrineRow}\n        <div class="dprofit-stat dprofit-stat-sub"><span class="label">Total Sell Fee${feePercent > 0 ? ` (${feePercent}%)` : ""}</span><span class="value" data-role="sellfee">${proj.feeAmount24h > 0 ? `-${fmt(proj.feeAmount24h)}` : "0"} ${FLOWER_ICON}</span></div>\n      </div>\n      <div class="dprofit-deductions-total-row">\n        <span class="label">Total Deductions</span>\n        <span class="value" data-role="total-deductions">-${fmt(proj.totalDeductions24h)} ${FLOWER_ICON}</span>\n      </div>\n      <div class="dprofit-net-row">\n        <span class="label">Total Net</span>\n        <span class="value ${isProfit ? "is-profit" : "is-loss"}" data-role="net-value">${isProfit ? "+" : ""}${fmt(proj.netProfit24h)} ${FLOWER_ICON}</span>\n      </div>\n    </div>\n  </div>`;
}

function updateDailyProfitCardDom(key, cycleCount) {
  const cardEl = $("dailyProfitBody")?.querySelector(`.dprofit-node-card[data-node="${CSS.escape(key)}"]`);
  if (!cardEl) return;
  const card = dailyProfitCardsCache.find(c => c.name.toLowerCase() === key);
  if (!card) return;
  const proj = computeDailyProfitProjection(card, cycleCount);
  const isProfit = proj.netProfit24h >= 0;
  cardEl.classList.toggle("is-profit", isProfit);
  cardEl.classList.toggle("is-loss", !isProfit);
  const setVal = (role, html) => {
    const el = cardEl.querySelector(`[data-role="${role}"]`);
    if (el) el.innerHTML = html;
  };
  const profitEl = cardEl.querySelector('[data-role="profit-value"]');
  if (profitEl) {
    profitEl.innerHTML = `${isProfit ? "+" : ""}${fmt(proj.netProfit24h)} ${FLOWER_ICON}`;
    profitEl.classList.toggle("is-profit", isProfit);
    profitEl.classList.toggle("is-loss", !isProfit);
  }
  setVal("yield-cycle", fmt(proj.yieldPerCycle));
  setVal("yield-24h", fmt(proj.totalYield24h));
  setVal("gross-cycle", `${fmt(proj.grossPerCycle)} ${FLOWER_ICON}`);
  setVal("gross-24h", `${fmt(proj.gross24h)} ${FLOWER_ICON}`);
  setVal("coin-cycle", `-${fmt(proj.coinCostPerCycle)} ${FLOWER_ICON}`);
  setVal("coin-24h", `-${fmt(proj.coinCost24h)} ${FLOWER_ICON}`);
  setVal("restock", `${proj.restockCost24h > 0 ? `-${fmt(proj.restockCost24h)}` : "0"} ${FLOWER_ICON}`);
  setVal("sellfee", `${proj.feeAmount24h > 0 ? `-${fmt(proj.feeAmount24h)}` : "0"} ${FLOWER_ICON}`);
  setVal("shrine", `${proj.shrineCost24h > 0 ? `-${fmt(proj.shrineCost24h)}` : "0"} ${FLOWER_ICON}`);
  setVal("total-deductions", `-${fmt(proj.totalDeductions24h)} ${FLOWER_ICON}`);
  const netEl = cardEl.querySelector('[data-role="net-value"]');
  if (netEl) {
    netEl.innerHTML = `${isProfit ? "+" : ""}${fmt(proj.netProfit24h)} ${FLOWER_ICON}`;
    netEl.classList.toggle("is-profit", isProfit);
    netEl.classList.toggle("is-loss", !isProfit);
  }
  updateDailyProfitSummary();
}

function attachDailyProfitCardEvents(container) {
  container.querySelectorAll(".dprofit-node-card").forEach(cardEl => {
    const key = cardEl.getAttribute("data-node");
    const toggle = cardEl.querySelector(".dprofit-node-toggle");
    if (toggle) {
      toggle.onclick = () => {
        const nowExpanded = cardEl.classList.toggle("expanded");
        if (nowExpanded) dailyProfitExpandedNames.add(key); else dailyProfitExpandedNames.delete(key);
      };
    }
    const input = cardEl.querySelector(".dprofit-cycle-input");
    if (input) {
      input.addEventListener("click", e => e.stopPropagation());
      input.addEventListener("pointerdown", e => e.stopPropagation());
      input.addEventListener("input", () => {
        const raw = parseFloat(input.value);
        const val = isFinite(raw) && raw >= 0 ? raw : 0;
        dailyProfitCycleOverrides.set(key, val);
        updateDailyProfitCardDom(key, val);
      });
    }
  });
}

function renderDailyProfitCard() {
  const body = $("dailyProfitBody");
  if (!body) return;
  if (!farmPanelGameState) {
    dailyProfitCardsCache = [];
    body.innerHTML = `<div class="dprofit-empty">🌱 Sync a Farm ID first to see your Daily Profit.</div>`;
    updateDailyProfitSummary();
    return;
  }
  const cards = farmPanelComputeInProgress(farmPanelGameState);
  dailyProfitCardsCache = cards;
  if (!cards.length) {
    body.innerHTML = `<div class="dprofit-empty">⏳ Nothing currently growing in this farm.</div>`;
    updateDailyProfitSummary();
    return;
  }
  const sorted = cards.slice().sort((a, b) => {
    const projA = computeDailyProfitProjection(a, dailyProfitGetCycleCount(a));
    const projB = computeDailyProfitProjection(b, dailyProfitGetCycleCount(b));
    return projB.netProfit24h - projA.netProfit24h;
  });
  body.innerHTML = sorted.map(renderDailyProfitCardHtml).join("");
  attachDailyProfitCardEvents(body);
  updateDailyProfitSummary();
}

function showDailyProfitCard() {
  const body = $("dailyProfitBody");
  if (body) body.innerHTML = `<div class="dprofit-empty">⏳ Counting today's coin…</div>`;
  const summary = $("dailyProfitSummary");
  if (summary) summary.innerHTML = "";
  $("dailyProfitOverlay").classList.add("show");
  requestAnimationFrame(() => requestAnimationFrame(renderDailyProfitCard));
}

function hideDailyProfitCard() {
  $("dailyProfitOverlay").classList.remove("show");
}

$("dailyProfitCloseBtn").onclick = hideDailyProfitCard;

$("openDailyProfitHeaderBtn").onclick = () => { closeMoreMenu(); showDailyProfitCard(); };

$("dailyProfitOverlay").addEventListener("click", e => {
  if (e.target.id === "dailyProfitOverlay") hideDailyProfitCard();
});

let pixelPickerOnSelect = null;

function openPixelPicker(title, options, selectedValue, onSelect) {
  pixelPickerOnSelect = onSelect;
  $("pixelPickerTitle").textContent = title;
  $("pixelPickerBody").innerHTML = options.map((o, i) => `\n    <div class="pixel-picker-option${o.value === selectedValue ? " is-selected" : ""}" data-value="${escapeHtml(o.value)}" style="--row-i:${i};">\n      <div class="pixel-picker-option-main">\n        <div class="pixel-picker-option-name">${o.name}</div>\n        ${o.meta ? `<div class="pixel-picker-option-meta">${o.meta}</div>` : ""}\n      </div>\n      ${o.badge ? `<div class="pixel-picker-option-badge">${escapeHtml(o.badge)}</div>` : ""}\n      ${o.value === selectedValue ? `<div class="pixel-picker-check">✓</div>` : ""}\n    </div>`).join("");
  const overlay = $("pixelPickerOverlay");
  overlay.classList.remove("show");
  void overlay.offsetWidth;
  overlay.classList.add("show");
  document.querySelectorAll("#pixelPickerBody .pixel-picker-option").forEach(row => {
    row.onclick = () => {
      const cb = pixelPickerOnSelect;
      closePixelPicker();
      if (cb) cb(row.dataset.value);
    };
  });
}

function closePixelPicker() {
  $("pixelPickerOverlay").classList.remove("show");
  pixelPickerOnSelect = null;
}

$("pixelPickerCloseBtn").onclick = closePixelPicker;

$("pixelPickerOverlay").addEventListener("click", e => {
  if (e.target.id === "pixelPickerOverlay") closePixelPicker();
});

