function beginLoadingSequence() {
  const screen = document.getElementById("appLoadingScreen");
  const fill = document.getElementById("loadingProgressFill");
  const label = document.getElementById("loadingProgressLabel");
  if (!screen || screen.dataset.loadingStarted) {
    window.dispatchEvent(new Event("goblinAppReady"));
    return;
  }
  screen.dataset.loadingStarted = "1";
  screen.classList.remove("show-prompt");
  document.documentElement.style.overflow = "hidden";
  if (fill) fill.style.transform = "scaleX(0)";
  if (label) label.textContent = "SYNCING FARM... 0%";
  if (goblinLoadingProgressTimer) clearInterval(goblinLoadingProgressTimer);
  let i = 0;
  goblinLoadingProgressTimer = setInterval(() => {
    i = Math.min(i + 1, APP_LOADING_STAGES.length - 1);
    const stage = APP_LOADING_STAGES[i];
    if (fill) fill.style.transform = "scaleX(" + stage.pct / 100 + ")";
    if (label) label.textContent = "SYNCING FARM... " + stage.pct + "%";
  }, 550);
}

function finishLoadingSequence() {
  const screen = document.getElementById("appLoadingScreen");
  const fill = document.getElementById("loadingProgressFill");
  const label = document.getElementById("loadingProgressLabel");
  if (goblinLoadingProgressTimer) {
    clearInterval(goblinLoadingProgressTimer);
    goblinLoadingProgressTimer = null;
  }
  if (!screen || !screen.dataset.loadingStarted) return;
  if (fill) fill.style.transform = "scaleX(1)";
  if (label) label.textContent = "SYNCING FARM... 100%";
  screen.classList.add("hide");
  document.documentElement.style.overflow = "";
  setTimeout(() => {
    screen.remove();
  }, 550);
  window.dispatchEvent(new Event("goblinAppReady"));
}

(function() {
  const btn = document.getElementById("footerCopyAddressBtn");
  const addr = document.getElementById("footerDonateAddress");
  if (!btn || !addr) return;
  btn.addEventListener("click", async () => {
    const text = addr.textContent.trim();
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(text);
      } else {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
      }
      const original = btn.textContent;
      btn.textContent = "✅";
      btn.classList.add("copied");
      setTimeout(() => {
        btn.textContent = original;
        btn.classList.remove("copied");
      }, 1500);
    } catch (e) {}
  });
})();

