function cookFoodIcon(name) {
  const imgSrc = COOKING_FOOD_IMAGES[name];
  if (imgSrc) return `<img src="${imgSrc}" alt="${escapeHtml(name)}" style="width:16px;height:16px;image-rendering:pixelated;vertical-align:middle;">`;
  return `<span style="font-size:19.2px;line-height:1;">${COOKING_FOOD_EMOJI[name] || "🍽️"}</span>`;
}


let cookingCounts = safeLSJSON(localStorage.getItem("hl_cooking_counts"), {});

function saveCookingCounts() {
  localStorage.setItem("hl_cooking_counts", JSON.stringify(cookingCounts));
}

function getCookingCount(name) {
  return Number(cookingCounts[name]) || 0;
}

function setCookingCount(name, val) {
  const n = Math.max(0, Math.floor(Number(val) || 0));
  if (n) cookingCounts[name] = n; else delete cookingCounts[name];
  saveCookingCounts();
}

let cookingCostMode = localStorage.getItem("hl_cooking_cost_mode") || "collect";

function setCookingCostMode(mode) {
  cookingCostMode = mode === "buy" ? "buy" : "collect";
  localStorage.setItem("hl_cooking_cost_mode", cookingCostMode);
}

let cookingActiveBuilding = localStorage.getItem("hl_cooking_active_building") || "Fire Pit";

function setCookingActiveBuilding(b) {
  cookingActiveBuilding = COOKING_BUILDINGS.includes(b) ? b : "Fire Pit";
  localStorage.setItem("hl_cooking_active_building", cookingActiveBuilding);
}

let cookingExpandedFoods = new Set(safeLSJSON(localStorage.getItem("hl_cooking_expanded"), []));

function saveCookingExpanded() {
  localStorage.setItem("hl_cooking_expanded", JSON.stringify([ ...cookingExpandedFoods ]));
}

const COOKING_FISH_DISHES = new Set([ "Furikake Sprinkle", "Gumbo", "Surimi Rice Bowl", "Creamy Crab Bite", "Crimstone Infused Fish Oil", "Chowder", "Fried Calamari", "Fish Burger", "Fish Omelette", "Ocean's Olive", "Seafood Basket", "Fish n Chips", "Sushi Roll", "Fermented Fish" ]);

const COOKING_CAKE_DISHES = new Set([ "Wheat Cake", "Sunflower Cake", "Potato Cake", "Pumpkin Cake", "Carrot Cake", "Cabbage Cake", "Beetroot Cake", "Cauliflower Cake", "Parsnip Cake", "Eggplant Cake", "Radish Cake", "Orange Cake", "Honey Cake", "Lemon Cheesecake" ]);

function cookingFindRecipeForFood(name) {
  for (const b of COOKING_BUILDINGS) {
    const rec = COOKING_RECIPES[b] && COOKING_RECIPES[b][name];
    if (rec) return rec;
  }
  return null;
}

function cookingIngredientIcon(name) {
  return cookingFindRecipeForFood(name) ? cookFoodIcon(name) : getIcon(name);
}

function cookingFoodHasIngredient(building, name, ingredientName) {
  const rec = COOKING_RECIPES[building] && COOKING_RECIPES[building][name];
  return !!(rec && rec.ingredients && rec.ingredients[ingredientName]);
}

function cookingSkillRankMultiplier(skillId, rankAddValues) {
  if (typeof isSkillActive !== "function" || !isSkillActive(skillId)) return 1;
  const rank = typeof getAscensionRank === "function" ? getAscensionRank(skillId) : 1;
  const idx = Math.min(Math.max(rank, 1), 3) - 1;
  return 1 + (rankAddValues[idx] !== undefined ? rankAddValues[idx] : rankAddValues[0]);
}

function getPortBudFishXpMult() {
  let maxBoost = 1;
  const g = typeof profileGetG === "function" ? profileGetG() : null;
  const buds = g && g.buds && typeof g.buds === "object" ? g.buds : {};
  Object.values(buds).forEach(bud => {
    if (!bud || !bud.coordinates) return;
    const traits = typeof farmSyncExtractBudTraits === "function" ? farmSyncExtractBudTraits(bud) : null;
    if (!traits || traits.type !== "Port") return;
    let auraBoost = 1;
    if (traits.aura === "Basic") auraBoost = 1.05; else if (traits.aura === "Green") auraBoost = 1.2; else if (traits.aura === "Rare") auraBoost = 2; else if (traits.aura === "Mythical") auraBoost = 5;
    const boost = 1 + auraBoost * .1;
    if (boost > maxBoost) maxBoost = boost;
  });
  (typeof fishBuds !== "undefined" ? fishBuds : []).forEach(bud => {
    if (!bud || bud.typeId !== "port") return;
    const aura = BUD_AURAS.find(a => a.id === bud.auraId) || BUD_AURAS[0];
    const boost = 1 + aura.mult * .1;
    if (boost > maxBoost) maxBoost = boost;
  });
  return maxBoost;
}

function cookingComputeFoodExp(building, name) {
  const memoKey = building + "|" + name;
  if (__cookingFoodExpMemo.has(memoKey)) return __cookingFoodExpMemo.get(memoKey);
  const result = cookingComputeFoodExpUncached(building, name);
  __cookingFoodExpMemo.set(memoKey, result);
  return result;
}

function cookingComputeFoodExpUncached(building, name) {
  const rec = COOKING_RECIPES[building][name];
  let exp = rec.exp;
  const boostsUsed = [];
  const applyMult = (m, label, icon) => {
    if (m && m !== 1) {
      exp *= m;
      boostsUsed.push({
        text: label,
        icon: icon || ""
      });
    }
  };
  const applyAdd = (a, label, icon) => {
    if (a) {
      exp += a;
      boostsUsed.push({
        text: label,
        icon: icon || ""
      });
    }
  };
  if (typeof isBoostActive === "function") {
    COOKING_BOOSTS.forEach(b => {
      if (!isBoostActive(b.id)) return;
      let applies = false;
      if (b.scope === "foodGlobal") applies = true; else if (b.scope === "foodFish") applies = COOKING_FISH_DISHES.has(name); else if (b.scope === "foodCake") applies = COOKING_CAKE_DISHES.has(name); else if (b.scope === "foodCheese") applies = cookingFoodHasIngredient(building, name, "Cheese"); else if (b.scope === "foodSpecific") applies = b.target === name;
      if (!applies) return;
      const icon = getBoostIcon(b.name);
      if (b.expMult) applyMult(b.expMult, `${b.name} ×${b.expMult}`, icon);
      if (b.expAdd) applyAdd(b.expAdd, `${b.name} +${fmt(b.expAdd)}`, icon);
    });
  }
  applyMult(cookingSkillRankMultiplier("skill_munching_mastery", [ .05, .1, .15 ]), "Munching Mastery");
  if (building === "Deli") applyMult(cookingSkillRankMultiplier("skill_drive_through_deli", [ .15, .2, .25 ]), "Drive-Through Deli");
  if (building === "Smoothie Shack") applyMult(cookingSkillRankMultiplier("skill_juicy_boost", [ .1, .2, .3 ]), "Juicy Boost");
  if (COOKING_FISH_DISHES.has(name)) {
    applyMult(cookingSkillRankMultiplier("skill_fishy_feast", [ .2, .25, .3 ]), "Fishy Feast");
    const portBudMult = getPortBudFishXpMult();
    if (portBudMult !== 1) applyMult(portBudMult, `Port Bud ×${portBudMult}`);
  }
  if (cookingFoodHasIngredient(building, name, "Honey")) applyMult(cookingSkillRankMultiplier("skill_buzzworthy_treats", [ .1, .2, .3 ]), "Buzzworthy Treats");
  try {
    const info = typeof farmPanelGetLastInfo === "function" ? farmPanelGetLastInfo() : null;
    if (info && info.vipActive) applyMult(1.1, "VIP Access ×1.1");
  } catch (e) {}
  try {
    if (typeof factionPetGetBoostMultiplier === "function") {
      const petMult = factionPetGetBoostMultiplier();
      if (petMult !== 1) applyMult(petMult, `Faction Pet Streak ×${petMult}`);
    }
  } catch (e) {}
  return {
    exp: exp,
    boostsUsed: boostsUsed,
    baseExp: rec.exp
  };
}

function cookingComputeFoodTime(building, name) {
  const memoKey = building + "|" + name;
  if (__cookingFoodTimeMemo.has(memoKey)) return __cookingFoodTimeMemo.get(memoKey);
  const result = cookingComputeFoodTimeUncached(building, name);
  __cookingFoodTimeMemo.set(memoKey, result);
  return result;
}

function cookingComputeFoodTimeUncached(building, name) {
  const rec = COOKING_RECIPES[building][name];
  let time = rec.time;
  const boostsUsed = [];
  if (time == null) return {
    time: null,
    boostsUsed: boostsUsed,
    baseTime: null
  };
  const applyMult = (m, label, icon) => {
    if (m && m !== 1) {
      time *= m;
      boostsUsed.push({
        text: label,
        icon: icon || ""
      });
    }
  };
  if (typeof isBoostActive === "function") {
    COOKING_BOOSTS.forEach(b => {
      if (b.scope !== "cookTimeGlobal") return;
      if (!isBoostActive(b.id)) return;
      if (b.timeMult) applyMult(b.timeMult, `${b.name} ×${b.timeMult}`, getBoostIcon(b.name));
    });
  }
  return {
    time: time,
    boostsUsed: boostsUsed,
    baseTime: rec.time
  };
}

function cookingIngredientUnitCostCoins(name, mode, visited) {
  const memoKey = mode + "|" + name;
  if (__cookingCostMemo.has(memoKey)) return __cookingCostMemo.get(memoKey);
  if (visited && visited.has(memoKey)) return 0;
  const branchVisited = new Set(visited || []);
  branchVisited.add(memoKey);
  const result = cookingIngredientUnitCostCoinsUncached(name, mode, branchVisited);
  __cookingCostMemo.set(memoKey, result);
  return result;
}

function cookingIngredientUnitCostCoinsUncached(name, mode, visited) {
  visited = visited || new Set;
  for (const b of COOKING_BUILDINGS) {
    const rec = COOKING_RECIPES[b] && COOKING_RECIPES[b][name];
    if (rec) {
      const key = "cook:" + name;
      if (visited.has(key)) return 0;
      const branchVisited = new Set(visited);
      branchVisited.add(key);
      let sum = 0;
      Object.keys(rec.ingredients).forEach(ing => {
        sum += rec.ingredients[ing] * cookingIngredientUnitCostCoins(ing, mode, new Set(branchVisited));
      });
      return sum;
    }
  }
  if (typeof getMaterialUnitCostCoins === "function") return getMaterialUnitCostCoins(name, mode, visited);
  return 0;
}

function cookingInvAmount(v) {
  if (v == null) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "string") return parseFloat(v) || 0;
  if (typeof v === "object") {
    if (typeof v.toNumber === "function") {
      try {
        return v.toNumber();
      } catch (e) {}
    }
    if (typeof v.toString === "function") {
      const n = parseFloat(v.toString());
      if (Number.isFinite(n)) return n;
    }
  }
  return 0;
}

function syncCookingCountsFromInventory(json) {
  if (!json || typeof farmSyncExtractGameState !== "function") return {
    matched: 0
  };
  const g = farmSyncExtractGameState(json);
  const inv = g && g.inventory;
  if (!inv || typeof inv !== "object") return {
    matched: 0
  };
  const normalizeInvKey = s => String(s || "").trim().toLowerCase();
  const invKeyByNormalized = {};
  Object.keys(inv).forEach(k => {
    invKeyByNormalized[normalizeInvKey(k)] = k;
  });
  const findInvKey = name => name in inv ? name : invKeyByNormalized[normalizeInvKey(name)] || null;
  let matched = 0;
  let synced = 0;
  const applyInvSync = (storeName, invKey) => {
    const qty = invKey ? Math.max(0, Math.floor(cookingInvAmount(inv[invKey]))) : 0;
    if (qty > 0) cookingCounts[storeName] = qty; else delete cookingCounts[storeName];
    synced++;
    if (invKey) matched++;
  };
  COOKING_BUILDINGS.forEach(b => {
    Object.keys(COOKING_RECIPES[b]).forEach(food => {
      const key = findInvKey(food);
      applyInvSync(food, key);
    });
  });
  if (typeof FISH_CATCH_NAMES !== "undefined") {
    [ "Basic Fish", "Aged Fish", "Prime Aged Fish" ].forEach(cat => {
      FISH_CATCH_NAMES.forEach(f => {
        const invName = fishInventoryNameForCategory(f, cat);
        const key = findInvKey(invName);
        applyInvSync(invName, key);
      });
    });
  }
  if (synced) saveCookingCounts();
  return {
    matched: matched
  };
}

function cookingComputeTotals() {
  let totalExpAdded = 0;
  let totalCostCoins = 0;
  COOKING_BUILDINGS.forEach(b => {
    Object.keys(COOKING_RECIPES[b]).forEach(food => {
      const count = getCookingCount(food);
      if (!count) return;
      const rec = COOKING_RECIPES[b][food];
      const {exp: exp} = cookingComputeFoodExp(b, food);
      totalExpAdded += exp * count;
      Object.keys(rec.ingredients).forEach(ing => {
        totalCostCoins += rec.ingredients[ing] * count * cookingIngredientUnitCostCoins(ing, cookingCostMode);
      });
    });
  });
  if (typeof cookingFishTotals === "function") {
    const fishTotals = cookingFishTotals();
    totalExpAdded += fishTotals.totalExpAdded;
    totalCostCoins += fishTotals.totalCostCoins;
  }
  return {
    totalExpAdded: totalExpAdded,
    totalCostCoins: totalCostCoins
  };
}

function factionPetGetEffectiveStreak() {
  const raw = localStorage.getItem("hl_faction_pet_week_streak");
  const n = parseInt(raw, 10);
  return !isNaN(n) && n >= 0 ? n : 0;
}

function factionPetSetManualStreak(val) {
  const n = parseInt(val, 10);
  localStorage.setItem("hl_faction_pet_week_streak", String(!isNaN(n) && n >= 0 ? n : 0));
}

function factionPetGetActiveTier(streak) {
  let active = null;
  FACTION_PET_BOOST_TIERS.forEach(tier => {
    if (streak >= tier.streak) active = tier;
  });
  return active;
}

function factionPetShouldApplyBoost() {
  if (factionPetManualMode) return true;
  const info = farmPanelGetLastInfo();
  if (info.factionIsMember && info.factionHasPetData && !info.factionIsContributing) return false;
  return true;
}

function factionPetGetBoostMultiplier() {
  if (!factionPetShouldApplyBoost()) return 1;
  const tier = factionPetGetActiveTier(factionPetGetEffectiveStreak());
  return tier ? 1 + tier.boost : 1;
}

function renderFactionPetHeader() {
  const wrap = $("factionPetSection");
  if (!wrap) return;
  const info = farmPanelGetLastInfo();
  const isMember = info.factionIsMember;
  const factionName = info.factionName;
  const hasPetData = info.factionHasPetData;
  const petLabel = isMember && factionName && FACTION_DISPLAY_NAMES[factionName] ? FACTION_DISPLAY_NAMES[factionName] : "No Faction Pet";
  const iconHtml = isMember && factionName && FACTION_PET_HAPPY_ICONS[factionName] ? `<img src="${FACTION_PET_HAPPY_ICONS[factionName]}" alt="${escapeHtml(petLabel)}">` : `<span class="fp-icon-unknown">❓</span>`;
  const goalXP = hasPetData ? info.factionGoalXP : 0;
  const totalXP = hasPetData ? info.factionTotalXP : 0;
  const pct = goalXP > 0 ? Math.min(100, totalXP / goalXP * 100) : 0;
  const barCaption = hasPetData ? `${fmt(totalXP)} / ${fmt(goalXP)} XP` : `No sync data yet`;
  const streak = factionPetGetEffectiveStreak();
  const tier = factionPetGetActiveTier(streak);
  const applies = factionPetShouldApplyBoost();
  const boostPct = tier && applies ? Math.round(tier.boost * 100) : 0;
  const boostBadgeInner = id => boostPct > 0 ? `<span class="fp-boost-badge" id="${id}">+${boostPct}% XP</span>` : `<span class="fp-boost-badge none" id="${id}">No boost</span>`;
  let statusHtml = "";
  if (factionPetManualMode) {
    statusHtml = `<div class="fp-status-msg is-good">Manual mode ON — boost is applied regardless of faction or contributor status.</div>`;
  } else if (!isMember) {
    statusHtml = `<div class="fp-status-msg">You are not a member of any faction. You can visit the plaza and choose your faction to get XP boost from the faction pet.</div>`;
  } else if (hasPetData && !info.factionIsContributing) {
    statusHtml = `<div class="fp-status-msg is-warn">Not a contributor. Visit your faction and feed your faction pet.</div>`;
  } else if (hasPetData && info.factionIsContributing) {
    statusHtml = `<div class="fp-status-msg is-good">Contributing member — faction pet boost is applied to food & fish XP.</div>`;
  } else {
    statusHtml = `<div class="fp-status-msg">Sync your farm to detect this week's faction pet contribution status.</div>`;
  }
  const tiersHtml = FACTION_PET_BOOST_TIERS.map(t => {
    const isActive = tier === t;
    return `\n      <div class="fp-boost-tier${isActive ? " active" : ""}">\n        <span class="fp-tier-check">${isActive ? "✓" : ""}</span>\n        <span>Week ${t.streak} streak achieved = +${Math.round(t.boost * 100)}% XP during ${t.weeksNote}</span>\n      </div>\n    `;
  }).join("");
  wrap.innerHTML = `\n    <div class="fp-title-bar">\n      <span>🐾 Faction Pet</span>\n      <label class="fp-manual-toggle" id="fpManualToggleRow">\n        <span class="fp-manual-toggle-label">Manual</span>\n        <span class="fp-manual-toggle-state">${factionPetManualMode ? "ON" : "OFF"}</span>\n        <span class="switch">\n          <input type="checkbox" id="fpManualToggleInput" ${factionPetManualMode ? "checked" : ""}>\n          <span class="slider"></span>\n        </span>\n      </label>\n    </div>\n    <div class="fp-card">\n      <div class="fp-top-row${fpBoostPanelOpen ? " open" : ""}" id="fpTopRow">\n        <div class="fp-icon-frame">${iconHtml}</div>\n        <div class="fp-name-col">\n          <div class="fp-name">${escapeHtml(petLabel)}</div>\n          <div class="fp-name-sub">Faction Pet</div>\n        </div>\n        ${boostBadgeInner("fpBoostBadgeTop")}\n        <span class="fp-chev">▾</span>\n      </div>\n      <div class="fp-progress-wrap">\n        <div class="fp-bar-track"><div class="fp-bar-fill" style="width:${pct}%;"></div></div>\n        <div class="fp-bar-caption"><span>${barCaption}</span><span id="fpBarStreakText">${streak > 0 ? `🔥 Streak ${streak}` : ""}</span></div>\n      </div>\n      ${statusHtml}\n      <div class="fp-streak-row">\n        <label for="fpStreakInput">Week Streak</label>\n        <input type="number" min="0" step="1" id="fpStreakInput" value="${streak}">\n        ${boostBadgeInner("fpBoostBadgeStreak")}\n      </div>\n      <div class="fp-boost-panel${fpBoostPanelOpen ? " open" : ""}" id="fpBoostPanel">\n        <div class="fp-boost-panel-title">⚡ Streak boost tiers</div>\n        <div id="fpTiersList">${tiersHtml}</div>\n        <div class="fp-boost-note">Beyond week 8, the pet still needs its weekly goal met to keep the streak bonus alive. If the goal isn't met by the end of the week, the streak resets and the pet sleeps for a week.</div>\n      </div>\n    </div>\n  `;
  const topRow = $("fpTopRow");
  if (topRow) {
    topRow.onclick = e => {
      if (e.target && e.target.id === "fpStreakInput") return;
      fpBoostPanelOpen = !fpBoostPanelOpen;
      renderFactionPetHeader();
    };
  }
  const streakInput = $("fpStreakInput");
  if (streakInput) {
    streakInput.onclick = e => e.stopPropagation();
    streakInput.oninput = () => {
      factionPetSetManualStreak(streakInput.value);
      if (typeof invalidateCostCache === "function") invalidateCostCache();
      factionPetUpdateBoostUI();
      renderCookingHeader();
      if (typeof renderCookingFoodList === "function") renderCookingFoodList();
    };
  }
  const manualToggleRow = $("fpManualToggleRow");
  const manualToggleInput = $("fpManualToggleInput");
  if (manualToggleRow && manualToggleInput) {
    manualToggleRow.onclick = e => e.stopPropagation();
    manualToggleInput.onchange = () => {
      setFactionPetManualMode(manualToggleInput.checked);
      if (typeof invalidateCostCache === "function") invalidateCostCache();
      renderFactionPetHeader();
      renderCookingHeader();
      if (typeof renderCookingFoodList === "function") renderCookingFoodList();
    };
  }
}

function factionPetUpdateBoostUI() {
  const streak = factionPetGetEffectiveStreak();
  const tier = factionPetGetActiveTier(streak);
  const applies = factionPetShouldApplyBoost();
  const boostPct = tier && applies ? Math.round(tier.boost * 100) : 0;
  const badgeText = boostPct > 0 ? `+${boostPct}% XP` : "No boost";
  [ $("fpBoostBadgeTop"), $("fpBoostBadgeStreak") ].forEach(badge => {
    if (!badge) return;
    badge.textContent = badgeText;
    badge.classList.toggle("none", boostPct === 0);
  });
  const streakText = $("fpBarStreakText");
  if (streakText) streakText.textContent = streak > 0 ? `🔥 Streak ${streak}` : "";
  const tiersWrap = $("fpTiersList");
  if (tiersWrap) {
    tiersWrap.innerHTML = FACTION_PET_BOOST_TIERS.map(t => {
      const isActive = tier === t;
      return `\n        <div class="fp-boost-tier${isActive ? " active" : ""}">\n          <span class="fp-tier-check">${isActive ? "✓" : ""}</span>\n          <span>Week ${t.streak} streak achieved = +${Math.round(t.boost * 100)}% XP during ${t.weeksNote}</span>\n        </div>\n      `;
    }).join("");
  }
}

function renderCookingHeader() {
  const wrap = $("cookHeader");
  if (!wrap) return;
  let experience = 0;
  let syncedAscensionLevel = 0;
  try {
    const info = typeof farmPanelGetLastInfo === "function" ? farmPanelGetLastInfo() : null;
    if (info) syncedAscensionLevel = info.ascensionLevel || 0;
    if (farmPanelGameState && typeof farmSyncExtractGameState === "function") {
      const g = farmSyncExtractGameState(farmPanelGameState);
      experience = g && g.bumpkin && Number(g.bumpkin.experience) || 0;
    }
  } catch (e) {}
  const cur = cookGetLevelInfo(experience);
  const {totalExpAdded: totalExpAdded, totalCostCoins: totalCostCoins} = cookingComputeTotals();
  const preview = cookGetLevelInfo(experience + totalExpAdded);
  const curPct = cur.span > 0 ? Math.min(100, cur.progress / cur.span * 100) : 100;
  const previewExtra = cur.isMax ? 0 : Math.min(cur.span - cur.progress, Math.max(0, totalExpAdded));
  const previewPct = cur.span > 0 ? Math.min(100, (cur.progress + previewExtra) / cur.span * 100) : 100;
  const flowerCost = typeof coinsToFlower === "function" ? coinsToFlower(totalCostCoins) : 0;
  const levelUpNote = preview.level > cur.level ? ` <span class="cook-levelup-pill">→ Level ${preview.level}!</span>` : "";
  const willCrossAscensionCap = cur.level >= PRE_ASCENSION_MAX_LEVEL || preview.level >= PRE_ASCENSION_MAX_LEVEL;
  let ascensionHtml = "";
  if (syncedAscensionLevel > 0 || willCrossAscensionCap) {
    const ascCur = resolveAscensionLevelInfo(experience);
    const ascPreview = resolveAscensionLevelInfo(experience + totalExpAdded);
    const ascCurPct = ascCur.experienceToNextLevel > 0 ? Math.min(100, ascCur.currentExperienceProgress / ascCur.experienceToNextLevel * 100) : 100;
    const ascPreviewExtra = ascCur.isReadyToAscend ? 0 : Math.min(Math.max(0, ascCur.experienceToNextLevel - ascCur.currentExperienceProgress), Math.max(0, totalExpAdded));
    const ascPreviewPct = ascCur.experienceToNextLevel > 0 ? Math.min(100, (ascCur.currentExperienceProgress + ascPreviewExtra) / ascCur.experienceToNextLevel * 100) : 100;
    const ascLevelUpNote = ascPreview.ascension > ascCur.ascension ? ` <span class="cook-levelup-pill">→ Ascension [${ascPreview.ascension}] Lv ${ascPreview.level}!</span>` : ascPreview.level > ascCur.level ? ` <span class="cook-levelup-pill">→ Level ${ascPreview.level}!</span>` : "";
    const projectedTag = syncedAscensionLevel > 0 ? "" : ` <span class="cook-ascension-projected">(projected — not ascended yet)</span>`;
    ascensionHtml = `\n    <div class="cook-ascension-row">\n      <span class="cook-ascension-badge">Ascension [${ascCur.ascension}] · Lv ${ascCur.level}${ascCur.isReadyToAscend ? " ✅ Ready" : ""}</span>${projectedTag}\n    </div>\n    <div class="cook-bar-stack">\n      <div class="cook-bar-track">\n        <div class="cook-bar-fill preview" style="width:${ascPreviewPct}%;"></div>\n        <div class="cook-bar-fill" style="width:${ascCurPct}%;"></div>\n      </div>\n    </div>\n    <div class="cook-bar-caption">${ascCur.isReadyToAscend ? "Ready to Ascend" : `${fmt(ascCur.currentExperienceProgress)} / ${fmt(ascCur.experienceToNextLevel)} EXP to Ascension [${ascCur.ascension}] Lv ${ascCur.level + 1}${ascLevelUpNote}`}</div>\n  `;
  }
  wrap.innerHTML = `\n    <div class="cook-header-row">\n      <span class="cook-level-badge"><span class="cook-level-badge-title">Bumpkin</span><span class="cook-level-badge-value">🧑‍🌾 Level ${cur.level}${cur.isMax ? " MAX" : ""}</span></span>\n      <span class="cook-exp-label">${fmt(experience)} EXP</span>\n    </div>\n    <div class="cook-bar-stack">\n      <div class="cook-bar-track">\n        <div class="cook-bar-fill preview" style="width:${previewPct}%;"></div>\n        <div class="cook-bar-fill" style="width:${curPct}%;"></div>\n      </div>\n    </div>\n    <div class="cook-bar-caption">${cur.isMax ? "Max level reached" : `${fmt(cur.progress)} / ${fmt(cur.span)} EXP to Level ${cur.level + 1}${levelUpNote}`}</div>\n    ${ascensionHtml}\n    <div class="cook-total-row">\n      <span>Total EXP added: <b>${fmt(totalExpAdded)}</b></span>\n      <span>Total cost: <b>${fmt(flowerCost)} ${typeof FLOWER_ICON !== "undefined" ? FLOWER_ICON : "FLOWER"}</b></span>\n    </div>\n  `;
}

function renderCookingModeToggle() {
  const wrap = $("cookModeToggle");
  if (!wrap) return;
  wrap.querySelectorAll("button").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.mode === cookingCostMode);
  });
}

function renderCookingBuildingTabs() {
  const wrap = $("cookBuildingTabs");
  if (!wrap) return;
  wrap.innerHTML = COOKING_BUILDINGS.map(b => `\n    <button type="button" class="${!cookingFishCategory && b === cookingActiveBuilding ? "active" : ""}" data-building="${escapeHtml(b)}">\n      ${COOKING_BUILDING_ICONS[b] || ""} ${escapeHtml(b)}\n    </button>\n  `).join("");
  wrap.querySelectorAll("button").forEach(btn => {
    btn.onclick = () => {
      setCookingActiveBuilding(btn.dataset.building);
      setCookingFishCategory("");
      renderCookingFishTabs();
      renderCookingBuildingTabs();
      renderCookingFoodList();
    };
  });
}

function renderCookingFoodCard(building, name) {
  const rec = COOKING_RECIPES[building][name];
  const {exp: boostedExp, boostsUsed: boostsUsed} = cookingComputeFoodExp(building, name);
  const isBoosted = Math.abs(boostedExp - rec.exp) > 1e-9;
  const count = getCookingCount(name);
  const isExpanded = cookingExpandedFoods.has(name);
  const {time: boostedTime, boostsUsed: timeBoostsUsed, baseTime: baseTime} = cookingComputeFoodTime(building, name);
  const isTimeBoosted = baseTime != null && Math.abs(boostedTime - baseTime) > 1e-9;
  const timeDisplay = baseTime == null ? "⏱ time unknown" : `⏱ ${isTimeBoosted ? `<span class="base">${formatDuration(baseTime)}</span>` : ""}${formatDuration(boostedTime)}`;
  const timeBoostNote = isTimeBoosted ? `<div class="cook-food-cost-line cook-boost-chip-row"><span class="cook-boost-chip-label">⚡ Time:</span><div class="cook-boost-chips">${timeBoostsUsed.map(bu => `<span class="boost-chip">${bu.icon}${escapeHtml(bu.text)}</span>`).join("")}</div></div>` : "";
  let totalCostCoins = 0;
  const ingredientRows = Object.keys(rec.ingredients).map(ing => {
    const qty = rec.ingredients[ing];
    const unitCoins = cookingIngredientUnitCostCoins(ing, cookingCostMode);
    totalCostCoins += qty * unitCoins;
    const displayVal = cookingCostMode === "buy" ? coinsToFlower(unitCoins) : unitCoins;
    const displayUnit = cookingCostMode === "buy" ? typeof FLOWER_ICON !== "undefined" ? FLOWER_ICON : "F" : typeof COIN_ICON !== "undefined" ? COIN_ICON : "c";
    let costLabel = "no cost data";
    if (unitCoins > 0) {
      costLabel = `${fmt(displayVal)}${displayUnit}/u`;
    } else if (cookingCostMode === "collect") {
      const freeBoosts = traceZeroCostBoosts(ing);
      if (freeBoosts.length) {
        costLabel = `Free — ${freeBoosts.map(b => `${getBoostIcon(b.name)}${escapeHtml(b.name)}`).join(", ")}`;
      }
    }
    return `\n      <div class="cook-ingredient-row">\n        <span>${cookingIngredientIcon(ing)}</span>\n        <span class="ing-name">${escapeHtml(ing)} ×${fmt(qty)}</span>\n        <span class="ing-cost">${costLabel}</span>\n      </div>`;
  }).join("");
  const totalFlower = coinsToFlower(totalCostCoins);
  const boostNote = isBoosted ? `<div class="cook-food-cost-line cook-boost-chip-row"><span class="cook-boost-chip-label">⚡ EXP:</span><div class="cook-boost-chips">${boostsUsed.map(bu => `<span class="boost-chip">${bu.icon}${escapeHtml(bu.text)}</span>`).join("")}</div></div>` : "";
  return `\n  <div class="cook-food-card${isExpanded ? " expanded" : ""}${count > 0 ? " is-ready" : ""}" data-food="${escapeHtml(name)}">\n    <div class="cook-food-toggle">\n      <span class="cook-food-icon">${cookFoodIcon(name)}</span>\n      <div class="cook-food-main">\n        <div class="cook-food-name">${escapeHtml(name)}</div>\n        <div class="cook-food-exp">${isBoosted ? `<span class="base">${fmt(rec.exp)}</span>` : ""}${fmt(boostedExp)} EXP · ${timeDisplay}</div>\n      </div>\n      <input type="number" min="0" step="1" class="cook-food-count" value="${count || ""}" placeholder="0" data-food="${escapeHtml(name)}">\n      <span class="cook-food-chev">▾</span>\n    </div>\n    <div class="cook-food-details">\n      ${boostNote}\n      ${timeBoostNote}\n      <div class="cook-food-cost-line">${fmt(totalFlower)} ${typeof FLOWER_ICON !== "undefined" ? FLOWER_ICON : "FLOWER"} total (${cookingCostMode === "buy" ? "Buy" : "Collect"}) — ingredients for 1×</div>\n      ${ingredientRows}\n    </div>\n  </div>`;
}

function renderCookingFoodList() {
  const wrap = $("cookFoodList");
  if (!wrap) return;
  invalidateCostCache();
  if (cookingFishCategory) {
    renderFishCatchList(cookingFishCategory);
    return;
  }
  const building = cookingActiveBuilding;
  const foods = Object.keys(COOKING_RECIPES[building] || {});
  wrap.innerHTML = foods.map(f => renderCookingFoodCard(building, f)).join("");
  wrap.querySelectorAll(".cook-food-toggle").forEach(el => {
    el.onclick = () => {
      const card = el.closest(".cook-food-card");
      const name = card.dataset.food;
      if (cookingExpandedFoods.has(name)) cookingExpandedFoods.delete(name); else cookingExpandedFoods.add(name);
      saveCookingExpanded();
      card.classList.toggle("expanded");
    };
  });
  wrap.querySelectorAll(".cook-food-count").forEach(el => {
    el.onclick = e => e.stopPropagation();
    el.oninput = () => {
      setCookingCount(el.dataset.food, el.value);
      renderCookingHeader();
      const card = el.closest(".cook-food-card");
      if (card) card.classList.toggle("is-ready", Number(el.value) > 0);
    };
  });
}

function renderCookingPanel() {
  if (!$("cookHeader")) return;
  invalidateCostCache();
  if (typeof renderFactionPetHeader === "function") renderFactionPetHeader();
  __markSub("      renderCookingPanel: renderFactionPetHeader");
  renderCookingHeader();
  __markSub("      renderCookingPanel: renderCookingHeader");
  renderCookingModeToggle();
  __markSub("      renderCookingPanel: renderCookingModeToggle");
  renderCookingFishTabs();
  __markSub("      renderCookingPanel: renderCookingFishTabs");
  renderCookingBuildingTabs();
  __markSub("      renderCookingPanel: renderCookingBuildingTabs");
  renderCookingGuaranteedCatchToggle();
  __markSub("      renderCookingPanel: renderCookingGuaranteedCatchToggle");
  renderCookingFoodList();
  __markSub("      renderCookingPanel: renderCookingFoodList (n=" + Object.keys(COOKING_RECIPES[cookingActiveBuilding] || {}).length + ")");
}

