const FISH_CATCH_NAMES = Object.keys(FISH_CATCH_DATA);

let fishingCostMode = localStorage.getItem("hl_fishing_cost_mode") || "collect";

function setFishingCostMode(mode) {
  fishingCostMode = mode === "buy" ? "buy" : "collect";
  localStorage.setItem("hl_fishing_cost_mode", fishingCostMode);
  invalidateCostCache();
}

function fishingMaterialIsFreeCost(name) {
  if (BASE_CROPS[name]) return hasFreeCostBoost(name);
  if (BASE_FRUITS[name]) return hasFreeCostBoostFruit(name);
  if (BASE_GREENHOUSE[name]) return hasFreeCostBoostGreenhouse(name);
  return false;
}

function fishingMaterialUnitCostCoins(name, visited) {
  if (fishingCostMode === "buy") return getMaterialUnitCostCoins(name, "buy", visited);
  const collectCost = getMaterialUnitCostCoins(name, "collect", visited);
  if (collectCost > 0) return collectCost;
  if (fishingMaterialIsFreeCost(name)) return 0;
  return getMaterialUnitCostCoins(name, "buy", visited);
}

function fishRodCostCoins() {
  if (typeof fishingRodIsFree === "function" && fishingRodIsFree()) return 0;
  let cost = typeof getToolCostCoins === "function" ? getToolCostCoins("default_rod") : 0;
  let rodsNeeded = 1;
  if (typeof isBoostActive === "function" && isBoostActive("skill_more_with_less")) rodsNeeded += 1;
  return cost * rodsNeeded;
}

function computeCrabFigures() {
  if (__crabFiguresMemo) return __crabFiguresMemo;
  const rodCost = fishRodCostCoins();
  const yieldMult = typeof fishingCrabYieldMult === "function" ? fishingCrabYieldMult() : 1;
  const costCoins = rodCost / yieldMult;
  __crabFiguresMemo = {
    rodCost: rodCost,
    yieldMult: yieldMult,
    costCoins: costCoins
  };
  return __crabFiguresMemo;
}

function computeSeaweedFigures() {
  if (__seaweedFiguresMemo) return __seaweedFiguresMemo;
  const rodCost = fishRodCostCoins();
  const yieldMult = typeof fishingCrabYieldMult === "function" ? fishingCrabYieldMult() : 1;
  const costCoins = rodCost / yieldMult;
  __seaweedFiguresMemo = {
    rodCost: rodCost,
    yieldMult: yieldMult,
    costCoins: costCoins
  };
  return __seaweedFiguresMemo;
}

function fishCatchYieldMult(tier) {
  let mult = 1;
  if (typeof isBoostActive !== "function") return mult;
  if (tier === "basic" && isBoostActive("skill_fishy_chance")) mult += .1;
  if (tier === "advanced" && isBoostActive("skill_fishy_roll")) mult += .1;
  if (tier === "expert" && isBoostActive("skill_fishy_gamble")) mult += .2;
  if (typeof fishingBoostYieldAdd === "function") mult += fishingBoostYieldAdd(tier);
  return mult;
}

function fishCheapestBait(fishName) {
  const d = FISH_CATCH_DATA[fishName];
  if (!d) return null;
  const name = FISH_TIER_BAIT[d.tier];
  return {
    name: name,
    cost: getMaterialUnitCostCoins(name, "collect")
  };
}

function fishChumUnitCostCoins(chumName, visited) {
  visited = visited || new Set;
  const key = "chum:" + chumName;
  if (visited.has(key)) return 0;
  visited.add(key);
  return fishingMaterialUnitCostCoins(chumName, visited);
}

function fishCheapestChum(fishName, visited) {
  const d = FISH_CATCH_DATA[fishName];
  if (!d || !d.likes || !d.likes.length) return null;
  let best = null;
  d.likes.forEach(chum => {
    const qty = CHUM_AMOUNTS_DATA[chum] || 1;
    const unit = fishChumUnitCostCoins(chum, visited);
    const cost = unit * qty;
    if (!best || cost < best.cost) best = {
      name: chum,
      qty: qty,
      unit: unit,
      cost: cost
    };
  });
  return best;
}

function computeBasicFishFigures(fishName, visited) {
  if (__fishBasicFiguresMemo.has(fishName)) return __fishBasicFiguresMemo.get(fishName);
  const guardKey = "fishfigures:" + fishName;
  if (visited && visited.has(guardKey)) return null;
  const branchVisited = new Set(visited || []);
  branchVisited.add(guardKey);
  const result = computeBasicFishFiguresUncached(fishName, branchVisited);
  __fishBasicFiguresMemo.set(fishName, result);
  return result;
}

function computeBasicFishFiguresUncached(fishName, visited) {
  const d = FISH_CATCH_DATA[fishName];
  if (!d) return null;
  const bait = fishCheapestBait(fishName);
  const chum = fishCheapestChum(fishName, visited);
  const rodCost = fishRodCostCoins();
  const baitCost = bait ? bait.cost : 0;
  const chumCost = chum ? chum.cost : 0;
  const rawCost = rodCost + baitCost + chumCost;
  const yieldMult = fishCatchYieldMult(d.tier);
  const costCoins = rawCost / yieldMult;
  return {
    tier: d.tier,
    bait: bait,
    chum: chum,
    rodCost: rodCost,
    baitCost: baitCost,
    chumCost: chumCost,
    rawCost: rawCost,
    yieldMult: yieldMult,
    costCoins: costCoins
  };
}

function getAgingMaxXPLocal(baseXP) {
  if (baseXP <= 200) return baseXP * 3;
  if (baseXP <= 330) return baseXP * 4;
  return baseXP * 5;
}

function getAgingSaltCostLocal(baseXP) {
  return Math.round(getAgingMaxXPLocal(baseXP) / 50);
}

function fishEffectiveBasicCostCoins(fishName) {
  if (typeof cookingGuaranteedCatchOn !== "undefined" && cookingGuaranteedCatchOn) {
    const item = fishMarketItemForFish(fishName);
    if (item) {
      const itemCostCoins = fishMarketItemCostCoins(item, "collect", previewSeason);
      const d = FISH_CATCH_DATA[fishName];
      const yieldMult = d ? fishCatchYieldMult(d.tier) : 1;
      return yieldMult > 0 ? itemCostCoins / yieldMult : itemCostCoins;
    }
  }
  const bf = computeBasicFishFigures(fishName);
  return bf ? bf.costCoins : 0;
}

function computeAgedFishFigures(fishName) {
  if (__fishAgedFiguresMemo.has(fishName)) return __fishAgedFiguresMemo.get(fishName);
  const basicFishCost = fishEffectiveBasicCostCoins(fishName);
  const xpEntry = FISH_XP_DATA[fishName];
  let result = null;
  if (xpEntry) {
    const saltQty = getAgingSaltCostLocal(xpEntry.basic) * (typeof getActiveAgingSaltCostMult === "function" ? getActiveAgingSaltCostMult() : 1);
    const saltCostCoins = saltQty * (typeof computeSaltUnitCostCoins === "function" ? computeSaltUnitCostCoins() : 0);
    const costCoins = basicFishCost + saltCostCoins;
    result = {
      basicFishCost: basicFishCost,
      saltQty: saltQty,
      saltCostCoins: saltCostCoins,
      costCoins: costCoins
    };
  }
  __fishAgedFiguresMemo.set(fishName, result);
  return result;
}

function fishCatchComputeXP(fishName, stage) {
  const memoKey = stage + "|" + fishName;
  if (__fishCatchXPMemo.has(memoKey)) return __fishCatchXPMemo.get(memoKey);
  const result = fishCatchComputeXPUncached(fishName, stage);
  __fishCatchXPMemo.set(memoKey, result);
  return result;
}

function fishCatchComputeXPUncached(fishName, stage) {
  const xpEntry = FISH_XP_DATA[fishName];
  if (!xpEntry) return {
    xp: 0,
    boostsUsed: [],
    baseXp: 0
  };
  let xp = xpEntry[stage];
  const baseXp = xp;
  const boostsUsed = [];
  const applyMult = (m, label, icon) => {
    if (m && m !== 1) {
      xp *= m;
      boostsUsed.push({
        text: label,
        icon: icon || ""
      });
    }
  };
  if (typeof isBoostActive === "function" && typeof COOKING_BOOSTS !== "undefined") {
    COOKING_BOOSTS.forEach(b => {
      if (!isBoostActive(b.id)) return;
      if (b.scope !== "foodGlobal" && b.scope !== "foodFish") return;
      if (!b.expMult) return;
      const icon = typeof getBoostIcon === "function" ? getBoostIcon(b.name) : "";
      applyMult(b.expMult, `${b.name} ×${b.expMult}`, icon);
    });
  }
  if (typeof cookingSkillRankMultiplier === "function") {
    applyMult(cookingSkillRankMultiplier("skill_munching_mastery", [ .05, .1, .15 ]), "Munching Mastery");
    applyMult(cookingSkillRankMultiplier("skill_fishy_feast", [ .2, .25, .3 ]), "Fishy Feast");
  }
  if (typeof getPortBudFishXpMult === "function") {
    const portBudMult = getPortBudFishXpMult();
    if (portBudMult !== 1) applyMult(portBudMult, `Port Bud ×${portBudMult}`);
  }
  if ((stage === "aged" || stage === "primeAged") && typeof getActiveAgedFishXpMult === "function") {
    const astrolabeMult = getActiveAgedFishXpMult();
    const icon = typeof getBoostIcon === "function" ? getBoostIcon("Astrolabe") : "";
    applyMult(astrolabeMult, `Astrolabe ×${astrolabeMult}`, icon);
  }
  try {
    const info = typeof farmPanelGetLastInfo === "function" ? farmPanelGetLastInfo() : null;
    if (info && info.vipActive) applyMult(1.1, "VIP Access ×1.1");
  } catch (e) {}
  try {
    if (typeof factionPetGetBoostMultiplier === "function") {
      const petMult = factionPetGetBoostMultiplier();
      if (petMult !== 1) applyMult(petMult, `Faction Pet Streak ×${petMult}`);
    }
  } catch (e) {}
  return {
    xp: xp,
    boostsUsed: boostsUsed,
    baseXp: baseXp
  };
}

let cookingGuaranteedCatchOn = localStorage.getItem("hl_cooking_guaranteed_catch") === "true";

function setCookingGuaranteedCatchOn(val) {
  cookingGuaranteedCatchOn = !!val;
  localStorage.setItem("hl_cooking_guaranteed_catch", String(cookingGuaranteedCatchOn));
  __fishAgedFiguresMemo.clear();
}

function fishMarketItemForFish(fishName) {
  return Object.keys(FISH_MARKET_GUARANTEED_CATCH).find(item => FISH_MARKET_GUARANTEED_CATCH[item].includes(fishName)) || null;
}

function fishCatchStageCostCoins(fishName, stage) {
  if (stage === "basic") return fishEffectiveBasicCostCoins(fishName);
  const af = computeAgedFishFigures(fishName);
  return af ? af.costCoins : 0;
}

function renderCookingGuaranteedCatchToggle() {
  const row = $("cookGuaranteedCatchToggleRow");
  const input = $("cookGuaranteedCatchToggleInput");
  if (!row || !input) return;
  row.style.display = cookingFishCategory === "Basic Fish" ? "" : "none";
  input.checked = cookingGuaranteedCatchOn;
  row.classList.toggle("is-active", cookingGuaranteedCatchOn);
  const applyToggle = val => {
    setCookingGuaranteedCatchOn(val);
    input.checked = cookingGuaranteedCatchOn;
    row.classList.toggle("is-active", cookingGuaranteedCatchOn);
    renderCookingHeader();
    renderCookingFoodList();
  };
  input.onchange = () => applyToggle(input.checked);
  row.onclick = e => {
    if (e.target.closest(".switch")) return;
    applyToggle(!input.checked);
  };
}

let cookingFishCategory = localStorage.getItem("hl_cooking_fish_category") || "";

function setCookingFishCategory(cat) {
  const valid = [ "", "Basic Fish", "Aged Fish", "Prime Aged Fish" ];
  cookingFishCategory = valid.includes(cat) ? cat : "";
  localStorage.setItem("hl_cooking_fish_category", cookingFishCategory);
}

function fishStageForCategory(cat) {
  if (cat === "Basic Fish") return "basic";
  if (cat === "Aged Fish") return "aged";
  if (cat === "Prime Aged Fish") return "primeAged";
  return null;
}

function fishInventoryNameForCategory(fishName, cat) {
  if (cat === "Aged Fish") return "Aged " + fishName;
  if (cat === "Prime Aged Fish") return "Prime Aged " + fishName;
  return fishName;
}

function renderCookingFishTabs() {
  const wrap = $("cookFishTabs");
  if (!wrap) return;
  const cats = [ "Basic Fish", "Aged Fish", "Prime Aged Fish" ];
  wrap.innerHTML = cats.map(cat => `\n    <button type="button" class="${cat === cookingFishCategory ? "active" : ""}" data-fish-category="${escapeHtml(cat)}">\n      🐟 ${escapeHtml(cat)}\n    </button>\n  `).join("");
  wrap.querySelectorAll("button").forEach(btn => {
    btn.onclick = () => {
      setCookingFishCategory(cookingFishCategory === btn.dataset.fishCategory ? "" : btn.dataset.fishCategory);
      renderCookingFishTabs();
      renderCookingBuildingTabs();
      renderCookingGuaranteedCatchToggle();
      renderCookingFoodList();
    };
  });
}

function renderFishCatchCard(fishName, cat) {
  const stage = fishStageForCategory(cat);
  const d = FISH_CATCH_DATA[fishName];
  const {xp: boostedXp, boostsUsed: boostsUsed, baseXp: baseXp} = fishCatchComputeXP(fishName, stage);
  const isBoosted = Math.abs(boostedXp - baseXp) > 1e-9;
  const invName = fishInventoryNameForCategory(fishName, cat);
  const count = getCookingCount(invName);
  const isExpanded = cookingExpandedFoods.has(invName);
  const costCoins = fishCatchStageCostCoins(fishName, stage);
  const totalFlower = coinsToFlower(costCoins);
  const boostNote = isBoosted ? `<div class="cook-food-cost-line cook-boost-chip-row"><span class="cook-boost-chip-label">⚡ EXP:</span><div class="cook-boost-chips">${boostsUsed.map(bu => `<span class="boost-chip">${bu.icon}${escapeHtml(bu.text)}</span>`).join("")}</div></div>` : "";
  const marketItem = stage === "basic" && cookingGuaranteedCatchOn ? fishMarketItemForFish(fishName) : null;
  const icon = stage === "basic" ? getIcon(fishName) : getFishIcon(fishName, stage === "primeAged");
  let ingredientRows = "";
  if (stage === "basic") {
    if (marketItem) {
      const marketItemTotalCoins = fishMarketItemCostCoins(marketItem, "collect", previewSeason);
      const fishYieldMult = fishCatchYieldMult(d.tier);
      const itemCostCoins = fishEffectiveBasicCostCoins(fishName);
      ingredientRows = `\n        <div class="cook-ingredient-row"><span>${getIcon(marketItem)}</span><span class="ing-name">${escapeHtml(marketItem)} ×1</span><span class="ing-cost">${fmt(coinsToFlower(marketItemTotalCoins))}${FLOWER_ICON}</span></div>\n        <div class="cook-ingredient-row"><span class="ing-name">÷ avg yield ×${fmt(fishYieldMult)}/rod</span><span class="ing-cost">= ${fmt(coinsToFlower(itemCostCoins))}${FLOWER_ICON}/u</span></div>\n        <div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">Guaranteed Catch active — cost uses the Fish Market's ${escapeHtml(marketItem)} recipe cost divided by ${escapeHtml(fishName)}'s avg catch yield instead of Rod + Bait + Chum.</div>\n      `;
    } else {
      const bf = computeBasicFishFigures(fishName);
      ingredientRows = `\n        <div class="cook-ingredient-row"><span>${getIcon("Rod")}</span><span class="ing-name">Rod ×1</span><span class="ing-cost">${fmt(coinsToFlower(bf.rodCost))}${FLOWER_ICON}/u</span></div>\n        <div class="cook-ingredient-row"><span>${getIcon(bf.bait ? bf.bait.name : "")}</span><span class="ing-name">${escapeHtml(bf.bait ? bf.bait.name : "?")} ×1</span><span class="ing-cost">${fmt(coinsToFlower(bf.baitCost))}${FLOWER_ICON}/u</span></div>\n        <div class="cook-ingredient-row"><span>${getIcon(bf.chum ? bf.chum.name : "")}</span><span class="ing-name">${escapeHtml(bf.chum ? bf.chum.name : "?")} ×${fmt(bf.chum ? bf.chum.qty : 0)}</span><span class="ing-cost">${fmt(coinsToFlower(bf.chumCost))}${FLOWER_ICON}/u</span></div>\n        <div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">Tier: ${escapeHtml(FISH_TIER_LABEL[d.tier])}${fishCatchYieldMult(d.tier) !== 1 ? ` · avg yield ×${fmt(fishCatchYieldMult(d.tier))} (chance skill)` : ``}</div>\n      `;
    }
  } else {
    const af = computeAgedFishFigures(fishName);
    ingredientRows = `\n      <div class="cook-ingredient-row"><span>${getIcon(fishName)}</span><span class="ing-name">${escapeHtml(fishName)} ×1</span><span class="ing-cost">${fmt(coinsToFlower(af.basicFishCost))}${FLOWER_ICON}/u</span></div>\n      <div class="cook-ingredient-row"><span>${getIcon("Salt")}</span><span class="ing-name">Salt ×${fmt(af.saltQty)}</span><span class="ing-cost">${fmt(coinsToFlower(af.saltCostCoins))}${FLOWER_ICON}/u</span></div>\n      ${stage === "primeAged" ? `<div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">Same recipe as Aged — Prime Aged is a bonus chance on the same batch, not an extra cost.</div>` : ``}\n      ${cookingGuaranteedCatchOn ? `<div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">🎯 Guaranteed Catch is on — the ${escapeHtml(fishName)} cost above already uses the Fish Market recipe cost instead of Rod + Bait + Chum.</div>` : ``}\n    `;
  }
  return `\n  <div class="cook-food-card${isExpanded ? " expanded" : ""}${count > 0 ? " is-ready" : ""}" data-food="${escapeHtml(invName)}">\n    <div class="cook-food-toggle">\n      <span class="cook-food-icon">${icon}</span>\n      <div class="cook-food-main">\n        <div class="cook-food-name">${escapeHtml(fishName)}</div>\n        <div class="cook-food-exp">${isBoosted ? `<span class="base">${fmt(baseXp)}</span>` : ""}${fmt(boostedXp)} EXP · ${fmt(totalFlower)} ${FLOWER_ICON}/u</div>\n      </div>\n      <input type="number" min="0" step="1" class="cook-food-count" value="${count || ""}" placeholder="0" data-food="${escapeHtml(invName)}">\n      <span class="cook-food-chev">▾</span>\n    </div>\n    <div class="cook-food-details">\n      ${boostNote}\n      <div class="cook-food-cost-line">${fmt(totalFlower)} ${FLOWER_ICON} FLOWER total — cost for 1×</div>\n      ${ingredientRows}\n    </div>\n  </div>`;
}

function renderFishCatchList(cat) {
  const wrap = $("cookFoodList");
  if (!wrap) return;
  wrap.innerHTML = FISH_CATCH_NAMES.map(f => renderFishCatchCard(f, cat)).join("");
  wrap.querySelectorAll(".cook-food-toggle").forEach(el => {
    el.onclick = () => {
      const card = el.closest(".cook-food-card");
      const name = card.dataset.food;
      if (cookingExpandedFoods.has(name)) cookingExpandedFoods.delete(name); else cookingExpandedFoods.add(name);
      saveCookingExpanded();
      card.classList.toggle("expanded");
    };
  });
  wrap.querySelectorAll(".cook-food-count").forEach(el => {
    el.onclick = e => e.stopPropagation();
    el.oninput = () => {
      setCookingCount(el.dataset.food, el.value);
      renderCookingHeader();
      const card = el.closest(".cook-food-card");
      if (card) card.classList.toggle("is-ready", Number(el.value) > 0);
    };
  });
}

function cookingFishTotals() {
  let totalExpAdded = 0;
  let totalCostCoins = 0;
  [ "Basic Fish", "Aged Fish", "Prime Aged Fish" ].forEach(cat => {
    const stage = fishStageForCategory(cat);
    FISH_CATCH_NAMES.forEach(f => {
      const invName = fishInventoryNameForCategory(f, cat);
      const count = getCookingCount(invName);
      if (!count) return;
      const {xp: xp} = fishCatchComputeXP(f, stage);
      totalExpAdded += xp * count;
      totalCostCoins += fishCatchStageCostCoins(f, stage) * count;
    });
  });
  return {
    totalExpAdded: totalExpAdded,
    totalCostCoins: totalCostCoins
  };
}

let fishingTierActive = localStorage.getItem("hl_fishing_tier") || "basic";

function setFishingTier(tier) {
  fishingTierActive = [ "basic", "advanced", "expert" ].includes(tier) ? tier : "basic";
  localStorage.setItem("hl_fishing_tier", fishingTierActive);
}

let fishingExpandedTierFish = new Set;

function renderFishingTierTabs() {
  const wrap = $("fishingTierToggle");
  if (!wrap) return;
  wrap.querySelectorAll("button").forEach(btn => {
    btn.classList.toggle("active", btn.dataset.tier === fishingTierActive);
    btn.onclick = () => {
      setFishingTier(btn.dataset.tier);
      renderFishingTierTabs();
      renderFishingTierList();
    };
  });
}

function renderFishingTierCard(fishName) {
  const d = FISH_CATCH_DATA[fishName];
  const bf = computeBasicFishFigures(fishName);
  if (!bf) return "";
  const totalFlower = coinsToFlower(bf.costCoins);
  const isExpanded = fishingExpandedTierFish.has(fishName);
  const yieldMult = bf.yieldMult;
  return `\n  <div class="cook-food-card${isExpanded ? " expanded" : ""}" data-fish="${escapeHtml(fishName)}">\n    <div class="cook-food-toggle">\n      <span class="cook-food-icon">${getIcon(fishName)}</span>\n      <div class="cook-food-main">\n        <div class="cook-food-name">${escapeHtml(fishName)}</div>\n        <div class="cook-food-exp">${fmt(totalFlower)} ${FLOWER_ICON}/u${yieldMult !== 1 ? ` · avg yield ×${fmt(yieldMult)}/rod` : ``}</div>\n      </div>\n      <span class="cook-food-chev">▾</span>\n    </div>\n    <div class="cook-food-details">\n      <div class="cook-food-cost-line">${fmt(totalFlower)} ${FLOWER_ICON} FLOWER — cost per fish</div>\n      <div class="cook-ingredient-row"><span>${getIcon("Rod")}</span><span class="ing-name">Rod ×1</span><span class="ing-cost">${bf.rodCost === 0 ? fishRodFreeCostLabel() : `${fmt(coinsToFlower(bf.rodCost / yieldMult))}${FLOWER_ICON}/u`}</span></div>\n      <div class="cook-ingredient-row"><span>${getIcon(bf.bait ? bf.bait.name : "")}</span><span class="ing-name">${escapeHtml(bf.bait ? bf.bait.name : "?")} ×1</span><span class="ing-cost">${fmt(coinsToFlower(bf.baitCost / yieldMult))}${FLOWER_ICON}/u</span></div>\n      <div class="cook-ingredient-row"><span>${getIcon(bf.chum ? bf.chum.name : "")}</span><span class="ing-name">${escapeHtml(bf.chum ? bf.chum.name : "?")} ×${fmt(bf.chum ? bf.chum.qty : 0)}</span><span class="ing-cost">${fmt(coinsToFlower(bf.chumCost / yieldMult))}${FLOWER_ICON}/u</span></div>\n      <div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">Avg yield per rod: ×${fmt(yieldMult)}${yieldMult !== 1 ? ` (Fishy Chance/Roll/Gamble skill &amp; 🎣 Fishing boosts applied)` : ``}</div>\n    </div>\n  </div>`;
}

function renderCrabTierCard() {
  const fig = computeCrabFigures();
  const totalFlower = coinsToFlower(fig.costCoins);
  const isExpanded = fishingExpandedTierFish.has("Crab");
  return `\n  <div class="cook-food-card${isExpanded ? " expanded" : ""}" data-fish="Crab">\n    <div class="cook-food-toggle">\n      <span class="cook-food-icon">${getIcon("Crab")}</span>\n      <div class="cook-food-main">\n        <div class="cook-food-name">Crab</div>\n        <div class="cook-food-exp">${fmt(totalFlower)} ${FLOWER_ICON}/u${fig.yieldMult !== 1 ? ` · avg yield ×${fmt(fig.yieldMult)}/rod` : ``}</div>\n      </div>\n      <span class="cook-food-chev">▾</span>\n    </div>\n    <div class="cook-food-details">\n      <div class="cook-food-cost-line">${fmt(totalFlower)} ${FLOWER_ICON} FLOWER — cost per crab</div>\n      <div class="cook-ingredient-row"><span>${getIcon("Rod")}</span><span class="ing-name">Rod ×1</span><span class="ing-cost">${fig.rodCost === 0 ? fishRodFreeCostLabel() : `${fmt(coinsToFlower(fig.rodCost / fig.yieldMult))}${FLOWER_ICON}/u`}</span></div>\n      <div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">1 Rod = 1 Crab, no bait or chum needed.${fig.yieldMult !== 1 ? ` Boosted by 🎣 Fishing boosts (e.g. Crab Hat).` : ` Turn on 🎣 Fishing boosts (e.g. Crab Hat) to boost Crab yield.`}</div>\n    </div>\n  </div>`;
}

function renderSeaweedTierCard() {
  const fig = computeSeaweedFigures();
  const totalFlower = coinsToFlower(fig.costCoins);
  const isExpanded = fishingExpandedTierFish.has("Seaweed");
  return `\n  <div class="cook-food-card${isExpanded ? " expanded" : ""}" data-fish="Seaweed">\n    <div class="cook-food-toggle">\n      <span class="cook-food-icon">${getIcon("Seaweed")}</span>\n      <div class="cook-food-main">\n        <div class="cook-food-name">Seaweed</div>\n        <div class="cook-food-exp">${fmt(totalFlower)} ${FLOWER_ICON}/u${fig.yieldMult !== 1 ? ` · avg yield ×${fmt(fig.yieldMult)}/rod` : ``}</div>\n      </div>\n      <span class="cook-food-chev">▾</span>\n    </div>\n    <div class="cook-food-details">\n      <div class="cook-food-cost-line">${fmt(totalFlower)} ${FLOWER_ICON} FLOWER — cost per seaweed</div>\n      <div class="cook-ingredient-row"><span>${getIcon("Rod")}</span><span class="ing-name">Rod ×1</span><span class="ing-cost">${fig.rodCost === 0 ? fishRodFreeCostLabel() : `${fmt(coinsToFlower(fig.rodCost / fig.yieldMult))}${FLOWER_ICON}/u`}</span></div>\n      <div style="font-size:9px;color:var(--ink-soft);margin-top:2px;">1 Rod = 1 Seaweed, no bait or chum needed.${fig.yieldMult !== 1 ? ` Boosted by 🎣 Fishing boosts (e.g. Crab Hat).` : ` Turn on 🎣 Fishing boosts (e.g. Crab Hat) to boost Seaweed yield.`}</div>\n    </div>\n  </div>`;
}

function renderFishingTierList() {
  const wrap = $("fishingTierList");
  if (!wrap) return;
  const names = FISH_CATCH_NAMES.filter(f => FISH_CATCH_DATA[f].tier === fishingTierActive);
  let html = names.map(f => renderFishingTierCard(f)).join("");
  if (fishingTierActive === "basic") html += renderCrabTierCard() + renderSeaweedTierCard();
  wrap.innerHTML = html;
  wrap.querySelectorAll(".cook-food-toggle").forEach(el => {
    el.onclick = () => {
      const card = el.closest(".cook-food-card");
      const name = card.dataset.fish;
      if (fishingExpandedTierFish.has(name)) fishingExpandedTierFish.delete(name); else fishingExpandedTierFish.add(name);
      card.classList.toggle("expanded");
    };
  });
}

